        function scDivMasterSheetUrl_(division, gid) {
            return `https://docs.google.com/spreadsheets/d/${SC_DIVMASTER_SHEETS_[division]}/export?format=csv&gid=${gid}`;
        }
        function scDivMasterParseMeta_(csvText, division) {
            const out = {};
            String(csvText || "").split(/\r?\n/).forEach((line, i) => {
                if (!line.trim()) return;
                const c = splitCsvLine(line);
                if (i === 0 && /^DC\s*NAME$/i.test(String(c[0] || "").trim())) return;
                const dc = normalizeDcName(c[0]);
                if (!dc) return;
                out[dc] = {
                    gid: String(c[1] || "").trim(),
                    state: String(c[2] || "").trim().toUpperCase(),
                    rows: Number(c[3]) || 0,
                    at: String(c[4] || "").trim(),
                    division: normalizeDcName(c[5]) || division,
                    prefixes: String(c[6] || "").split(/[,\s]+/).filter((x) => /^\d{4}$/.test(x))
                };
            });
            return out;
        }
