        function formatOmvigCellDate_(value) {
            if (value instanceof Date) {
                // BUG FIX (2026-09-15, USER-REPORTED): kuch paid rows jinka asli
                // Pay_date "date-only" tha (koi real time nahi, source system se
                // midnight placeholder) - Excel apne andar date ko decimal number
                // ke roop me store karta hai, aur is number me kabhi-kabhi ek
                // bahut chhota (~10 second ka) floating-point imprecision hota
                // hai jo Excel ki apni display me round hokar "12:00:00 AM"
                // saaf dikhta hai, lekin jab yahan precisely (millisecond tak)
                // padh kar IST me convert kiya jaata tha, to wo chhota sa farak
                // MIDNIGHT ki boundary galat taraf paar kara deta tha - poori
                // DATE hi ek din PEECHE (jaise 14-Sep ki jagah 13-Sep) ban jaati
                // thi. Fix: date-components nikaalne se pehle NEAREST MINUTE par
                // round kar dete hain - itna chhota (<30s) drift ab kabhi
                // din/ghante ki boundary paar nahi karega.
                const rounded = new Date(Math.round(value.getTime() / 60000) * 60000);
                const y = rounded.getFullYear(), m = String(rounded.getMonth() + 1).padStart(2, "0"), d = String(rounded.getDate()).padStart(2, "0");
                const hh = String(rounded.getHours()).padStart(2, "0"), mm = String(rounded.getMinutes()).padStart(2, "0");
                return `${d}-${m}-${y} ${hh}:${mm}`;
            }
            return String(value ?? "").trim();
        }

        async function readOmvigPaidFile(file) {
            if (!file) return [];
            if (!window.XLSX) throw new Error("Excel reader could not be loaded. Please check internet and refresh.");
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: "array", cellDates: true });
            const sheet = workbook.Sheets[workbook.SheetNames[0]];
            const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: "" });
            if (!rows.length) return [];
            const headers = (rows[0] || []).map((h) => String(h || "").trim().toLowerCase());
            const idx = (names) => {
                for (const n of names) {
                    const i = headers.indexOf(n.toLowerCase());
                    if (i > -1) return i;
                }
                return -1;
            };
            const circleIdx = idx(["Circle"]);
            const divisionIdx = idx(["Division"]);
            const panchanamaIdx = idx(["Panchanama_no", "Panchanama_No"]);
            const amountIdx = idx(["amount", "Amount"]);
            const payDateIdx = idx(["Pay_date", "Pay Date"]);
            const payModeIdx = idx(["Pay_mode", "Pay Mode"]);
            const txIdx = idx(["Tx_number", "Tx Number"]);
            if (panchanamaIdx < 0 || amountIdx < 0) throw new Error("Paid list file format does not match (Panchanama_no / amount column not found)");

            return rows.slice(1).map((row) => {
                const panchanamaNo = String(row[panchanamaIdx] || "").trim();
                if (!panchanamaNo) return null;
                return {
                    Circle: circleIdx > -1 ? String(row[circleIdx] || "").trim() : "",
                    Division: divisionIdx > -1 ? String(row[divisionIdx] || "").trim() : "",
                    Panchanama_no: panchanamaNo,
                    amount: row[amountIdx],
                    Pay_date: payDateIdx > -1 ? formatOmvigCellDate_(row[payDateIdx]) : "",
                    Pay_mode: payModeIdx > -1 ? String(row[payModeIdx] || "").trim() : "",
                    Tx_number: txIdx > -1 ? String(row[txIdx] || "").trim() : ""
                };
            }).filter(Boolean);
        }

        async function uploadOmvigPaidList() {
            const fileInput = document.getElementById("omvig-paid-file-input");
            const uploadBtn = document.getElementById("omvig-paid-upload-btn");
            const statusBox = document.getElementById("omvig-paid-upload-status");
            const file = fileInput?.files?.[0] || null;
            if (!file) return showToast("Please select the Paid List file first", false);
            setActionButtonState(uploadBtn, "processing", "Upload Paid List");
            if (statusBox) { statusBox.style.display = "block"; statusBox.innerHTML = `<div style="text-align:center; font-size:0.75rem; font-weight:800; color:#1d4ed8;">Reading file...</div>`; }
            try {
                const rows = await readOmvigPaidFile(file);
                if (!rows.length) throw new Error("No valid row found in the file");
                if (statusBox) statusBox.innerHTML = `<div style="text-align:center; font-size:0.75rem; font-weight:800; color:#1d4ed8;">Uploading ${rows.length} rows... please wait</div>`;
                const response = await fetchWithTimeout(omvigSubmitScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "text/plain;charset=utf-8" },
                    body: JSON.stringify({ action: "uploadPaidList", admin_password: omvigAdminPasswordEntered, rows })
                }, 90000);
                const text = await response.text();
                let parsed = {};
                try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                if (parsed.status !== "success") throw new Error(parsed.message || "Upload failed");
                setActionButtonState(uploadBtn, "done", "Upload Paid List");
                showToast(parsed.message || "Paid list uploaded", true);
                // BUG FIX (2026-09-23, USER-REPORTED - "summary samajh nahi aa raha"):
                // pehle sirf raw "X matched, Y unmatched, Z duplicate skip" ek line me
                // dikhta tha - na yeh bataya jaata tha "matched/unmatched" ka matlab kya
                // hai, na "duplicate skip" (jo bilkul NORMAL/safe hai, koi problem nahi)
                // alarming kyu nahi hai, aur "nayi entry bani" wala breakdown (kitni
                // rows WAKAI is baar pehli baar add hui vs kitni pehle se maujood thi)
                // yahan bilkul nahi dikhta tha (sirf upar wali "Last Upload" line me
                // dikhta tha - do alag boxes me do alag level ka detail, isliye confusing
                // lagta tha). Ab ek hi jagah, plain language me, poora breakdown:
                // total rows, DC-match hui vs nahi hui, un dono me se kitni NAYI vs
                // kitni PEHLE-SE-MAUJOOD (isiliye skip hui) - dono field already
                // backend response (parsed.new_matched/new_unmatched) me aate hain,
                // bas ab yahan dikhaye ja rahe hain.
                if (statusBox) {
                    const totalRows = (parsed.matched || 0) + (parsed.unmatched || 0);
                    const newMatched = parsed.new_matched ?? 0;
                    const newUnmatched = parsed.new_unmatched ?? 0;
                    const oldMatched = Math.max(0, (parsed.matched || 0) - newMatched);
                    const oldUnmatched = Math.max(0, (parsed.unmatched || 0) - newUnmatched);
                    const unmatchedBlock = parsed.unmatched
                        ? `<div style="margin-top:8px; padding:9px 11px; background:#fff7ed; border:1.2px solid #fdba74; border-radius:12px; text-align:left;">
                                <div style="color:#9a3412; font-weight:950; font-size:0.72rem;">⚠️ DC could not be identified for ${parsed.unmatched} rows</div>
                                <div style="font-weight:700; color:#78350f; font-size:0.66rem; margin-top:3px;">Panchanama No of these rows was not found in the "Pending List". ${newUnmatched} row${newUnmatched === 1 ? "" : "s"} added to the "UNMATCHED" list for the first time${oldUnmatched ? `, the other ${oldUnmatched} were already there` : ""}. Please check the Panchanama No again.</div>
                            </div>`
                        : "";
                    statusBox.innerHTML = `
                        <div style="text-align:center; padding:10px 12px; background:#f0fdf4; border:1.2px solid #86efac; border-radius:12px;">
                            <div style="font-size:0.85rem; font-weight:950; color:#166534;">✅ Upload Successful</div>
                            <div style="font-size:0.68rem; font-weight:700; color:#475569; margin-top:4px;">Total ${totalRows} rows in the file</div>
                        </div>
                        <div style="margin-top:8px; padding:9px 11px; background:#eff6ff; border:1.2px solid #93c5fd; border-radius:12px; text-align:left;">
                            <div style="color:#1d4ed8; font-weight:950; font-size:0.72rem;">🟢 DC matched correctly for ${parsed.matched} rows</div>
                            <div style="font-weight:700; color:#334155; font-size:0.66rem; margin-top:3px;">Of these, ${newMatched} row${newMatched === 1 ? "" : "s"} were NEW (added to the DC list for the first time)${oldMatched ? `, the other ${oldMatched} already existed (skipped on re-upload - no problem, data is safe)` : ""}.</div>
                        </div>
                        ${unmatchedBlock}
                        <div style="margin-top:8px; font-size:0.62rem; font-weight:700; color:#64748b; text-align:center; line-height:1.5;">ℹ️ A total of ${parsed.skipped_duplicate} rows were already in the system, so they were NOT counted again (this is normal - on re-upload an old entry is not added again, and there is no data loss or error).</div>
                        <div style="margin-top:8px; font-size:0.7rem; font-weight:850; color:#334155; text-align:center;">DC tabs updated:<br><span style="font-weight:700;">${(parsed.dc_tabs_updated || []).join(", ") || "-"}</span></div>
                    `;
                }
                omvigPendingCache_ = {}; omvigPaidCache_ = {}; omvigReportCache_ = null; omvigFreezeStatusCache_ = null; omvigDailyReportCache_ = null;
                if (fileInput) fileInput.value = "";
                const nameBox = document.getElementById("omvig-paid-file-name");
                if (nameBox) nameBox.innerText = "";
                // USER REQUEST (2026-09-15): admin ko panel dobara khole bina
                // hi yahin turant "last upload" line dikh jaani chahiye.
                try {
                    const freshStatus = await fetchOmvigFreezeStatus_(true);
                    omvigAdminStatus = { freeze_date: freshStatus.freeze_date, pending_count: freshStatus.pending_count, last_upload_at: freshStatus.last_upload_at, last_upload_summary: freshStatus.last_upload_summary };
                    renderOmvigAdminStatus();
                } catch (_) {
                    // status refresh fail ho to bhi upload khud successful ho chuka hai - chup rehte hain, agli baar panel khulne par sahi dikh jayega.
                }
            } catch (error) {
                setActionButtonState(uploadBtn, "failed", "Upload Paid List");
                showToast(error?.message || "Paid list upload failed", false);
                if (statusBox) statusBox.innerHTML = `<div style="text-align:center; font-size:0.75rem; font-weight:800; color:#b91c1c;">Upload fail: ${escapeHtml(error?.message || "")}</div>`;
            } finally {
                setTimeout(() => setActionButtonState(uploadBtn, "idle", "Upload Paid List"), 900);
            }
        }

        function normalizeOmvigPendingRow_(row) {
            return {
                circle: String(row[0] || "").trim(),
                division: String(row[1] || "").trim(),
                dc_name: String(row[2] || "").trim(),
                checked_by: String(row[3] || "").trim(),
                inspection_date: String(row[4] || "").trim(),
                panchanama_no: String(row[5] || "").trim(),
                ez_no: String(row[6] || "").trim(),
                consumer_name: String(row[7] || "").trim(),
                consumer_no: String(row[8] || "").trim(),
                tariff_name: String(row[9] || "").trim(),
                case_name: String(row[10] || "").trim(),
                balanced_amount: cleanOmvigAmount_(row[11])
            };
        }

        function normalizeOmvigPaidRow_(row) {
            return {
                circle: String(row[0] || "").trim(),
                division: String(row[1] || "").trim(),
                panchanama_no: String(row[2] || "").trim(),
                amount: cleanOmvigAmount_(row[3]),
                pay_date: String(row[4] || "").trim(),
                pay_mode: String(row[5] || "").trim(),
                tx_number: String(row[6] || "").trim(),
                uploaded_at: String(row[7] || "").trim(),
                // USER REQUEST (2026-09-14): Daily (fast) mode ke liye - backend ab
                // is 9th column me DC naam bhejta hai (PAID sheet ke naam se hi
                // derive hota hai server-side, koi extra sheet-read nahi) - purane
                // backend (jab tak .gs redeploy na ho) is index par khaali string
                // dega, tab yeh empty rahega (koi crash nahi).
                dc_name: String(row[8] || "").trim()
            };
        }

        // USER-REPORTED SLOWNESS FIX (2026-09-14): fast, data-light check (sirf
        // freeze_date + pending_count) - `loadOmvigReportData_` isse pehle call
        // karta hai taaki "abhi freeze nahi hua" case me poori (~9500 row) Circle
        // list fetch hi na karni pade (jo 1-2+ min leti hai aur pehle timeout+
        // "data load nahi ho payi" error deti thi).
        // BUG FIX (2026-09-14, USER-REPORTED "TRY AGAIN par bhi fetch nahi ho
        // raha" - EXACT SAME root cause jo Freeze Report me pehle mila tha,
        // 2026-09-13 ko din-bhar lag kar solve hua tha: ek hi Apps Script
        // project par bahut saari concurrent request jaane par Google ka
        // "echo" content-delivery layer kabhi-kabhi 404 de deta hai (Chrome
        // Network tab me "script.googleusercontent.com/macros/echo...404").
        // Uss waqt saari Freeze/Revenue calls ke liye
        // `withAppsScriptConcurrencyGate_` (max 2 concurrent request per
        // script-URL, baaki queue me wait karte hain) laga diya gaya tha -
        // lekin O&M/VIG naya module hai, uski teeno fetch call
        // (getFreezeStatus/getPendingSummary/getPaidSummary) is gate ke
        // bina hi likhi gayi thi, isliye yahi purana bug yahan wapas aa gaya.
        // Fix: teeno call ab bhi wahi gate use karti hain - future me koi
        // bhi naya O&M/VIG fetch bhi isi gate se hokar jaana chahiye.
        // BUG FIX PART 2 (2026-09-14): sirf concurrency gate se poora fix nahi
        // hua tha - Freeze module ke asli fix (ensureRevenueFreezeActiveInfo/
        // fetchRevenueFreezeSnapshotRows, ~line 3379/3420) me ek DOOSRA hissa
        // bhi tha jo O&M/VIG me chhoot gaya tha: agar "echo" layer ka 404/HTML
        // error kabhi phir bhi aa jaaye (JSON.parse fail), to sirf EK attempt
        // hone se poora call turant fail ho jaata tha. Fix: yahan bhi wahi 2
        // attempt + 800ms gap wala retry (`withOmvigRetry_`) laga diya - ab
        // ek transient "echo" glitch dusri koshish me aksar chal jaata hai.
        async function withOmvigRetry_(task, attempts = 2) {
            let lastErr = null;
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    return await task();
                } catch (err) {
                    lastErr = err;
                    if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 800));
                }
            }
            throw lastErr;
        }

        // O&M/VIG PUBLIC CACHE (USER REQUEST 2026-09-26): backend ki public copy (bilkul wahi JSON)
        // - freeze status, paid (sabhi), daily report, pending (sabhi). META "OK" na ho => purana raasta.
        const SC_PUB_OMVIG_SHEET_ID = "1bf5lnYkPrScm6NbgXYD9nCmS79iAf1h5J5aoAOncFD0";
        let scPubOmvigMetaP_ = null, scPubOmvigMetaAt_ = 0;
        const scPubOmvigJsonMem_ = {};
        function scPubOmvigMeta_() {
            if (!SC_PUB_OMVIG_SHEET_ID) return Promise.resolve(null);
            if (scPubOmvigMetaP_ && Date.now() - scPubOmvigMetaAt_ < 60000) return scPubOmvigMetaP_;
            scPubOmvigMetaAt_ = Date.now();
            scPubOmvigMetaP_ = (async () => {
                try {
                    const rows = await scPubFetchCsv_(SC_PUB_OMVIG_SHEET_ID, 0, 20000);
                    const m = {};
                    rows.slice(1).forEach((r) => { if (r[0]) m[r[0]] = scPubStrip_(r[1]); });
                    if (m.state !== "OK" || !m.sig) return null;
                    return { sig: m.sig, gids: JSON.parse(m.gids || "{}") };
                } catch (_) { return null; }
            })();
            return scPubOmvigMetaP_;
        }
        async function scPubOmvigJson_(key) {
            try {
                const meta = await scPubOmvigMeta_();
                if (!meta || meta.gids[key] === undefined) return null;
                const memKey = `${meta.sig}|${key}`;
                if (!scPubOmvigJsonMem_[memKey]) {
                    scPubOmvigJsonMem_[memKey] = scPubFetchCsv_(SC_PUB_OMVIG_SHEET_ID, meta.gids[key], 60000).then((rows) => {
                        const parts = rows.slice(1).filter((r) => r[0] !== "" && r[0] !== undefined).map((r) => [Number(r[0]), scPubStrip_(r[1])]);
                        const obj = scPubJoinChunks_(parts);
                        if (!obj || obj.status !== "success") throw new Error("bad");
                        return obj;
                    });
                    scPubOmvigJsonMem_[memKey].catch(() => { delete scPubOmvigJsonMem_[memKey]; });
                }
                return JSON.parse(JSON.stringify(await scPubOmvigJsonMem_[memKey]));
            } catch (_) { return null; }
        }

        async function fetchOmvigFreezeStatus_(forceRefresh = false) {
            if (!forceRefresh && omvigFreezeStatusCache_) return omvigFreezeStatusCache_;
            const data = (await scPubOmvigJson_("FREEZE_STATUS")) || await withOmvigRetry_(() => withAppsScriptConcurrencyGate_(omvigSubmitScriptUrl, () => loadRemoteJson(`${omvigSubmitScriptUrl}?action=getFreezeStatus&t=${Date.now()}`, 45000))); // PUBLIC CACHE 2026-09-26
            if (data?.status === "error") throw new Error(data.message || "O&M/VIG freeze status load fail");
            let freezeDate = data?.freeze_date || "";
            const pendingCount = Number(data?.pending_count) || 0;
            // USER REQUEST (2026-09-14): koi bhi (admin panel ya seedha report)
            // sabse pehle yahi fast check karta hai - agar freeze abhi tak nahi
            // hui, yahin se silently ek hi baar auto-freeze kar dete hain, taaki
            // report kabhi bhi "not frozen" error na de sirf isliye ki admin
            // panel kabhi khola hi nahi gaya.
            if (!freezeDate) {
                freezeDate = await autoFreezeOmvigBaseline_();
                if (freezeDate) { omvigPendingCache_ = {}; omvigReportCache_ = null; }
            }
            // USER REQUEST (2026-09-15): "last upload kab hua" admin panel par
            // dikhana hai - backend isi fast endpoint se de deta hai, extra
            // call nahi lagti.
            const lastUploadAt = data?.last_upload_at || "";
            const lastUploadSummary = data?.last_upload_summary || "";
            omvigFreezeStatusCache_ = { freeze_date: freezeDate, pending_count: pendingCount, last_upload_at: lastUploadAt, last_upload_summary: lastUploadSummary };
            return omvigFreezeStatusCache_;
        }

        // BUG FIX PART 3 (2026-09-14, USER-REPORTED - error persisted even
        // after gate+retry, aur is baar sirf EK tab khula tha, dono retry
        // attempts bhi 404 ho gaye Network tab me): concurrency/retry dono
        // theek jagah lage the, lekin asli wajah kuch aur nikli - unscoped
        // (Division/Circle) `getPendingSummary` ek hi call me ~9500+ rows ka
        // bahut bada JSON response deta hai, aur Apps Script ka "echo"
        // content-delivery layer itne BADE response ko reliably serve hi
        // nahi kar pa raha (bar-bar 404, sirf transient glitch nahi) - isse
        // koi bhi retry help nahi karta, dono attempt bhi fail ho jaate hain.
        // Fix: Freeze module jaisa hi chunking - poora Circle/Division ka
        // data ab EK badi call me nahi, balki har DC ki apni CHHOTI call
        // (jo already DC-level par reliably kaam karti hai) se, max 5 ek
        // saath (parallel), fetch + client-side merge karte hain. Koi bhi
        // ek DC ka response ab kabhi bhi itna bada nahi hoga ki echo layer
        // usse serve na kar paaye.
        async function fetchOmvigPendingSingleDc_(dcName) {
            const key = dcName;
            if (omvigPendingCache_[key]) return omvigPendingCache_[key];
            try { // SPEED 29/09: DC ke liye bhi public PENDING_ALL copy (backend dc-filter jaisa), pehle 14s Apps Script
                const pub = await scPubOmvigJson_("PENDING_ALL");
                if (pub && Array.isArray(pub.data)) {
                    const dcNorm = String(dcName).trim().toUpperCase();
                    const rows = pub.data.filter((row) => String(row[2] || "").trim().toUpperCase() === dcNorm);
                    omvigPendingCache_[key] = { rows: rows.map(normalizeOmvigPendingRow_), freeze_date: pub.freeze_date || "" };
                    return omvigPendingCache_[key];
                }
            } catch (_) {}
            const url = `${omvigSubmitScriptUrl}?action=getPendingSummary&dc=${encodeURIComponent(dcName)}&t=${Date.now()}`;
            const data = await withOmvigRetry_(() => withAppsScriptConcurrencyGate_(omvigSubmitScriptUrl, () => loadRemoteJson(url, 45000)));
            if (data?.status === "error") throw new Error(data.message || `O&M/VIG ${dcName} data load fail`);
            const rows = Array.isArray(data?.data) ? data.data : [];
            const result = { rows: rows.map(normalizeOmvigPendingRow_), freeze_date: data?.freeze_date || "" };
            omvigPendingCache_[key] = result;
            return result;
        }

        function getAllOmvigDcNames_() {
            return Object.keys(divisionConfigs).flatMap((divisionName) => getDivisionDcNames(divisionName));
        }

        // SPEED FIX (2026-09-16): Division/Circle ka purana flow har DC ke liye
        // alag getPendingSummary call karta tha. Backend har call me poori ~9500-row
        // baseline sheet read karke uske baad DC filter karta tha; Circle me iska
        // matlab lagbhag 24 full-sheet scans tha. Naya additive `dc_names` batch
        // mode 6 DC ek call me laata hai, isliye Circle me aam taur par sirf 4
        // full-sheet scans hote hain. Batch fail ho to backward-compatible per-DC
        // fallback chalta hai, taaki frontend/backend deployment mismatch se report
        // na toote.
        async function fetchOmvigPendingBatch_(dcNames) {
            const normalizedDcs = Array.from(new Set((dcNames || []).map((name) => String(name || "").trim()).filter(Boolean)));
            if (!normalizedDcs.length) return { rows: [], freeze_date: "" };

            const allCached = normalizedDcs.every((dcName) => !!omvigPendingCache_[dcName]);
            if (allCached) {
                const cachedRows = [];
                let cachedFreezeDate = "";
                normalizedDcs.forEach((dcName) => {
                    const cached = omvigPendingCache_[dcName];
                    cachedRows.push(...cached.rows);
                    if (!cachedFreezeDate && cached.freeze_date) cachedFreezeDate = cached.freeze_date;
                });
                return { rows: cachedRows, freeze_date: cachedFreezeDate };
            }

            const url = `${omvigSubmitScriptUrl}?action=getPendingSummary&dc_names=${encodeURIComponent(normalizedDcs.join(","))}&t=${Date.now()}`;
            const data = await withOmvigRetry_(() => withAppsScriptConcurrencyGate_(omvigSubmitScriptUrl, () => loadRemoteJson(url, 60000)));
            if (data?.status === "error") throw new Error(data.message || "O&M/VIG batch data load fail");
            if (data?.scope_mode !== "batch") throw new Error("O&M/VIG batch endpoint is not deployed on the backend");
            const freezeDate = data?.freeze_date || "";
            const rows = (Array.isArray(data?.data) ? data.data : []).map(normalizeOmvigPendingRow_);

            const dcMap = {};
            normalizedDcs.forEach((dcName) => { dcMap[normalizeDcName(dcName)] = []; });
            rows.forEach((row) => {
                const key = normalizeDcName(row.dc_name);
                if (dcMap[key]) dcMap[key].push(row);
            });
            normalizedDcs.forEach((dcName) => {
                omvigPendingCache_[dcName] = { rows: dcMap[normalizeDcName(dcName)] || [], freeze_date: freezeDate };
            });
            return { rows, freeze_date: freezeDate };
        }

        async function fetchOmvigPendingForDcs_(dcNames) {
            const BATCH = 6;
            // PUBLIC CACHE 2026-09-26: sabhi DC ki pending list public copy se (backend ke dc-filter jaisa hi)
            try {
                const missing = (dcNames || []).filter((dcName) => !omvigPendingCache_[dcName]);
                if (missing.length) {
                    const pub = await scPubOmvigJson_("PENDING_ALL");
                    if (pub && Array.isArray(pub.data)) {
                        missing.forEach((dcName) => {
                            const dcNorm = String(dcName).trim().toUpperCase();
                            const rows = pub.data.filter((row) => String(row[2] || "").trim().toUpperCase() === dcNorm);
                            omvigPendingCache_[dcName] = { rows: rows.map(normalizeOmvigPendingRow_), freeze_date: pub.freeze_date || "" };
                        });
                    }
                }
            } catch (_) {}
            let freezeDateOut = "";
            const allRows = [];
            const failedDcs = [];
            const fetchOneDc = async (dcName) => {
                try {
                    const r = await fetchOmvigPendingSingleDc_(dcName);
                    allRows.push(...r.rows);
                    if (!freezeDateOut && r.freeze_date) freezeDateOut = r.freeze_date;
                } catch (e) {
                    failedDcs.push(dcName);
                }
            };
            for (let i = 0; i < dcNames.length; i += BATCH) {
                const batch = dcNames.slice(i, i + BATCH);
                try {
                    const result = await fetchOmvigPendingBatch_(batch);
                    allRows.push(...result.rows);
                    if (!freezeDateOut && result.freeze_date) freezeDateOut = result.freeze_date;
                } catch (_) {
                    await Promise.all(batch.map(fetchOneDc));
                }
            }
            if (failedDcs.length) {
                const retryList = failedDcs.slice();
                failedDcs.length = 0;
                await Promise.all(retryList.map(fetchOneDc));
            }
            if (failedDcs.length) {
                throw new Error(`O&M/VIG data could not be loaded - DC(s): ${failedDcs.join(", ")}`);
            }
            return { rows: allRows, freeze_date: freezeDateOut };
        }

        // Purane call-sites (agar kahin bhi ho) ke liye backward-compatible -
        // `dc` diya ho to single-DC, na diya ho to POORI Circle (sabhi DC
        // chunked) - lekin `loadOmvigReportData_` ab Division ke liye seedhe
        // `fetchOmvigPendingForDcs_(getDivisionDcNames(activeDiv))` use karta
        // hai (poori Circle fetch karke baad me filter karne se behtar - kam
        // DC = kam calls = fast).
        async function fetchOmvigPending_(dc) {
            if (dc) return fetchOmvigPendingSingleDc_(dc);
            return fetchOmvigPendingForDcs_(getAllOmvigDcNames_());
        }

        async function fetchOmvigPaid_(dc) {
            const key = dc || "ALL";
            if (omvigPaidCache_[key]) return omvigPaidCache_[key];
            const url = `${omvigSubmitScriptUrl}?action=getPaidSummary${dc ? `&dc=${encodeURIComponent(dc)}` : ""}&t=${Date.now()}`;
            const data = (!dc ? await scPubOmvigJson_("PAID_ALL") : null) || await withOmvigRetry_(() => withAppsScriptConcurrencyGate_(omvigSubmitScriptUrl, () => loadRemoteJson(url, dc ? 45000 : 90000))); // PUBLIC CACHE 2026-09-26
            if (data?.status === "error") throw new Error(data.message || "O&M/VIG paid data load fail");
            const rows = Array.isArray(data?.data) ? data.data : [];
            const result = rows.map(normalizeOmvigPaidRow_);
            omvigPaidCache_[key] = result;
            return result;
        }

        function groupOmvigPaidByPanchanama_(paidRows) {
            const map = {};
            paidRows.forEach((p) => {
                if (!p.panchanama_no) return;
                if (!map[p.panchanama_no]) map[p.panchanama_no] = [];
                map[p.panchanama_no].push(p);
            });
            return map;
        }

        // USER REQUEST (2026-09-14): sirf woh payments ginte hain jinki Pay_date
        // FREEZE DATE ke BAAD ki hai (isse purani, freeze se pehle ki koi bhi
        // payment count nahi hoti) - aur dikhaya gaya paid amount hamesha is
        // case ke Balanced Amount tak hi seemित (capped) rehta hai, jaisa
        // Freeze NP ke us bug-fix me tha (kabhi bhi consumer ki poori history
        // ka number nahi dikhna chahiye).
        // BUG FIX (2026-09-15, USER-REPORTED): "freeze DATE ke baad (>)" ka
        // matlab STRICTLY agle din se maana gaya tha - lekin freeze aur pehli
        // Paid List upload aksar EK HI din ho sakte hain (subah freeze, sham
        // tak usi din ki payments upload) - us case me payDateKey aur
        // freezeDate dono barabar the, "> " kabhi true nahi hota tha, isliye
        // Monthly report SAB DC me 0 paid dikha raha tha chahe payments
        // genuinely valid hon. Fix: "`>`" ko "`>=`" kar diya - freeze wale din
        // ki bhi payments ab count hoti hain (sirf freeze se PEHLE ki purani
        // payments hi exclude hoti hain, jo hi asli intent tha).
        // ===== OM DATE FIX (2026-09-29, USER-REPORTED) =====
        // Paid list me Pay_date do format me aata hai: "yyyy-mm-dd" (Sheet ki
        // Date cell) aur "dd-mm-yyyy hh:mm" (app upload ka text). Pehle seedha
        // string compare hota tha (freeze "2026-09-14" se) - "27-09-2026" <
        // "2026-..." hone se kai sahi payments gin hi nahi rahi thi. Ab dono ko
        // pehle "yyyy-mm-dd" me badal kar compare karte hain.
        function scOmIsoDate_(v) {
            const s = String(v == null ? "" : v).trim();
            let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
            if (m) return `${m[1]}-${m[2].padStart(2, "0")}-${m[3].padStart(2, "0")}`;
            m = s.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/);
            if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
            return "";
        }
        function scOmDmy_(iso) {
            return iso ? `${iso.slice(8, 10)}-${iso.slice(5, 7)}-${iso.slice(0, 4)}` : "";
        }
        // ===== END OM DATE FIX =====
        // ===== OM NEW CASES (2026-09-29, USER REQUEST) =====
        // Paid list me jo panchnama FREEZE LIST me nahi hain (backend UNMATCHED
        // tab -> getDailyReport ka `new_cases`), unki vasooli freeze ki ginti me
        // shamil NAHI hoti - sirf ALAG line me dikhti hai (screen + download +
        // Daily Brief). Paid list me DC nahi hota, isliye sirf Circle/Division.
        // "Naye" = panchnama no. ki tarikh freeze date ya uske baad; baaki
        // (purane, freeze list me na mile) alag chhoti line me.
        function scOmPnDate_(pn) {
            const m = String(pn || "").trim().match(/^[A-Za-z]+\d{0,2}?(20\d{2})(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])/);
            return m ? `${m[1]}-${m[2]}-${m[3]}` : "";
        }
        function scOmNewDivKey_(v) {
            const k = String(v || "").toUpperCase().replace(/^DIVISION\s+/, "").replace(/[^A-Z]/g, "");
            return k.startsWith("LAKHNAD") ? "LAKHNADON" : k;
        }
        // "" = poora Circle, "SEONI"/"LAKHNADON" = sirf woh Division, null = mat dikhao (DC scope)
        function scOmNewCasesScopeDiv_() {
            if (activeViewLevel === "DC" || omvigFilterDc) return null;
            if (activeViewLevel === "DIVISION") return scOmNewDivKey_(activeDiv);
            return omvigFilterDivision ? scOmNewDivKey_(omvigFilterDivision) : "";
        }
        function scOmNewCasesSummary_(newCases, freezeIso, fromIso, toIso, divKey) {
            const out = { newCnt: 0, newAmt: 0, oldCnt: 0, oldAmt: 0, byDiv: {} };
            if (divKey === null) return out;
            (Array.isArray(newCases) ? newCases : []).forEach((c) => {
                const dk = scOmNewDivKey_(c && c.division);
                if (divKey && dk !== divKey) return;
                let amt = 0;
                (Array.isArray(c.payments) ? c.payments : []).forEach((pm) => {
                    const d = scOmIsoDate_(pm && pm[0]);
                    if (d && (!fromIso || d >= fromIso) && (!toIso || d <= toIso)) amt += Number(pm[1]) || 0;
                });
                if (!(amt > 0)) return;
                const pd = scOmPnDate_(c.panchanama_no);
                if (pd && (!freezeIso || pd >= freezeIso)) {
                    out.newCnt += 1; out.newAmt += amt;
                    const b = out.byDiv[dk] || (out.byDiv[dk] = { cnt: 0, amt: 0 });
                    b.cnt += 1; b.amt += amt;
                } else { out.oldCnt += 1; out.oldAmt += amt; }
            });
            return out;
        }
        function scOmRs_(a) { return `₹${Math.round(Number(a) || 0).toLocaleString("en-IN")}`; }
        function scOmNewCasesHtml_(sm, title) {
            if (!sm || (!sm.newCnt && !sm.oldCnt)) return "";
            // USER (29/09 11:39): chhoti line (upar) - poori summary/list "NEW CASES" dropdown me
            return `<div style="margin:6px auto 0; max-width:440px; padding:6px 9px; background:#fff7ed; border:1px dashed #fb923c; border-radius:10px; text-align:center; font-size:0.64rem; font-weight:900; color:#9a3412;">🆕 ${escapeHtml(title)}: ${sm.newCnt} cases · ₹ ${scBriefLakh_(sm.newAmt)}${sm.oldCnt ? ` <span style="font-weight:700; color:#78716c;">(+ old ${sm.oldCnt} · ₹ ${scBriefLakh_(sm.oldAmt)})</span>` : ""}<div style="font-size:0.56rem; font-weight:700; color:#b45309;">Not included in Freeze count · select "NEW CASES" in the dropdown above for summary/list/download</div></div>`;
        }
        function scOmNewCasesHtmlOld_(sm, title) {
            if (!sm || (!sm.newCnt && !sm.oldCnt)) return "";
            const divs = Object.keys(sm.byDiv).sort();
            const divLine = divs.length > 1 ? `<div style="margin-top:3px; font-size:0.6rem; font-weight:800; color:#9a3412;">${divs.map((k) => `${escapeHtml(k)}: ${sm.byDiv[k].cnt} cases · ${scOmRs_(sm.byDiv[k].amt)}`).join(" &nbsp;|&nbsp; ")}</div>` : "";
            const oldLine = sm.oldCnt ? `<div style="margin-top:3px; font-size:0.58rem; font-weight:700; color:#78716c;">Old cases not found in Freeze list: ${sm.oldCnt} cases · ${scOmRs_(sm.oldAmt)}</div>` : "";
            return `<div style="margin-top:10px; padding:8px 10px; background:#fff7ed; border:1px dashed #fb923c; border-radius:10px; text-align:center;">
                <div style="font-size:0.68rem; font-weight:900; color:#9a3412;">🆕 ${escapeHtml(title)}: ${sm.newCnt} cases · ${scOmRs_(sm.newAmt)}</div>
                <div style="font-size:0.56rem; font-weight:700; color:#b45309;">(Not included in Freeze count - found in paid list, not in freeze list)</div>${divLine}${oldLine}</div>`;
        }
        // Download (Excel rows / PDF table) ke liye rows - [label, cases, amount]
        function scOmNewCasesDlRows_(sm) {
            if (!sm || (!sm.newCnt && !sm.oldCnt)) return [];
            const rows = [];
            const divs = Object.keys(sm.byDiv).sort();
            if (divs.length > 1) divs.forEach((k) => rows.push([`New cases - ${k}`, sm.byDiv[k].cnt, Math.round(sm.byDiv[k].amt)]));
            rows.push(["New cases (after freeze) - TOTAL", sm.newCnt, Math.round(sm.newAmt)]);
            if (sm.oldCnt) rows.push(["Old cases not found in Freeze list", sm.oldCnt, Math.round(sm.oldAmt)]);
            return rows;
        }
        // ----- NEW CASE COLUMN (USER 29/09 12:32) -----
        // Summary table me PENDING ke baad "NEW CASE" (COUNT / AMT LAKH) column;
        // PAID ka naam "(FREEZE)". NEW CASE = paid list ke woh case jo freeze
        // list me nahi (naye + purane dono). Paid list me DC nahi hota -> DC row
        // me "-", sirf Division TOTAL / GRAND TOTAL row me figure. List download
        // me paid ke saath "NEW CASE" rows (poori row alag rang).
        let scOmNewCtx_ = null; // { newCases, freezeIso, from, to } | null
        function scOmNewCtxMake_(newCases, freezeIso, fromIso, toIso) {
            if (!Array.isArray(newCases) || omvigFilterStatus === "PENDING" || scOmSlabOn_() || scOmNewCasesScopeDiv_() === null) return null;
            return { newCases, freezeIso: freezeIso || "", from: fromIso || "", to: toIso || "" };
        }
        function scOmNewOn_() { return !!scOmNewCtx_ && scOmNewCasesScopeDiv_() !== null && omvigFilterStatus !== "PENDING" && !scOmSlabOn_(); }
        function scOmSlabOn_() { return !!omvigFilterSlab; } // slab me NEW CASE (freeze amount nahi) shamil nahi
        function scOmNewFor_(divKey) {
            const c = scOmNewCtx_;
            const sm = scOmNewCasesSummary_(c.newCases, c.freezeIso, c.from, c.to, divKey);
            return { newCnt: sm.newCnt + sm.oldCnt, newAmt: sm.newAmt + sm.oldAmt };
        }
        function scOmAttachNewCases_(rows) {
            if (!scOmNewOn_()) return rows;
            const scopeDiv = scOmNewCasesScopeDiv_();
            return rows.map((r) => {
                if (r.type === "SUB_TOTAL") return { ...r, ...scOmNewFor_(scOmNewDivKey_(String(r.name || "").replace(/\s+DIVISION\s+TOTAL$/i, ""))) };
                if (r.type === "GRAND_TOTAL") return { ...r, ...scOmNewFor_(scopeDiv) };
                return { ...r, newCnt: null, newAmt: null };
            });
        }
        function scOmSummaryTableHtml_(nameColLabel, rows, titleText, paidColLabel, pendingColLabel) {
            const on = scOmNewOn_();
            const html = renderFreezeGroupSummaryTableHtml(nameColLabel, on ? scOmAttachNewCases_(rows) : rows, titleText, paidColLabel, pendingColLabel, on);
            return on ? html + `<div style="font-size:0.56rem; font-weight:700; color:#9a3412; text-align:center; margin-top:4px;">NEW CASE = a case found in the paid list that is not in the freeze list (separate from the freeze count). The paid list has no DC, so the figure is shown only in the Division/Total row.</div>` : html;
        }
        function scOmSumHead_(on) {
            const pl = omvigReportMode === "DAILY" ? "YESTERDAY PAID (FREEZE)" : "PAID (FREEZE)";
            return ["DC NAME", "TOTAL", `${pl} COUNT`, `${pl} AMT`, "PENDING COUNT", "PENDING AMT", "PAID %", "PENDING %"].concat(on ? ["NEW CASE COUNT", "NEW CASE AMT"] : []);
        }
        function scOmSumRow_(r, on) {
            return [r.name, r.totalCount, r.paidCount, r.paidAmount, r.pendingCount, r.pendingAmount, `${r.paidPercent}%`, `${r.pendingPercent}%`]
                .concat(on ? [r.newCnt == null ? "-" : r.newCnt, r.newAmt == null ? "-" : Math.round(r.newAmt)] : []);
        }
        // ----- NEW CASES dropdown view (USER 29/09 11:39) -----
        // Upar dropdown: FREEZE CASES (purana report, koi badlav nahi) / NEW CASES
        // (paid list me mile par freeze list me nahi). NEW me Division-wise
        // summary (amount LAKH me) + list (amount Rs me) + apne Excel/PDF.
        // Sirf Circle/Division level (paid list me DC nahi hota).
        let omvigCaseType = "FREEZE"; // "FREEZE" | "NEW"
        function scOmIsNewCaseView_() { return omvigCaseType === "NEW" && activeViewLevel !== "DC"; }
        function scOmCaseTypeSelectHtml_() {
            if (activeViewLevel === "DC") return "";
            const opt = (v, l) => `<option value="${v}" ${omvigCaseType === v ? "selected" : ""}>${l}</option>`;
            return `<select id="omvig-case-type-select" onchange="setOmvigCaseType(this.value)" style="width:100%; max-width:360px; height:38px; margin:0 auto 6px; display:block; border:2px solid #ea580c; border-radius:10px; padding:0 10px; font-size:0.74rem; font-weight:900; color:#9a3412; background:#fff7ed;">${opt("FREEZE", "📌 FREEZE CASES (freeze list)")}${opt("NEW", "🆕 NEW CASES (not in freeze list)")}</select>`;
        }
        function setOmvigCaseType(v) {
            omvigCaseType = v === "NEW" ? "NEW" : "FREEZE";
            omvigFilterDc = ""; omvigFilterStatus = "";
            loadAndRenderOmvigReport(false);
        }
        function scOmNewCasesListRows_(newCases, freezeIso, fromIso, toIso, divKey) {
            const out = [];
            if (divKey === null) return out;
            (Array.isArray(newCases) ? newCases : []).forEach((c) => {
                const dk = scOmNewDivKey_(c && c.division);
                if (divKey && dk !== divKey) return;
                let amt = 0, n = 0, last = "";
                (Array.isArray(c.payments) ? c.payments : []).forEach((pm) => {
                    const d = scOmIsoDate_(pm && pm[0]);
                    if (d && (!fromIso || d >= fromIso) && (!toIso || d <= toIso)) { amt += Number(pm[1]) || 0; n += 1; if (d > last) last = d; }
                });
                if (!(amt > 0)) return;
                const pd = scOmPnDate_(c.panchanama_no);
                const isNew = !!pd && (!freezeIso || pd >= freezeIso);
                out.push({ pn: String(c.panchanama_no || ""), div: dk, type: isNew ? "NAYA" : "PURANA", last, lastDmy: scOmDmy_(last), n, amt });
            });
            out.sort((a, b) => (a.type === b.type ? 0 : (a.type === "NAYA" ? -1 : 1)) || a.div.localeCompare(b.div) || b.last.localeCompare(a.last) || a.pn.localeCompare(b.pn));
            return out;
        }
        // Division-wise summary rows (scope ke hisab se) + TOTAL
        function scOmNewCasesSumRows_(list, divKey) {
            const keys = divKey ? [divKey] : Object.keys(divisionConfigs).map((n) => scOmNewDivKey_(n));
            list.forEach((r) => { if (!keys.includes(r.div)) keys.push(r.div); });
            const mk = (name) => ({ name, nCnt: 0, nAmt: 0, oCnt: 0, oAmt: 0 });
            const map = {}; keys.forEach((k) => { map[k] = mk(`${k} DIVISION`); });
            const tot = mk("TOTAL");
            list.forEach((r) => {
                const g = map[r.div];
                if (r.type === "NAYA") { g.nCnt += 1; g.nAmt += r.amt; tot.nCnt += 1; tot.nAmt += r.amt; }
                else { g.oCnt += 1; g.oAmt += r.amt; tot.oCnt += 1; tot.oAmt += r.amt; }
            });
            const rows = keys.map((k) => map[k]);
            if (rows.length > 1) rows.push({ ...tot, type: "TOTAL" });
            return rows;
        }
        function scOmL_(a) { return ((Number(a) || 0) / 100000).toFixed(2); }
        async function scOmNewCasesData_(forceRefresh) {
            const nd = await fetchOmvigDailyReport_(forceRefresh);
            let fz = nd.freezeIso || "";
            if (!fz) { try { fz = scOmIsoDate_((await fetchOmvigFreezeStatus_(false)).freeze_date); } catch (_) {} }
            const isDaily = omvigReportMode === "DAILY";
            const yd = scOmIsoDate_(nd.date);
            const from = isDaily ? yd : fz, to = isDaily ? yd : getTodayIsoDate();
            const divKey = scOmNewCasesScopeDiv_();
            const list = scOmNewCasesListRows_(nd.newCases, fz, from, to, divKey);
            const period = isDaily ? `Payment of yesterday (${nd.date || "-"})` : `Payment from Freeze (${scOmDmy_(fz)}) till today`;
            return { nd, fz, isDaily, list, sumRows: scOmNewCasesSumRows_(list, divKey), period, hasField: Array.isArray(nd.newCases) };
        }
        function scOmNewCasesViewHtml_(v) {
            const divFilterHtml = activeViewLevel === "CIRCLE"
                ? omvigFilterSelectHtml_("omvig-circle-division-select", "-- Select Division --", Object.keys(divisionConfigs).map((n) => ({ value: n, label: n.replace(/^DIVISION\s+/i, "") })), omvigFilterDivision)
                : "";
            const head = `<div style="text-align:center; font-size:0.66rem; font-weight:800; color:#475569; margin-top:4px;">${escapeHtml(v.period)}${v.nd.noYesterday ? `<br><span style="color:#b45309;">Paid List with yesterday's payments is not uploaded yet</span>` : ""}</div>
                <div style="text-align:center; font-size:0.58rem; font-weight:700; color:#b45309; margin-top:2px;">These cases are NOT included in the FREEZE count. NEW = panchnama created after freeze; OLD = created before freeze but not found in the freeze list.</div>`;
            const gc = "grid-template-columns: 1.4fr 0.8fr 0.9fr 0.8fr 0.9fr;";
            const sumHtml = `<div class="summary-wrapper" style="margin-top:8px;"><div class="summary-table-header" style="${gc}"><div>DIVISION</div><div>NEW CASES</div><div>AMT (LAKH)</div><div>OLD</div><div>AMT (LAKH)</div></div>${v.sumRows.map((r) => `<div class="summary-table-row" style="${gc}${r.type === "TOTAL" ? " background:#fff7ed; font-weight:900; color:#9a3412;" : ""}"><div style="text-align:left;">${escapeHtml(r.name)}</div><div class="font-black">${r.nCnt}</div><div class="font-black">${scOmL_(r.nAmt)}</div><div>${r.oCnt}</div><div>${scOmL_(r.oAmt)}</div></div>`).join("")}</div>`;
            const lim = scListLimit_(Infinity);
            const gl = "grid-template-columns: 2fr 1fr 1fr;";
            const listHtml = v.list.length
                ? `<div class="summary-wrapper" style="margin-top:10px;"><div class="summary-table-header" style="${gl}"><div>PANCHANAMA NO</div><div>PAY DATE</div><div>AMOUNT</div></div>${v.list.slice(0, lim).map((r) => `<div class="summary-table-row" style="${gl} text-align:left;"><div>${escapeHtml(r.pn)}<br><span style="font-size:0.58rem; color:${r.type === "NAYA" ? "#c2410c" : "#78716c"}; font-weight:800;">${r.type === "NAYA" ? "NEW" : "OLD"} · ${escapeHtml(r.div)}${r.n > 1 ? ` · ${r.n} payments` : ""}</span></div><div>${escapeHtml(r.lastDmy)}</div><div class="font-black">${formatProgressReportAmount(r.amt)}</div></div>`).join("")}${v.list.length > lim ? scListMoreNoteHtml_(v.list.length, lim) : ""}</div>`
                : `<div style="text-align:center; color:#64748b; font-size:0.7rem; padding:14px 0;">${v.hasField ? "No new case payment found in this period." : "New cases data is not available yet (O&M backend update + publishOmvigPublicCacheNow required)."}</div>`;
            const btns = `<div class="omvig-dl-btns" style="display:flex; gap:8px; margin-top:12px; flex-wrap:wrap;">
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#16a34a; color:#fff;" onclick="downloadOmvigNewCases('XLS')">⬇️ Excel</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#0891b2; color:#fff;" onclick="downloadOmvigNewCases('PDF_SUMMARY')">📊 Summary PDF</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#dc2626; color:#fff;" onclick="downloadOmvigNewCases('PDF_LIST')">📋 List PDF</button>
                   </div>`;
            return head + divFilterHtml + sumHtml + listHtml + btns + SC_OMVIG_DL_STATUS_HTML_;
        }
        async function scOmvigNewCasesDownloadCore_(fmt) {
            try {
                const v = await scOmNewCasesData_(false);
                let scope = activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE";
                if (activeViewLevel === "CIRCLE" && omvigFilterDivision) scope += ` - ${omvigFilterDivision.replace(/^DIVISION\s+/i, "")}`;
                const reportTitle = `O&M-VIG NEW CASES ${v.isDaily ? "Daily" : "Report"} - ${scope}`;
                const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");
                const note = "Not included in Freeze count. NEW = panchnama created after freeze; OLD = created before freeze but not in the freeze list.";
                const sumHead = ["DIVISION", "NEW CASES", "NEW AMT (LAKH)", "OLD CASES", "OLD AMT (LAKH)"];
                const sumBody = v.sumRows.map((r) => [r.name, r.nCnt, scOmL_(r.nAmt), r.oCnt, scOmL_(r.oAmt)]);
                const listHead = ["S.NO", "DIVISION", "PANCHANAMA NO", "TYPE", "LAST PAY DATE", "PAYMENTS", "AMOUNT (Rs)"];
                const listBody = v.list.slice().sort((x, y) => (Number(y.amt) || 0) - (Number(x.amt) || 0)).map((r, i) => [i + 1, r.div, r.pn, r.type, r.lastDmy, r.n, Math.round(r.amt * 100) / 100]);
                if (fmt === "XLS") {
                    const csvSafe = (value) => { const text = String(value ?? "").replace(/\r\n|\r|\n/g, " "); return /[",]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                    const rows = [[reportTitle], [v.period], [note], [], sumHead, ...sumBody, [], listHead, ...listBody];
                    const csv = rows.map((row) => row.map(csvSafe).join(",")).join("\n");
                    await saveShmsBlob(`${fileName}.csv`, new Blob([csv], { type: "text/csv;charset=utf-8" }), "text/csv;charset=utf-8");
                    return showToast("Excel report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
                }
                if (!window.jspdf?.jsPDF) return showToast("PDF library could not be loaded", false);
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF("l", "mm", "a4");
                const hy = scPdfHeader_(doc, { title: fmt === "PDF_LIST" ? `${reportTitle} - Full List` : reportTitle, lines: [v.period, note], color: SC_PDF_THEME.omvig });
                const startY = (Number(hy) || 28) + 2;
                if (fmt !== "PDF_LIST") {
                    doc.autoTable({ startY, head: [sumHead], body: sumBody, theme: "grid", headStyles: { fillColor: [194, 65, 12], halign: "center" }, styles: { fontSize: 8, cellPadding: 1.6, halign: "center" }, columnStyles: { 0: { halign: "left", fontStyle: "bold" } },
                        didParseCell: (h) => { if (h.section === "body" && v.sumRows[h.row.index] && v.sumRows[h.row.index].type === "TOTAL") { h.cell.styles.fontStyle = "bold"; h.cell.styles.fillColor = [255, 237, 213]; } } });
                } else {
                    doc.autoTable({ startY, head: [listHead], body: listBody.length ? listBody : [listHead.map(() => "")], theme: "grid", headStyles: { fillColor: [17, 24, 39], halign: "center" }, styles: { fontSize: 7.5, cellPadding: 1.4, halign: "center" }, columnStyles: { 2: { halign: "left" }, 6: { halign: "right" } } });
                }
                scPdfFinalize_(doc); const pdfBlob = doc.output("blob");
                await saveShmsBlob(`${fileName}.pdf`, pdfBlob, "application/pdf");
                showToast("PDF report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
            } catch (error) {
                showToast(error?.message || "O&M/VIG New Cases download failed", false);
            }
        }
        function downloadOmvigNewCases(fmt) {
            return scRunStandardDownload_("omvig", () => document.getElementById("omvig-download-status"),
                () => Array.from(document.querySelectorAll(".omvig-dl-btns button")), fmt, scOmvigNewCasesDownloadCore_);
        }
        // ===== END OM NEW CASES =====
        function computeOmvigReportRows_(pendingRows, paidByPanchanama, freezeDate) {
            const freezeIso = scOmIsoDate_(freezeDate);
            return pendingRows.map((r) => {
                const paidList = paidByPanchanama[r.panchanama_no] || [];
                let paidAmountNow = 0, paidDateNow = "", paidIsoNow = "";
                paidList.forEach((p) => {
                    const payDateKey = scOmIsoDate_(p.pay_date);
                    if (freezeIso && payDateKey && payDateKey >= freezeIso) {
                        paidAmountNow += p.amount;
                        if (!paidIsoNow || payDateKey > paidIsoNow) { paidIsoNow = payDateKey; paidDateNow = scOmDmy_(payDateKey); }
                    }
                });
                const balancedAmount = r.balanced_amount;
                const remainingPending = Math.max(0, balancedAmount - paidAmountNow);
                const isPaidNow = paidAmountNow > 0 && remainingPending <= 0;
                return {
                    ...r,
                    pending_amount: balancedAmount, // buildFreezeDcWiseSummaryRows ke saath field-name reuse ke liye
                    paidAmountNow,
                    remainingPending,
                    isPaidNow,
                    paidDateNow
                };
            });
        }

        async function loadOmvigReportData_(forceRefresh = false) {
            const scopeKey = `${activeViewLevel}:${activeViewLevel === "DC" ? activeDC : (activeViewLevel === "DIVISION" ? activeDiv : "CIRCLE")}`;
            if (!forceRefresh && omvigReportCache_ && omvigReportCache_.scopeKey === scopeKey) return omvigReportCache_;

            // Pehle fast freeze-status check - agar freeze hua hi nahi hai to
            // poori (potentially ~9500 row, slow) pending/paid list fetch karne
            // ki zaroorat nahi, seedha empty result de dete hain.
            const freezeStatus = await fetchOmvigFreezeStatus_(forceRefresh);
            if (!freezeStatus.freeze_date) {
                omvigReportCache_ = { scopeKey, rowsWithStatus: [], freeze_date: "" };
                return omvigReportCache_;
            }
            const lastUploadAt = freezeStatus.last_upload_at || "";
            const lastUploadSummary = freezeStatus.last_upload_summary || "";

            const dcParam = activeViewLevel === "DC" ? activeDC : "";
            // BUG FIX (2026-09-14): pehle Division level bhi POORI Circle
            // (sabhi 24 DC) fetch karke baad me client-side filter karta tha -
            // ab seedha sirf USI Division ki DC list chunked-fetch hoti hai
            // (kam call = kam data = fast, aur echo-404 ka risk bhi kam).
            let pending;
            if (activeViewLevel === "DC") {
                pending = await fetchOmvigPendingSingleDc_(activeDC);
            } else if (activeViewLevel === "DIVISION") {
                pending = await fetchOmvigPendingForDcs_(getDivisionDcNames(activeDiv));
            } else {
                pending = await fetchOmvigPendingForDcs_(getAllOmvigDcNames_());
            }
            const paid = await fetchOmvigPaid_(dcParam);

            const pendingRows = pending.rows;
            const paidMap = groupOmvigPaidByPanchanama_(paid);
            const rowsWithStatus = computeOmvigReportRows_(pendingRows, paidMap, pending.freeze_date);

            omvigReportCache_ = { scopeKey, rowsWithStatus, freeze_date: pending.freeze_date, lastUploadAt, lastUploadSummary };
            return omvigReportCache_;
        }

        function renderOmvigDcListHtml_(rowsWithStatus) {
            if (!rowsWithStatus.length) return `<div style="text-align:center; color:#9f1239; font-size:0.72rem; margin-top:10px;">No O&M/VIG case found for this DC.</div>`;
            const totalCount = rowsWithStatus.length;
            const paidCount = rowsWithStatus.filter((r) => r.isPaidNow).length;
            const partPaidCount = rowsWithStatus.filter((r) => !r.isPaidNow && r.paidAmountNow > 0).length;
            const pendingCount = totalCount - paidCount;
            const scLimO_ = scListLimit_(Infinity); // STATUS PACK 3a: screen par pehle 50, poori list download me
            const rowsHtml = rowsWithStatus.slice(0, scLimO_).map((r) => {
                const statusLabel = r.isPaidNow ? `PAID${r.paidDateNow ? ` (${r.paidDateNow})` : ""}` : (r.paidAmountNow > 0 ? `PENDING - PART PAID${r.paidDateNow ? ` (${r.paidDateNow})` : ""}` : "PENDING");
                const statusColor = r.isPaidNow ? "#166534" : (r.paidAmountNow > 0 ? "#dc2626" : "#1e293b");
                return `<div class="summary-table-row" style="grid-template-columns: 2fr 1.3fr 1fr; text-align:left;">
                    <div>${escapeHtml(r.consumer_name)}<br><span style="font-size:0.58rem; color:#64748b;">${escapeHtml(r.panchanama_no)} | ${escapeHtml(r.case_name)}</span></div>
                    <div style="font-weight:900; color:${statusColor};">${statusLabel}</div>
                    <div class="font-black">${formatProgressReportAmount(r.isPaidNow ? r.balanced_amount : r.remainingPending)}</div>
                </div>`;
            }).join("");
            return `
                <div style="text-align:center; font-size:0.7rem; font-weight:900; color:#0f172a; margin-top:6px;">Total: ${totalCount} | Paid: ${paidCount} | Part Paid: ${partPaidCount} | Pending: ${pendingCount}</div>
                <div class="summary-wrapper" style="margin-top:6px;"><div class="summary-table-header" style="grid-template-columns: 2fr 1.3fr 1fr;"><div>CASE</div><div>STATUS</div><div>AMOUNT</div></div>${rowsHtml}${rowsWithStatus.length > scLimO_ ? scListMoreNoteHtml_(rowsWithStatus.length, scLimO_) : ""}</div>`;
        }

        // USER REQUEST (2026-10-02): PART PAID case Pending hi rahega.
        // Sirf poori balanced amount cover hone par case Paid hoga; part payment
        // ki bachi hui rashi Pending amount me shamil rahegi.
        function filterOmvigRowsByStatus_(rows, status) {
            if (status === "PAID") return rows.filter((r) => r.isPaidNow);
            if (status === "PENDING") return rows.filter((r) => !r.isPaidNow);
            return rows;
        }

        // DC/Division/Circle summaries me bhi wahi rule: fully settled = Paid,
        // aur Part Paid = Pending (remaining balance ke saath).
        function omvigIsInPaidBucket_(r) {
            return !!r.isPaidNow;
        }
        function omvigPaidBucketAmount_(r) {
            return Number(r.pending_amount || 0);
        }

        // DC level ke liye ek hi row ka summary (Freeze NP ke DC-wise summary
        // jaisa hi shape/table, bas is scope me hamesha ek hi row hogi).
        function buildOmvigSingleDcSummaryRow_(rowsWithStatus, dcName) {
            const g = { name: dcName || "-", totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 };
            rowsWithStatus.forEach((r) => {
                g.totalCount += 1;
                if (omvigIsInPaidBucket_(r)) { g.paidCount += 1; g.paidAmount += omvigPaidBucketAmount_(r); }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });
            return g;
        }

        // USER REQUEST (2026-09-14): Paid/Unpaid dropdown chunne par SUMMARY
        // row bhi usi status tak simat jaani chahiye (jaise poori app me
        // filter lagate hi screen filter hoti hai) - total/dusra column ab
        // 0 rahega, sirf jo status choose kiya wahi count/amount dikhega,
        // niche ki list se exactly match karega.
        function buildOmvigStatusSummaryRow_(filteredRows, dcName, status) {
            const g = { name: dcName || "-", totalCount: filteredRows.length, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 };
            filteredRows.forEach((r) => {
                if (status === "PAID") { g.paidCount += 1; g.paidAmount += Number(r.isPaidNow ? r.pending_amount : r.paidAmountNow) || 0; }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });
            return g;
        }

        // USER REQUEST (2026-09-14): Circle level par sirf Division chuni ho
        // (DC abhi nahi) to summary bhi sirf USI Division ki DC-wise table
        // dikhaye, sabhi 24 DC ki nahi - Division-level jaisa hi DC-list
        // (bina sub-total/grand-total ke).
        function buildOmvigDivisionDcSummaryRows_(rowsWithStatus, divisionName) {
            const emptyGroup = (key) => ({ name: key, totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 });
            const map = {};
            rowsWithStatus.forEach((r) => {
                const key = normalizeDcName(r.dc_name) || "-";
                if (!map[key]) map[key] = emptyGroup(key);
                const g = map[key];
                g.totalCount += 1;
                if (omvigIsInPaidBucket_(r)) { g.paidCount += 1; g.paidAmount += omvigPaidBucketAmount_(r); }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });
            return getDivisionDcNames(divisionName).map((dcName) => map[normalizeDcName(dcName)] || emptyGroup(normalizeDcName(dcName)));
        }

        // USER REQUEST (2026-09-16): Circle level par jab KOI Division filter
        // nahi laga hota, poori Circle ki DC-wise summary (har Division ka
        // SUB_TOTAL + aakhir me GRAND_TOTAL) pehle SHARED `buildFreezeDcWiseSummaryRows`
        // (Freeze Tracking Report ke saath common) se aati thi - us function ko
        // O&M/VIG ke naye "PART PAID bhi PAID bucket me" rule ke liye nahi
        // chheda (Freeze Report ka apna alag business meaning hai, scope
        // discipline). Yeh O&M/VIG-only copy hai, bilkul wahi DC-wise+SUB_TOTAL+
        // GRAND_TOTAL shape, bas naye omvigIsInPaidBucket_/omvigPaidBucketAmount_
        // rule ke saath - is function ka call sirf CIRCLE, no-division-filter
        // scope se hota hai (renderOmvigCircleLevelHtml_ + getOmvigDownloadSummaryRows_),
        // isliye DIVISION-level branch ki zaroorat nahi.
        function buildOmvigCircleDcWiseSummaryRows_(rowsWithStatus) {
            const emptyGroup = (key) => ({ name: key, totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 });
            const withPercents = (g) => ({
                ...g,
                paidPercent: g.totalCount ? ((g.paidCount / g.totalCount) * 100).toFixed(1) : "0.0",
                pendingPercent: g.totalCount ? ((g.pendingCount / g.totalCount) * 100).toFixed(1) : "0.0"
            });
            const map = {};
            (rowsWithStatus || []).forEach((r) => {
                const key = normalizeDcName(r.dc_name) || "-";
                if (!map[key]) map[key] = emptyGroup(key);
                const g = map[key];
                g.totalCount += 1;
                if (omvigIsInPaidBucket_(r)) { g.paidCount += 1; g.paidAmount += omvigPaidBucketAmount_(r); }
                else { g.pendingCount += 1; g.pendingAmount += Number(r.remainingPending || 0); }
            });

            const rows = [];
            const grand = emptyGroup("GRAND TOTAL");
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const dcRows = getDivisionDcNames(divisionName).map((dcName) => {
                    const key = normalizeDcName(dcName);
                    return withPercents(map[key] || emptyGroup(key));
                });
                rows.push(...dcRows);
                const divTotal = emptyGroup(getDivisionTotalLabel(divisionName));
                dcRows.forEach((r) => {
                    divTotal.totalCount += r.totalCount; divTotal.paidCount += r.paidCount; divTotal.paidAmount += r.paidAmount;
                    divTotal.pendingCount += r.pendingCount; divTotal.pendingAmount += r.pendingAmount;
                });
                rows.push({ ...withPercents(divTotal), type: "SUB_TOTAL" });
                grand.totalCount += divTotal.totalCount; grand.paidCount += divTotal.paidCount; grand.paidAmount += divTotal.paidAmount;
                grand.pendingCount += divTotal.pendingCount; grand.pendingAmount += divTotal.pendingAmount;
            });
            rows.push({ ...withPercents(grand), type: "GRAND_TOTAL" });
            return rows;
        }

        // USER REQUEST (2026-09-16, USER-REPORTED via screenshot): Circle (Division
        // filter laga hua) aur Division-level summary table me neeche ek TOTAL row
        // missing thi - sirf per-DC rows dikhte the. Dono jagah buildOmvigDivisionDcSummaryRows_
        // (O&M/VIG-only helper, Freeze Report ke saath SHARED nahi) use hoti hai -
        // isliye total sirf yahin jodte hain, Freeze Report ki shared
        // buildFreezeDcWiseSummaryRows/renderFreezeDcWiseSummaryHtml ko bilkul nahi
        // chhedte (wahan already Circle-wide view me SUB_TOTAL+GRAND_TOTAL sahi
        // dikh rahe hain, unse koi lena-dena nahi). Daily aur Monthly dono ek hi
        // renderOmvigDivisionLevelHtml_/renderOmvigCircleLevelHtml_ reuse karte
        // hain, isliye yeh fix dono me apne aap aa jaata hai.
        function appendOmvigTotalRow_(rows) {
            const total = { name: "TOTAL", totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0, type: "GRAND_TOTAL" };
            rows.forEach((r) => {
                total.totalCount += r.totalCount; total.paidCount += r.paidCount; total.paidAmount += r.paidAmount;
                total.pendingCount += r.pendingCount; total.pendingAmount += r.pendingAmount;
            });
            total.paidPercent = total.totalCount ? ((total.paidCount / total.totalCount) * 100).toFixed(1) : "0.0";
            total.pendingPercent = total.totalCount ? ((total.pendingCount / total.totalCount) * 100).toFixed(1) : "0.0";
            return rows.concat([total]);
        }

        function omvigFilterSelectHtml_(id, placeholder, options, selectedValue) {
            const optionsHtml = options.map((opt) => `<option value="${escapeHtml(opt.value)}" ${selectedValue === opt.value ? "selected" : ""}>${escapeHtml(opt.label)}</option>`).join("");
            return `<select id="${id}" onchange="onOmvigFilterChange()" style="width:100%; max-width:360px; height:38px; margin:6px auto 0; display:block; border:1.5px solid #94a3b8; border-radius:10px; padding:0 10px; font-size:0.74rem; font-weight:900; color:#0f172a; background:#ffffff;">
                <option value="">${escapeHtml(placeholder)}</option>
                ${optionsHtml}
            </select>`;
        }

        // 2026-10-17: Freeze Amount slab dropdown - baaki filters ke saath NEECHE (Paid/Unpaid ke baad)
        function omvigSlabSelectHtml_() { return omvigFilterSelectHtml_("omvig-slab-select", "-- Select Freeze Amount Slab --", OMVIG_SLAB_OPTIONS_, omvigFilterSlab); }
        const OMVIG_STATUS_OPTIONS_ = [{ value: "PAID", label: "PAID (incl. Part Paid)" }, { value: "PENDING", label: "PENDING" }];
        // USER REQUEST (2026-10-14): Freeze amount (BALANCED AMOUNT at freeze) slab dropdown - teeno level.
        // Lower limit shamil, upper limit shamil nahi (25000 -> 25000-50000 slab me). Paid/part-paid cases bhi
        // apne freeze amount ke slab me dikhte hain.
        const OMVIG_SLAB_OPTIONS_ = [
            { value: "S1", label: "Freeze Amt: 0 - 25,000", lo: 0, hi: 25000 },
            { value: "S2", label: "Freeze Amt: 25,000 - 50,000", lo: 25000, hi: 50000 },
            { value: "S3", label: "Freeze Amt: 50,000 - 1 Lakh", lo: 50000, hi: 100000 },
            { value: "S4", label: "Freeze Amt: 1 Lakh - 2 Lakh", lo: 100000, hi: 200000 },
            { value: "S5", label: "Freeze Amt: Above 2 Lakh", lo: 200000, hi: Infinity }
        ];
        function omvigApplySlab_(rows) {
            const sl = OMVIG_SLAB_OPTIONS_.find((o) => o.value === omvigFilterSlab);
            if (!sl) return rows;
            return rows.filter((r) => { const a = Number(r.freeze_amount != null ? r.freeze_amount : r.balanced_amount) || 0; return a >= sl.lo && a < sl.hi; });
        }

        // USER REQUEST (2026-09-16): Daily mode ke summary table me "PAID"
        // column "YESTERDAY PAID" dikhna chahiye (Monthly me "PAID" hi rehta
        // hai) - taaki 0 PENDING wale Daily view ko log global "aaj pending
        // zero hai" na samjh baithein, balki samjhein ki yeh sirf us din ke
        // jama (settlement) hain.
        function omvigPaidColLabel_() {
            return omvigReportMode === "DAILY" ? "YESTERDAY PAID (FREEZE)" : "PAID (FREEZE)";
        }

        // USER REQUEST (2026-09-14 + fix): DC level par ab poori list seedhe
        // nahi dikhti - sirf is DC ka ek-row SUMMARY. Paid/Unpaid dropdown
        // chunte hi SUMMARY bhi usi status tak simat jaati hai (poori app ke
        // pattern jaisa - filter lagte hi screen filter ho jaani chahiye) aur
        // niche filtered list bhi dikhti hai (DC level par yeh dropdown hi
        // list dikhane ke liye hai, isliye yahan list intentionally rehti hai
        // - sirf Circle/Division level par list on-screen nahi aani chahiye,
        // per user's latest request).
        function renderOmvigDcLevelHtml_(rowsWithStatus) {
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-dc-status-select", "-- Select Paid/Unpaid to View List --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            let summaryHtml, listHtml = "";
            if (omvigFilterStatus) {
                const filteredRows = filterOmvigRowsByStatus_(rowsWithStatus, omvigFilterStatus);
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, activeDC, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
                listHtml = renderOmvigDcListHtml_(filteredRows);
            } else {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigSingleDcSummaryRow_(rowsWithStatus, activeDC)], "DC SUMMARY (AMOUNT IN LAKH)", omvigPaidColLabel_(), "PENDING");
            }
            return summaryHtml + statusSelectHtml + listHtml;
        }

        // USER REQUEST (2026-09-14 + fix): Division level - DC dropdown
        // chunne se pehle poori Division ki DC-wise summary. DC chunte hi
        // summary bhi sirf USI DC tak simat jaati hai; Paid/Unpaid chunte hi
        // summary aur bhi aage usi status tak simat jaati hai - har filter
        // step par screen filter hoti hai. USER REQUEST (2026-09-14, follow-up):
        // Division level par status select karne par case-LIST on-screen
        // NAHI khulni chahiye - sirf summary hi filtered dikhe (list sirf
        // download me milegi).
        // USER REQUEST (2026-09-22): Paid/Unpaid dropdown ab DC select kiye
        // BINA bhi kaam karta hai - pehle yeh sirf DC chunne ke BAAD hi
        // dikhta tha, isliye poori Division ki DC-wise summary sirf Paid ya
        // sirf Pending tak filter nahi ho paati thi (DC chunna zaroori tha,
        // jo galat tha - Division/Circle-wide filter chahiye tha). Ab Division
        // dropdown aur Paid/Unpaid dropdown DO ALAG, INDEPENDENT filters hain -
        // DC chuno ya na chuno, Paid/Unpaid hamesha available hai aur jo bhi
        // current scope hai (poori Division ya ek DC) usi par lagta hai.
        function renderOmvigDivisionLevelHtml_(rowsWithStatus) {
            const dcOptions = getDivisionDcNames(activeDiv).map((n) => ({ value: n, label: n }));
            const dcSelectHtml = omvigFilterSelectHtml_("omvig-division-dc-select", "-- Select DC --", dcOptions, omvigFilterDc);
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-division-status-select", "-- Select Paid/Unpaid --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            const filteredRowsWithStatus = omvigFilterStatus ? filterOmvigRowsByStatus_(rowsWithStatus, omvigFilterStatus) : rowsWithStatus;
            const titleSuffix = omvigFilterStatus ? ` - ${omvigFilterStatus}` : "";
            let summaryHtml;
            if (!omvigFilterDc) {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", appendOmvigTotalRow_(buildOmvigDivisionDcSummaryRows_(filteredRowsWithStatus, activeDiv)), `DC WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
            } else if (!omvigFilterStatus) {
                const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigSingleDcSummaryRow_(dcRows, omvigFilterDc)], "DC SUMMARY (AMOUNT IN LAKH)", omvigPaidColLabel_(), "PENDING");
            } else {
                const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                const filteredRows = filterOmvigRowsByStatus_(dcRows, omvigFilterStatus);
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, omvigFilterDc, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
            }
            return summaryHtml + dcSelectHtml + statusSelectHtml;
        }

        // USER REQUEST (2026-09-14 + fix): Circle level - Division dropdown
        // chunne se pehle poori Circle ki DC-wise summary (sabhi division).
        // Division chunte hi summary sirf USI Division ki DC-wise table tak
        // simat jaati hai (sabhi 24 DC nahi); DC chunte hi single-DC row tak;
        // status chunte hi usi status tak - har step par screen filter hoti
        // hai. USER REQUEST (2026-09-14, follow-up): Circle level par bhi
        // status select karne par case-LIST on-screen NAHI khulni chahiye -
        // sirf summary hi filtered dikhe (list sirf download me milegi).
        // USER REQUEST (2026-09-22): pehle Paid/Unpaid dropdown sirf tab dikhta
        // tha jab Division + DC dono chun liye ho - isliye poori Circle ya
        // poori Division ki DC-wise summary kabhi sirf Paid ya sirf Pending
        // tak filter nahi ho paati thi (DC select karna zaroori tha). Ab
        // Division/DC dropdown aur Paid/Unpaid dropdown DO ALAG, INDEPENDENT
        // filters hain - Paid/Unpaid hamesha available hai (Circle-wide,
        // Division-wide ya single-DC - jo bhi abhi scope hai, usi par lagta
        // hai), DC chunna zaroori nahi.
        function renderOmvigCircleLevelHtml_(rowsWithStatus) {
            const divOptions = Object.keys(divisionConfigs).map((n) => ({ value: n, label: n.replace(/^DIVISION\s+/i, "") }));
            const divSelectHtml = omvigFilterSelectHtml_("omvig-circle-division-select", "-- Select Division --", divOptions, omvigFilterDivision);
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-circle-status-select", "-- Select Paid/Unpaid --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            const filteredRowsWithStatus = omvigFilterStatus ? filterOmvigRowsByStatus_(rowsWithStatus, omvigFilterStatus) : rowsWithStatus;
            const titleSuffix = omvigFilterStatus ? ` - ${omvigFilterStatus}` : "";
            let summaryHtml, dcSelectHtml = "";
            if (!omvigFilterDivision) {
                // USER REQUEST (2026-09-16): pehle yahan SHARED renderFreezeDcWiseSummaryHtml
                // (Freeze Tracking Report ke saath common) use hota tha - naye
                // "PART PAID bhi PAID bucket me" rule + Daily "YESTERDAY PAID"
                // label ke liye ab O&M/VIG-only buildOmvigCircleDcWiseSummaryRows_
                // (bilkul wahi DC-wise+SUB_TOTAL+GRAND_TOTAL shape) use karte hain,
                // Freeze Report ka shared function bilkul nahi chheda.
                summaryHtml = scOmSummaryTableHtml_("DC NAME", buildOmvigCircleDcWiseSummaryRows_(filteredRowsWithStatus), `DC WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
            } else {
                const dcOptions = getDivisionDcNames(omvigFilterDivision).map((n) => ({ value: n, label: n }));
                dcSelectHtml = omvigFilterSelectHtml_("omvig-circle-dc-select", "-- Select DC --", dcOptions, omvigFilterDc);
                if (!omvigFilterDc) {
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", appendOmvigTotalRow_(buildOmvigDivisionDcSummaryRows_(filteredRowsWithStatus, omvigFilterDivision)), `DC-WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
                } else if (!omvigFilterStatus) {
                    const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigSingleDcSummaryRow_(dcRows, omvigFilterDc)], "DC SUMMARY (AMOUNT IN LAKH)", omvigPaidColLabel_(), "PENDING");
                } else {
                    const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                    const filteredRows = filterOmvigRowsByStatus_(dcRows, omvigFilterStatus);
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, omvigFilterDc, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, omvigPaidColLabel_(), "PENDING");
                }
            }
            return summaryHtml + divSelectHtml + dcSelectHtml + statusSelectHtml;
        }

        // Dropdown badalte hi sirf state update karke poora report block dobara
        // render karte hain - data pehle se hi cache me hai (omvigReportCache_),
        // isliye yeh turant hota hai, koi naya network call nahi.
        function onOmvigFilterChange() {
            // USER REQUEST (2026-09-22): Paid/Unpaid status filter ab Division/DC
            // scope-selection se SAPERATE (independent) hai - Division ya DC badalne
            // par status filter reset NAHI hota (pehle hota tha), taaki Circle/Division
            // ki poori DC-wise summary bhi sirf Paid ya sirf Unpaid ki nikali ja sake
            // bina kisi ek DC par drill-down kiye. Status dropdown ab hamesha DOM me
            // maujood rahta hai (Circle/Division/DC teeno level par), isliye seedhe
            // uska current value padh lete hain - "kaunsa dropdown badla" guess karne
            // ki zaroorat nahi.
            omvigFilterSlab = document.getElementById("omvig-slab-select")?.value || "";
            if (activeViewLevel === "CIRCLE") {
                const newDiv = document.getElementById("omvig-circle-division-select")?.value || "";
                if (newDiv !== omvigFilterDivision) {
                    omvigFilterDivision = newDiv;
                    omvigFilterDc = ""; // scope narrowed/widened -> DC selection reset
                } else {
                    omvigFilterDc = document.getElementById("omvig-circle-dc-select")?.value || "";
                }
                omvigFilterStatus = document.getElementById("omvig-circle-status-select")?.value || "";
            } else if (activeViewLevel === "DIVISION") {
                omvigFilterDc = document.getElementById("omvig-division-dc-select")?.value || "";
                omvigFilterStatus = document.getElementById("omvig-division-status-select")?.value || "";
            } else if (activeViewLevel === "DC") {
                omvigFilterStatus = document.getElementById("omvig-dc-status-select")?.value || "";
            }
            loadAndRenderOmvigReport(false);
        }

        function renderOmvigReportHtml_(data, newCasesHtml = "") {
            // USER REQUEST (2026-09-22): Daily jaisa hi - Monthly (Full) me bhi
            // "Latest Paid Upload" (asli upload date+time, Indian format) dikhega
            // agar upload record maujood ho, warna sirf Freeze Date dikhega
            // (pehle jaisa).
            const lastUploadLine = data.lastUploadAt
                ? `<div style="text-align:center; font-size:0.66rem; font-weight:800; color:#475569; margin-top:2px;">🕒 Latest Paid Upload: ${escapeHtml(formatIndianDateTimeDisplay_(data.lastUploadAt))}${data.lastUploadSummary ? `<br><span style="font-weight:700; color:#64748b;">${escapeHtml(data.lastUploadSummary)}</span>` : ""}</div>`
                : "";
            const freezeLine = `<div style="text-align:center; font-size:0.66rem; font-weight:800; color:#475569; margin-top:4px;">Freeze Date: ${escapeHtml(data.freeze_date)}</div>${lastUploadLine}`;
            let bodyHtml;
            const slabRows = omvigApplySlab_(data.rowsWithStatus);
            if (activeViewLevel === "DC") {
                bodyHtml = renderOmvigDcLevelHtml_(slabRows);
            } else if (activeViewLevel === "DIVISION") {
                bodyHtml = renderOmvigDivisionLevelHtml_(slabRows);
            } else {
                bodyHtml = renderOmvigCircleLevelHtml_(slabRows);
            }
            
            // USER REQUEST (2026-09-14): DC level par pehle jaisa hi ek Excel +
            // ek PDF (poori DC ki list). Division/Circle par ab Excel (summary+
            // list combined, pehle jaisa) ke saath PDF 2 ALAG button me baant
            // diya - "Summary PDF" (sirf totals+DC-wise table) aur "List PDF"
            // (sirf poori raw list) - taaki sirf summary chahiye ho to poori
            // list wali badi PDF na download karni pade.
            // USER REQUEST (2026-10-14): DC level par bhi Division/Circle jaisa same flow (Excel + Summary PDF + List PDF).
            const downloadButtons = `<div class="omvig-dl-btns"                 style="display:flex; gap:8px; margin-top:12px; flex-wrap:wrap;">
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#16a34a; color:#fff;" onclick="downloadOmvigReport('XLS')">⬇️ Excel</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#0891b2; color:#fff;" onclick="downloadOmvigReport('PDF_SUMMARY')">📊 Summary PDF</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#dc2626; color:#fff;" onclick="downloadOmvigReport('PDF_LIST')">📋 List PDF</button>
                   </div>`;
            return freezeLine + (newCasesHtml || "") + bodyHtml + downloadButtons + SC_OMVIG_DL_STATUS_HTML_;
        }

        // USER REQUEST (2026-09-14): "Daily/Monthly" toggle - Revenue jaisa hi,
        // top par hamesha dikhta hai (loading/error/success sabhi state me) taaki
        // user kabhi bhi switch kar sake.
        function renderOmvigModeToggleHtml_() {
            const dailyActive = omvigReportMode === "DAILY";
            const btnStyle = (active) => `flex:1; height:38px; border-radius:10px; border:2px solid #0d9488; font-size:0.72rem; font-weight:900; ${active ? "background:#0d9488; color:#fff;" : "background:#fff; color:#0d9488;"}`;
            return `<div style="display:flex; gap:8px; margin-bottom:10px;">
                <button type="button" onclick="setOmvigReportMode('DAILY')" style="${btnStyle(dailyActive)}">⚡ DAILY (Fast)</button>
                <button type="button" onclick="setOmvigReportMode('MONTHLY')" style="${btnStyle(!dailyActive)}">MONTHLY (Full)</button>
            </div>`;
        }

        function setOmvigReportMode(mode) {
            if (omvigReportMode === mode) return;
            omvigReportMode = mode;
            loadAndRenderOmvigReport(false);
        }

        async function loadAndRenderOmvigReport(forceRefresh = false) {
            const body = document.getElementById("summary-content");
            if (!body) return;
            const myToken = ++omvigProgressToken;
            const toggleHtml = renderOmvigModeToggleHtml_(); // 29/09 12:32: NEW CASE ab summary column me (dropdown nahi)
            omvigCaseType = "FREEZE";
            if (scOmIsNewCaseView_()) { // OM NEW CASES dropdown view (chhota data, snapshot nahi)
                const progress = renderSyncingProgress(body, () => myToken === omvigProgressToken, "SYNCING DATA... PLEASE WAIT");
                try {
                    const v = await scOmNewCasesData_(forceRefresh);
                    if (myToken !== omvigProgressToken) { progress.stop(); return; }
                    const html = toggleHtml + scOmNewCasesViewHtml_(v);
                    await progress.finish();
                    if (myToken !== omvigProgressToken) return;
                    body.innerHTML = html;
                } catch (error) {
                    progress.stop();
                    if (myToken !== omvigProgressToken) return;
                    body.innerHTML = toggleHtml + `<div style="text-align:center; color:#991b1b; font-size:0.72rem; margin-top:10px;">New cases data could not be loaded</div><button class="btn-unique" style="width:100%; margin-top:8px; background:#0891b2; color:#fff;" onclick="loadAndRenderOmvigReport(true)">Try Again</button>`;
                }
                return;
            }
            if (omvigReportMode === "DAILY") {
                const scOmKey = activeViewLevel !== "DC" ? scSnapshotKey_("OMVIG-DAILY") : ""; // SPEED PHASE 1
                const scOmHost = scOmKey ? await scShowSnapshot_(body, scOmKey) : null;
                if (myToken !== omvigProgressToken) return;
                const progress = renderSyncingProgress(scOmHost || body, () => myToken === omvigProgressToken, "SYNCING DATA... PLEASE WAIT");
                try {
                    const data = await loadOmvigDailyReportData_(forceRefresh);
                    if (myToken !== omvigProgressToken) { progress.stop(); return; }
                    const omYd = scOmIsoDate_(data.date);
                    scOmNewCtx_ = scOmNewCtxMake_(data.newCases, data.freezeIso, omYd, omYd);
                    const html = toggleHtml + renderOmvigDailyReportHtml_(data);
                    await progress.finish();
                    if (myToken !== omvigProgressToken) return;
                    body.innerHTML = html;
                    if (scOmKey) scSaveSnapshot_(scOmKey, html);
                } catch (error) {
                    progress.stop();
                    if (myToken !== omvigProgressToken) return;
                    body.innerHTML = toggleHtml + `<div style="text-align:center; color:#991b1b; font-size:0.72rem; margin-top:10px;">Daily data could not be loaded</div><button class="btn-unique" style="width:100%; margin-top:8px; background:#0891b2; color:#fff;" onclick="loadAndRenderOmvigReport(true)">Try Again</button>`;
                }
                return;
            }
            // MONTHLY (purana/existing poora PAID/PENDING/PART-PAID view, koi badlav nahi)
            // USER REQUEST (2026-09-14): pehle yahan hamesha "Division/Circle me..."
            // dono likha rehta tha (chahe user Circle dekh raha ho ya Division) -
            // confusing tha. Ab jis level ki report abhi khul rahi hai SIRF uska
            // hi naam dikhta hai, aur wait-note (English) ab ek alag niche wali
            // row me hai (renderSyncingProgress ka naya subLabel param), "SYNCING
            // DATA... PLEASE WAIT" wali upar wali line ab hamesha clean rehti hai.
            const levelLabel = activeViewLevel === "DIVISION" ? "Division" : (activeViewLevel === "CIRCLE" ? "Circle" : "DC");
            const subLabel = activeViewLevel === "DC" ? "" : `(${levelLabel} level may take 1-2 minutes)`;
            const scOmMKey = activeViewLevel !== "DC" ? scSnapshotKey_("OMVIG-MONTHLY") : ""; // SPEED PHASE 1
            const scOmMHost = scOmMKey ? await scShowSnapshot_(body, scOmMKey) : null;
            if (myToken !== omvigProgressToken) return;
            const progress = renderSyncingProgress(scOmMHost || body, () => myToken === omvigProgressToken, "SYNCING DATA... PLEASE WAIT", subLabel);
            try {
                const pOmNew = scOmNewCasesScopeDiv_() === null ? null : fetchOmvigDailyReport_(forceRefresh).catch(() => null); // OM NEW CASES
                const data = await loadOmvigReportData_(forceRefresh);
                if (myToken !== omvigProgressToken) { progress.stop(); return; }
                const omNewD = pOmNew ? await pOmNew : null;
                if (myToken !== omvigProgressToken) { progress.stop(); return; }
                const omFzIso = scOmIsoDate_(data.freeze_date);
                scOmNewCtx_ = omNewD ? scOmNewCtxMake_(omNewD.newCases, omFzIso, omFzIso, getTodayIsoDate()) : null;
                const omNewHtml = "";
                if (!data.freeze_date) {
                    progress.stop();
                    if (myToken !== omvigProgressToken) return;
                    body.innerHTML = toggleHtml + `<div style="text-align:center; color:#9f1239; font-size:0.72rem; margin-top:10px;">O&M/VIG is not frozen yet. Please set the Freeze Date from the Admin panel of Sub DN Chhapara under "🔒 ADMIN O&M/VIG UPLOAD".</div>`;
                    return;
                }
                const html = toggleHtml + renderOmvigReportHtml_(data, omNewHtml);
                await progress.finish();
                if (myToken !== omvigProgressToken) return;
                body.innerHTML = html;
                if (scOmMKey) scSaveSnapshot_(scOmMKey, html);
            } catch (error) {
                progress.stop();
                if (myToken !== omvigProgressToken) return;
                body.innerHTML = toggleHtml + `<div style="text-align:center; color:#991b1b; font-size:0.72rem; margin-top:10px;">O&M/VIG data could not be loaded (network may be slow, especially for Division/Circle)</div><button class="btn-unique" style="width:100%; margin-top:8px; background:#0891b2; color:#fff;" onclick="loadAndRenderOmvigReport(true)">Try Again</button>`;
            }
        }

        // SPEED FIX (2026-09-15, USER-REPORTED slowness): pehle yahan
        // `fetchOmvigLatestDayPaidRows_()` (chhoti, fast) ke baad har active DC
        // ke liye ALAG `fetchOmvigPendingForDcs_()` call hoti thi taaki consumer
        // naam/DC enrichment ho sake - lekin server par `getPendingSummary`
        // `dc` diye jaane par bhi POORI ~9500-row baseline sheet padhta tha
        // (filter sirf JS me values-read ke BAAD lagta hai), isliye Circle-level
        // Daily me 20-24 active DC hone par baseline 20-24 baar poori read hoti
        // thi (2-concurrent gate ke through queue), 1-2+ minute lag jaate the.
        // FIX: ab ek dedicated `getDailyReport` backend endpoint hai jo paid-
        // sheets + pending-baseline dono SIRF EK-EK BAAR padhta hai aur
        // enrichment (consumer naam, DC) server par hi kar deta hai - client ko
        // sirf ek hi chhoti call lagti hai, active-DC-count se ab call-count ka
        // koi lena-dena nahi, isliye Circle/Division Daily bhi ab seconds me
        // load hona chahiye.
        async function fetchOmvigDailyReport_(forceRefresh = false) {
            if (forceRefresh) omvigDailyReportCache_ = null;
            if (omvigDailyReportCache_) return omvigDailyReportCache_;
            const url = `${omvigSubmitScriptUrl}?action=getDailyReport&t=${Date.now()}`;
            const data = (await scPubOmvigJson_("DAILY")) || await withOmvigRetry_(() => withAppsScriptConcurrencyGate_(omvigSubmitScriptUrl, () => loadRemoteJson(url, 45000))); // PUBLIC CACHE 2026-09-26
            if (data?.status === "error") throw new Error(data.message || "O&M/VIG daily report load fail");
            const rows = Array.isArray(data?.rows) ? data.rows.map((r) => ({
                dc_name: String(r.dc_name || "").trim(),
                consumer_name: String(r.consumer_name || "").trim(),
                panchanama_no: String(r.panchanama_no || "").trim(),
                amount: Number(r.amount) || 0,
                pay_mode: String(r.pay_mode || "").trim(),
                freeze_amount: (r.freeze_amount === undefined || r.freeze_amount === "" || r.freeze_amount === null) ? null : (Number(r.freeze_amount) || 0) // 2026-10-17 slab
            })) : [];
            // USER REQUEST (2026-09-16, round 2): "TOTAL CONSUMER" aur "PENDING"
            // Daily me bhi Monthly jaisa hi SAHI/TRUE dikhna chahiye (poore
            // baseline ka), sirf "PAID" column hi latest-date ("yesterday") tak
            // simat rahe. Backend (`getDailyReport`) ab ek chhota per-DC
            // `dc_summary` (~24 row) bhejta hai jisme yeh already compute hoke
            // aata hai (baseline poori padhi to jaati hai backend par, par
            // client ko sirf summary milta hai - poora ~9500-row baseline nahi,
            // isliye Daily FAST hi rehta hai). Purane backend (jab tak .gs
            // redeploy na ho) me yeh field hoga hi nahi - `dcSummaryMap` khaali
            // rahega, sabhi DC ka TOTAL/PENDING 0 dikhega (crash nahi hoga).
            const dcSummaryList = Array.isArray(data?.dc_summary) ? data.dc_summary : [];
            const dcSummaryMap = {};
            dcSummaryList.forEach((s) => {
                const key = normalizeDcName(s?.dc_name);
                if (!key) return;
                dcSummaryMap[key] = {
                    totalCount: Number(s.totalCount) || 0,
                    pendingCount: Number(s.pendingCount) || 0,
                    pendingAmount: Number(s.pendingAmount) || 0,
                    yesterdayPaidCount: Number(s.yesterdayPaidCount) || 0,
                    yesterdayPaidAmount: Number(s.yesterdayPaidAmount) || 0,
                    slabs: (s.slabs && typeof s.slabs === "object") ? s.slabs : null // 2026-10-17: Freeze-Amount slab-wise figures (backend)
                };
            });
            // USER REQUEST (2026-09-29): Daily me sirf KAL (yesterday) ki pay-date
            // wali payment dikhe. Aaj ki paid list upload nahi hui (latest
            // pay-date kal ki nahi hai) to PAID 0 - TOTAL/PENDING waise hi.
            const latestIso = scOmIsoDate_(data?.date_iso || data?.date);
            const yd = new Date(); yd.setDate(yd.getDate() - 1);
            const yIso = `${yd.getFullYear()}-${String(yd.getMonth() + 1).padStart(2, "0")}-${String(yd.getDate()).padStart(2, "0")}`;
            const noYesterday = !!latestIso && latestIso !== yIso;
            if (noYesterday) {
                rows.length = 0;
                Object.keys(dcSummaryMap).forEach((k) => { dcSummaryMap[k].yesterdayPaidCount = 0; dcSummaryMap[k].yesterdayPaidAmount = 0; });
            }
            omvigDailyReportCache_ = { date: latestIso ? scOmDmy_(noYesterday ? yIso : latestIso) : "", rows, dcSummaryMap, noYesterday, latestPayDate: scOmDmy_(latestIso), newCases: Array.isArray(data?.new_cases) ? data.new_cases : [], freezeIso: scOmIsoDate_(data?.freeze_date) };
            return omvigDailyReportCache_;
        }

        // Daily ke per-DC TRUE summary group - `dcSummaryMap` (backend se) se
        // TOTAL CONSUMER/PENDING leta hai, "PAID" sirf yesterday ka
        // count/amount (Monthly ke buildOmvigSingleDcSummaryRow_/
        // buildOmvigDivisionDcSummaryRows_ jaisa SHAPE hi return karta hai,
        // taaki renderFreezeGroupSummaryTableHtml/appendOmvigTotalRow_ dono
        // bina badlaav reuse ho sakein).
        function scOmDailySlabReady_(dcSummaryMap) {
            return Object.keys(dcSummaryMap || {}).some((k) => dcSummaryMap[k] && dcSummaryMap[k].slabs);
        }
        function omvigDailyDcSummaryGroup_(dcSummaryMap, dcName) {
            let s = dcSummaryMap[normalizeDcName(dcName)];
            // 2026-10-17: Freeze-Amount slab chuna ho to backend ke slab-wise figures (slabs na mile to unfiltered hi)
            if (omvigFilterSlab && s && s.slabs) s = s.slabs[omvigFilterSlab] || { totalCount: 0, pendingCount: 0, pendingAmount: 0, yesterdayPaidCount: 0, yesterdayPaidAmount: 0 };
            return {
                name: dcName || "-",
                totalCount: s ? s.totalCount : 0,
                paidCount: s ? s.yesterdayPaidCount : 0,
                paidAmount: s ? s.yesterdayPaidAmount : 0,
                pendingCount: s ? s.pendingCount : 0,
                pendingAmount: s ? s.pendingAmount : 0
            };
        }

        // USER REQUEST (2026-09-22): Daily (Fast) me row-level "pending" data
        // client ke paas hoti hi nahi (sirf yesterday ki paid entries row-level
        // aati hain, speed ke liye poora baseline nahi bhejte) - lekin per-DC
        // TRUE paidCount/pendingCount dcSummaryMap me already sahi maujood hai.
        // Isliye Paid/Unpaid filter yahan row-filter se nahi, seedha
        // dcSummaryMap ke sahi figures dikha/chhupa ke lagta hai - Monthly
        // (buildOmvigStatusSummaryRow_) jaisa hi: TOTAL = filtered bucket ka
        // count, doosra bucket 0.
        function omvigDailyDcSummaryGroupFiltered_(dcSummaryMap, dcName, status) {
            const base = omvigDailyDcSummaryGroup_(dcSummaryMap, dcName);
            if (!status) return base;
            if (status === "PAID") return { ...base, totalCount: base.paidCount, pendingCount: 0, pendingAmount: 0 };
            return { ...base, totalCount: base.pendingCount, paidCount: 0, paidAmount: 0 };
        }

        function omvigDailyDivisionDcSummaryRows_(dcSummaryMap, divisionName, status) {
            return getDivisionDcNames(divisionName).map((dcName) => omvigDailyDcSummaryGroupFiltered_(dcSummaryMap, dcName, status));
        }

        // Circle-wide (bina Division filter) DC-wise + per-Division SUB_TOTAL +
        // GRAND_TOTAL - buildOmvigCircleDcWiseSummaryRows_ jaisa hi shape, bas
        // source dcSummaryMap hai (case-level rowsWithStatus nahi).
        function omvigDailyCircleDcWiseSummaryRows_(dcSummaryMap, status) {
            const emptyGroup = (key) => ({ name: key, totalCount: 0, paidCount: 0, paidAmount: 0, pendingCount: 0, pendingAmount: 0 });
            const withPercents = (g) => ({
                ...g,
                paidPercent: g.totalCount ? ((g.paidCount / g.totalCount) * 100).toFixed(1) : "0.0",
                pendingPercent: g.totalCount ? ((g.pendingCount / g.totalCount) * 100).toFixed(1) : "0.0"
            });
            const rows = [];
            const grand = emptyGroup("GRAND TOTAL");
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const dcRows = getDivisionDcNames(divisionName).map((dcName) => withPercents(omvigDailyDcSummaryGroupFiltered_(dcSummaryMap, dcName, status)));
                rows.push(...dcRows);
                const divTotal = emptyGroup(getDivisionTotalLabel(divisionName));
                dcRows.forEach((r) => {
                    divTotal.totalCount += r.totalCount; divTotal.paidCount += r.paidCount; divTotal.paidAmount += r.paidAmount;
                    divTotal.pendingCount += r.pendingCount; divTotal.pendingAmount += r.pendingAmount;
                });
                rows.push({ ...withPercents(divTotal), type: "SUB_TOTAL" });
                grand.totalCount += divTotal.totalCount; grand.paidCount += divTotal.paidCount; grand.paidAmount += divTotal.paidAmount;
                grand.pendingCount += divTotal.pendingCount; grand.pendingAmount += divTotal.pendingAmount;
            });
            rows.push({ ...withPercents(grand), type: "GRAND_TOTAL" });
            return rows;
        }

        function scopeOmvigDailyRowsToView_(rows) {
            if (activeViewLevel === "DC" && activeDC) {
                const dcNorm = normalizeDcName(activeDC);
                return rows.filter((r) => normalizeDcName(r.dc_name) === dcNorm);
            }
            if (activeViewLevel === "DIVISION" && activeDiv) {
                const dcSet = new Set(getDivisionDcNames(activeDiv).map((n) => normalizeDcName(n)));
                return rows.filter((r) => dcSet.has(normalizeDcName(r.dc_name)));
            }
            return rows;
        }

        // USER REQUEST (2026-09-16): Daily ko bhi Monthly jaisa hi summary+dropdown
        // UX chahiye - Circle/Division level par seedhi list nahi, DC-wise summary
        // table (Division dropdown se drill-down), DC level par single-DC summary +
        // Paid/Unpaid dropdown (list sirf tabhi). USER REQUEST (2026-09-16, round
        // 2): DC-WISE SUMMARY table ke TOTAL CONSUMER/PENDING ab `dcSummaryMap`
        // (backend se, TRUE poore baseline ka) se aate hain - naye
        // omvigDailyDcSummaryGroup_/omvigDailyDivisionDcSummaryRows_/
        // omvigDailyCircleDcWiseSummaryRows_ (upar dekhein) use hote hain, Monthly
        // wale shared builders (buildOmvigSingleDcSummaryRow_ etc., jo case-level
        // rowsWithStatus se kaam karte hain) Daily ke SUMMARY table ke liye ab
        // nahi. Yeh mapOmvigDailyRowsWithStatus_ ab bhi zaroori hai - DC-level ka
        // Paid/Unpaid dropdown chunne par "list" (kis consumer ne kal kitna paya)
        // isi flat shape se banti hai, wahan koi badlav nahi.
        function mapOmvigDailyRowsWithStatus_(rows, date) {
            return rows.map((r) => ({
                dc_name: r.dc_name,
                consumer_name: r.consumer_name,
                panchanama_no: r.panchanama_no,
                case_name: "", // Daily ke getDailyReport data me case_name available nahi hai
                pay_mode: r.pay_mode,
                pending_amount: r.amount,
                remainingPending: 0,
                paidAmountNow: r.amount,
                balanced_amount: r.amount,
                isPaidNow: true,
                paidDateNow: date,
                freeze_amount: r.freeze_amount
            }));
        }

        async function loadOmvigDailyReportData_(forceRefresh = false) {
            // enrichment (consumer naam, DC fallback) ab backend (`getDailyReport`)
            // hi kar ke deta hai - yahan sirf view-level (DC/Division/Circle)
            // scoping baaki hai, jo purani tarah in-memory/free hai.
            // USER REQUEST (2026-09-22): screen par "Latest Paid Upload" line ab
            // Pay_date (jo intentionally "yesterday" hota hai) ki jagah ASLI
            // upload timestamp (last_upload_at, TIME sahit, Indian format) dikhani
            // hai - yeh admin panel me pehle se available hai (fetchOmvigFreezeStatus_),
            // usi cached/fast call ko yahan bhi (parallel) use kar lete hain, koi
            // naya slow call nahi.
            const [{ date, rows, dcSummaryMap, noYesterday, latestPayDate, newCases, freezeIso }, freezeStatus] = await Promise.all([
                fetchOmvigDailyReport_(forceRefresh),
                fetchOmvigFreezeStatus_(forceRefresh).catch(() => null)
            ]);
            const scoped = scopeOmvigDailyRowsToView_(rows);
            return {
                date,
                rowsWithStatus: mapOmvigDailyRowsWithStatus_(scoped, date),
                dcSummaryMap,
                noYesterday: !!noYesterday,
                latestPayDate: latestPayDate || "",
                newCases: newCases || [],
                freezeIso: freezeIso || "",
                lastUploadAt: freezeStatus?.last_upload_at || "",
                lastUploadSummary: freezeStatus?.last_upload_summary || ""
            };
        }

        // Daily-specific render functions (Monthly ki renderOmvigDcLevelHtml_/
        // renderOmvigDivisionLevelHtml_/renderOmvigCircleLevelHtml_ jaisi hi
        // dropdown/structure, bas "no filter" summary ab TRUE dcSummaryMap se
        // banti hai; Paid/Unpaid dropdown chunne wala hissa purane flat
        // rowsWithStatus-based tareeke se hi hai, wahan koi badlav nahi).
        function renderOmvigDailyDcLevelHtml_(rowsWithStatus, dcSummaryMap) {
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-dc-status-select", "-- Select Paid/Unpaid to View List --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            let summaryHtml, listHtml = "";
            if (omvigFilterStatus) {
                const filteredRows = filterOmvigRowsByStatus_(rowsWithStatus, omvigFilterStatus);
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, activeDC, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
                listHtml = renderOmvigDcListHtml_(filteredRows);
            } else {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [omvigDailyDcSummaryGroup_(dcSummaryMap, activeDC)], "DC SUMMARY (AMOUNT IN LAKH)", "YESTERDAY PAID (FREEZE)", "PENDING");
            }
            return summaryHtml + statusSelectHtml + listHtml;
        }

        // USER REQUEST (2026-09-22): Daily (Fast) me bhi Monthly jaisa hi -
        // Paid/Unpaid dropdown ab DC select kiye BINA kaam karta hai. DC-WISE
        // SUMMARY (poori Division) ko bhi ab sirf Paid ya sirf Pending tak
        // filter kar sakte hain, DC chunna zaroori nahi.
        function renderOmvigDailyDivisionLevelHtml_(rowsWithStatus, dcSummaryMap) {
            const dcOptions = getDivisionDcNames(activeDiv).map((n) => ({ value: n, label: n }));
            const dcSelectHtml = omvigFilterSelectHtml_("omvig-division-dc-select", "-- Select DC --", dcOptions, omvigFilterDc);
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-division-status-select", "-- Select Paid/Unpaid --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            const titleSuffix = omvigFilterStatus ? ` - ${omvigFilterStatus}` : "";
            let summaryHtml;
            if (!omvigFilterDc) {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", appendOmvigTotalRow_(omvigDailyDivisionDcSummaryRows_(dcSummaryMap, activeDiv, omvigFilterStatus)), `DC WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
            } else if (!omvigFilterStatus) {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [omvigDailyDcSummaryGroup_(dcSummaryMap, omvigFilterDc)], "DC SUMMARY (AMOUNT IN LAKH)", "YESTERDAY PAID (FREEZE)", "PENDING");
            } else {
                const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                const filteredRows = filterOmvigRowsByStatus_(dcRows, omvigFilterStatus);
                summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, omvigFilterDc, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
            }
            return summaryHtml + dcSelectHtml + statusSelectHtml;
        }

        function renderOmvigDailyCircleLevelHtml_(rowsWithStatus, dcSummaryMap) {
            const divOptions = Object.keys(divisionConfigs).map((n) => ({ value: n, label: n.replace(/^DIVISION\s+/i, "") }));
            const divSelectHtml = omvigFilterSelectHtml_("omvig-circle-division-select", "-- Select Division --", divOptions, omvigFilterDivision);
            const statusSelectHtml = omvigFilterSelectHtml_("omvig-circle-status-select", "-- Select Paid/Unpaid --", OMVIG_STATUS_OPTIONS_, omvigFilterStatus) + omvigSlabSelectHtml_();
            const titleSuffix = omvigFilterStatus ? ` - ${omvigFilterStatus}` : "";
            let summaryHtml, dcSelectHtml = "";
            if (!omvigFilterDivision) {
                summaryHtml = scOmSummaryTableHtml_("DC NAME", omvigDailyCircleDcWiseSummaryRows_(dcSummaryMap, omvigFilterStatus), `DC WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
            } else {
                const dcOptions = getDivisionDcNames(omvigFilterDivision).map((n) => ({ value: n, label: n }));
                dcSelectHtml = omvigFilterSelectHtml_("omvig-circle-dc-select", "-- Select DC --", dcOptions, omvigFilterDc);
                if (!omvigFilterDc) {
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", appendOmvigTotalRow_(omvigDailyDivisionDcSummaryRows_(dcSummaryMap, omvigFilterDivision, omvigFilterStatus)), `DC-WISE SUMMARY${titleSuffix} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
                } else if (!omvigFilterStatus) {
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", [omvigDailyDcSummaryGroup_(dcSummaryMap, omvigFilterDc)], "DC SUMMARY (AMOUNT IN LAKH)", "YESTERDAY PAID (FREEZE)", "PENDING");
                } else {
                    const dcRows = rowsWithStatus.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
                    const filteredRows = filterOmvigRowsByStatus_(dcRows, omvigFilterStatus);
                    summaryHtml = scOmSummaryTableHtml_("DC NAME", [buildOmvigStatusSummaryRow_(filteredRows, omvigFilterDc, omvigFilterStatus)], `DC SUMMARY - ${omvigFilterStatus} (AMOUNT IN LAKH)`, "YESTERDAY PAID (FREEZE)", "PENDING");
                }
            }
            return summaryHtml + divSelectHtml + dcSelectHtml + statusSelectHtml;
        }

        // Download button-set bhi Monthly jaisa hi (dekhein downloadOmvigDailyReport
        // neeche) - column-set sirf Daily ke actual data (DC/Consumer/Panchanama/
        // Pay Mode/Amount) tak simat hai, kyunki Monthly wale Circle/Division/
        // Checked-By/Inspection-Date/EZ-No/Tariff/Case/Balanced-Amount columns
        // Daily data me hote hi nahi.
        function renderOmvigDailyReportHtml_(data) {
            if (!data.date) {
                return `<div style="text-align:center; color:#64748b; font-size:0.72rem; padding:20px 0;">No Paid List has been uploaded yet.</div>`;
            }
            // USER REQUEST (2026-09-22, USER-REPORTED): pehle yahan sirf Pay_date
            // (jo Daily report ke "yesterday" business-logic ke hisab se sahi hi
            // hai, isko chhedna nahi tha) dikhta tha - koi TIME nahi, aur agar
            // aaj hi Paid List upload hui ho to bhi yeh date "purani" (yesterday's
            // pay-date) hi dikhti thi, jisse lagta tha ki "aaj ka upload dikh hi
            // nahi raha". Ab ASLI upload timestamp (last_upload_at, date+time,
            // formatIndianDateTimeDisplay_ se Indian dd-mm-yyyy hh:mm format me)
            // dikhate hain - agar aaj upload hui hai to aaj ki hi date+time
            // dikhegi. last_upload_at na mile (bahut purana/khaali data) to
            // purana Pay_date-only fallback dikhta hai.
            const dateLine = data.lastUploadAt
                ? `<div style="text-align:center; font-size:0.66rem; font-weight:800; color:#475569; margin-bottom:4px;">🕒 Latest Paid Upload: ${escapeHtml(formatIndianDateTimeDisplay_(data.lastUploadAt))}${data.lastUploadSummary ? `<br><span style="font-weight:700; color:#64748b;">${escapeHtml(data.lastUploadSummary)}</span>` : ""}</div>`
                : `<div style="text-align:center; font-size:0.66rem; font-weight:800; color:#475569; margin-bottom:4px;">Latest Paid Upload - Date: ${escapeHtml(data.date)}</div>`;
            const noYdNote = data.noYesterday ? `<div style="text-align:center; font-size:0.64rem; font-weight:800; color:#b45309; background:#fffbeb; border-radius:8px; padding:5px 7px; margin-bottom:6px;">Paid List with payments of yesterday (${escapeHtml(data.date)}) is not uploaded yet${data.latestPayDate ? ` (last payment date: ${escapeHtml(data.latestPayDate)})` : ""} - so Yesterday Paid is 0</div>` : "";
            let bodyHtml;
            const slabReadyDaily_ = scOmDailySlabReady_(data.dcSummaryMap);
            const slabRowsDaily_ = (omvigFilterSlab && slabReadyDaily_) ? omvigApplySlab_(data.rowsWithStatus) : data.rowsWithStatus;
            if (activeViewLevel === "DC") {
                bodyHtml = renderOmvigDailyDcLevelHtml_(slabRowsDaily_, data.dcSummaryMap);
            } else if (activeViewLevel === "DIVISION") {
                bodyHtml = renderOmvigDailyDivisionLevelHtml_(slabRowsDaily_, data.dcSummaryMap);
            } else {
                bodyHtml = renderOmvigDailyCircleLevelHtml_(slabRowsDaily_, data.dcSummaryMap);
            }
            bodyHtml = ((omvigFilterSlab && !slabReadyDaily_) ? `<div style="text-align:center; font-size:0.64rem; font-weight:800; color:#b45309; background:#fffbeb; border-radius:8px; padding:5px 7px; margin-top:6px;">Slab-wise Daily data is not available yet (backend update pending). Showing without slab.</div>` : "")
                + bodyHtml;
            // USER REQUEST (2026-10-14): DC level par bhi Division/Circle jaisa same flow (Excel + Summary PDF + List PDF).
            const downloadButtons = `<div class="omvig-dl-btns" style="display:flex; gap:8px; margin-top:12px; flex-wrap:wrap;">
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#16a34a; color:#fff;" onclick="downloadOmvigDailyReport('XLS')">⬇️ Excel</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#0891b2; color:#fff;" onclick="downloadOmvigDailyReport('PDF_SUMMARY')">📊 Summary PDF</button>
                     <button class="btn-unique" style="flex:1; min-width:100px; background:#dc2626; color:#fff;" onclick="downloadOmvigDailyReport('PDF_LIST')">📋 List PDF</button>
                   </div>`;
            const ydIso = scOmIsoDate_(data.date);
            const newHtml = ""; // 29/09 12:32: NEW CASE ab summary column me
            return dateLine + noYdNote + newHtml + bodyHtml + downloadButtons + SC_OMVIG_DL_STATUS_HTML_;
        }

        // USER REQUEST (2026-09-14): on-screen dropdown filter (Division/DC/
        // Paid-Unpaid) jo abhi chuna hua hai, download (Excel/PDF, sabhi
        // format) ko bhi wahi scope dikhna chahiye - pehle download hamesha
        // poora unscoped Circle/Division data bhej deta tha, on-screen filter
        // se bilkul bekhabar. `scopedRows` = Division+DC tak scope (status
        // filter se pehle - DC-wise Paid/Pending breakdown table isi se
        // banti hai), `finalRows` = status filter bhi laga hua (list +
        // top stats box isi se banti hai) - bilkul on-screen render jaisa.
        function getOmvigDownloadScopedRows_(rowsWithStatus) {
            let rows = rowsWithStatus;
            if (activeViewLevel === "CIRCLE" && omvigFilterDivision) {
                const dcSet = new Set(getDivisionDcNames(omvigFilterDivision).map((n) => normalizeDcName(n)));
                rows = rows.filter((r) => dcSet.has(normalizeDcName(r.dc_name)));
            }
            if ((activeViewLevel === "CIRCLE" || activeViewLevel === "DIVISION") && omvigFilterDc) {
                rows = rows.filter((r) => normalizeDcName(r.dc_name) === normalizeDcName(omvigFilterDc));
            }
            return rows;
        }

        // USER REQUEST (2026-09-16): download (Excel/PDF) ka DC-wise summary
        // table on-screen wale se HAMESHA match karna chahiye - isliye ab yahan
        // bhi wahi O&M/VIG-only builders (aur TOTAL row) use karte hain jo
        // screen par use hote hain, SHARED buildFreezeDcWiseSummaryRows nahi
        // (jisme na to naya "PART PAID bhi PAID" rule hai, na Division-level
        // par TOTAL row).
        function getOmvigDownloadSummaryRows_(scopedRows, finalRows) {
            const dcInScope = activeViewLevel === "DC" ? activeDC : omvigFilterDc;
            let rows;
            if (dcInScope) {
                rows = omvigFilterStatus
                    ? [buildOmvigStatusSummaryRow_(finalRows, dcInScope, omvigFilterStatus)]
                    : [buildOmvigSingleDcSummaryRow_(scopedRows, dcInScope)];
            } else if (activeViewLevel === "CIRCLE" && omvigFilterDivision) {
                rows = appendOmvigTotalRow_(buildOmvigDivisionDcSummaryRows_(scopedRows, omvigFilterDivision));
            } else if (activeViewLevel === "DIVISION") {
                rows = appendOmvigTotalRow_(buildOmvigDivisionDcSummaryRows_(scopedRows, activeDiv));
            } else {
                rows = buildOmvigCircleDcWiseSummaryRows_(scopedRows);
            }
            return rows.map((r) => ({
                ...r,
                paidPercent: r.paidPercent !== undefined ? r.paidPercent : (r.totalCount ? ((r.paidCount / r.totalCount) * 100).toFixed(1) : "0.0"),
                pendingPercent: r.pendingPercent !== undefined ? r.pendingPercent : (r.totalCount ? ((r.pendingCount / r.totalCount) * 100).toFixed(1) : "0.0")
            }));
        }

        // USER REQUEST (2026-09-16, round 2): Daily ke download (Excel/PDF) ka
        // DC-wise summary table bhi on-screen jaisa hi TRUE TOTAL CONSUMER/
        // PENDING dikhaye (dcSummaryMap se) - status-filtered (Paid/Unpaid
        // dropdown chuna hua) case purane flat rowsWithStatus-based (finalRows)
        // tareeke se hi hai, wahan koi badlav nahi.
        function getOmvigDailyDownloadSummaryRows_(finalRows, dcSummaryMap) {
            const dcInScope = activeViewLevel === "DC" ? activeDC : omvigFilterDc;
            let rows;
            if (dcInScope) {
                rows = omvigFilterStatus
                    ? [buildOmvigStatusSummaryRow_(finalRows, dcInScope, omvigFilterStatus)]
                    : [omvigDailyDcSummaryGroup_(dcSummaryMap, dcInScope)];
            } else if (activeViewLevel === "CIRCLE" && omvigFilterDivision) {
                rows = appendOmvigTotalRow_(omvigDailyDivisionDcSummaryRows_(dcSummaryMap, omvigFilterDivision));
            } else if (activeViewLevel === "DIVISION") {
                rows = appendOmvigTotalRow_(omvigDailyDivisionDcSummaryRows_(dcSummaryMap, activeDiv));
            } else {
                rows = omvigDailyCircleDcWiseSummaryRows_(dcSummaryMap);
            }
            return rows.map((r) => ({
                ...r,
                paidPercent: r.paidPercent !== undefined ? r.paidPercent : (r.totalCount ? ((r.paidCount / r.totalCount) * 100).toFixed(1) : "0.0"),
                pendingPercent: r.pendingPercent !== undefined ? r.pendingPercent : (r.totalCount ? ((r.pendingCount / r.totalCount) * 100).toFixed(1) : "0.0")
            }));
        }

        async function scOmvigReportDownloadCore_(fmt) {
            try {
                const data = await loadOmvigReportData_();
                if (!data.freeze_date) return showToast("Please set the Freeze Date first", false);
                const omNewDl = (scOmNewCasesScopeDiv_() === null || omvigFilterStatus === "PENDING" || scOmSlabOn_()) ? null : await fetchOmvigDailyReport_().catch(() => null);
                const omFzDl = scOmIsoDate_(data.freeze_date);
                scOmNewCtx_ = omNewDl ? scOmNewCtxMake_(omNewDl.newCases, omFzDl, omFzDl, getTodayIsoDate()) : null;
                const omNewOn = scOmNewOn_();
                const omNewList = omNewOn ? scOmNewCasesListRows_(scOmNewCtx_.newCases, scOmNewCtx_.freezeIso, scOmNewCtx_.from, scOmNewCtx_.to, scOmNewCasesScopeDiv_()) : [];
                const omNewRows = [];
                const scopedRows = omvigApplySlab_(getOmvigDownloadScopedRows_(data.rowsWithStatus));
                // USER REQUEST (2026-10-14): download ki case list me BALANCED AMOUNT sabse jyada upar, sabse kam niche (har level par)
                const rowsWithStatus = (omvigFilterStatus ? filterOmvigRowsByStatus_(scopedRows, omvigFilterStatus) : scopedRows)
                    .map((r, i) => ({ r, i }))
                    .sort((x, y) => ((Number(y.r.balanced_amount) || 0) - (Number(x.r.balanced_amount) || 0)) || (x.i - y.i))
                    .map((x) => x.r);
                const totalCount = rowsWithStatus.length;
                // USER REQUEST (2026-09-16): PART PAID bhi ab "PAID" bucket me
                // ginte hain (on-screen DC-wise summary table jaisa hi) - taaki
                // is top box ka PAID/PENDING count niche wali DC-wise summary
                // table se hamesha match kare.
                const paidCount = rowsWithStatus.filter((r) => omvigIsInPaidBucket_(r)).length;
                const pendingCount = totalCount - paidCount;
                const paidPercent = totalCount ? ((paidCount / totalCount) * 100).toFixed(1) : "0.0";
                const pendingPercent = totalCount ? ((pendingCount / totalCount) * 100).toFixed(1) : "0.0";
                let scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                // USER REQUEST (2026-09-14): download ka title/filename bhi
                // batana chahiye ki kaunsa filter laga hua hai (jab laga ho).
                const scopeExtras = [];
                if (activeViewLevel === "CIRCLE" && omvigFilterDivision) scopeExtras.push(omvigFilterDivision.replace(/^DIVISION\s+/i, ""));
                if ((activeViewLevel === "CIRCLE" || activeViewLevel === "DIVISION") && omvigFilterDc) scopeExtras.push(omvigFilterDc);
                if (omvigFilterStatus) scopeExtras.push(omvigFilterStatus);
                { const sl_ = OMVIG_SLAB_OPTIONS_.find((o) => o.value === omvigFilterSlab); if (sl_) scopeExtras.push(sl_.label.replace("Freeze Amt: ", "")); }
                if (scopeExtras.length) scope += ` - ${scopeExtras.join(" - ")}`;
                const reportTitle = `O&M-VIG Report - ${scope}`;
                const fileName = `${reportTitle}-${getTodayIsoDate()}`.replace(/[\\/:*?"<>|]+/g, "_");

                const listHeaders = ["S.NO", "CIRCLE", "DIVISION", "DC", "CHECKED BY", "INSPECTION DATE", "PANCHANAMA NO", "EZ NO", "CONSUMER NAME", "CONSUMER NO", "TARIFF NAME", "CASE NAME", "BALANCED AMOUNT", "STATUS", "PAID AMT", "PAID DATE"];
                const statusColIndex = 13; // 0-based, matches listHeaders order above
                // USER REQUEST (2026-09-14): Freeze NP jaisa hi - PAID row GREEN
                // (PDF), PART PAID row RED (PDF); CSV plain text hai (colour
                // support nahi), isliye wahan "++ PAID ++"/"** PART PAID **"
                // marker se alag pehchana jaata hai. `paymentStateFlags` sirf
                // colour/marker ke liye hai, row ka position/order isse bilkul
                // nahi badalta.
                const paymentStateFlags = rowsWithStatus.map((r) => (r.isPaidNow ? 2 : (r.paidAmountNow > 0 ? 1 : 0)));
                const listBodyRows = rowsWithStatus.map((r, index) => [
                    index + 1, r.circle, r.division, r.dc_name, r.checked_by, r.inspection_date, r.panchanama_no, r.ez_no,
                    r.consumer_name, r.consumer_no, r.tariff_name, r.case_name, r.balanced_amount,
                    r.isPaidNow ? "PAID" : (r.paidAmountNow > 0 ? "PART PAID" : "PENDING"),
                    r.isPaidNow ? r.balanced_amount : r.paidAmountNow, r.paidDateNow || ""
                ]);
                omNewList.forEach((nc) => { // NEW CASE rows (paid ke saath, alag rang)
                    listBodyRows.push([listBodyRows.length + 1, "SEONI", nc.div, "-", "", "", nc.pn, "", "", "", "", nc.type === "NAYA" ? "NEW CASE (after freeze)" : "NEW CASE (not in freeze list)", "", "NEW CASE", Math.round(nc.amt * 100) / 100, nc.lastDmy]);
                    paymentStateFlags.push(3);
                });

                if (fmt === "XLS") {
                    // BUG FIX (2026-09-14): user ne download me ek column ka data
                    // left-right shift hote dekha - root cause: kuch pending-sheet
                    // cell (Consumer Name/Case Name jaise text field) me embedded
                    // \r ya \n ho sakta hai (Sheets me multi-line cell), jo purana
                    // csvSafe (sirf `,`/`"`/`\n` quote karta tha, `\r` nahi) hamesha
                    // sahi se escape nahi karta tha - kuch CSV viewer bare `\r` ko
                    // row-break maan lete hain, jisse agli row ka data pichli row
                    // ke galat column me chala jaata dikhta hai. Fix: `\r` bhi
                    // quote-trigger me shamil kiya, AUR extra safety ke liye har
                    // cell ke andar ka koi bhi line-break pehle hi single space se
                    // replace kar dete hain (data kho nahi raha, sirf ek line me
                    // aa raha hai) - taaki kisi bhi CSV viewer me row/column shift
                    // ki gunjaish hi na rahe.
                    const csvSafe = (value) => {
                        const text = String(value ?? "").replace(/\r\n|\r|\n/g, " ");
                        return /[",]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
                    };
                    const markedListBodyRows = listBodyRows.map((row, i) => {
                        const copy = row.slice();
                        const state = paymentStateFlags[i];
                        if (state === 2) copy[statusColIndex] = `++ ${copy[statusColIndex]} ++`;
                        else if (state === 1) copy[statusColIndex] = `** ${copy[statusColIndex]} **`;
                        return copy;
                    });
                    const rows = [[reportTitle], [`Freeze Date: ${data.freeze_date}`], [],
                        ["TOTAL CASES", "PAID COUNT", "PAID %", "PENDING COUNT", "PENDING %"],
                        [totalCount, paidCount, `${paidPercent}%`, pendingCount, `${pendingPercent}%`], []];
                    if (activeViewLevel !== "DC") {
                        const summaryRows = scOmAttachNewCases_(getOmvigDownloadSummaryRows_(scopedRows, rowsWithStatus));
                        rows.push(scOmSumHead_(omNewOn));
                        summaryRows.forEach((r) => rows.push(scOmSumRow_(r, omNewOn)));
                        rows.push([]);
                    }
                    if (omNewRows.length) { rows.push(["NEW CASES - AFTER FREEZE (not included in freeze count, from freeze till now)", "CASES", "AMOUNT"], ...omNewRows, []); }
                    rows.push(listHeaders, ...markedListBodyRows);
                    const csv = rows.map((row) => row.map(csvSafe).join(",")).join("\n");
                    await saveShmsBlob(`${fileName}.csv`, new Blob([csv], { type: "text/csv;charset=utf-8" }), "text/csv;charset=utf-8");
                    return showToast("Excel report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
                }

                if (!window.jspdf?.jsPDF) return showToast("PDF library could not be loaded", false);
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF("l", "mm", "a4");
                // USER REQUEST (2026-09-14, professional-alignment fix): text/ID
                // columns (naam, panchanama no, consumer no, tariff/case name)
                // left-align, paise wale columns right-align, baaki (circle/
                // division/dc/date/status codes) center - taaki har column me
                // value hamesha ek hi jagah se shuru ho (pehle CONSUMER NO jaisa
                // column hamesha CENTER tha, isliye alag-alag length ki values
                // "idhar-udhar" dikhti thi).
                const LEFT_ALIGN_COLS_ = [4, 6, 7, 8, 9, 10, 11];
                const RIGHT_ALIGN_COLS_ = [12, 14];
                const omvigColumnStyles_ = {};
                LEFT_ALIGN_COLS_.forEach((i) => { omvigColumnStyles_[i] = { halign: "left" }; });
                RIGHT_ALIGN_COLS_.forEach((i) => { omvigColumnStyles_[i] = { halign: "right" }; });
                const drawFullListTable = (startY, tDoc = doc) => { // tDoc: Hindi pre-warm scratch (2026-09-26)
                    tDoc.autoTable({
                        startY,
                        head: [listHeaders],
                        body: listBodyRows.length ? listBodyRows : [listHeaders.map(() => "")],
                        theme: "grid", headStyles: { fillColor: [17, 24, 39], halign: "center" },
                        styles: { fontSize: 5.5, cellPadding: 1.2, halign: "center", valign: "middle", overflow: "linebreak" },
                        columnStyles: omvigColumnStyles_,
                        // USER REQUEST (2026-09-14): Pending sheet ke text columns
                        // (CHECKED BY / CONSUMER NAME / CASE NAME / TARIFF NAME etc.)
                        // me Devanagari/Hindi text ho sakta hai - jsPDF khud usko
                        // render nahi kar paata, isliye Meter Checking report me pehle
                        // se bana Canvas-image fix (`meterCheckingCellHasDevanagari_`/
                        // `drawMeterCheckingHindiCell_`) yahan bhi reuse kiya hai, ab
                        // koi bhi column ho (remark-column-specific nahi, har body
                        // cell check hoti hai) - Hindi cell ke upar ek chhoti sahi
                        // Devanagari image chipka di jaati hai, English/number cell
                        // bilkul normal PDF text hi rehte hain.
                        // USER REQUEST (2026-09-14): STATUS column me bhi Freeze NP
                        // jaisa hi colour - PAID = green, PART PAID = red.
                        didParseCell: (cellData) => {
                            if (cellData.section === "body" && paymentStateFlags[cellData.row.index] === 3) { cellData.cell.styles.fillColor = [255, 237, 213]; cellData.cell.styles.textColor = [154, 52, 18]; cellData.cell.styles.fontStyle = "bold"; }
                            if (cellData.section === "body" && cellData.column.index === statusColIndex) {
                                const state = paymentStateFlags[cellData.row.index];
                                if (state === 2) { cellData.cell.styles.textColor = [22, 101, 52]; cellData.cell.styles.fontStyle = "bold"; }
                                else if (state === 1) { cellData.cell.styles.textColor = [220, 38, 38]; cellData.cell.styles.fontStyle = "bold"; }
                            }
                            // USER REQUEST (2026-09-22): Hindi cell ki row ko thodi
                            // zyada minimum height do - autoTable row-height Latin
                            // font-metrics se estimate karta hai, jo Devanagari
                            // glyph ke liye kam pad jaata hai, isliye Hindi image
                            // banate waqt font choti karni padti thi. Thoda extra
                            // height dene se ab bade font me hi fit ho jaata hai.
                            if (cellData.section === "body" && meterCheckingCellHasDevanagari_(cellData.cell.raw)) {
                                scHindiProxyText_(cellData); // 2026-09-27: English jaisa size (pehle minCellHeight 6)
                            }
                        },
                        // USER REQUEST (2026-09-14, alignment fix): Hindi image ab
                        // column ke apne halign (left/center) ke hisab se banti hai,
                        // taaki plain text values ke saath ek hi jagah se align ho -
                        // pehle hamesha canvas ke left se banti thi, isliye center
                        // wale columns me values "idhar-udhar" dikhti thi.
                        didDrawCell: (cellData) => {
                            if (cellData.section === "body" && meterCheckingCellHasDevanagari_(cellData.cell.raw)) {
                                const align = LEFT_ALIGN_COLS_.includes(cellData.column.index) ? "left" : "center";
                                drawMeterCheckingHindiCell_(tDoc, cellData, align);
                            }
                        }
                    });
                };

                // USER REQUEST (2026-09-14): Division/Circle level par "PDF_LIST"
                // ek chhota, seedha PDF hai - sirf poori list, koi summary table
                // nahi (jab sirf list chahiye ho to poori summary ka bojh na ho).
                if (fmt === "PDF_LIST") {
                    scPdfHeader_(doc, { title: `${reportTitle} - Full List`, lines: [`Freeze Date: ${data.freeze_date}`], color: SC_PDF_THEME.omvig });
                    await scPrewarmHindiCells_(drawFullListTable, 26); // SPEED FIX 2026-09-26
                    drawFullListTable(26);
                    scPdfFinalize_(doc); const pdfBlob = doc.output("blob");
                    await saveShmsBlob(`${fileName}.pdf`, pdfBlob, "application/pdf");
                    return showToast("PDF report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
                }

                scPdfHeader_(doc, { title: reportTitle, lines: [`Freeze Date: ${data.freeze_date}`], color: SC_PDF_THEME.omvig });
                doc.autoTable({
                    startY: 29,
                    head: [["TOTAL CASES", "PAID COUNT", "PAID %", "PENDING COUNT", "PENDING %"]],
                    body: [[totalCount, paidCount, `${paidPercent}%`, pendingCount, `${pendingPercent}%`]],
                    theme: "grid", headStyles: { fillColor: [17, 24, 39], halign: "center" }, styles: { fontSize: 9, halign: "center" }
                });

                if (activeViewLevel !== "DC") {
                    const summaryRows = scOmAttachNewCases_(getOmvigDownloadSummaryRows_(scopedRows, rowsWithStatus));
                    const rowTypeFlags = summaryRows.map((r) => (r.type === "GRAND_TOTAL" ? 2 : (r.type === "SUB_TOTAL" ? 1 : 0)));
                    doc.autoTable({
                        startY: doc.lastAutoTable.finalY + 6,
                        head: [scOmSumHead_(omNewOn)],
                        body: summaryRows.map((r) => scOmSumRow_(r, omNewOn)),
                        theme: "grid", headStyles: { fillColor: [8, 145, 178], halign: "center" }, styles: { fontSize: 7, cellPadding: 1.5, halign: "center" },
                        didParseCell: function (hookData) {
                            if (hookData.section === "body") {
                                const flag = rowTypeFlags[hookData.row.index];
                                if (flag === 2) { hookData.cell.styles.fillColor = [219, 234, 254]; hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [159, 18, 57]; }
                                else if (flag === 1) { hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [29, 78, 216]; }
                            }
                        }
                    });
                }

                if (omNewRows.length) { // OM NEW CASES
                    doc.autoTable({
                        startY: doc.lastAutoTable.finalY + 6,
                        head: [["NEW CASES - AFTER FREEZE (not included in freeze count, from freeze till now)", "CASES", "AMOUNT"]],
                        body: omNewRows,
                        theme: "grid", headStyles: { fillColor: [194, 65, 12], halign: "center" }, styles: { fontSize: 7.5, cellPadding: 1.5, halign: "center" }, columnStyles: { 0: { halign: "left" } }
                    });
                }
                // USER REQUEST (2026-09-14): "PDF_SUMMARY" (Division/Circle) yahin
                // ruk jaata hai - poori list wala page nahi jodte. Sirf "PDF" (DC
                // level, jahan koi alag summary-only option hai hi nahi) aur na
                // hone par bhi poori list jodte hain.
                if (fmt !== "PDF_SUMMARY") {
                    doc.addPage("a4", "l");
                    scPdfHeader_(doc, { title: `${reportTitle} - Full List`, lines: [], color: SC_PDF_THEME.omvig });
                    await scPrewarmHindiCells_(drawFullListTable, 20); // SPEED FIX 2026-09-26
                    drawFullListTable(20);
                }

                scPdfFinalize_(doc); const pdfBlob = doc.output("blob");
                await saveShmsBlob(`${fileName}.pdf`, pdfBlob, "application/pdf");
                showToast("PDF report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
            } catch (error) {
                showToast(error?.message || "O&M/VIG report download failed", false);
            }
        }

        // USER REQUEST (2026-09-16): Daily ke liye Monthly jaisa hi download
        // pattern - Excel + Summary PDF + List PDF (Division/Circle), Excel + PDF
        // (DC level), wahi dropdown-scoping (getOmvigDownloadScopedRows_/
        // getOmvigDownloadSummaryRows_/filterOmvigRowsByStatus_ - sab reused,
        // Monthly-agnostic hain). Column-set Daily ke actual data tak simat hai
        // (DC/Consumer/Panchanama/Pay Mode/Amount) - Monthly wale Circle/Division/
        // Checked-By/Inspection-Date/EZ-No/Tariff/Case/Balanced-Amount columns
        // Daily data me hote hi nahi, isliye copy nahi kiye ja sakte.
        async function scOmvigDailyReportDownloadCore_(fmt) {
            try {
                const data = await loadOmvigDailyReportData_();
                if (!data.date) return showToast("No Paid List has been uploaded yet", false);
                const omYdDl = scOmIsoDate_(data.date);
                scOmNewCtx_ = scOmNewCtxMake_(data.newCases, data.freezeIso, omYdDl, omYdDl);
                const omNewOn = scOmNewOn_();
                const omNewList = omNewOn ? scOmNewCasesListRows_(scOmNewCtx_.newCases, scOmNewCtx_.freezeIso, scOmNewCtx_.from, scOmNewCtx_.to, scOmNewCasesScopeDiv_()) : [];
                const omNewRows = [];
                const slabOkDl_ = !omvigFilterSlab || scOmDailySlabReady_(data.dcSummaryMap);
                const scopedRows = (omvigFilterSlab && slabOkDl_) ? omvigApplySlab_(getOmvigDownloadScopedRows_(data.rowsWithStatus)) : getOmvigDownloadScopedRows_(data.rowsWithStatus);
                // USER REQUEST (2026-10-14): Daily list me AMOUNT sabse jyada upar, sabse kam niche
                const rowsWithStatus = (omvigFilterStatus ? filterOmvigRowsByStatus_(scopedRows, omvigFilterStatus) : scopedRows)
                    .map((r, i) => ({ r, i }))
                    .sort((x, y) => ((Number(y.r.paidAmountNow) || 0) - (Number(x.r.paidAmountNow) || 0)) || (x.i - y.i))
                    .map((x) => x.r);
                const totalCount = rowsWithStatus.length;
                const totalAmount = rowsWithStatus.reduce((sum, r) => sum + (Number(r.paidAmountNow) || 0), 0);

                let scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
                const scopeExtras = [];
                if (activeViewLevel === "CIRCLE" && omvigFilterDivision) scopeExtras.push(omvigFilterDivision.replace(/^DIVISION\s+/i, ""));
                if ((activeViewLevel === "CIRCLE" || activeViewLevel === "DIVISION") && omvigFilterDc) scopeExtras.push(omvigFilterDc);
                if (omvigFilterStatus) scopeExtras.push(omvigFilterStatus);
                { const sl_ = OMVIG_SLAB_OPTIONS_.find((o) => o.value === omvigFilterSlab); if (sl_ && slabOkDl_) scopeExtras.push(sl_.label.replace("Freeze Amt: ", "")); }
                if (scopeExtras.length) scope += ` - ${scopeExtras.join(" - ")}`;
                const reportTitle = `O&M-VIG Daily Report - ${scope}`;
                const fileName = `${reportTitle}-${data.date}`.replace(/[\\/:*?"<>|]+/g, "_");

                const listHeaders = ["S.NO", "DC", "CONSUMER NAME", "PANCHANAMA NO", "PAY MODE", "AMOUNT"];
                const listBodyRows = rowsWithStatus.map((r, index) => [index + 1, r.dc_name, r.consumer_name, r.panchanama_no, r.pay_mode, r.paidAmountNow]);
                omNewList.forEach((nc) => listBodyRows.push([listBodyRows.length + 1, `${nc.div} DIVISION`, nc.type === "NAYA" ? "(after freeze)" : "(not in freeze list)", nc.pn, "NEW CASE", Math.round(nc.amt * 100) / 100])); // NEW CASE rows

                if (fmt === "XLS") {
                    const csvSafe = (value) => {
                        const text = String(value ?? "").replace(/\r\n|\r|\n/g, " ");
                        return /[",]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
                    };
                    const rows = [[reportTitle], [`Date: ${data.date}`], [],
                        ["TOTAL SETTLEMENTS", "TOTAL AMOUNT"],
                        [totalCount, totalAmount], []];
                    if (activeViewLevel !== "DC") {
                        const summaryRows = scOmAttachNewCases_(getOmvigDailyDownloadSummaryRows_(rowsWithStatus, data.dcSummaryMap));
                        rows.push(scOmSumHead_(omNewOn));
                        summaryRows.forEach((r) => rows.push(scOmSumRow_(r, omNewOn)));
                        rows.push([]);
                    }
                    if (omNewRows.length) { rows.push([`NEW CASES - YESTERDAY (${data.date}) (not included in freeze count)`, "CASES", "AMOUNT"], ...omNewRows, []); }
                    rows.push(listHeaders, ...listBodyRows);
                    const csv = rows.map((row) => row.map(csvSafe).join(",")).join("\n");
                    await saveShmsBlob(`${fileName}.csv`, new Blob([csv], { type: "text/csv;charset=utf-8" }), "text/csv;charset=utf-8");
                    return showToast("Excel report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
                }

                if (!window.jspdf?.jsPDF) return showToast("PDF library could not be loaded", false);
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF("l", "mm", "a4");
                const LEFT_ALIGN_COLS_ = [2, 3];
                const RIGHT_ALIGN_COLS_ = [5];
                const omvigDailyColumnStyles_ = {};
                LEFT_ALIGN_COLS_.forEach((i) => { omvigDailyColumnStyles_[i] = { halign: "left" }; });
                RIGHT_ALIGN_COLS_.forEach((i) => { omvigDailyColumnStyles_[i] = { halign: "right" }; });
                const drawFullListTable = (startY, tDoc = doc) => { // tDoc: Hindi pre-warm scratch (2026-09-26)
                    tDoc.autoTable({
                        startY,
                        head: [listHeaders],
                        body: listBodyRows.length ? listBodyRows : [listHeaders.map(() => "")],
                        theme: "grid", headStyles: { fillColor: [17, 24, 39], halign: "center" },
                        styles: { fontSize: 6.5, cellPadding: 1.4, halign: "center", valign: "middle", overflow: "linebreak" },
                        columnStyles: omvigDailyColumnStyles_,
                        // USER REQUEST (2026-09-22): Monthly List PDF jaisa hi -
                        // Hindi cell ki row ko thodi zyada minimum height taaki
                        // font choti na karni pade (English jaisa hi size rahe).
                        didParseCell: (cellData) => {
                            if (cellData.section === "body" && Array.isArray(cellData.row.raw) && cellData.row.raw[3] === "NEW CASE") { cellData.cell.styles.fillColor = [255, 237, 213]; cellData.cell.styles.textColor = [154, 52, 18]; cellData.cell.styles.fontStyle = "bold"; }
                            if (cellData.section === "body" && meterCheckingCellHasDevanagari_(cellData.cell.raw)) {
                                scHindiProxyText_(cellData); // 2026-09-27: English jaisa size (pehle minCellHeight 6)
                            }
                        },
                        didDrawCell: (cellData) => {
                            if (cellData.section === "body" && meterCheckingCellHasDevanagari_(cellData.cell.raw)) {
                                const align = LEFT_ALIGN_COLS_.includes(cellData.column.index) ? "left" : "center";
                                drawMeterCheckingHindiCell_(tDoc, cellData, align);
                            }
                        }
                    });
                };

                if (fmt === "PDF_LIST") {
                    scPdfHeader_(doc, { title: `${reportTitle} - Full List`, lines: [`Date: ${data.date}`], color: SC_PDF_THEME.omvig });
                    await scPrewarmHindiCells_(drawFullListTable, 26); // SPEED FIX 2026-09-26
                    drawFullListTable(26);
                    scPdfFinalize_(doc); const pdfBlob = doc.output("blob");
                    await saveShmsBlob(`${fileName}.pdf`, pdfBlob, "application/pdf");
                    return showToast("PDF report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
                }

                scPdfHeader_(doc, { title: reportTitle, lines: [`Date: ${data.date}`], color: SC_PDF_THEME.omvig });
                doc.autoTable({
                    startY: 29,
                    head: [["TOTAL SETTLEMENTS", "TOTAL AMOUNT"]],
                    body: [[totalCount, totalAmount]],
                    theme: "grid", headStyles: { fillColor: [17, 24, 39], halign: "center" }, styles: { fontSize: 9, halign: "center" }
                });

                if (activeViewLevel !== "DC") {
                    const summaryRows = scOmAttachNewCases_(getOmvigDailyDownloadSummaryRows_(rowsWithStatus, data.dcSummaryMap));
                    const rowTypeFlags = summaryRows.map((r) => (r.type === "GRAND_TOTAL" ? 2 : (r.type === "SUB_TOTAL" ? 1 : 0)));
                    doc.autoTable({
                        startY: doc.lastAutoTable.finalY + 6,
                        head: [scOmSumHead_(omNewOn)],
                        body: summaryRows.map((r) => scOmSumRow_(r, omNewOn)),
                        theme: "grid", headStyles: { fillColor: [8, 145, 178], halign: "center" }, styles: { fontSize: 7, cellPadding: 1.5, halign: "center" },
                        didParseCell: function (hookData) {
                            if (hookData.section === "body") {
                                const flag = rowTypeFlags[hookData.row.index];
                                if (flag === 2) { hookData.cell.styles.fillColor = [219, 234, 254]; hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [159, 18, 57]; }
                                else if (flag === 1) { hookData.cell.styles.fontStyle = "bold"; hookData.cell.styles.textColor = [29, 78, 216]; }
                            }
                        }
                    });
                }

                if (omNewRows.length) { // OM NEW CASES
                    doc.autoTable({
                        startY: doc.lastAutoTable.finalY + 6,
                        head: [[`NEW CASES - YESTERDAY (${data.date}) (not included in freeze count)`, "CASES", "AMOUNT"]],
                        body: omNewRows,
                        theme: "grid", headStyles: { fillColor: [194, 65, 12], halign: "center" }, styles: { fontSize: 7.5, cellPadding: 1.5, halign: "center" }, columnStyles: { 0: { halign: "left" } }
                    });
                }
                if (fmt !== "PDF_SUMMARY") {
                    doc.addPage("a4", "l");
                    scPdfHeader_(doc, { title: `${reportTitle} - Full List`, lines: [], color: SC_PDF_THEME.omvig });
                    await scPrewarmHindiCells_(drawFullListTable, 20); // SPEED FIX 2026-09-26
                    drawFullListTable(20);
                }

                scPdfFinalize_(doc); const pdfBlob = doc.output("blob");
                await saveShmsBlob(`${fileName}.pdf`, pdfBlob, "application/pdf");
                showToast("PDF report request has been sent. If the file does not appear in preview, please check in the browser or GitHub version.", true);
            } catch (error) {
                showToast(error?.message || "O&M/VIG Daily report download failed", false);
            }
        }

        async function getPeakLoadMissingDateKeys(substation, selectedDateIso) {
            const startKey = "2026-07-03";
            const selectedKey = normalizePeakLoadDateKey(selectedDateIso);
            const todayKey = getTodayIsoDate();
            const endKey = selectedKey && selectedKey < todayKey ? selectedKey : todayKey;
            if (!selectedKey || selectedKey <= startKey) return [];

            const requiredKeys = getPeakLoadDateRangeKeys(startKey, getPreviousIsoDateKey_(selectedKey));
            if (!requiredKeys.length) return [];

            const submittedRows = await loadPeakLoadSubmittedRows();
            const substationKey = normalizeFeederSubstationKey_(substation);
            const submittedKeys = new Set(
                submittedRows
                    .filter((row) => normalizeFeederSubstationKey_(row.substation) === substationKey)
                    .map((row) => row.dateKey)
            );

            return requiredKeys.filter((dateKey) => dateKey <= endKey && !submittedKeys.has(dateKey));
        }

        async function checkPeakLoadPendingAlertForSelectedSubstation() {
            const substation = selectedPeakLoadSubstation;
            if (!substation) return [];

            const checkToken = ++peakLoadPendingCheckToken;
            try {
                const pendingDateKeys = await getPeakLoadMissingDateKeys(substation, selectedPeakLoadDateIso || getTodayIsoDate());
                if (checkToken !== peakLoadPendingCheckToken || substation !== selectedPeakLoadSubstation) return [];

                if (pendingDateKeys.length) {
                    const pendingDates = pendingDateKeys.map(formatPeakLoadDateKeyForAlert).join(", ");
                    showToast(`Your entry for ${pendingDates} is not done`, false);
                }

                return pendingDateKeys;
            } catch (_) {
                return [];
            }
        }

        function getPreviousIsoDateKey_(dateKey) {
            const date = new Date(`${dateKey}T00:00:00`);
            if (Number.isNaN(date.getTime())) return dateKey;
            date.setDate(date.getDate() - 1);
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, "0");
            const day = String(date.getDate()).padStart(2, "0");
            return `${year}-${month}-${day}`;
        }

        function buildFeederRowsFromReport_(rows) {
            const list = Array.isArray(rows) ? rows : [];
            const deduped = [];
            const seen = new Set();

            list.forEach((row) => {
                const substation = String(row["33/11 KV SUBSTATION"] || row.substation || "").replace(/\s+/g, " ").trim();
                const feeder = String(row["33 AND 11 KV FEEDER"] || row.feeder || "").replace(/\s+/g, " ").trim();
                if (!substation || !feeder) return;

                const key = `${normalizeFeederSubstationKey_(substation)}|${feeder.toUpperCase()}`;
                if (seen.has(key)) return;
                seen.add(key);

                deduped.push({
                    substation,
                    feeder,
                    meterNo: String(row["METER NO"] || row.meter_no || row.meterNo || row.meter || "").replace(/\s+/g, " ").trim(),
                    mf: String(row["MF"] || row.mf || "").replace(/\s+/g, " ").trim(),
                    previousReading: "",
                    currentReading: "",
                    csvPreviousReading: String(row["PREVIUS READING"] || row.previous_reading || "").replace(/\s+/g, " ").trim(),
                    csvCurrentReading: String(row["CURRENT READING"] || row.current_reading || "").replace(/\s+/g, " ").trim(),
                    dcName: String(row["DC NAME"] || row.dc_name || row.dcName || "").replace(/\s+/g, " ").trim(),
                    feederType: feeder.includes("33") ? "33 KV" : "11 KV"
                });
            });

            return deduped;
        }

        function parseFeederReportCsv(csvText) {
            const lines = (csvText || "").split(/\r?\n/).filter((line) => line.trim());
            if (lines.length < 2) return [];

            const headerCols = splitCsvLine(lines[0]).map((item) => String(item || "").trim());
            const headerKeys = headerCols.map((item) => item.toLowerCase().replace(/[^a-z0-9]+/g, ""));
            const findHeaderIndex = (keywords, fallback) => {
                const idx = headerKeys.findIndex((key) => keywords.some((word) => key.includes(word)));
                return idx > -1 ? idx : fallback;
            };

            const substationIndex = findHeaderIndex(["substation", "ssname"], 0);
            const feederIndex = findHeaderIndex(["feeder"], 1);
            const meterIndex = findHeaderIndex(["meter", "meterno", "meternumber"], 2);
            const previousIndex = findHeaderIndex(["previusreading", "previousreading", "prevreading"], 3);
            const currentIndex = findHeaderIndex(["currentreading", "currreading"], 4);
            const mfIndex = findHeaderIndex(["mf"], 5);
            const consumptionIndex = findHeaderIndex(["consumption"], 6);
            const dcNameIndex = findHeaderIndex(["dcname"], 7);
            const dateIndex = findHeaderIndex(["dateddmmyyy", "date"], 8);
            const timeIndex = findHeaderIndex(["timehhmm", "time"], 9);

            return lines.slice(1).map((line) => {
                const cols = splitCsvLine(line);
                const substation = String(cols[substationIndex] || "").replace(/\s+/g, " ").trim();
                const feeder = String(cols[feederIndex] || "").replace(/\s+/g, " ").trim();
                if (!substation || !feeder) return null;
                return {
                    "33/11 KV SUBSTATION": substation,
                    "33 AND 11 KV FEEDER": feeder,
                    "METER NO": String(cols[meterIndex] || "").replace(/\s+/g, " ").trim(),
                    "PREVIUS READING": String(cols[previousIndex] || "").replace(/\s+/g, " ").trim(),
                    "CURRENT READING": String(cols[currentIndex] || "").replace(/\s+/g, " ").trim(),
                    "MF": String(cols[mfIndex] || "").replace(/\s+/g, " ").trim(),
                    "CONSUMPTION": String(cols[consumptionIndex] || "").replace(/\s+/g, " ").trim(),
                    "DC NAME": String(cols[dcNameIndex] || "").replace(/\s+/g, " ").trim(),
                    "DATE(DD/MM/YYY)": String(cols[dateIndex] || "").replace(/\s+/g, " ").trim(),
                    "TIME(HH/MM)": String(cols[timeIndex] || "").replace(/\s+/g, " ").trim()
                };
            }).filter(Boolean);
        }

