        function formatStmComplaintTimeInput(input) {
            if (!input) return;
            const digits = String(input.value || "").replace(/\D/g, "").slice(0, 4);
            if (digits.length <= 2) {
                input.value = digits;
                return;
            }
            input.value = `${digits.slice(0, 2)}:${digits.slice(2)}`;
        }

        async function submitStmComplaintStub() {
            const sharedMode = String(document.getElementById("stm-complaint-shared-mode")?.value || "").trim();
            const dateValue = String(document.getElementById("stm-complaint-date")?.value || "").trim();
            const timeValue = String(document.getElementById("stm-complaint-time")?.value || "").trim();
            const callingInfo = String(document.getElementById("stm-complaint-calling-info")?.value || "").trim();
            const complaintDetails = String(document.getElementById("stm-complaint-details")?.value || "").trim();
            const photoInput = document.getElementById("stm-complaint-photo");
            const submitBtn = document.getElementById("stm-complaint-submit-btn");
            if (!selectedStmComplaintSubstation) return showToast("Please select a substation", false);
            if (!sharedMode) return showToast("Please select Information shared at", false);
            if (!dateValue || !timeValue) return showToast("Please enter date and time", false);
            if (sharedMode === "CALLING" && !callingInfo) return showToast("Please enter calling details", false);
            if (!complaintDetails) return showToast("Please enter complaint details", false);
            if (!activeStmComplaintOperator) return showToast("Please save signup first", false);

            const file = photoInput?.files?.[0] || null;
            let photoBase64 = "";
            let photoName = "";
            let photoMimeType = "";

            setActionButtonState(submitBtn, "processing", "Submit");

            try {
                if (file) {
                    photoBase64 = await resizeImageForUpload(file, 1280, 0.78);
                    photoName = file.name || `stm-complaint-${Date.now()}.jpg`;
                    photoMimeType = file.type || "image/jpeg";
                }

                // Hindi/Devanagari complaint text ko reliably UTF-8 me bhejne ke liye
                // ab JSON body use kar rahe hain (form-urlencoded me kabhi-kabhi
                // Unicode galat decode ho raha tha, jisse mail me "?" boxes aa rahe
                // the). Content-Type "text/plain" rakha hai taki browser CORS
                // preflight na bheje (Apps Script Web App OPTIONS handle nahi karta),
                // server side body ko JSON hi maan ke parse karta hai.
                const payload = {
                    substation: selectedStmComplaintSubstation,
                    operator_name: activeStmComplaintOperator.fullName || "",
                    mobile_no: activeStmComplaintOperator.mobileNo || "",
                    information_shared_at: sharedMode,
                    date: dateValue,
                    time: timeValue,
                    calling_info: callingInfo,
                    complaint_details: complaintDetails,
                    photo_base64: photoBase64,
                    photo_name: photoName,
                    photo_mime_type: photoMimeType
                };

                // OFFLINE QUEUE 3: client_uuid - retry par dohri complaint/mail nahi
                payload.client_uuid = generateClientUuid_();
                const scRes = await scOffqLiveSubmit_("STM", `STM__${payload.client_uuid}`, `${selectedStmComplaintSubstation} - ${dateValue} ${timeValue}`, stmComplaintScriptUrl, "text/plain;charset=utf-8", JSON.stringify(payload));
                if (scRes.kind === "queuefail") throw new Error(SC_OFFQ_FAIL_MSG_);
                if (scRes.kind === "rejected") throw new Error(scRes.message || "STM complaint could not be submitted");
                const parsed = scRes.kind === "ok" ? (scRes.parsed || {}) : {};

                setActionButtonState(submitBtn, "done", "Submit");
                showToast(scRes.kind === "queued" ? "No network. Complaint is saved safely on the phone and will be submitted automatically when internet is available." : (parsed.message || "STM complaint submitted"), true);

                const sharedModeInput = document.getElementById("stm-complaint-shared-mode");
                const dateInput = document.getElementById("stm-complaint-date");
                const timeInput = document.getElementById("stm-complaint-time");
                const callingInfoInput = document.getElementById("stm-complaint-calling-info");
                const detailsInput = document.getElementById("stm-complaint-details");
                const photoNameLabel = document.getElementById("stm-complaint-photo-name");

                selectedStmComplaintSubstation = "";
                if (sharedModeInput) sharedModeInput.value = "";
                if (dateInput) dateInput.value = "";
                if (timeInput) timeInput.value = "";
                if (callingInfoInput) callingInfoInput.value = "";
                if (detailsInput) detailsInput.value = "";
                if (photoInput) photoInput.value = "";
                if (photoNameLabel) photoNameLabel.innerText = "You can select a photo from either camera or gallery";
                populateStmComplaintSubstations();
                updateStmComplaintProgressiveUi();
            } catch (error) {
                setActionButtonState(submitBtn, "failed", "Submit");
                showToast(error?.message || "STM complaint could not be submitted", false);
            } finally {
                setTimeout(() => setActionButtonState(submitBtn, "idle", "Submit"), 900);
            }
        }

