        async function performCourtSearch() {
            const caseNo = document.getElementById("search-case-no").value.trim();
            if (!caseNo) return showToast("Please enter Case No", false);
            if (!courtCaseRaw) {
                const loaded = await loadCourtCaseData();
                if (!loaded || !courtCaseRaw) return showToast("Lok Adalat data is not loaded yet", false);
            }
            await preloadDuplicateTrackingData(true);
            const normalizedDc = normalizeLookupValue(activeDC || "");
            const normalizedCaseNo = normalizeLookupValue(caseNo);
            const byCase = courtCaseRecords.filter((record) => normalizeLookupValue(record.caseNo) === normalizedCaseNo);
            if (!byCase.length) return showToast(`Case No ${caseNo} not found in CSV`, false);
            let found = byCase.find((record) => normalizeLookupValue(record.dcName) === normalizedDc);
            if (!found) {
                const firstMatchDc = byCase[0].dcName || "UNKNOWN";
                return showToast(`Case found but it belongs to DC ${firstMatchDc}`, false);
            }
            currentCourtRecord = found;
            document.getElementById("court-panchnama").innerText = found.panchnamaNo || "N/A";
            document.getElementById("court-consumer").innerText = found.consumerName || "N/A";
            document.getElementById("court-section").innerText = found.section || "N/A";
            document.getElementById("court-civil").innerText = found.civilAmt || "0";
            document.getElementById("court-compounding").innerText = found.compoundingAmt || "0";
            document.getElementById("court-billed").innerText = found.billedAmt || "0";
            document.getElementById("court-rebate").innerText = found.rebate || "0";
            document.getElementById("court-total").innerText = found.totalPayableAmount || "0";
            document.getElementById("court-result-box").style.display = "block";
            const courtSubmitBtn = document.getElementById("court-submit-btn");
            if (isCourtCaseAlreadyServed(found)) {
                courtSubmitBtn.style.display = "none";
                showToast("Notice Already Surved", false);
                return;
            }
            courtSubmitBtn.style.display = "block";
        }

        async function updateReceiverPhotoName() {
            const input = document.getElementById("receiver-photo");
            const label = document.getElementById("receiver-photo-name");
            label.innerText = input.files && input.files[0] ? input.files[0].name : "No photo selected";
            if (input.files && input.files[0]) {
                await captureReceiverGeoLocation();
            } else {
                receiverGeoData = null;
                updatePhotoMetaUI();
            }
        }

        async function submitCourtCaseDemo() {
            const receiverName = document.getElementById("receiver-name").value.trim();
            const receiverMobile = document.getElementById("receiver-mobile").value.trim();
            const photoInput = document.getElementById("receiver-photo");
            if (!currentCourtRecord) return showToast("Please search the case first", false);
            await preloadDuplicateTrackingData(true);
            if (isCourtCaseAlreadyServed(currentCourtRecord)) return showToast("Notice Already Surved", false);
            if (!receiverName) return showToast("Please enter receiver name", false);
            if (receiverMobile.length !== 10) return showToast("Please enter a 10-digit mobile number", false);
            if (!photoInput.files || !photoInput.files[0]) return showToast("Please select receiver photo", false);
            const submitBtn = document.getElementById("court-submit-btn");
            setActionButtonState(submitBtn, "processing", "Submit");
            try {
                const photoFile = photoInput.files[0];
                const photoData = await resizeImageForUpload(photoFile);
                const payload = new URLSearchParams();
                payload.append("date", getCurrentDateDDMMYYYY());
                payload.append("dc_name", activeDC || "");
                payload.append("case_no", currentCourtRecord.caseNo || "");
                payload.append("panchnama_no", currentCourtRecord.panchnamaNo || "");
                payload.append("consumer_name", currentCourtRecord.consumerName || "");
                payload.append("section", currentCourtRecord.section || "");
                payload.append("civil_amt", currentCourtRecord.civilAmt || "");
                payload.append("compounding_amt", currentCourtRecord.compoundingAmt || "");
                payload.append("billed_amt", currentCourtRecord.billedAmt || "");
                payload.append("rebate", currentCourtRecord.rebate || "");
                payload.append("total_payable_amount", currentCourtRecord.totalPayableAmount || "");
                payload.append("receiver_name", receiverName);
                payload.append("receiver_mobile", receiverMobile);
                payload.append("photo_name", photoFile.name || `receiver_${currentCourtRecord.caseNo}.jpg`);
                payload.append("photo_data", photoData);
                payload.append("gps_latitude", receiverGeoData?.latitude || "");
                payload.append("gps_longitude", receiverGeoData?.longitude || "");
                payload.append("gps_location", receiverGeoData?.locationText || "");

                // OFFLINE QUEUE 3: network na ho to phone me save; retry se pehle server par served-check
                const scCourtRecKey = getCourtRecordStorageKey(currentCourtRecord);
                const scCourtKey = `COURT__${scCourtRecKey}`;
                if (await scOffqFind_("COURT", scCourtKey)) {
                    setActionButtonState(submitBtn, "failed", "Submit");
                    return showToast("Entry of this case is already saved as pending on this phone (it will be submitted when internet is available)", false);
                }
                const scRes = await scOffqLiveSubmit_("COURT", scCourtKey, `Case ${currentCourtRecord.caseNo || ""} | ${currentCourtRecord.consumerName || ""} | Receiver ${receiverName}`, lokAdalatScriptUrl, "application/x-www-form-urlencoded;charset=UTF-8", payload.toString(), { courtKey: scCourtRecKey });
                const scQueued = scRes.kind === "queued";
                const submitOk = scRes.kind === "ok" || scQueued;
                const submitMessage = scQueued ? SC_OFFQ_SAVED_MSG_
                    : (scRes.kind === "ok" ? "Submitted Successfully" : (scRes.kind === "queuefail" ? SC_OFFQ_FAIL_MSG_ : (scRes.message || "Submit error occurred")));

                showToast(submitMessage, submitOk);
                setActionButtonState(submitBtn, submitOk ? "done" : "failed", "Submit");
                if (!submitOk) return;
                if (!scQueued) markCourtCaseServed(currentCourtRecord);
                document.getElementById("receiver-name").value = "";
                document.getElementById("receiver-mobile").value = "";
                document.getElementById("receiver-photo").value = "";
                document.getElementById("receiver-photo-name").innerText = "No photo selected";
                receiverGeoData = null;
                updatePhotoMetaUI();
                document.getElementById("court-submit-btn").style.display = "none";
            } catch (e) {
                setActionButtonState(submitBtn, "failed", "Submit");
                showToast("Submit error occurred", false);
            } finally {
                setTimeout(() => setActionButtonState(submitBtn, "idle", "Submit"), 900);
            }
        }

