        async function submitStockDemo(type) {
            if (type === "receive") {
                const source = document.getElementById("receive-source").value.trim();
                const person = document.getElementById("receive-person").value.trim();
                if (!pendingReceiveItems.length) return showToast("Please add to the material list first", false);
                if (!source) return showToast("Please enter Received From", false);
                if (!person) return showToast("Please enter Receive Person Name", false);
                const submitBtn = document.querySelector("#material-receive-view .stock-submit");
                setActionButtonState(submitBtn, "processing", "Save Receive Entry");
                try {
                    const scStockRes = await submitStockEntriesToSheet("receive"); // OFFLINE QUEUE 3
                    pendingReceiveItems.forEach((entry) => {
                        entry.item.inward += entry.qty;
                        entry.item.currentBalance = getStockBalance(entry.item) + entry.qty;
                        stockMovements.unshift({
                            type: "RECEIVE",
                            material: entry.item.name,
                            qty: entry.qty,
                            date: getCurrentDateDDMMYYYY().replace(/-/g, "/"),
                            note: `${source} | Received By ${person}`
                        });
                    });
                    pendingReceiveItems = [];
                    document.getElementById("receive-source").value = "";
                    document.getElementById("receive-person").value = "";
                    resetStockSearchSelection("receive");
                    renderStockDashboard();
                    setActionButtonState(submitBtn, "done", "Save Receive Entry");
                    showToast(scStockRes && scStockRes.__scQueued ? SC_OFFQ_SAVED_MSG_ : "Receive entry list saved", true);
                } catch (error) {
                    setActionButtonState(submitBtn, "failed", "Save Receive Entry");
                    showToast(error.message || "Receive submit failed", false);
                } finally {
                    setTimeout(() => setActionButtonState(submitBtn, "idle", "Save Receive Entry"), 900);
                }
            } else {
                const issueTo = document.getElementById("issue-to").value.trim();
                const issueRemark = document.getElementById("issue-remark").value.trim();
                if (!pendingIssueItems.length) return showToast("Please add to the material list first", false);
                if (!activeIssueDc) return showToast("Please select DC Name", false);
                if (!issueTo) return showToast("Please enter Issue To Person Name", false);
                for (const entry of pendingIssueItems) {
                    if (getStockBalance(entry.item) <= 0) return showToast("Stock Not Available", false);
                    if (entry.qty > getStockBalance(entry.item)) return showToast(`Stock of ${entry.item.name} is low`, false);
                }
                const submitBtn = document.querySelector("#material-issue-view .stock-submit");
                setActionButtonState(submitBtn, "processing", "Save Issue Entry");
                try {
                    const scStockRes = await submitStockEntriesToSheet("issue"); // OFFLINE QUEUE 3
                    pendingIssueItems.forEach((entry) => {
                        entry.item.issue += entry.qty;
                        entry.item.currentBalance = Math.max(0, getStockBalance(entry.item) - entry.qty);
                        stockMovements.unshift({
                            type: "ISSUE",
                            material: entry.item.name,
                            qty: entry.qty,
                            date: getCurrentDateDDMMYYYY().replace(/-/g, "/"),
                            note: `${activeIssueDc} | Issued To ${issueTo}${issueRemark ? ` | ${issueRemark}` : ""}`
                        });
                    });
                    pendingIssueItems = [];
                    document.getElementById("issue-to").value = "";
                    document.getElementById("issue-remark").value = "";
                    activeIssueDc = "";
                    document.getElementById("issue-dc-label").innerText = "Select DC Name...";
                    resetStockSearchSelection("issue");
                    renderStockDashboard();
                    setActionButtonState(submitBtn, "done", "Save Issue Entry");
                    showToast(scStockRes && scStockRes.__scQueued ? SC_OFFQ_SAVED_MSG_ : "Issue entry list saved", true);
                } catch (error) {
                    setActionButtonState(submitBtn, "failed", "Save Issue Entry");
                    showToast(error.message || "Issue submit failed", false);
                } finally {
                    setTimeout(() => setActionButtonState(submitBtn, "idle", "Save Issue Entry"), 900);
                }
            }
        }

        // NOTE: "Chhapara Feeder Calculator" (add/list/delete feeder-output entries with
        // 2-DC percentage split, localStorage-persisted) - initChhaparaFeederCalculator,
        // readChhaparaFeederForm, calculateChhaparaFeederData, previewChhaparaFeederCalc,
        // addChhaparaFeederEntry, persistChhaparaFeederEntries, clearChhaparaFeederForm,
        // renderChhaparaFeederEntries, deleteChhaparaFeederEntry - hata diya gaya hai. Iski
        // koi HTML UI (button/page) index.html me kabhi thi hi nahi, isliye yeh dead code
        // tha (har app-load par bekaar init hota tha). formatChhaparaNumber() alag hai -
        // wo "Feeder Reading" (updateFeederConsumptionPreview) ke live feature me abhi bhi
