        async function addVehicleReadingToList() {
            if (vehicleReadingSubmitInProgress) return showToast("Submit in progress, please wait", false);
            if (!selectedVehicleNo) return showToast("Please select a vehicle no first", false);
            const entryDate = getCurrentDateDDMMYYYY();
            const historyRefreshed = await loadVehicleReadingHistoryFromSheet();
            if (historyRefreshed && isVehicleReadingAlreadySubmitted(selectedVehicleNo, entryDate)) return showToast("Already submitted", false);
            const previousInput = document.getElementById("vehicle-previous-reading");
            const currentInput = document.getElementById("vehicle-current-reading");
            const previousReading = String(previousInput?.value || "").trim();
            const currentReading = String(currentInput?.value || "").trim();
            const previousNumber = Number(previousReading || 0);
            const currentNumber = Number(currentReading);

            if (!currentReading || Number.isNaN(currentNumber)) return showToast("Please enter current reading", false);
            if (previousReading && currentNumber < previousNumber) return showToast("Current reading cannot be less than previous", false);
            const differenceReading = previousReading ? String(Number((currentNumber - previousNumber).toFixed(2))) : "";

            const entry = {
                id: `vehicle-${Date.now()}`,
                vehicleNo: selectedVehicleNo,
                date: entryDate,
                time: getCurrentTimeHHMM(),
                previousReading,
                currentReading,
                differenceReading,
                photoName: vehiclePhotoName || ""
            };

            setVehicleReadingSubmitting(true);
            try {
                if (vehicleReadingSubmitScriptUrl) {
                    const payload = new URLSearchParams();
                    payload.append("date", entry.date);
                    payload.append("time", entry.time);
                    payload.append("vehicle_no", entry.vehicleNo);
                    payload.append("previous_reading", entry.previousReading);
                    payload.append("current_reading", entry.currentReading);
                    payload.append("difference_reading", entry.differenceReading);
                    payload.append("photo_base64", vehiclePhotoDataUrl || "");
                    payload.append("photo_name", vehiclePhotoName || "");

                    // OFFLINE QUEUE 3: network na ho to phone me save; retry se pehle sheet me check hota hai
                    const scKey = `VEHICLE__${getVehicleReadingKey(entry.vehicleNo, entry.date)}`;
                    if (await scOffqFind_("VEHICLE", scKey)) {
                        setActionButtonState(document.getElementById("vehicle-submit-btn"), "failed", "Submit");
                        return showToast("Today's reading of this vehicle is already saved as pending on this phone (it will be submitted when internet is available)", false);
                    }
                    const scRes = await scOffqLiveSubmit_("VEHICLE", scKey, `${entry.vehicleNo} | ${entry.date} ${entry.time} | Reading ${entry.currentReading}`, vehicleReadingSubmitScriptUrl, "application/x-www-form-urlencoded;charset=UTF-8", payload.toString(), { vehicleNo: entry.vehicleNo, date: entry.date });
                    if (scRes.kind === "queued") {
                        selectVehicleNo(selectedVehicleNo);
                        setActionButtonState(document.getElementById("vehicle-submit-btn"), "done", "Submit");
                        return showToast(SC_OFFQ_SAVED_MSG_, true);
                    }
                    if (scRes.kind !== "ok") {
                        setActionButtonState(document.getElementById("vehicle-submit-btn"), "failed", "Submit");
                        return showToast(scRes.kind === "queuefail" ? SC_OFFQ_FAIL_MSG_ : (scRes.message || "Vehicle reading submit error occurred"), false);
                    }
                } else {
                    showToast("Vehicle reading saved locally. Apps Script URL must be added to submit to the sheet", false);
                }

                vehicleReadingEntries.unshift(entry);
                try {
                    localStorage.setItem(vehicleReadingListStorageKey, JSON.stringify(vehicleReadingEntries));
                } catch (_) {}

                const state = getVehicleReadingState();
                state[selectedVehicleNo] = {
                    lastReading: currentReading,
                    updatedAt: `${entry.date} ${entry.time}`
                };
                saveVehicleReadingState(state);
                const submittedVehicleNo = selectedVehicleNo;
                selectVehicleNo(submittedVehicleNo);
                setActionButtonState(document.getElementById("vehicle-submit-btn"), "done", "Submit");
                if (vehicleReadingSubmitScriptUrl) showToast("Vehicle reading submitted", true);
            } finally {
                setTimeout(() => setVehicleReadingSubmitting(false), 900);
            }
        }

        function renderVehicleReadingList() {
            const block = document.getElementById("vehicle-list-block");
            const content = document.getElementById("vehicle-list-content");
            if (!block || !content) return;
            if (!selectedVehicleNo) {
                block.style.display = "none";
                content.innerHTML = "";
                return;
            }
            const todayEntries = vehicleReadingEntries
                .filter((entry) => entry.date === getCurrentDateDDMMYYYY() && entry.vehicleNo === selectedVehicleNo)
                .slice(0, 12);
            if (!todayEntries.length) {
                block.style.display = "none";
                content.innerHTML = "";
                return;
            }
            block.style.display = "block";
            content.innerHTML = todayEntries.map((entry) => `
                <div class="vehicle-reading-item">
                    <div style="font-size:12px; font-weight:900; color:#991b1b;">${escapeHtml(entry.vehicleNo)} | ${escapeHtml(entry.date)} ${escapeHtml(entry.time)}</div>
                    <div style="font-size:11px; font-weight:800; color:#334155; margin-top:4px;">Previous: ${escapeHtml(entry.previousReading || "-")} | Current: ${escapeHtml(entry.currentReading)} | Difference: ${escapeHtml(entry.differenceReading || "-")}</div>
                    <div style="font-size:11px; font-weight:800; color:${entry.photoName ? "#16a34a" : "#64748b"}; margin-top:4px;">${entry.photoName ? "Photo captured" : "Photo not added"}</div>
                </div>
            `).join("");
        }

