        async function performStaffAdminAction(adminAction) {
            if (!staffAdminUnlocked || !staffAdminCurrentAccount) return showToast("Please search the staff first", false);
            const labels = {
                RESET_DEVICE: "registered device of this staff has been reset",
                RESET_PIN: "PIN of this staff has been reset",
                UNLOCK_ACCOUNT: "is staff account ko unlock",
                DEACTIVATE_ACCOUNT: "DEACTIVATE this staff account? The staff will NOT be able to log in or register again until you press ACTIVATE (or Reset Registration)",
                ACTIVATE_ACCOUNT: "ACTIVATE this staff account again (the old PIN will work)",
                RESET_REGISTRATION: "registration of this staff has been reset so that the staff can register again"
            };
            const approved = await showCustomConfirmBox("Please Confirm", `Do you want to ${labels[adminAction] || "this action"}?`);
            if (!approved) return;
            setStaffAdminStatus("Processing...", true);
            try {
                const response = await postRevenueMessageStaffApi({
                    action: "staffAdminAction",
                    admin_password: staffAdminActionPasswordEntered,
                    admin_action: adminAction,
                    dc_name: staffAdminCurrentAccount.dc_name || "",
                    mobile_no: staffAdminCurrentAccount.mobile_no || ""
                });
                staffAdminCurrentAccount = response.staff || staffAdminCurrentAccount;
                renderStaffAdminAccount(staffAdminCurrentAccount);
                const temporaryPassword = response.temporary_password
                    ? `<br><span style="display:inline-block; margin-top:7px; padding:7px 10px; border-radius:10px; background:#fef3c7; color:#92400e; font-size:0.88rem;">Temporary Password: <strong>${escapeHtml(response.temporary_password)}</strong></span><br><span style="font-size:0.68rem;">Please give this password to the staff. A new 6-digit PIN must be created on first login.</span>`
                    : "";
                setStaffAdminStatus(`${escapeHtml(response.message || "Action successful")}${temporaryPassword}`, true);
                showToast(response.message || "Staff Admin action successful", true);
            } catch (error) {
                setStaffAdminStatus(escapeHtml(error?.message || "Action was not completed"), false);
            }
        }

