        function getRevenueMessageDeviceId() {
            let deviceId = "";
            try { deviceId = localStorage.getItem(revenueMessageDeviceStorageKey) || ""; } catch (_) {}
            if (!deviceId) {
                deviceId = (window.crypto && typeof window.crypto.randomUUID === "function")
                    ? window.crypto.randomUUID()
                    : `device-${Date.now()}-${Math.random().toString(36).slice(2)}`;
                try { localStorage.setItem(revenueMessageDeviceStorageKey, deviceId); } catch (_) {}
            }
            return deviceId;
        }

        function getStoredRevenueMessageSession() {
            try {
                const raw = localStorage.getItem(revenueMessageSessionStorageKey) || sessionStorage.getItem(revenueMessageSessionStorageKey) || "null";
                const parsed = JSON.parse(raw);
                return parsed && parsed.token ? parsed : null;
            } catch (_) {
                return null;
            }
        }

        function saveRevenueMessageSession(session, remember = true) {
            const sessionWithRemember = session ? { ...session, remember: !!remember } : null;
            revenueMessageSession = sessionWithRemember;
            try {
                localStorage.removeItem(revenueMessageSessionStorageKey);
                sessionStorage.removeItem(revenueMessageSessionStorageKey);
                if (sessionWithRemember) {
                    const stored = JSON.stringify(sessionWithRemember);
                    (remember ? localStorage : sessionStorage).setItem(revenueMessageSessionStorageKey, stored);
                }
            } catch (_) {}
        }

        function setRevenueMessageAuthStatus(message, ok = true) {
            const box = document.getElementById("revenue-message-auth-status");
            if (!box) return;
            box.style.display = message ? "block" : "none";
            box.style.background = ok ? "#ecfdf5" : "#fff1f2";
            box.style.border = `1.5px solid ${ok ? "#86efac" : "#fda4af"}`;
            box.style.color = ok ? "#166534" : "#991b1b";
            box.innerText = message || "";
        }

        function showRevenueMessageAuthPanel(panelName) {
            const loginPanel = document.getElementById("revenue-message-login-panel");
            const registerPanel = document.getElementById("revenue-message-register-panel");
            const pinPanel = document.getElementById("revenue-message-pin-panel");
            const profilePanel = document.getElementById("revenue-message-profile-panel");
            if (loginPanel) loginPanel.style.display = panelName === "LOGIN" ? "block" : "none";
            if (registerPanel) registerPanel.style.display = panelName === "REGISTER" ? "block" : "none";
            if (pinPanel) pinPanel.style.display = panelName === "PIN" ? "block" : "none";
            if (profilePanel) profilePanel.style.display = panelName === "PROFILE" ? "block" : "none";
            if (panelName === "PROFILE") renderRevenueMessageStaffProfile();
        }

        async function postRevenueMessageStaffApi(payload) {
            if (!revenueCollectionSubmitScriptUrl) throw new Error("Revenue backend URL is missing");
            const body = new URLSearchParams();
            Object.entries(payload || {}).forEach(([key, value]) => body.append(key, value ?? ""));
            const response = await fetchWithTimeout(revenueCollectionSubmitScriptUrl, {
                method: "POST",
                headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                body: body.toString(),
                keepalive: true
            }, 45000);
            const text = await response.text();
            let parsed = {};
            try { parsed = JSON.parse(text || "{}"); } catch (_) {}
            if (!response.ok || parsed.status !== "success") throw new Error(parsed.message || "Staff request could not be completed");
            return parsed;
        }

        async function initRevenueMessageLogin() {
            setRevenueMessageAuthStatus("", true);
            const saved = getStoredRevenueMessageSession();
            if (!saved?.token) {
                saveRevenueMessageSession(null);
                showRevenueMessageAuthPanel("LOGIN");
                return;
            }

            setRevenueMessageAuthStatus("Verifying session...", true);
            try {
                const url = `${revenueCollectionSubmitScriptUrl}?action=staffValidateSession&session_token=${encodeURIComponent(saved.token)}&device_id=${encodeURIComponent(getRevenueMessageDeviceId())}&t=${Date.now()}`;
                const response = await fetchWithTimeout(url, {}, 30000);
                const parsed = await response.json();
                if (!response.ok || parsed.status !== "success" || !parsed.valid) throw new Error(parsed.message || "Session expired");
                saveRevenueMessageSession({ token: saved.token, staff: parsed.staff, mustChangePin: !!parsed.must_change_pin }, !!saved.remember);
                setRevenueMessageAuthStatus("", true);
                showRevenueMessageAuthPanel(parsed.must_change_pin ? "PIN" : "PROFILE");
            } catch (error) {
                saveRevenueMessageSession(null);
                showRevenueMessageAuthPanel("LOGIN");
                setRevenueMessageAuthStatus(error?.message || "Session has expired. Please login again", false);
            }
        }

        async function loginRevenueMessageStaff() {
            const loginId = String(document.getElementById("revenue-message-login-id")?.value || "").trim();
            const password = String(document.getElementById("revenue-message-password")?.value || "").trim();
            const remember = !!document.getElementById("revenue-message-login-remember")?.checked;
            const button = document.getElementById("revenue-message-login-btn");
            if (!loginId || !password) return setRevenueMessageAuthStatus("Please enter Staff ID and password", false);

            setActionButtonState(button, "processing", "Login");
            setRevenueMessageAuthStatus("Verifying login...", true);
            try {
                const parsed = await postRevenueMessageStaffApi({
                    action: "staffLogin",
                    login_id: loginId,
                    password,
                    device_id: getRevenueMessageDeviceId()
                });
                saveRevenueMessageSession({ token: parsed.session_token, staff: parsed.staff, mustChangePin: !!parsed.must_change_pin }, remember);
                const passwordInput = document.getElementById("revenue-message-password");
                if (passwordInput) passwordInput.value = "";
                setRevenueMessageAuthStatus(parsed.must_change_pin ? "First login successful. Now create your 6-digit PIN." : "Login successful", true);
                showRevenueMessageAuthPanel(parsed.must_change_pin ? "PIN" : "PROFILE");
                setActionButtonState(button, "done", "Login");
            } catch (error) {
                setRevenueMessageAuthStatus(error?.message || "Login failed", false);
                setActionButtonState(button, "failed", "Login");
            } finally {
                setTimeout(() => setActionButtonState(button, "idle", "Login"), 900);
            }
        }

        function getRevenueMessageActiveDivision() {
            const current = String(activeDiv || "").toUpperCase().replace(/^DIVISION\s+/, "").trim();
            if (current === "SEONI" || current === "LAKHNADON") return current;
            const dcKey = normalizeLookupValue(activeDC || "");
            const divisionName = Object.keys(divisionConfigs || {}).find((name) => (
                getDivisionDcNames(name).some((dc) => normalizeLookupValue(dc) === dcKey)
            ));
            return String(divisionName || "").toUpperCase().replace(/^DIVISION\s+/, "").trim();
        }

