        function getRevenueMessageAllowedRows(rows) {
            const staff = revenueMessageSession?.staff;
            if (!staff) return [];
            const dcKey = normalizeLookupValue(staff.dc_name || "");
            const hqKey = normalizeLookupValue(staff.hq_name || "");
            // USER REQUEST (2026-09-30): AE/JE apne DC ke sabhi HQ consumers ko
            // SMS/WhatsApp bhej sakte hain; baaki designations apne assigned HQ tak hi.
            const allHqAccess = isRevenueMessageAllHqRole(staff.role);
            return (rows || []).filter((row) => {
                const rowDc = normalizeLookupValue(activeDC || staff.dc_name || "");
                if (rowDc !== dcKey) return false;
                if (!allHqAccess && hqKey && normalizeLookupValue(row.hqName || "") !== hqKey) return false;
                return true;
            });
        }

        function normalizeRevenueMessageMobile(value) {
            const digits = String(value || "").replace(/\D/g, "");
            const mobile = digits.length > 10 ? digits.slice(-10) : digits;
            return /^[6-9]\d{9}$/.test(mobile) ? mobile : "";
        }

        // "Wrong Mobile No List" (aur Daily Progress ka WRONG MOBILE NO column) ke
        // liye - format-valid (10 digit, 6-9 se start) ke aage bhi ek check: agar
        // sabhi 10 digit ek hi anka ke repeat hain (9999999999, 8888888888 waghera -
        // field me commonly dala jaane wala dummy/placeholder number), usko bhi
        // "wrong" maante hain. normalizeRevenueMessageMobile() KHUD nahi badla -
        // wahi SMS/WhatsApp button enable/disable jaise purane, alag features me
        // bhi use hoti hai, unko chhedna nahi hai (strict scope).
        function isMobileNoConsideredWrong(value) {
            const valid = normalizeRevenueMessageMobile(value);
            if (!valid) return true;
            if (/^(\d)\1{9}$/.test(valid)) return true;
            return false;
        }

        // Ek hi mobile no yadi ek DC me 5 baar se adhik (6 ya usse zyada) alag-alag
        // consumers me mile to practically itne connection ek hi number par sahi nahi
        // ho sakte - is threshold se zyada baar repeat hone wale number "duplicate"
        // maane jaate hain aur unke saare consumer bhi Wrong Mobile No List me dikhaye
        // jaate hain (dobara manual verify karne ke liye). Pehle se blank/galat-format/
        // dummy-repeated-digit wale number is duplicate-check me shamil nahi kiye jaate
        // (wo already isMobileNoConsideredWrong se pakde ja chuke hain).
        const MOBILE_WRONG_DUPLICATE_THRESHOLD = 5; // USER REQUEST (2026-09-25): 10 se ghata kar 5 - ab 6 ya usse zyada consumer par same no = WRONG

        function computeMobileDuplicateFreqMap(rows, getMobile) {
            const freq = {};
            rows.forEach((row) => {
                const raw = getMobile(row);
                if (isMobileNoConsideredWrong(raw)) return;
                const valid = normalizeRevenueMessageMobile(raw);
                if (!valid) return;
                freq[valid] = (freq[valid] || 0) + 1;
            });
            return freq;
        }

        function isMobileNoDuplicateOverThreshold(raw, freqMap) {
            if (isMobileNoConsideredWrong(raw)) return false;
            const valid = normalizeRevenueMessageMobile(raw);
            if (!valid) return false;
            return (freqMap[valid] || 0) > MOBILE_WRONG_DUPLICATE_THRESHOLD;
        }

        // =====================================================================
        // SPEED PHASE 1 (2026-09-25, USER-APPROVED): Division/Circle summary
        // reports ko tez karna - OUTPUT BILKUL WAHI, sirf speed.
        // (1) IndexedDB chhota cache (localStorage quota bhara ho tab bhi chale).
        // (2) "Pichhli baar ka result" snapshot: Circle/Division report kholte hi
        //     pichhla result (dhundhla, click band) turant dikhta hai, upar banner
        //     "naya data aa raha hai"; asli fresh result aate hi poori screen
        //     usi se badal jaati hai (numbers hamesha fresh hi final hote hain).
        // (3) Mobile: har DC ka compact summary (TOTAL + sirf wrong-candidate
        //     IVRS) - 27MB master download ka intezaar nahi; master background
        //     me aata hai, kuch badla ho to report khud dobara ban jaati hai.
        // =====================================================================
        var scIdbPromise_ = null;
        function scIdbOpen_() {
            if (scIdbPromise_) return scIdbPromise_;
            scIdbPromise_ = new Promise((resolve) => {
                let done = false;
                const finish = (db) => { if (!done) { done = true; resolve(db); } };
                setTimeout(() => finish(null), 2000);
                try {
                    const req = indexedDB.open("seoni-speed-cache-v1", 1);
                    req.onupgradeneeded = () => { try { req.result.createObjectStore("kv"); } catch (_) {} };
                    req.onsuccess = () => finish(req.result);
                    req.onerror = () => finish(null);
                    req.onblocked = () => finish(null);
                } catch (_) { finish(null); }
            });
            return scIdbPromise_;
        }
        async function scCacheGet_(key) {
            try {
                const db = await scIdbOpen_();
                if (!db) return null;
                return await new Promise((resolve) => {
                    try {
                        const r = db.transaction("kv", "readonly").objectStore("kv").get(key);
                        r.onsuccess = () => resolve(r.result === undefined ? null : r.result);
                        r.onerror = () => resolve(null);
                    } catch (_) { resolve(null); }
                });
            } catch (_) { return null; }
        }
        async function scCacheSet_(key, value) {
            try {
                const db = await scIdbOpen_();
                if (!db) return false;
                return await new Promise((resolve) => {
                    try {
                        const tx = db.transaction("kv", "readwrite");
                        tx.objectStore("kv").put(value, key);
                        tx.oncomplete = () => resolve(true);
                        tx.onerror = () => resolve(false);
                        tx.onabort = () => resolve(false);
                    } catch (_) { resolve(false); }
                });
            } catch (_) { return false; }
        }

        function scSnapshotKey_(extra) {
            const dateVal = (document.getElementById("report-date") || {}).value || "";
            return ["snap-v1", summaryModule, activeViewLevel, activeDiv || "", activeDC || "", summaryMode, dateVal, extra || ""].join("|");
        }
        // Pichhla result dikhata hai (agar ho) aur progress-bar ke liye ek chhota
        // host element lautata hai; na ho to null (tab purana normal flow).
        async function scShowSnapshot_(cont, key) {
            if (!cont || !key) return null;
            const snap = await scCacheGet_(key);
            if (!snap || !snap.html) return null;
            let when = "";
            try {
                const d = new Date(Number(snap.at || 0));
                when = `${String(d.getDate()).padStart(2, "0")}-${String(d.getMonth() + 1).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
            } catch (_) {}
            cont.innerHTML = `<div style="margin:4px 0 8px; padding:8px 10px; border:1px solid #fbbf24; background:#fffbeb; color:#92400e; border-radius:12px; font-size:0.66rem; font-weight:900; text-align:center; line-height:1.4;">🔄 Display Report Before 15 Min, Please wait for Latest Report</div><div class="sc-swr-progress"></div><div style="pointer-events:none; opacity:0.5; filter:grayscale(0.4);">${snap.html}</div>`;
            return cont.querySelector(".sc-swr-progress");
        }
        function scSaveSnapshot_(key, html) {
            if (!key || !html || html.length > 1500000) return;
            scCacheSet_(key, { html: String(html), at: Date.now() });
        }

        // ---- Mobile compact per-DC summary ----
        var mobileDcHeaderOnlyFlags_ = {};
        const MOBILE_DC_SUMMARY_KEY_PREFIX_ = "mobile-dc-summary-v1|";
        function buildMobileDcSummary_(rows, getMobile) {
            const freq = computeMobileDuplicateFreqMap(rows, getMobile);
            const cand = [];
            rows.forEach((row) => {
                const raw = getMobile(row);
                const ivrs = normalizeLookupDigits(getConsumerField(row, ["IVRS", "IVRS NO", "IVRS NUMBER", "IVRSNO"]));
                if (isMobileNoConsideredWrong(raw)) { cand.push([ivrs, 1, ""]); return; }
                const valid = normalizeRevenueMessageMobile(raw);
                if (valid && (freq[valid] || 0) > MOBILE_WRONG_DUPLICATE_THRESHOLD) cand.push([ivrs, 0, valid]);
            });
            return { v: 1, th: MOBILE_WRONG_DUPLICATE_THRESHOLD, tc: rows.length, cand, at: Date.now() };
        }
        // Wahi ginti jo getStats() poore master se nikalta hai - sirf candidates se.
        function computeMobileWrongFromDcSummary_(summary, fixedSet) {
            const active = (summary.cand || []).filter((c) => !(c[0] && fixedSet.has(c[0])));
            const freq = {};
            active.forEach((c) => { if (!c[1] && c[2]) freq[c[2]] = (freq[c[2]] || 0) + 1; });
            let tw = 0;
            active.forEach((c) => { if (c[1] || (freq[c[2]] || 0) > MOBILE_WRONG_DUPLICATE_THRESHOLD) tw++; });
            return { tc: Number(summary.tc) || 0, tw };
        }
        function isMobileDcSummaryUsable_(s) {
            return !!(s && s.v === 1 && s.th === MOBILE_WRONG_DUPLICATE_THRESHOLD && Array.isArray(s.cand));
        }
        async function loadMobileDcSummaryCacheMap_(dcNames) {
            const map = {};
            await Promise.all((dcNames || []).map(async (dc) => {
                const nd = normalizeDcName(dc);
                const s = await scCacheGet_(MOBILE_DC_SUMMARY_KEY_PREFIX_ + nd);
                if (isMobileDcSummaryUsable_(s)) map[nd] = s;
            }));
            return map;
        }
        function saveMobileDcSummaryIfChanged_(normDc, rows, getMobile, oldSummary) {
            if (!rows.length && !mobileDcHeaderOnlyFlags_[normDc]) return false;
            const fresh = buildMobileDcSummary_(rows, getMobile);
            const changed = !oldSummary || oldSummary.tc !== fresh.tc || JSON.stringify(oldSummary.cand) !== JSON.stringify(fresh.cand);
            if (changed) scCacheSet_(MOBILE_DC_SUMMARY_KEY_PREFIX_ + normDc, fresh);
            return changed;
        }
        function refreshMobileDcSummaryCacheInBackground_(dcNames, usedMap, isStillSameScreen) {
            ensureConsumerDataLoadedFor(dcNames).then(() => {
                const getMobile = (row) => getConsumerField(row, ["MOBILE NO", "MOBILE NUMBER", "MOBILE"]);
                let changed = false;
                dcNames.forEach((dc) => {
                    const nd = normalizeDcName(dc);
                    if (saveMobileDcSummaryIfChanged_(nd, getConsumerRows(nd), getMobile, usedMap[nd])) changed = true;
                });
                if (changed && isStillSameScreen()) refreshSummary();
            }).catch(() => {});
        }

        function buildRevenueConsumerMessage(row) {
            return `सम्मानीय उपभोक्ता - ${String(row?.consumerName || "उपभोक्ता").trim()} जी, आपका बिजली बिल ₹${String(row?.netBill || "0").trim()} है। IVRS: ${normalizeRevenueIvrs(row?.ivrsNo)}। कृपया समय पर भुगतान करें। — विद्युत वितरण केंद्र ${activeDC || revenueMessageSession?.staff?.dc_name || ""}`;
        }

        function toggleRevenueMessageConsumer(ivrsNo, checked) {
            const key = normalizeRevenueIvrs(ivrsNo);
            if (!key) return;
            if (!checked) {
                revenueMessageSelectedRows.delete(key);
                renderRevenuePendingList();
                return;
            }
            if (revenueMessageSelectedRows.size >= revenueMessageBatchLimit) {
                showToast(`A maximum of ${revenueMessageBatchLimit} consumers can be selected in one batch`, false);
                renderRevenuePendingList();
                return;
            }
            const row = getRevenueMessageAllowedRows(getRevenuePendingFilteredRows()).find((item) => normalizeRevenueIvrs(item.ivrsNo) === key);
            if (!row) return;
            const mobile = normalizeRevenueMessageMobile(row.mobileNo);
            if (!mobile) {
                showToast("This consumer does not have a valid 10-digit mobile number", false);
                renderRevenuePendingList();
                return;
            }
            revenueMessageSelectedRows.set(key, { ...row, mobileNo: mobile });
            renderRevenuePendingList();
        }

        function selectAllRevenueMessageFiltered() {
            const rows = getRevenueMessageAllowedRows(getRevenuePendingFilteredRows());
            revenueMessageSelectedRows = new Map();
            let invalidCount = 0;
            rows.forEach((row) => {
                if (revenueMessageSelectedRows.size >= revenueMessageBatchLimit) return;
                const mobile = normalizeRevenueMessageMobile(row.mobileNo);
                if (!mobile) {
                    invalidCount += 1;
                    return;
                }
                revenueMessageSelectedRows.set(normalizeRevenueIvrs(row.ivrsNo), { ...row, mobileNo: mobile });
            });
            renderRevenuePendingList();
            const limitNote = rows.length > revenueMessageBatchLimit ? ` First ${revenueMessageBatchLimit} valid consumers were selected.` : "";
            showToast(`${revenueMessageSelectedRows.size} consumers selected.${limitNote}${invalidCount ? ` ${invalidCount} invalid mobiles skipped.` : ""}`, true);
        }

        function clearRevenueMessageSelection() {
            revenueMessageSelectedRows = new Map();
            revenueMessageQueue = [];
            revenueMessageQueueIndex = 0;
            revenueMessageChannel = "";
            revenueMessageCurrentOpened = false;
            revenueMessageOpenedCount = 0;
            revenueMessageSkippedCount = 0;
            renderRevenuePendingList();
        }

        // USER REQUEST (2026-09-30): Kam technical staff ke liye ek-button WhatsApp batch.
        // Existing 25 limit, HQ access, manual Send aur per-consumer logging bilkul wahi rehte hain.
        async function startRevenueMessageEasyBatch(channel) {
            selectAllRevenueMessageFiltered();
            if (!revenueMessageSelectedRows.size) return;
            await startRevenueMessageQueue(channel);
        }

        function renderRevenueMessagePendingSelection(rows, statusBox, listBox) {
            const allowedRows = getRevenueMessageAllowedRows(rows);
            const selectedCount = revenueMessageSelectedRows.size;
            const visibleRows = allowedRows.slice(0, 50);
            statusBox.innerHTML = `Message Mode | Pending: <strong>${allowedRows.length}</strong> | Selected: <strong>${selectedCount}/${revenueMessageBatchLimit}</strong>`;

            const queueHtml = revenueMessageQueue.length ? renderRevenueMessageQueueHtml() : "";
            const consumerHtml = visibleRows.map((row) => {
                const ivrs = normalizeRevenueIvrs(row.ivrsNo);
                const mobile = normalizeRevenueMessageMobile(row.mobileNo);
                const checked = revenueMessageSelectedRows.has(ivrs);
                return `
                    <label style="display:block; margin-top:9px; background:#ffffff; border:1.5px solid ${checked ? "#22c55e" : "#cbd5e1"}; border-radius:15px; padding:11px; box-shadow:0 6px 14px rgba(15,23,42,0.05); cursor:${mobile ? "pointer" : "not-allowed"}; opacity:${mobile ? "1" : "0.62"};">
                        <div style="display:flex; gap:10px; align-items:flex-start;">
                            <input type="checkbox" ${checked ? "checked" : ""} ${mobile ? "" : "disabled"} onchange="toggleRevenueMessageConsumer('${ivrs}', this.checked)" style="width:20px; height:20px; margin-top:2px; accent-color:#16a34a;">
                            <div style="min-width:0; flex:1;">
                                <div style="font-size:0.8rem; font-weight:950; color:#0f172a;">${escapeHtml(row.consumerName || "-")}</div>
                                <div style="font-size:0.68rem; font-weight:800; color:#475569; margin-top:3px; line-height:1.45;">IVRS: ${escapeHtml(ivrs)} | Mobile: ${escapeHtml(mobile || "INVALID")}</div>
                                <div style="font-size:0.68rem; font-weight:850; color:#b45309; margin-top:2px;">HQ: ${escapeHtml(row.hqName || "-")} | Net Bill: ₹${escapeHtml(row.netBill || "0")}</div>
                            </div>
                        </div>
                    </label>
                `;
            }).join("");

            listBox.innerHTML = `
                <div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:16px; padding:11px;">
                    <div style="display:flex; gap:8px;">
                        <button onclick="selectAllRevenueMessageFiltered()" style="flex:1; min-height:42px; border:none; border-radius:12px; background:#16a34a; color:#fff; font-size:0.72rem; font-weight:950;">SELECT ALL FILTERED</button>
                        <button onclick="clearRevenueMessageSelection()" style="flex:0.75; min-height:42px; border:1.5px solid #fca5a5; border-radius:12px; background:#fff1f2; color:#b91c1c; font-size:0.72rem; font-weight:950;">CLEAR</button>
                    </div>
                    <button onclick="startRevenueMessageEasyBatch('WHATSAPP')" style="width:100%; min-height:48px; margin-top:8px; border:none; border-radius:13px; background:#15803d; color:#fff; font-size:0.78rem; font-weight:950;">EASY WHATSAPP: FIRST ${revenueMessageBatchLimit} CONSUMERS</button>
                    <div style="text-align:center; margin-top:5px; color:#166534; font-size:0.64rem; font-weight:850;">Press Start once. Then press NEXT WHATSAPP for each consumer.</div>
                    <div style="display:flex; gap:8px; margin-top:8px;">
                        <button onclick="startRevenueMessageQueue('SMS')" ${selectedCount ? "" : "disabled"} style="flex:1; min-height:44px; border:none; border-radius:12px; background:#2563eb; color:#fff; font-size:0.75rem; font-weight:950; opacity:${selectedCount ? "1" : "0.5"};">SEND BY SMS</button>
                        <button onclick="startRevenueMessageQueue('WHATSAPP')" ${selectedCount ? "" : "disabled"} style="flex:1; min-height:44px; border:none; border-radius:12px; background:#16a34a; color:#fff; font-size:0.75rem; font-weight:950; opacity:${selectedCount ? "1" : "0.5"};">SEND BY WHATSAPP</button>
                    </div>
                    <div style="text-align:center; margin-top:8px; color:#166534; font-size:0.68rem; font-weight:850;">Selected: ${selectedCount} | Maximum ${revenueMessageBatchLimit} per batch</div>
                </div>
                ${queueHtml}
                ${allowedRows.length > visibleRows.length ? `<div style="margin-top:10px; padding:9px; border-radius:12px; background:#fff7ed; color:#9a3412; font-size:0.68rem; font-weight:850; text-align:center;">Showing the first 50 consumers to keep the phone fast. Search a consumer by IVRS or filter.</div>` : ""}
                <div>${consumerHtml || `<div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.8rem; font-weight:900; text-align:center;">No valid pending consumer found in this filter.</div>`}</div>
            `;
        }

        async function startRevenueMessageQueue(channel) {
            if (!revenueMessageSession?.token) return openRevenueMessageCenter();
            const rows = Array.from(revenueMessageSelectedRows.values());
            if (!rows.length) return showToast("Please select a consumer first", false);
            const approved = await showCustomConfirmBox("Please Confirm", `Send message to ${rows.length} consumers through ${channel}?`);
            if (!approved) return;
            revenueMessageQueue = rows;
            revenueMessageQueueIndex = 0;
            revenueMessageChannel = channel;
            revenueMessageCurrentOpened = false;
            revenueMessageOpenedCount = 0;
            revenueMessageSkippedCount = 0;
            renderRevenuePendingList();
            showToast("Press the NEXT button below. The next consumer will be ready when you come back.", true);
        }

        function getCurrentRevenueMessageConsumer() {
            return revenueMessageQueue[revenueMessageQueueIndex] || null;
        }

        function renderRevenueMessageQueueHtml() {
            const row = getCurrentRevenueMessageConsumer();
            if (!row) return `
                <div style="margin-top:10px; background:#ecfdf5; border:1.5px solid #86efac; border-radius:15px; padding:12px; color:#166534; text-align:center; font-size:0.76rem; font-weight:900;">Quick batch complete<br><span style="font-size:0.7rem;">Opened for Send: ${revenueMessageOpenedCount} | Skipped: ${revenueMessageSkippedCount}</span></div>
            `;
            const messagePreview = buildRevenueConsumerMessage(row);
            return `
                <div id="revenue-message-queue-box" style="margin-top:10px; background:#eff6ff; border:1.5px solid #93c5fd; border-radius:16px; padding:12px;">
                    <div style="text-align:center; color:#1d4ed8; font-size:0.76rem; font-weight:950;">${escapeHtml(revenueMessageChannel)} | Consumer ${revenueMessageQueueIndex + 1} of ${revenueMessageQueue.length}</div>
                    <div style="margin-top:8px; background:#fff; border:1.5px solid #bfdbfe; border-radius:13px; padding:10px;">
                        <div style="color:#0f172a; font-size:0.8rem; font-weight:950;">TO: ${escapeHtml(row.consumerName || "-")}</div>
                        <div style="color:#1d4ed8; font-size:0.72rem; font-weight:900; margin-top:3px;">+91${escapeHtml(normalizeRevenueMessageMobile(row.mobileNo) || row.mobileNo || "-")}</div>
                        <div style="color:#475569; font-size:0.68rem; font-weight:850; margin-top:3px;">IVRS: ${escapeHtml(row.ivrsNo || "-")}</div>
                    </div>
                    <div style="margin-top:8px; background:#ffffff; border:1.5px dashed #93c5fd; border-radius:13px; padding:10px; color:#334155; font-size:0.7rem; font-weight:800; line-height:1.45; white-space:pre-wrap;">${escapeHtml(messagePreview)}</div>
                    <div style="margin-top:7px; color:#92400e; background:#fffbeb; border:1px solid #fde68a; border-radius:11px; padding:8px; text-align:center; font-size:0.65rem; font-weight:900;">Press the NEXT button below, send in WhatsApp/Messages and come Back. The next consumer will be ready automatically.</div>
                    <button id="revenue-message-open-send-btn" onclick="openCurrentRevenueMessageConsumer(this)" style="width:100%; height:50px; margin-top:9px; border:none; border-radius:12px; background:#15803d; color:#fff; font-size:0.8rem; font-weight:950;">NEXT ${escapeHtml(revenueMessageChannel)} (${revenueMessageQueueIndex + 1}/${revenueMessageQueue.length})</button>
                    <div style="display:flex; gap:7px; margin-top:7px;">
                        <button onclick="skipRevenueMessageConsumer()" style="flex:1; min-height:42px; border:1.5px solid #fdba74; border-radius:12px; background:#fff7ed; color:#c2410c; font-size:0.68rem; font-weight:950;">SKIP THIS CONSUMER</button>
                    </div>
                    <button onclick="stopRevenueMessageQueue()" style="width:100%; height:38px; margin-top:7px; border:1.5px solid #fca5a5; border-radius:12px; background:#fff1f2; color:#b91c1c; font-size:0.68rem; font-weight:950;">STOP BATCH</button>
                </div>
            `;
        }

        function refreshRevenueMessageQueuePanel() {
            const box = document.getElementById("revenue-message-queue-box");
            if (!box) return;
            box.outerHTML = renderRevenueMessageQueueHtml();
        }

        async function openCurrentRevenueMessageConsumer(button) {
            if (revenueMessageOpenInProgress) return;
            const row = getCurrentRevenueMessageConsumer();
            if (!row) return finishRevenueMessageQueue();
            const mobile = normalizeRevenueMessageMobile(row.mobileNo);
            if (!mobile) return skipRevenueMessageConsumer("INVALID MOBILE");
            const message = buildRevenueConsumerMessage(row);
            revenueMessageOpenInProgress = true;
            const openButton = button || document.getElementById("revenue-message-open-send-btn");
            if (openButton) {
                openButton.disabled = true;
                openButton.style.opacity = "0.7";
                openButton.innerText = `OPENING ${revenueMessageChannel}...`;
            }
            showToast(`Opening ${revenueMessageChannel}...`, true);

            // Native SMS/WhatsApp ko backend response ka wait karaye bina turant kholen.
            logRevenueMessageActivity(row, "OPENED FOR SEND", message).catch(() => {});
            revenueMessageOpenedCount += 1;
            revenueMessageQueueIndex += 1;
            revenueMessageCurrentOpened = false;
            refreshRevenueMessageQueuePanel();

            await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
            if (revenueMessageChannel === "WHATSAPP") {
                revenueMessageOpenInProgress = false;
                window.location.href = `https://wa.me/91${mobile}?text=${encodeURIComponent(message)}`;
                return;
            }

            const smsNumber = `+91${mobile}`;
            if (navigator.clipboard?.writeText) navigator.clipboard.writeText(message).catch(() => {});
            const isApple = /iPhone|iPad|iPod/i.test(navigator.userAgent || "");
            if (isApple) {
                showToast("Message copied. Paste it in the SMS app and send.", true);
                revenueMessageOpenInProgress = false;
                window.location.href = `sms:${smsNumber}`;
            } else {
                showToast("SMS is opening for +91 number. The message is also copied to the clipboard.", true);
                revenueMessageOpenInProgress = false;
                window.location.href = `sms:${smsNumber}?body=${encodeURIComponent(message)}`;
            }
        }

        function skipRevenueMessageConsumer(status = "SKIPPED") {
            const row = getCurrentRevenueMessageConsumer();
            if (row) logRevenueMessageActivity(row, status, buildRevenueConsumerMessage(row)).catch(() => {});
            revenueMessageSkippedCount += 1;
            revenueMessageQueueIndex += 1;
            revenueMessageCurrentOpened = false;
            if (revenueMessageQueueIndex >= revenueMessageQueue.length) return finishRevenueMessageQueue();
            renderRevenuePendingList();
        }

        function stopRevenueMessageQueue() {
            revenueMessageQueue = [];
            revenueMessageQueueIndex = 0;
            revenueMessageChannel = "";
            revenueMessageCurrentOpened = false;
            revenueMessageOpenedCount = 0;
            revenueMessageSkippedCount = 0;
            renderRevenuePendingList();
            showToast("Message batch stopped", false);
        }

        function finishRevenueMessageQueue() {
            const completed = revenueMessageQueue.length;
            revenueMessageQueueIndex = revenueMessageQueue.length;
            revenueMessageCurrentOpened = false;
            renderRevenuePendingList();
            showToast(`Quick batch complete: ${revenueMessageOpenedCount} opened, ${revenueMessageSkippedCount} skipped`, true);
        }

        function logRevenueMessageActivity(row, logStatus, message) {
            if (!revenueMessageSession?.token || !row) return Promise.reject(new Error("Staff session is missing"));
            return postRevenueMessageStaffApi({
                action: "staffLogMessage",
                session_token: revenueMessageSession.token,
                device_id: getRevenueMessageDeviceId(),
                dc_name: activeDC || revenueMessageSession.staff?.dc_name || "",
                ivrs_no: row.ivrsNo || "",
                consumer_name: row.consumerName || "",
                mobile_no: row.mobileNo || "",
                net_bill: row.netBill || "",
                channel: revenueMessageChannel,
                log_status: logStatus,
                message
            });
        }

        async function initRevenuePendingList() {
            // USER REQUEST (2026-09-24): Pending DO List card ke upar "DC NAME - ..."
            const dcNameBox_ = document.getElementById("revenue-pending-dc-name");
            if (dcNameBox_) dcNameBox_.textContent = activeDC ? `DC NAME - ${activeDC}` : "";
            const statusBox = document.getElementById("revenue-pending-status");
            const listBox = document.getElementById("revenue-pending-list-box");
            const hqSelect = document.getElementById("revenue-pending-hq");
            const refreshToken = ++revenuePendingPaidRefreshToken;
            // Baaki reports (Live Progress, HQ/Village, Cash Reconcile) jaisa hi animated
            // syncing bar - pehle yahan sirf static "load ho rahi hai..." text tha.
            const isPendingRenderValid = () => refreshToken === revenuePendingPaidRefreshToken && document.getElementById("revenue-pending-list-view")?.classList.contains("active");
            let pendingListProgress = null;
            if (statusBox) {
                statusBox.style.display = "block";
                pendingListProgress = renderSyncingProgress(statusBox, isPendingRenderValid, "SYNCING DATA... PLEASE WAIT");
            }
            if (listBox) listBox.innerHTML = "";
            populateRevenueSelect(hqSelect, [], revenueHqAllLabel());
            populateRevenueSelect(document.getElementById("revenue-pending-village"), [], revenueVillageAllLabel());
            populateRevenueSelect(document.getElementById("revenue-pending-category"), [], "All Categories");
            // NOTE: pehle yahan turant local/purana paid-set (getRevenuePendingPaidIvrsSetLocal)
            // laga ke list render kar dete the, aur sahi (uploaded cash list wala) paid-set
            // background me chhup ke baad me update hota tha - isse "Pending Consumer: ..."
            // wala number pehle GALAT dikhta tha, phir kisi dropdown ko chhedne par hi sahi
            // hota tha (jaisa aapne report kiya). Ab Daily Progress jaisa hi strict flow hai:
            // jab tak dono - base consumer rows AUR sahi paid-set (uploaded cash list) - fetch
            // hoke ready nahi ho jaate, tab tak syncing bar hi dikhta rahega (1 se 99 dhire
            // dhire, 99 par pahunch ke blink), display kabhi bhi galat number nahi dikhayega.
            try {
                // Pending DO List ka paid/unpaid rule ab HQ/Village Paid-Unpaid
                // MONTHLY report jaisa hi canonical Cash List reconciliation hai.
                // Paid-by-Staff rows, local all-time cache, aur duplicate raw
                // master rows ko yahan jaan-boojhkar use nahi karte.
                const [_, paidSet] = await Promise.all([
                    ensureRevenueCategoryMasterDataLoadedStrict_([activeDC]),
                    getRevenuePendingCashListPaidIvrsSet_()
                ]);
                // BUG FIX (2026-09-24, USER-REPORTED "15 sec ki jagah 1 min+ aur GANESHGANJ
                // master load error"): Line TD sync (80s+ lag sakta hai) ko upar Promise.all
                // me INTEZAAR me daal diya gaya tha - list ruk jaati thi aur saath chalte
                // requests timeout ho jaate the. Ab TD sync sirf BACKGROUND me chalta hai
                // (list pehle jaisi turant khulti hai, local TD data se); sync poora hone par
                // agar user abhi bhi isi screen par hai to list chup-chaap dobara render hoti hai.
                syncRevenueTdEntriesFromSheet(3, false, activeDC).then(() => {
                    if (refreshToken === revenuePendingPaidRefreshToken && document.getElementById("revenue-pending-list-view")?.classList.contains("active")) scheduleRevenuePendingRender(0);
                }).catch(() => {});
                if (refreshToken !== revenuePendingPaidRefreshToken) { if (pendingListProgress) pendingListProgress.stop(); return; }
                revenuePendingPaidIvrsSet = paidSet;
                // Bade DC (SEONI (T) jaise) me kabhi-kabhi backend se poori "paid" list
                // sync fail ho jaati hai (network/timeout) aur app chup-chap adhura/local
                // data dikha deta - isse Pending count galat (bahut zyada) dikhta tha
                // bina kisi warning ke. Ab agar poora backend sync nahi ho paaya to
                // status line me saaf warning dikhayenge, taaki number par bharosa na
                // kiya jaaye aur user dobara try kar sake.
                revenuePendingPaidDataIncomplete = false;
                // Same DC+IVRS canonical master list jo HQ/Village report use
                // karti hai. Isse Total = Paid + Pending invariant dono reports
                // me same consumer universe par chalega.
                const loadedRows = getRevenueMasterRowsForDc(activeDC);
                revenuePendingDiag.masterRows = loadedRows.length;
                const assignedHq = revenueMessageSelectionMode ? String(revenueMessageSession?.staff?.hq_name || "").trim() : "";
                revenuePendingBaseRows = loadedRows.filter((row) => (
                    getRevenuePendingNetBillAmount(row) > 0
                    && (!assignedHq || normalizeLookupValue(row.hqName) === normalizeLookupValue(assignedHq))
                ));
                revenuePendingIndex = buildRevenuePendingIndex(revenuePendingBaseRows);
                populateRevenueSelect(hqSelect, assignedHq ? [assignedHq] : getRevenueUniqueValues(revenuePendingBaseRows, "hqName"), assignedHq ? `Assigned ${revenueHqLabel()}` : revenueHqAllLabel());
                if (hqSelect) {
                    hqSelect.value = assignedHq || "";
                    hqSelect.disabled = !!assignedHq;
                    hqSelect.style.opacity = assignedHq ? "0.75" : "1";
                }
                const villageSelect = document.getElementById("revenue-pending-village");
                const categorySelect = document.getElementById("revenue-pending-category");
                populateRevenueSelect(villageSelect, getRevenueUniqueValues(revenuePendingBaseRows, "village"), revenueVillageAllLabel());
                populateRevenueSelect(categorySelect, getRevenueUniqueValues(revenuePendingBaseRows, "tariffCategory"), "All Categories");
                if (villageSelect) villageSelect.value = "";
                if (categorySelect) categorySelect.value = "";
                const slabSelect = document.getElementById("revenue-pending-arrears-slab");
                if (slabSelect) slabSelect.value = "";
                const ivrsSearch = document.getElementById("revenue-pending-ivrs-search");
                if (ivrsSearch) ivrsSearch.value = "";
                if (pendingListProgress) await pendingListProgress.finish();
                if (refreshToken !== revenuePendingPaidRefreshToken) return;
                renderRevenuePendingList();
            } catch (error) {
                if (pendingListProgress) pendingListProgress.stop();
                if (statusBox) {
                    statusBox.style.display = "block";
                    statusBox.innerHTML = escapeHtml(error?.message || "Pending list could not be loaded. Please check internet and try again.");
                }
            }
        }

        function buildRevenuePendingIndex(rows) {
            const index = { hqMap: new Map(), villageMap: new Map(), categoryMap: new Map(), rowsMap: new Map() };
            (rows || []).forEach((row) => {
                if (getRevenuePendingNetBillAmount(row) <= 0) return;
                const hqName = String(row.hqName || "").trim();
                const village = String(row.village || "").trim();
                const category = String(row.tariffCategory || "").trim();
                if (!hqName || !village || !category) return;

                const hqKey = normalizeLookupValue(hqName);
                const villageKey = normalizeLookupValue(village);
                const categoryKey = normalizeLookupValue(category);
                const hqVillageKey = `${hqKey}||${villageKey}`;
                const fullKey = `${hqVillageKey}||${categoryKey}`;

                index.hqMap.set(hqKey, hqName);
                if (!index.villageMap.has(hqKey)) index.villageMap.set(hqKey, new Map());
                index.villageMap.get(hqKey).set(villageKey, village);
                if (!index.categoryMap.has(hqVillageKey)) index.categoryMap.set(hqVillageKey, new Map());
                index.categoryMap.get(hqVillageKey).set(categoryKey, category);
                if (!index.rowsMap.has(fullKey)) index.rowsMap.set(fullKey, []);
                index.rowsMap.get(fullKey).push(row);
            });
            return index;
        }

        function getRevenuePendingNetBillAmount(row) {
            const raw = String(row?.netBill ?? row?.net_bill ?? row?.["NET BILL"] ?? "").trim();
            if (!raw) return 0;
            const cleaned = raw.replace(/,/g, "").replace(/[^0-9.+-]/g, "");
            let amount = Number(cleaned);
            if (!Number.isFinite(amount)) return 0;
            if (/^\s*\(.*\)\s*$/.test(raw) && amount > 0) amount = -amount;
            if (/\bCR\b/i.test(raw) && amount > 0) amount = -amount;
            return amount;
        }

        function populateRevenueSelect(selectEl, values, placeholder) {
            if (!selectEl) return;
            selectEl.innerHTML = `<option value="">${escapeHtml(placeholder)}</option>` + (values || []).map((value) => {
                return `<option value="${escapeHtml(value)}">${escapeHtml(value)}</option>`;
            }).join("");
        }

        function getRevenueUniqueValues(rows, key) {
            return Array.from(new Set((rows || []).map((row) => String(row[key] || "").trim()).filter(Boolean)))
                .sort((a, b) => a.localeCompare(b));
        }

        function onRevenuePendingHqChange() {
            const hqValue = document.getElementById("revenue-pending-hq")?.value || "";
            const scopedRows = revenuePendingBaseRows.filter((row) => (
                !hqValue || normalizeLookupValue(row.hqName) === normalizeLookupValue(hqValue)
            ));
            populateRevenueSelect(document.getElementById("revenue-pending-village"), getRevenueUniqueValues(scopedRows, "village"), revenueVillageAllLabel());
            populateRevenueSelect(document.getElementById("revenue-pending-category"), getRevenueUniqueValues(scopedRows, "tariffCategory"), "All Categories");
            renderRevenuePendingList();
        }

        function onRevenuePendingVillageChange() {
            const hqValue = document.getElementById("revenue-pending-hq")?.value || "";
            const villageValue = document.getElementById("revenue-pending-village")?.value || "";
            const scopedRows = revenuePendingBaseRows.filter((row) => (
                (!hqValue || normalizeLookupValue(row.hqName) === normalizeLookupValue(hqValue))
                && (!villageValue || normalizeLookupValue(row.village) === normalizeLookupValue(villageValue))
            ));
            populateRevenueSelect(document.getElementById("revenue-pending-category"), getRevenueUniqueValues(scopedRows, "tariffCategory"), "All Categories");
            renderRevenuePendingList();
        }

        function scheduleRevenuePendingRender(delay = 60) {
            clearTimeout(revenuePendingRenderTimer);
            revenuePendingRenderTimer = setTimeout(() => {
                revenuePendingRenderTimer = 0;
                renderRevenuePendingList();
            }, delay);
        }

        function isRevenuePendingNetBillInSlab(row, slabValue) {
            if (!slabValue) return true;
            const amount = getRevenuePendingNetBillAmount(row);
            if (slabValue === "0-500") return amount >= 0 && amount <= 500;
            if (slabValue === "500-1000") return amount > 500 && amount <= 1000;
            if (slabValue === "1000-5000") return amount > 1000 && amount <= 5000;
            if (slabValue === "5000-10000") return amount > 5000 && amount <= 10000;
            if (slabValue === "10000-25000") return amount > 10000 && amount <= 25000;
            if (slabValue === "25000+") return amount > 25000;
            return true;
        }

        // ISOLATED ADDITION (2026-09-24, USER REQUEST): Pending DO List me Line TD
        // filter (All / Pending No Action / TD) + download me "TD DATE / TIME" column.
        // getRevenuePendingFilteredRows() jaan-boojh kar NAHI chheda - Revenue Message
        // Center bhi use karta hai; TD filter sirf Pending DO List screen + download par.
        // Jama karne wala consumer pehle ki tarah list se hat hi jaata hai (TD ho chuka ho tab bhi).
        function getRevenuePendingTdMap_() {
            const dcKey = normalizeLookupValue(activeDC || "");
            const map = new Map();
            (getRevenueTdEntriesLocal() || []).forEach((entry) => {
                if (normalizeLookupValue(entry.dcName || "") !== dcKey) return;
                const ivrs = normalizeRevenueIvrs(entry.ivrsNo);
                if (!ivrs) return;
                const sortKey = `${revenueUploadDateKey_(entry.tdDate || "")} ${String(formatRevenuePaidTime(entry.tdTime || "") || "").padStart(5, "0")}`;
                const prev = map.get(ivrs);
                if (!prev || sortKey > prev.sortKey) map.set(ivrs, { sortKey, date: entry.tdDate || "", time: formatRevenuePaidTime(entry.tdTime || "") || "" });
            });
            return map;
        }

        function getRevenuePendingTdText_(tdInfo) {
            if (!tdInfo) return "";
            return `TD: ${String(tdInfo.date || "-").replace(/\//g, "-")}${tdInfo.time ? " " + tdInfo.time : ""}`;
        }

        function applyRevenuePendingTdFilter_(rows) {
            const tdValue = document.getElementById("revenue-pending-td")?.value || "";
            if (!tdValue) return rows;
            const tdMap = getRevenuePendingTdMap_();
            return (rows || []).filter((row) => {
                const hasTd = tdMap.has(normalizeRevenueIvrs(row.ivrsNo));
                return tdValue === "TD" ? hasTd : !hasTd;
            });
        }

        function getRevenuePendingFilteredRows() {
            const hqValue = document.getElementById("revenue-pending-hq")?.value || "";
            const villageValue = document.getElementById("revenue-pending-village")?.value || "";
            const categoryValue = document.getElementById("revenue-pending-category")?.value || "";
            const slabValue = document.getElementById("revenue-pending-arrears-slab")?.value || "";
            const govtValue = document.getElementById("revenue-pending-govt")?.value || "";
            const ivrsSearch = normalizeRevenueIvrs(document.getElementById("revenue-pending-ivrs-search")?.value || "");
            return revenuePendingBaseRows.filter((row) => {
                const ivrsNo = normalizeRevenueIvrs(row.ivrsNo);
                return ivrsNo
                    && getRevenuePendingNetBillAmount(row) > 0
                    && (!ivrsSearch || ivrsNo.includes(ivrsSearch))
                    && (!hqValue || normalizeLookupValue(row.hqName) === normalizeLookupValue(hqValue))
                    && (!villageValue || normalizeLookupValue(row.village) === normalizeLookupValue(villageValue))
                    && (!categoryValue || normalizeLookupValue(row.tariffCategory) === normalizeLookupValue(categoryValue))
                    && isRevenuePendingNetBillInSlab(row, slabValue)
                    && (!govtValue || (govtValue === "GOVT" ? !!row.govtFlag : !row.govtFlag))
                    && !isRevenuePendingIvrsPaid(ivrsNo);
            }).sort((a, b) => {
                const nameCompare = String(a.consumerName || "").trim().localeCompare(
                    String(b.consumerName || "").trim(),
                    "en",
                    { sensitivity: "base", numeric: true }
                );
                if (nameCompare !== 0) return nameCompare;
                return normalizeRevenueIvrs(a.ivrsNo).localeCompare(normalizeRevenueIvrs(b.ivrsNo), "en", { numeric: true });
            });
        }

        function isRevenuePendingIvrsPaid(ivrsNo) {
            const normalizedIvrs = normalizeRevenueIvrs(ivrsNo);
            if (!normalizedIvrs) return true;
            return revenuePendingPaidIvrsSet.has(normalizedIvrs);
        }

        function renderRevenuePendingList() {
            const statusBox = document.getElementById("revenue-pending-status");
            const listBox = document.getElementById("revenue-pending-list-box");
            const hqValue = document.getElementById("revenue-pending-hq")?.value || "";
            const villageValue = document.getElementById("revenue-pending-village")?.value || "";
            const categoryValue = document.getElementById("revenue-pending-category")?.value || "";
            const slabValue = document.getElementById("revenue-pending-arrears-slab")?.value || "";
            const govtValue = document.getElementById("revenue-pending-govt")?.value || "";
            const govtLabel = govtValue === "GOVT" ? "Govt" : (govtValue === "NONGOVT" ? "Non Govt" : "ALL");
            const ivrsSearch = normalizeRevenueIvrs(document.getElementById("revenue-pending-ivrs-search")?.value || "");
            if (!statusBox || !listBox) return;

            const allFilteredRows_ = getRevenuePendingFilteredRows();
            if (revenueMessageSelectionMode) {
                renderRevenueMessagePendingSelection(allFilteredRows_, statusBox, listBox);
                return;
            }
            // USER REQUEST (2026-09-24): Line TD filter sirf is screen + download par
            const rows = applyRevenuePendingTdFilter_(allFilteredRows_);
            const tdMapForStatus_ = getRevenuePendingTdMap_();
            const tdDoneCount_ = rows.filter((row) => tdMapForStatus_.has(normalizeRevenueIvrs(row.ivrsNo))).length;
            const tdFilterValue_ = document.getElementById("revenue-pending-td")?.value || "";
            const tdLabel_ = tdFilterValue_ === "TD" ? "TD" : (tdFilterValue_ === "NOACTION" ? "Pending (No Action)" : "ALL");
            const incompleteWarning = revenuePendingPaidDataIncomplete ? `
                <div style="background:#fff1f2; border:1.5px solid #fda4af; border-radius:12px; padding:10px; color:#991b1b; font-size:0.74rem; font-weight:900; text-align:center; margin-bottom:8px;">
                    ⚠️ Paid (Cash List) data could not be fully synced - this number may be wrong / higher. Please check internet and return to this report to sync again.
                </div>
            ` : "";
            // Deep-diagnostic line - SEONI (T) jaisi galat count wali DC me exactly
            // yeh dekhne ke liye ki dikkat kahan hai: Master (total consumer jinka
            // net bill > 0 hai), Uploaded Cash List fetch (backend se jitne "paid"
            // rows mile), aur Live entries (app se manually paid). Agar Uploaded
            // Fetch bahut kam/0 hai to backend/sheet me dikkat hai; agar fetch to
            // poora hai lekin fir bhi Pending zyada hai to IVRS format/matching me
            // dikkat hai.
            const diagLine = `<div style="font-size:0.66rem; color:#64748b; margin-top:4px;">Diagnostic - Canonical Master: ${revenuePendingDiag.masterRows} | Cash List Paid (current month): ${revenuePendingDiag.uploadedFetched} | Paid-by-Staff: not used</div>`;
            statusBox.innerHTML = `${incompleteWarning}Pending Consumer: <strong>${rows.length}</strong> | HQ: ${escapeHtml(hqValue || "ALL")} | Village: ${escapeHtml(villageValue || "ALL")} | Category: ${escapeHtml(categoryValue || "ALL")} | Net Bill Slab: ${escapeHtml(slabValue || "ALL")} | Type: ${escapeHtml(govtLabel)} | TD Filter: ${escapeHtml(tdLabel_)} | IVRS: ${escapeHtml(ivrsSearch || "ALL")}<div style="font-size:0.72rem; font-weight:950; color:#dc2626; margin-top:4px;">Line TD done (in this list): ${tdDoneCount_} | Pending (No Action): ${rows.length - tdDoneCount_}</div>${diagLine}`;
            listBox.innerHTML = rows.length ? `
                <div style="display:flex; gap:10px; width:100%; margin:0 auto;">
                    <button id="revenue-pending-pdf-btn" onclick="downloadRevenuePendingList('PDF')" style="flex:1; height:44px; border:none; border-radius:14px; background:#ef4444; color:#ffffff; font-size:0.78rem; font-weight:950;">PDF</button>
                    <button id="revenue-pending-excel-btn" onclick="downloadRevenuePendingList('EXCEL')" style="flex:1; height:44px; border:none; border-radius:14px; background:#16a34a; color:#ffffff; font-size:0.78rem; font-weight:950;">EXCEL</button>
                </div>
                <div id="revenue-pending-download-status" style="display:none; margin-top:10px; border-radius:14px; padding:10px; background:#eff6ff; border:1.5px solid #93c5fd; color:#1d4ed8; font-size:0.76rem; font-weight:950; text-align:center;">Downloading...</div>
            ` : `
                <div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.8rem; font-weight:900; text-align:center;">No pending consumer found in this filter.</div>
            `;
            setRevenuePendingDownloadState(false, "", true);
        }

        function getRevenuePendingExportHeaders() {
            return ["S.NO", "IVRS NO", "CONSUMER NAME", "FATHER NAME", revenueVillageLabelUpper(), revenueHqLabelUpper(), "TARRIF CATEGORY", "GOVT/NON GOVT", "MOBILE NO", "ARREARS", "NET BILL", "TD DATE / TIME"];
        }

        function getRevenuePendingExportRows(rows) {
            const tdMap_ = getRevenuePendingTdMap_();
            return (rows || []).map((row, index) => [
                index + 1, row.ivrsNo || "",
                row.consumerName || "",
                row.fatherName || "",
                row.village || "",
                row.hqName || "",
                row.tariffCategory || "",
                row.govtFlag ? "GOVT" : "NON GOVT",
                row.mobileNo || "",
                row.arrears || "",
                row.netBill || "",
                getRevenuePendingTdText_(tdMap_.get(normalizeRevenueIvrs(row.ivrsNo)))
            ]);
        }

        function getRevenuePendingFileName() {
            const hqValue = document.getElementById("revenue-pending-hq")?.value || "ALL-HQ";
            const villageValue = document.getElementById("revenue-pending-village")?.value || "ALL-VILLAGES";
            const categoryValue = document.getElementById("revenue-pending-category")?.value || "ALL-CATEGORIES";
            const slabValue = document.getElementById("revenue-pending-arrears-slab")?.value || "ALL-NET-BILL";
            const govtValue = document.getElementById("revenue-pending-govt")?.value || "ALL-TYPE";
            const tdValue = document.getElementById("revenue-pending-td")?.value || "";
            return `pending-list-${activeDC || "DC"}-${hqValue}-${villageValue}-${categoryValue}-${slabValue}-${govtValue}${tdValue ? "-" + tdValue : ""}`.replace(/[\\/:*?"<>|]+/g, "_");
        }

        function setRevenuePendingDownloadState(isLoading, message = "", ok = true) {
            revenuePendingDownloadInProgress = isLoading;
            scApplyDownloadBoxState_("revenue-pending", isLoading, message, ok);
        }

        function downloadRevenuePendingList(type) {
            if (revenuePendingDownloadInProgress) return showToast("Download in progress, please wait", false);
            const rows = applyRevenuePendingTdFilter_(getRevenuePendingFilteredRows()); // USER REQUEST (2026-09-24): TD filter bhi
            if (!rows.length) return showToast("No data in the pending list", false);
            const headers = getRevenuePendingExportHeaders();
            const exportRows = getRevenuePendingExportRows(rows);
            const title = `Pending DO List - ${activeDC || ""}`;

            setRevenuePendingDownloadState(true, "Download in progress... please wait", true);
            setTimeout(() => {
                try {
                    if (type === "PDF") {
                        if (!window.jspdf || !window.jspdf.jsPDF) {
                            setRevenuePendingDownloadState(false, "PDF library could not be loaded", false);
                            return showToast("PDF library could not be loaded", false);
                        }
                        const { jsPDF } = window.jspdf;
                        const doc = new jsPDF("l", "mm", "a4");
                        scPdfHeader_(doc, { title, lines: [], focus: { hq: (document.getElementById("revenue-pending-hq")?.value || "") } }); // SC PDF KIT
                        doc.setFontSize(8.5);
                        doc.setTextColor(51, 65, 85);
                        // BUG FIX (2026-09-24, USER-REPORTED header overlap): status text ab kai line
                        // ka hai (filters + TD count + diagnostic) - pehle table hamesha y=34 se
                        // shuru hota tha aur lines uske upar chadh jaati thi. Ab text ko page
                        // width me wrap karke, jitni lines baniin utni jagah chhod kar table shuru.
                        const pendingHeaderLines_ = doc.splitTextToSize((document.getElementById("revenue-pending-status")?.innerText || "").replace(/\n+/g, "\n"), 268);
                        doc.text(pendingHeaderLines_, 10, 19);
                        doc.autoTable({
                            startY: 19 + pendingHeaderLines_.length * 4.2 + 2,
                            head: [headers],
                            body: exportRows,
                            theme: "grid",
                            headStyles: { fillColor: [251, 146, 60], textColor: 255, halign: "center" },
                            styles: { fontSize: 7, cellPadding: 1.6, halign: "center" },
                            columnStyles: {
                                1: { halign: "left" },
                                2: { halign: "left" },
                                3: { halign: "left" },
                                4: { halign: "left" }
                            },
                            // USER REQUEST (2026-09-24): TD DATE / TIME wala text laal (red)
                            didParseCell: (hook) => {
                                if (hook.section === "body" && hook.column.index === headers.length - 1 && String(hook.cell.raw || "")) {
                                    hook.cell.styles.textColor = [220, 38, 38];
                                    hook.cell.styles.fontStyle = "bold";
                                }
                            }
                        });
            savePdfDocumentForDevice(doc, `${getRevenuePendingFileName()}.pdf`);
                        setRevenuePendingDownloadState(false, "PDF downloaded", true);
                        showToast("Pending PDF downloaded", true);
                        return;
                    }

                    const csv = [[scPdfFocusTitle_(title, { hq: (document.getElementById("revenue-pending-hq")?.value || "") })], [], headers, ...exportRows] // 2026-09-27: PDF jaisa title
                        .map((items) => items.map((item) => `"${String(item || "").replace(/"/g, '""')}"`).join(","))
                        .join("\n");
                    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
                    const link = document.createElement("a");
                    link.href = URL.createObjectURL(blob);
                    link.download = `${getRevenuePendingFileName()}.csv`;
                    link.click();
                    setTimeout(() => URL.revokeObjectURL(link.href), 1000);
                    setRevenuePendingDownloadState(false, "Excel downloaded", true);
                    showToast("Pending Excel downloaded", true);
                } catch (error) {
                    setRevenuePendingDownloadState(false, "Download failed, please try again", false);
                    showToast(error?.message || "Pending report download failed", false);
                }
            }, 80);
        }

        // Pending DO List deliberately has no date/month control. Its fixed
        // period is the current calendar month, matching the default current-
        // month HQ/Village Paid-Unpaid report. Only Cash List reconciliation is
        // authoritative here; Paid-by-Staff and local all-time cache are excluded.
        async function getRevenuePendingCashListPaidIvrsSet_() {
            const paidSet = new Set();
            const dcName = normalizeDcName(activeDC || "");
            const currentMonth = getTodayIsoDate().slice(0, 7);
            const reconciliation = await ensureRevenueCategoryReconciliationLoaded("MONTHLY", currentMonth);
            if (!reconciliation?.supported) {
                throw new Error("Cash List reconciliation backend is not available; Pending DO List is not shown using the old mixed logic.");
            }
            reconciliation.byKey.forEach((info, key) => {
                const separator = key.indexOf("|");
                if (separator < 0) return;
                const rowDc = key.slice(0, separator);
                const ivrsNo = key.slice(separator + 1);
                // Partial ho ya full: HQ/Village monthly report ki tarah ek
                // valid positive Cash List payment consumer ko PAID banati hai.
                if (rowDc === dcName && ivrsNo && scCountableReconAmount_(rowDc, ivrsNo, info) > 0) paidSet.add(ivrsNo); // PAID DATE RULE
            });
            revenuePendingDiag.liveTotal = 0;
            revenuePendingDiag.liveDcMatched = 0;
            revenuePendingDiag.uploadedFetched = paidSet.size;
            return paidSet;
        }

        // Legacy helper retained only for backward compatibility with any old
        // caller. Pending DO List no longer calls it because it mixed Staff and
        // all-time Cash List data, which could not match the canonical report.
        async function getRevenuePendingPaidIvrsSet() {
            const paidSet = new Set();
            try {
                // NOTE (bug fix): yahan pehle sirf 3.5 second ka withTimeout tha - Live
                // Entries endpoint SABHI DC ka combined data ek saath deta hai, bade DC
                // (jaise SEONI (T)) ke waqt is response me itna time lag jaata tha ki
                // 3.5 second me timeout ho jaata aur purana/khali local cache (getRevenueLiveEntries)
                // turant fallback ho jaata - isi wajah se sync "turant 100%" dikhta tha
                // lekin asal me sahi data sync hi nahi hota tha, aur bahut saare already-paid
                // consumer galti se "pending" dikh jaate the (jaise 1200 ki jagah 19276).
                // BUG FIX (user report): 45-second cap bhi bade DC (SEONI (T),
                // 34,000+ consumer) ke liye kaafi nahi tha - syncRevenueLiveEntriesFromSheet
                // apne andar hi 3 attempt + retry-delay karta hai, jisse poora sync
                // 45 second se zyada le sakta hai, aur bahar ka timeout use beech me
                // hi cut karke adhura local data thop deta tha. Ab koi outer timeout
                // nahi laga rahe - syncRevenueLiveEntriesFromSheet() ko jitna time
                // chahiye utna lene denge (uske apne 3 attempt khud hi ek waqt ke
                // baad give up kar dete hain), taaki bade DC me bhi poora sahi data
                // mile chahe thoda zyada time lage.
                // SPEED FIX (2026-09-15, USER-REPORTED slowness): yeh call bina
                // scopeDc ke poori Circle (sabhi 24 DC) ki Live Entries fetch karti
                // thi, jabki Pending DO List hamesha sirf `activeDC` ke liye hi
                // dikhti hai (neeche saara matching activeDC se hi hota hai) - Daily
                // Progress (Revenue tab) me already isi tarah `scopeDc` diya jaata
                // hai (`revenueSummaryScopeDc` dekhein) - wahi proven, safe pattern
                // yahan bhi. `syncRevenueLiveEntriesFromSheet` khud hi apni scope-
                // tracking (`revenueLiveEntriesCachedScopeDc`) rakhta hai, isliye
                // agar kisi aur report ne pehle hi POORI (sabhi-DC) fetch kar rakhi
                // ho to wahi turant reuse ho jaayegi - dobara scoped fetch nahi
                // hogi. `activeDC` khaali ho (kabhi is screen ko Division/Circle
                // scope me khola jaaye) to `scopeDc` bhi khaali jaayega, matlab
                // pehle jaisa hi (poora) fetch hoga - koi regression nahi.
                const liveRows = await syncRevenueLiveEntriesFromSheet(3, false, activeDC || null);
                revenuePendingDiag.liveTotal = liveRows.length;
                let liveDcMatched = 0;
                liveRows.forEach((row) => {
                    if (normalizeLookupValue(row.dcName || "") === normalizeLookupValue(activeDC || "")) {
                        liveDcMatched++;
                        const ivrsNo = normalizeRevenueIvrs(row.ivrsNo);
                        if (ivrsNo) paidSet.add(ivrsNo);
                    }
                });
                revenuePendingDiag.liveDcMatched = liveDcMatched;
            } catch (_) {}

            // NOTE: pehle yahan uploaded-paid-entries fetch ko sirf 3.5 second ka
            // withTimeout diya hua tha (bina retry ke) - chhoti DC ke liye theek chal
            // jaata tha, lekin bade DC (jaise KURAI - 7700+ rows) me Apps Script se itna
            // bada sheet padhne me 3.5 second se zyada time lagta hai, isliye timeout ho
            // jaata tha aur purana/khali local cache use hota tha - matlab Cash List
            // upload karne ke baad bhi Pending DO List me wahi consumer "pending" dikhte
            // rehte the jo asal me pehle hi paid ho chuke the. Ab yahan bhi Category
            // Wise/HQ-Village report jaisa hi robust fetch (45 second + 2 retry) use
            // karte hain, taaki bade DC ke liye bhi latest uploaded paid data sahi mile.
            const uploadedRows = await getRevenueUploadedPaidMasterRows();
            revenuePendingDiag.uploadedFetched = uploadedRows.length;
            uploadedRows.forEach((row) => {
                const ivrsNo = normalizeRevenueIvrs(row.ivrs_no || row.ivrsNo || row.consumerNo);
                if (ivrsNo) paidSet.add(ivrsNo);
            });
            return paidSet;
        }

        function getRevenueUploadedPaidMasterRowsLocal() {
            const cache = getRevenueUploadedPaidCache();
            return Object.values(cache).filter((row) => normalizeLookupValue(row.dcName || row.dc_name || "") === normalizeLookupValue(activeDC || ""));
        }

        function withTimeout(promise, ms, fallbackValue) {
            return new Promise((resolve) => {
                let done = false;
                const timer = setTimeout(() => {
                    if (done) return;
                    done = true;
                    resolve(fallbackValue);
                }, ms);
                Promise.resolve(promise).then((value) => {
                    if (done) return;
                    done = true;
                    clearTimeout(timer);
                    resolve(value);
                }).catch(() => {
                    if (done) return;
                    done = true;
                    clearTimeout(timer);
                    resolve(fallbackValue);
                });
            });
        }

        // Cash Reconcile aur Pending DO List dono isi function se "uploaded cash
        // list" (kaun-kaun paid hai NGB me) laate hain. Pehle har call par poora
        // backend fetch hota tha, isliye ek report me sync hone ke baad dusri
        // report par jaane par bhi dobara fetch hota tha. Ab DC-scoped 60-second
        // shared TTL cache hai - same DC ke liye 60 second ke andar dusri report
        // usi cache ko turant reuse karegi.
        let revenueUploadedPaidMasterRowsCache = null; // { dcKey, rows, syncedAt, backendSynced }
        // RESTORED (user confirmed root cause tha NGB Cash List upload data
        // replace kar deta tha, is caching me koi dikkat nahi thi) - DC-scoped
        // shared 60-second TTL cache wapas ON hai.
        const REVENUE_UPLOADED_PAID_MASTER_SYNC_TTL_MS = 60000;
        // In-flight fetch dedupe (per-DC) - same reason as revenueLiveEntriesSyncFetchPromise
        // upar: DC-select ke background warming aur user ka khud kisi report par
        // jaana (jo yahi function call karta hai) dono ek hi chal rahi backend
        // request share karein, dobara alag fetch shuru na ho.
        const revenueUploadedPaidMasterFetchPromises = {};

        async function getRevenueUploadedPaidMasterRows(forceRefresh = false) {
            const dcKey = normalizeLookupValue(activeDC || "");
            if (!forceRefresh && revenueUploadedPaidMasterFetchPromises[dcKey]) {
                return revenueUploadedPaidMasterFetchPromises[dcKey];
            }
            if (!forceRefresh && revenueUploadedPaidMasterRowsCache
                && revenueUploadedPaidMasterRowsCache.dcKey === dcKey
                && revenueUploadedPaidMasterRowsCache.backendSynced
                && Date.now() - revenueUploadedPaidMasterRowsCache.syncedAt < REVENUE_UPLOADED_PAID_MASTER_SYNC_TTL_MS) {
                return revenueUploadedPaidMasterRowsCache.rows;
            }
            revenueUploadedPaidMasterFetchPromises[dcKey] = getRevenueUploadedPaidMasterRowsInner_(dcKey, forceRefresh).finally(() => {
                delete revenueUploadedPaidMasterFetchPromises[dcKey];
            });
            return revenueUploadedPaidMasterFetchPromises[dcKey];
        }

        async function getRevenueUploadedPaidMasterRowsInner_(dcKey, forceRefresh) {
            // NOTE (bug fix): pehle yahan har outcome - chahe backend se poora sync
            // safal hua ho ya (bade DC jaise SEONI (T) me) fetch fail/timeout hoke
            // sirf adhura local fallback mila ho - dono ko ek jaisa 60-second "fresh"
            // cache maan liya jaata tha. Isse agar ek baar sync fail ho jaaye to
            // adhuri paid list (bahut kam ya khali) 60 second tak "sahi/fresh" maan
            // kar Pending DO List/Cash Reconcile jaisi SABHI reports me reuse hoti
            // rahti thi - jisse Pending count bahut zyada galat (jaise 1200 ki jagah
            // 19276) dikhta tha. Ab sirf backendSynced:true wale cache ko hi "fresh"
            // maante hain; adhura/fallback result cache to hota hai (turant dikhane
            // ke liye) lekin usko fresh nahi maana jaata, isliye agla call turant
            // dobara backend se poora sahi data laane ki koshish karega.
            // (Freshness check outer getRevenueUploadedPaidMasterRows() me already
            // ho chuki hai, yahan dobara nahi karte.)
            // Upload ke turant baad local cache me entries turant save ho jaati hain
            // (saveRevenueUploadedPaidEntriesLocalBulk), backend fetch se pehle hi -
            // isliye yahan backend call se pehle current local rows capture kar lete
            // hain, taaki agar backend response us waqt thoda incomplete/stale aaye
            // (jaise abhi-abhi upload hui bade DC ki list, ya koi backend delay) to
            // bhi turant-upload hui entries paid-set se chhoote na. Isse Pending DO
            // List me abhi-abhi paid hue consumer galti se "pending" nahi dikhenge.
            const localRowsBeforeSync = getRevenueUploadedPaidMasterRowsLocal();
            if (revenueCollectionSubmitScriptUrl) {
                try {
                    // Sirf "kaun paid hai" pata karne ke liye halka (dc_name + ivrs_no +
                    // uploaded_date) response fetch karte hain - bade DC me bhi fast aur
                    // reliable. NOTE: is response ko purane full-detail local cache
                    // (getRevenueUploadedPaidEntryLocal - jo search/amount display me
                    // kaam aata hai) me save NAHI karte, kyunki yeh data lean hai; usse
                    // save karne se poori detail (amount/payment_rows) overwrite ho
                    // jaati - baaki features (Search screen paid-amount display) us
                    // alag, already-working upload-flow cache par hi depend karte rahenge.
                    const parsed = await fetchUploadedPaidIvrsListWithRetry_(activeDC || "");
                    const rows = Array.isArray(parsed?.entries) ? parsed.entries : (Array.isArray(parsed?.data) ? parsed.data : []);
                    if (parsed && parsed.status === "success" && rows.length) {
                        const backendRows = rows.filter((row) => normalizeLookupValue(row.dc_name || activeDC || "") === normalizeLookupValue(activeDC || ""));
                        // Backend rows + turant-upload hui local rows ko IVRS ke hisaab
                        // se merge (union) karte hain - kisi bhi ek source par poori tarah
                        // depend nahi karte, taaki koi bhi paid consumer chhoote nahi.
                        const merged = new Map();
                        localRowsBeforeSync.forEach((row) => {
                            const key = normalizeRevenueIvrs(row.ivrs_no || row.ivrsNo || row.consumerNo);
                            if (key) merged.set(key, row);
                        });
                        backendRows.forEach((row) => {
                            const key = normalizeRevenueIvrs(row.ivrs_no || row.ivrsNo || row.consumerNo);
                            if (key) merged.set(key, row);
                        });
                        const finalRows = Array.from(merged.values());
                        revenueUploadedPaidMasterRowsCache = { dcKey, rows: finalRows, syncedAt: Date.now(), backendSynced: true };
                        return finalRows;
                    }
                } catch (_) {}
            }
            // Backend se poora sync nahi ho paaya (fail/timeout/purana backend) -
            // turant dikhane ke liye local fallback rows cache to karte hain, lekin
            // backendSynced:false rakhte hain taaki isse "fresh"/authoritative na
            // maana jaaye aur agla call turant fir se poora backend fetch try kare.
            revenueUploadedPaidMasterRowsCache = { dcKey, rows: localRowsBeforeSync, syncedAt: Date.now(), backendSynced: false };
            return localRowsBeforeSync;
        }

        // User request: DC select karte hi (app khulte hi), background me chup-chap
        // (bina UI block kiye, koi progress bar dikhaye bina) in teeno shared
        // cache (Live Entries, TD Entries, Uploaded Paid Master) ko warm kar dete
        // hain. Isse agar user Revenue me paid entry bhar kar turant Pending DO
        // List / Cash Reconcile / Live Progress / Date-Month Wise Report kisi bhi
        // report par jaaye, to backend se data pehle hi (poora ya kam se kam
        // shuru ho chuka) sync mil jaata hai - report khulne me kam ya bilkul
        // time nahi lagta, kyunki shared 60-second TTL cache (upar dekhein) usi
        // pehle se warm data ko reuse kar leta hai.
        // PERF FIX (2026-08-20, Point 1): pehle yahan hamesha SABHI 24 DC ka poora
        // data background me fetch hota tha (chahe user ek hi DC dekhne wala ho) -
        // isliye "background syncing" se bhi actual load time me zyada fark nahi
        // padta tha, kyunki background wala fetch bhi utna hi bhaari/slow tha.
        // Ab agar hum sach me ek DC ke context me hain (activeDC set hai aur
        // dcName wahi DC hai, "CIRCLE"/"DIVISION" jaisa scope-level string nahi),
        // to sirf usi DC ka data maangte hain (poori history, date-filter nahi -
        // kyunki Report Download/Progress Report ko purane mahino ka data bhi
        // chahiye hota hai) - 24 DC ki jagah 1 DC, isliye bahut fast. Circle/
        // Division level warm-up abhi bhi purane (sabhi DC) tarike se hi hota
        // hai kyunki wahan sach me sabhi DC ka data chahiye hota hai.
        function prefetchRevenueBackgroundDataForDc(dcName) {
            if (!dcName || !revenueCollectionSubmitScriptUrl) return;
            const scopeDc = (activeDC && normalizeDcName(dcName) === normalizeDcName(activeDC)) ? activeDC : null;
            Promise.all([
                syncRevenueLiveEntriesFromSheet(3, false, scopeDc),
                syncRevenueTdEntriesFromSheet(3, false, scopeDc),
                getRevenueUploadedPaidMasterRows()
            ]).catch(() => {});
        }

        function initRevenuePaidUpload() {
            const dcLabel = document.getElementById("revenue-paid-upload-dc");
            const lockBox = document.getElementById("revenue-admin-lock-box");
            const uploadPanel = document.getElementById("revenue-paid-upload-panel");
            const passwordInput = document.getElementById("revenue-admin-password");
            if (dcLabel) dcLabel.innerText = `DC: ${activeDC || "-"}`;
            if (passwordInput) passwordInput.value = "";
            if (revenuePaidUploadUnlocked) {
                if (lockBox) lockBox.style.display = "none";
                if (uploadPanel) uploadPanel.style.display = "block";
            } else {
                if (lockBox) lockBox.style.display = "block";
                if (uploadPanel) uploadPanel.style.display = "none";
            }
            setRevenuePaidUploadStatus("", true, false);
            const localMeta = getRevenuePaidUploadMeta(activeDC || "");
            renderRevenuePaidUploadSummary(localMeta);
            // Upload summary is local-first: is device ka purana/cached summary
            // turant dikhta hai (taaki panel khulte hi khaali na lage), lekin
            // saath hi background me backend se fresh/confirmed summary bhi
            // fetch karte hain.
            // USER REQUEST (2026-09-21): pehle yeh backend-fetch kabhi call hi
            // nahi hoti thi (function bana hua tha par istemal nahi ho raha
            // tha), isliye yahan hamesha purana local data hi dikhta rehta tha,
            // chahe backend par asal me kuch aur ho. Ab panel khulte hi neeche
            // "lal patti" (Revenue Collection ki tarah) spinner ke saath dikhti
            // hai jab tak backend se confirm na ho jaaye - isse user ko pata
            // chalta hai ki abhi jo summary dikh rahi hai wo purani ho sakti
            // hai, wait karna hai.
            refreshRevenuePaidUploadSummaryFromBackend_(activeDC || "");
        }

        let revenuePaidUploadSummaryFetchRunId_ = 0;

        async function refreshRevenuePaidUploadSummaryFromBackend_(dcName) {
            const banner = document.getElementById("revenue-paid-upload-summary-fetch-banner");
            const bannerText = document.getElementById("revenue-paid-upload-summary-fetch-text");
            if (!banner || !dcName) return;
            const runId = ++revenuePaidUploadSummaryFetchRunId_;
            if (bannerText) bannerText.innerText = "Fetching Last Upload Summary from backend, please stay on this screen...";
            banner.style.display = "block";
            try {
                const serverMeta = await fetchRevenuePaidUploadSummaryFromServer(dcName);
                if (runId !== revenuePaidUploadSummaryFetchRunId_ || activeDC !== dcName) return;
                if (serverMeta) {
                    // USER REQUEST (2026-09-21): fetchRevenuePaidUploadSummaryFromServer
                    // backend ka jo bhi "latest" entry mile use hamesha backendSynced:true
                    // maan leta hai - chahe wo AAJ ke pending upload ka na ho, kisi PURANE
                    // din ka ho. Agar abhi local summary genuinely "99% pending" dikha rahi
                    // hai (matlab abhi-abhi ek upload hua hai jiska backend confirm nahi
                    // hua), to is fetch ko use kabhi "100% Successfully Uploaded" me upgrade
                    // nahi karna - warna aaj ka pending upload chhup kar purane din ka
                    // "success" galti se dikhega. Sirf tabhi overwrite karte hain jab ya to
                    // pehle se koi pending state hai hi nahi, ya backend ka latest data
                    // SACH ME AAJ (isi upload) ka hai.
                    const existingMeta = getRevenuePaidUploadMeta(dcName);
                    const existingPending = existingMeta && existingMeta.backendSynced === false;
                    const todayNow = new Date();
                    const todayDDMMYYYY = `${String(todayNow.getDate()).padStart(2, "0")}-${String(todayNow.getMonth() + 1).padStart(2, "0")}-${todayNow.getFullYear()}`;
                    const serverDatePart = String(serverMeta.uploadedAtDisplay || "").split(" ")[0];
                    const serverIsFromToday = serverDatePart === todayDDMMYYYY;
                    if (!existingPending || serverIsFromToday) {
                        saveRevenuePaidUploadMeta(serverMeta);
                        renderRevenuePaidUploadSummary(serverMeta);
                    }
                    // existingPending true aur serverIsFromToday false ho to - purani
                    // "99% Verification Pending" summary hi sach hai, usse chhedte nahi.
                }
                // serverMeta null hone par (backend par aaj tak kabhi upload
                // nahi hua, ya fetch fail hui) purani local summary jo already
                // dikh rahi hai wahi rehne dete hain - kuch todte nahi.
            } catch (_) {
                // Chup-chaap ignore - local summary jaisi hai waisi dikhti rahegi.
            } finally {
                if (runId === revenuePaidUploadSummaryFetchRunId_) banner.style.display = "none";
            }
        }

        async function unlockRevenuePaidUpload() {
            const input = document.getElementById("revenue-admin-password");
            const password = String(input?.value || "").trim();
            if (!password) return showToast("Enter password", false);
            // USER REQUEST (2026-09-26): sirf sahi password se khule
            const vr = await scVerifyAdminPassword_(revenueCollectionSubmitScriptUrl, { action: "verifyAdminPassword", type: "revenue", admin_password: password });
            if (vr === "wrong" || vr === "net") { scAdminPwdFailToast_(vr); if (vr === "wrong" && input) input.value = ""; return; }
            // USER DECISION (2026-09-21): Paid Master Upload ka password ab
            // yahan frontend me fixed check nahi hota - jo bhi type kiya jaaye,
            // wahi neeche admin_password field me backend ko bhejte hain; asli
            // check poori tarah backend (Script Property REV_REVENUE_ADMIN_
            // PASSWORD) par hota hai. Galat password se panel khul jaayega,
            // lekin asli Upload galat password se fail hoga.
            revenuePaidUploadPasswordEntered = password;
            revenuePaidUploadUnlocked = true;
            initRevenuePaidUpload();
            showToast("Admin upload unlocked", true);
        }

        function setRevenuePaidUploadStatus(message, ok = true, show = true) {
            const statusBox = document.getElementById("revenue-paid-upload-status");
            if (!statusBox) return;
            statusBox.style.display = show ? "block" : "none";
            statusBox.style.background = ok ? "#ecfdf5" : "#fff1f2";
            statusBox.style.border = `1.5px solid ${ok ? "#86efac" : "#fda4af"}`;
            statusBox.style.color = ok ? "#14532d" : "#991b1b";
            statusBox.innerHTML = message;
        }

        // USER REQUEST (2026-09-24): Cash List upload ka % ab baaki "SYNCING" reports
        // jaisa DHEERE-DHEERE badhta hai (seedha 70 par nahi kudta), neeche
        // "CASH LIST UPLOADING... PLEASE WAIT" aur chalta hua seconds-timer dikhta hai.
        // SIRF DISPLAY badla hai - upload/verification ka koi logic nahi chhua:
        // asli milestone (5/18/32/45/60/70/72/.../99/100) wahi hain, dikhne wala %
        // unki taraf dheere chalta hai aur beech me intezaar ke waqt thoda-thoda
        // aage creep karta hai (kabhi peeche nahi jaata, 99 se upar nahi jaata jab
        // tak asli 100 na aaye). Upload khatam (100 / PENDING / error) hote hi ruk jaata hai.
        var revenuePaidUploadAnim_ = null;

        function stopRevenuePaidUploadAnim_() {
            if (revenuePaidUploadAnim_ && revenuePaidUploadAnim_.timer) clearInterval(revenuePaidUploadAnim_.timer);
            revenuePaidUploadAnim_ = null;
        }

        function setRevenuePaidUploadProgress(percent, message, ok = true) {
            const safePercent = Math.max(0, Math.min(100, Math.round(Number(percent) || 0)));
            const msgText = String(message || "Uploading...");
            const isFinal = safePercent >= 100 || /PENDING|SUCCESSFULLY/i.test(msgText) || !revenuePaidUploadInProgress;
            let anim = revenuePaidUploadAnim_;
            if (!anim || !document.getElementById(anim.id)) {
                stopRevenuePaidUploadAnim_();
                anim = revenuePaidUploadAnim_ = { id: `rpu-anim-${Date.now()}`, startedAt: Date.now(), shown: 0, target: 0, timer: null };
            }
            anim.target = safePercent;
            if (isFinal) anim.shown = safePercent;
            const shownNow = Math.floor(isFinal ? safePercent : Math.max(anim.shown, 0));
            const secs = Math.round((Date.now() - anim.startedAt) / 1000);
            const barColor = safePercent === 100 ? "#16a34a" : "#2563eb";
            setRevenuePaidUploadStatus(`
                <div id="${anim.id}" style="text-align:center;">
                <div style="font-size:0.82rem; font-weight:950; margin-bottom:8px; text-align:center;">${escapeHtml(msgText)}</div>
                <div style="height:14px; border-radius:999px; overflow:hidden; background:#dbeafe; border:1px solid #93c5fd;">
                    <div id="${anim.id}-bar" style="height:100%; width:${shownNow}%; background:${barColor}; transition:width 0.35s ease;"></div>
                </div>
                <div id="${anim.id}-pct" style="font-size:1rem; font-weight:1000; margin-top:6px; text-align:center;">${shownNow}%</div>
                ${isFinal ? (revenuePaidUploadInProgress ? `<div style="font-size:0.7rem; font-weight:850; color:#64748b; margin-top:4px; text-align:center;">⏱️ Total time: ${secs}s</div>` : "") : `
                <div style="font-size:0.74rem; font-weight:950; color:#1d4ed8; margin-top:6px; text-align:center;">CASH LIST UPLOADING... PLEASE WAIT</div>
                <div id="${anim.id}-sec" style="font-size:0.7rem; font-weight:850; color:#64748b; margin-top:2px; text-align:center;">⏱️ ${secs}s</div>`}
                </div>
            `, ok, true);
            if (isFinal) { stopRevenuePaidUploadAnim_(); return; }
            if (!anim.timer) {
                anim.timer = setInterval(() => {
                    const a = revenuePaidUploadAnim_;
                    if (!a || !document.getElementById(a.id)) { stopRevenuePaidUploadAnim_(); return; }
                    if (a.shown < a.target) {
                        a.shown = Math.min(a.target, a.shown + Math.max(0.6, (a.target - a.shown) * 0.12));
                    } else {
                        // Intezaar ke dauraan dheere creep: agle milestone se pehle ruk jaata hai
                        const cap = a.target >= 70 ? 98 : Math.min(98, a.target + 9);
                        if (a.shown < cap) a.shown = Math.min(cap, a.shown + Math.max(0.03, (cap - a.shown) * 0.004));
                    }
                    const val = Math.floor(a.shown);
                    const bar = document.getElementById(`${a.id}-bar`);
                    const pct = document.getElementById(`${a.id}-pct`);
                    const sec = document.getElementById(`${a.id}-sec`);
                    if (bar) bar.style.width = `${val}%`;
                    if (pct) pct.textContent = `${val}%`;
                    if (sec) sec.textContent = `⏱️ ${Math.round((Date.now() - a.startedAt) / 1000)}s`;
                }, 300);
            }
        }

        function getRevenuePaidUploadMeta(dcName = activeDC) {
            try {
                const allMeta = JSON.parse(localStorage.getItem(revenuePaidUploadMetaStorageKey) || "{}") || {};
                return allMeta[normalizeLookupValue(dcName || "")] || null;
            } catch (_) {
                return null;
            }
        }

        function saveRevenuePaidUploadMeta(meta) {
            try {
                const allMeta = JSON.parse(localStorage.getItem(revenuePaidUploadMetaStorageKey) || "{}") || {};
                allMeta[normalizeLookupValue(meta.dcName || activeDC || "")] = meta;
                localStorage.setItem(revenuePaidUploadMetaStorageKey, JSON.stringify(allMeta));
            } catch (_) {}
        }

        function formatRevenueUploadDateTime(value) {
            const date = value instanceof Date ? value : new Date(value);
            if (Number.isNaN(date.getTime())) return "-";
            const dd = String(date.getDate()).padStart(2, "0");
            const mm = String(date.getMonth() + 1).padStart(2, "0");
            const yyyy = date.getFullYear();
            const hh = String(date.getHours()).padStart(2, "0");
            const min = String(date.getMinutes()).padStart(2, "0");
            return `${dd}-${mm}-${yyyy} ${hh}:${min}`;
        }

        // User-facing date/time display: always Indian numeric format.
        function formatIndianDateTimeDisplay_(dateValue, timeValue = "") {
            const rawDate = String(dateValue || "").trim();
            const datePart = rawDate.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
            // BUG FIX (2026-09-21, USER REPORT): backend (Master Backend ka
            // REV_formatDate_ ho ya OMVIG ka Utilities.formatDate) hamesha
            // "dd/MM/yyyy" (din pehle - Indian order) bhejta hai. Yahan pehle
            // group[1] aur group[2] ko HAMESHA swap kar diya jaata tha (jaise
            // input MM/DD ho) - isse ek sahi "19/09/2026" (19 Sept) ulta hoke
            // "09-19-2026" (galat, mahina 19 ban jaata) dikhta tha. Backend ka
            // din-pehle order already sahi hai, ise dobara swap nahi karna.
            const normalized = datePart
                ? `${datePart[1].padStart(2, "0")}-${datePart[2].padStart(2, "0")}-${datePart[3]}`
                : normalizeRevenueReportDate(rawDate);
            let dateText = normalized ? normalized : rawDate;
            if (dateText.includes("/")) dateText = dateText.replaceAll("/", "-");
            const timeText = formatRevenuePaidTime(timeValue || (rawDate.match(/\b\d{1,2}:\d{2}(?::\d{2})?\b/) || [""])[0]);
            return dateText ? `${dateText}${timeText && timeText !== "-" ? ` ${timeText}` : ""}` : "-";
        }

        function renderRevenuePaidUploadSummary(meta) {
            const summaryBox = document.getElementById("revenue-paid-upload-summary");
            if (!summaryBox) return;
            if (!meta) {
                summaryBox.style.display = "none";
                summaryBox.innerHTML = "";
                return;
            }
            const lastUploadText = meta.uploadedAtDisplay || formatRevenueUploadDateTime(meta.uploadedAt);
            summaryBox.style.display = "block";
            summaryBox.innerHTML = `
                <div style="font-size:0.78rem; font-weight:950; color:#166534; text-align:center; margin-bottom:8px;">Last Upload Summary</div>
                <div><strong>Selected DC:</strong> ${escapeHtml(meta.dcName || "-")}</div>
                <div><strong>Record Count:</strong> ${escapeHtml(meta.uniqueCount || "0")} Unique IVRS</div>
                <div><strong>Normal Rows:</strong> ${escapeHtml(meta.normalRows || "0")} | <strong>AG Rows:</strong> ${escapeHtml(meta.agRows || "0")}</div>
                <div><strong>Last Upload:</strong> ${escapeHtml(lastUploadText)}</div>
                <div><strong>Old Data Status:</strong> ${meta.oldDataReplaced ? "Old data replaced" : "Old data not replaced"}</div>
                <div><strong>Upload Progress:</strong> ${meta.backendSynced ? "100%" : "99%"}</div>
                <div><strong>Backend Status:</strong> ${meta.backendSynced ? "Successfully Uploaded" : "Verification pending"}</div>
                ${meta.backendSynced && meta.backendRowsSaved !== null && meta.backendRowsSaved !== undefined ? `
                <div style="margin-top:6px; padding:6px 8px; border-radius:10px; background:#dcfce7; color:#166534; font-weight:800;">Backend confirmed: ${escapeHtml(meta.backendNormalRows)} Normal IVRS newly saved + ${escapeHtml(meta.backendAgRowsUpdated)} AG IVRS updated | Total ${escapeHtml(meta.backendRowsSaved)} rows in sheet</div>` : ""}
                ${meta.backendSynced && meta.backendConfirmedBy === "VERIFICATION" ? `
                <div style="margin-top:6px; padding:6px 8px; border-radius:10px; background:#dcfce7; color:#166534; font-weight:800;">All ${escapeHtml(meta.uniqueCount || "0")} IVRS of this upload were found in the backend with today's upload date (confirmed by verification)</div>` : ""}
                ${!meta.backendSynced ? `
                <div style="margin-top:6px; padding:6px 8px; border-radius:10px; background:#fef3c7; color:#92400e; font-weight:800;">This upload is not confirmed in the backend yet. The app will keep checking in the background for about 5 minutes. If it still shows this after 10 minutes, please upload again.</div>` : ""}
            `;
        }

        function convertUploadedDateToDDMMYYYY(value) {
            // Backend ne "uploaded_date" DD/MM/YYYY text bhejne ki koshish karta hai,
            // lekin Google Sheet ka locale kabhi-kabhi is string ko date samajh kar
            // MM/DD ulta kar deta tha (jaise 03/08/2026 -> 08/03/2026 store ho jaata
            // tha) - confirmed via actual backend response. Backend script me ab yeh
            // column plain-text force kar diya hai (naye uploads se yeh bug nahi
            // aayega), lekin pehle se corrupt ho chuki purani entries ke liye yahan
            // month/day swap karke DD/MM/YYYY wapas banate hain.
            const raw = String(value || "").trim();
            const match = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
            if (!match) return normalizeRevenueReportDate(raw);
            const month = match[1].padStart(2, "0");
            const day = match[2].padStart(2, "0");
            const year = match[3];
            return `${day}/${month}/${year}`;
        }

        // USER REQUEST (2026-09-21): CHHAPARA-1 jaisi badi DC me Cash List upload ke
        // baad backend verification me kaafi time lagta hai. Pehle is dauraan
        // (checkRevenueUploadFreshness chal rahi ho tab) box hidden hi rehta tha -
        // lagta tha jaise kuch ho hi nahi raha, aur agar yeh check khud fail/timeout
        // ho jaaye to bhi box hide ho jaata tha (matlab galti se "sab thik hai" jaisa
        // dikhta tha). runId race-guard rakha hai taaki DC jaldi-jaldi switch karne
        // par purani (slow) check ka result naye DC ki screen par overwrite na kare.
        let revenueUploadFreshnessRunId_ = 0;

        async function checkRevenueUploadFreshness() {
            // USER REQUEST (2026-09-21): DC dashboard par "Revenue Collection"
            // button ke NEECHE jo alag/standalone red patti (ticker box) thi, use
            // PERMANENTLY hata diya gaya hai (index.html se bhi element hata diya).
            // Ab sirf button ke ANDAR wala chhota blink text rahega - yahi wahi
            // hai jo user ne "REVENUE KE UNDER" bola tha, use vaisa hi rehne diya.
            const inline = document.getElementById("revenue-upload-freshness-inline");
            if (!inline) return;
            const dcName = activeDC;
            if (!dcName || !revenueCollectionSubmitScriptUrl) {
                inline.style.display = "none";
                return;
            }
            const runId = ++revenueUploadFreshnessRunId_;
            const today = new Date();
            const todayDDMMYYYY = `${String(today.getDate()).padStart(2, "0")}/${String(today.getMonth() + 1).padStart(2, "0")}/${today.getFullYear()}`;

            // NOTE: pehle yahan ek alag backend action "getPaidMasterLastUploadDate" call
            // hoti thi, jo Cash List upload ho jaane ke baad bhi kabhi-kabhi purani/galat
            // date laut rahi thi (isliye upload ho jaane par bhi warning ticker chhupta
            // nahi tha). Ab usi proven, already-tested action ("getUploadedPaidEntries")
            // se check karte hain jo Category Wise/HQ-Village reports me hamesha sahi
            // latest uploaded data deta hai - agar aaj ki date ka koi bhi entry mil jaaye
            // to ticker turant chhup jayega.
            try {
                const parsed = await fetchUploadedPaidIvrsListWithRetry_(normalizeDcName(dcName), 1);
                if (activeDC !== dcName || runId !== revenueUploadFreshnessRunId_) return;
                const entries = Array.isArray(parsed?.entries) ? parsed.entries : (Array.isArray(parsed?.data) ? parsed.data : []);
                const uploadedToday = parsed?.status === "success" && entries.some((entry) => {
                    const rawDate = String(entry?.uploaded_date || entry?.uploadedDate || "").trim();
                    if (!rawDate) return false;
                    // Dono tarah check karte hain (jaisa aaya waisa, aur month/day
                    // swap karke) - taaki purani (Sheet-locale se corrupt hui) aur
                    // nayi (backend fix ke baad sahi text-format) dono tarah ki
                    // dates ke liye "aaj upload hua" sahi pehchana jaaye. NOTE:
                    // normalizeRevenueReportDate DD-MM-YYYY (dash) format deta hai,
                    // isliye formatRevenueDateIndian se slash format me convert karna
                    // zaroori hai - yahi missing step tha jiski wajah se pichhli baar
                    // sahi data hone ke bawajood bhi ticker match nahi ho pa raha tha.
                    return formatRevenueDateIndian(normalizeRevenueReportDate(rawDate)) === todayDDMMYYYY
                        || convertUploadedDateToDDMMYYYY(rawDate) === todayDDMMYYYY;
                });
                if (uploadedToday) {
                    inline.style.display = "none";
                    return;
                }
                inline.innerText = "Today's Cash List is not uploaded";
                inline.style.display = "block";
            } catch (_) {
                if (activeDC !== dcName || runId !== revenueUploadFreshnessRunId_) return;
                // USER REQUEST (2026-09-21): pehle yahan check fail/timeout hone par
                // ticker poori tarah hide ho jaata tha - jaise upload sab thik ho gaya
                // ho, chahe asal me status pata hi na chal paaya ho. Ab clearly bata
                // dete hain ki confirm nahi ho paaya, taaki galti se "safe" na lage.
                inline.innerText = "⚠️ Status could not be confirmed";
                inline.style.display = "block";
            }
        }

        // USER REQUEST (2026-09-22): "aaj ki Cash List Upload nahi hui" wali
        // red patti ab Revenue Collection ki IVRS SEARCH screen par, DC name
        // chip ke UPAR dikhti hai (pehle yah DC dashboard par Revenue button
        // ke neeche standalone box ke roop me thi - vahan se yahan shift ki
        // gayi hai). Flow bilkul checkRevenueUploadFreshness() jaisa hi hai
        // (backend se aaj ka upload-status check, upload na mile tabhi
        // dikhna) - lekin yah apna ALAG element/runId use karta hai taaki
        // Revenue button ke ANDAR wale blink text (revenue-upload-freshness-
        // inline, jo checkRevenueUploadFreshness() handle karta hai) par
        // iska koi asar na pade - usse bilkul chheda nahi gaya hai.
        let revenueSearchUploadFreshnessRunId_ = 0;

        async function checkRevenueSearchUploadFreshness() {
            const box = document.getElementById("revenue-search-upload-freshness-ticker");
            if (!box) return;
            const dcName = activeDC;
            if (!dcName || !revenueCollectionSubmitScriptUrl) {
                box.style.display = "none";
                return;
            }
            const runId = ++revenueSearchUploadFreshnessRunId_;
            const today = new Date();
            const todayDDMMYYYY = `${String(today.getDate()).padStart(2, "0")}/${String(today.getMonth() + 1).padStart(2, "0")}/${today.getFullYear()}`;
            try {
                const parsed = await fetchUploadedPaidIvrsListWithRetry_(normalizeDcName(dcName), 1);
                if (activeDC !== dcName || runId !== revenueSearchUploadFreshnessRunId_) return;
                const entries = Array.isArray(parsed?.entries) ? parsed.entries : (Array.isArray(parsed?.data) ? parsed.data : []);
                const uploadedToday = parsed?.status === "success" && entries.some((entry) => {
                    const rawDate = String(entry?.uploaded_date || entry?.uploadedDate || "").trim();
                    if (!rawDate) return false;
                    return formatRevenueDateIndian(normalizeRevenueReportDate(rawDate)) === todayDDMMYYYY
                        || convertUploadedDateToDDMMYYYY(rawDate) === todayDDMMYYYY;
                });
                if (uploadedToday) {
                    box.style.display = "none";
                    return;
                }
                const span = box.querySelector(".ticker-text");
                if (span) {
                    span.innerText = `⚠️ As Cash List was not uploaded today (${todayDDMMYYYY}), Latest Paid Consumer data will not be shown   ⚠️   As Cash List was not uploaded today (${todayDDMMYYYY}), Latest Paid Consumer data will not be shown`;
                }
                box.style.display = "block";
            } catch (_) {
                if (activeDC !== dcName || runId !== revenueSearchUploadFreshnessRunId_) return;
                box.style.display = "none";
            }
        }

        async function fetchRevenuePaidUploadSummaryFromServer(dcName = activeDC) {
            const normalizedDc = normalizeDcName(dcName || "");
            if (!normalizedDc || !revenueCollectionSubmitScriptUrl) return null;
            try {
                const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getUploadedPaidEntries&dc_name=${encodeURIComponent(normalizedDc)}&t=${Date.now()}`);
                const parsed = await response.json();
                if (parsed?.status !== "success" || !Array.isArray(parsed?.entries) || !parsed.entries.length) return null;
                const entries = parsed.entries;
                const normalRows = entries.filter((e) => normalizeLookupValue(e.source_type || "") === "NORMAL").length;
                const agRows = entries.filter((e) => normalizeLookupValue(e.source_type || "") === "AG").length;
                const latest = entries[entries.length - 1] || {};
                const uploadedAtDisplay = formatIndianDateTimeDisplay_(latest.uploaded_date, latest.uploaded_time);
                return {
                    dcName: normalizedDc,
                    uniqueCount: entries.length,
                    normalRows,
                    agRows,
                    uploadedAtDisplay,
                    oldDataReplaced: true,
                    backendSynced: true
                };
            } catch (_) {
                return null;
            }
        }

        async function refreshRevenuePaidUploadBackendStatus(dcName = activeDC) {
            const meta = getRevenuePaidUploadMeta(dcName);
            if (!meta || meta.backendSynced) return;
            const normalizedDc = normalizeDcName(dcName || "");
            const localEntries = Object.values(getRevenueUploadedPaidCache() || {}).filter((entry) => (
                getRevenueUploadedPaidRowDcName(entry, normalizedDc) === normalizedDc
            ));
            if (!localEntries.length || Number(meta.uniqueCount || 0) !== localEntries.length) return;
            setRevenuePaidUploadProgress(95, "Verifying the backend status of the last upload...");
            const verified = await verifyRevenuePaidBackendUpload(localEntries, normalizedDc, 1, meta.uploadedAt || null);
            if (!verified) {
                setRevenuePaidUploadProgress(95, "BACKEND VERIFICATION PENDING");
                return;
            }
            const verifiedMeta = {
                ...meta,
                backendSynced: true,
                backendConfirmedBy: "VERIFICATION",
                backendVerifiedAt: new Date().toISOString()
            };
            saveRevenuePaidUploadMeta(verifiedMeta);
            renderRevenuePaidUploadSummary(verifiedMeta);
            setRevenuePaidUploadProgress(100, "SUCCESSFULLY UPLOADED — Backend report is verified.");
        }

        function getRevenueUploadedPaidCache() {
            if (Object.keys(revenueUploadedPaidCache || {}).length) return revenueUploadedPaidCache;
            try {
                revenueUploadedPaidCache = JSON.parse(localStorage.getItem(revenueUploadedPaidStorageKey) || "{}") || {};
            } catch (_) {
                revenueUploadedPaidCache = {};
            }
            return revenueUploadedPaidCache;
        }

        function setRevenueUploadedPaidCache(cache) {
            revenueUploadedPaidVer_++; // cache usi object me badla ja sakta hai - memo ke liye version
            revenueUploadedPaidCache = cache || {};
            try {
                localStorage.setItem(revenueUploadedPaidStorageKey, JSON.stringify(revenueUploadedPaidCache));
            } catch (_) {}
        }

        function getRevenueCategoryRawPaymentRows() {
            if (Array.isArray(revenueCategoryRawPaymentCache)) return revenueCategoryRawPaymentCache;
            try {
                const stored = JSON.parse(localStorage.getItem(revenueCategoryRawPaymentStorageKey) || "[]");
                revenueCategoryRawPaymentCache = Array.isArray(stored) ? stored : [];
            } catch (_) {
                revenueCategoryRawPaymentCache = [];
            }
            return revenueCategoryRawPaymentCache;
        }

        function openRevenueCategoryRawPaymentDb() {
            return new Promise((resolve, reject) => {
                if (!window.indexedDB) return reject(new Error("IndexedDB unavailable"));
                const request = indexedDB.open(revenueCategoryRawPaymentDbName, 1);
                request.onupgradeneeded = () => {
                    const db = request.result;
                    if (!db.objectStoreNames.contains(revenueCategoryRawPaymentStoreName)) {
                        db.createObjectStore(revenueCategoryRawPaymentStoreName, { keyPath: "dc_name" });
                    }
                };
                request.onsuccess = () => resolve(request.result);
                request.onerror = () => reject(request.error || new Error("Payment database open failed"));
            });
        }

        async function ensureRevenueCategoryRawPaymentRowsLoaded() {
            const legacyRows = getRevenueCategoryRawPaymentRows();
            try {
                const db = await openRevenueCategoryRawPaymentDb();
                const records = await new Promise((resolve, reject) => {
                    const transaction = db.transaction(revenueCategoryRawPaymentStoreName, "readonly");
                    const request = transaction.objectStore(revenueCategoryRawPaymentStoreName).getAll();
                    request.onsuccess = () => resolve(Array.isArray(request.result) ? request.result : []);
                    request.onerror = () => reject(request.error || new Error("Payment database read failed"));
                });
                db.close();
                if (records.length) {
                    const storedDcs = new Set(records.map((record) => normalizeDcName(record?.dc_name)).filter(Boolean));
                    const retainedLegacyRows = legacyRows.filter((row) => !storedDcs.has(getRevenueUploadedPaidRowDcName(row)));
                    const storedRows = records.flatMap((record) => Array.isArray(record?.rows) ? record.rows : []);
                    revenueCategoryRawPaymentCache = [...retainedLegacyRows, ...storedRows];
                }
            } catch (_) {}
            return getRevenueCategoryRawPaymentRows();
        }

        async function saveRevenueCategoryRawPaymentRows(rows, dcName = activeDC) {
            const normalizedDc = normalizeDcName(dcName || activeDC || "");
            if (!normalizedDc) return;
            const retainedRows = getRevenueCategoryRawPaymentRows().filter((row) => getRevenueUploadedPaidRowDcName(row) !== normalizedDc);
            // "uploaded_date" = aaj ki date (jab yeh file upload ho rahi hai) - ise
            // yahin per-row stamp kar dete hain (local raw cache me). User request
            // (2026-08-13): paid-status ab row ki apni "payment date" se nahi,
            // is "uploaded_date" ke mahine se decide hota hai (isRevenueUploaded-
            // PaidInCategoryPeriod me) - kyunki billing cycle 20 tareek ke baad
            // agle mahine ka maana jaata hai, isliye poori uploaded file usi
            // mahine ki maani jaati hai jis mahine woh upload hui, chahe kisi
            // row ki andar ki payment date pichhle mahine ki ho.
            const uploadedDateStamp = getCurrentDateDDMMYYYY();
            const compactRows = (rows || []).map((row) => ({
                dc_name: normalizedDc,
                ivrs_no: normalizeRevenueIvrs(row.ivrsNo || row.ivrs_no),
                amount_paid: String(Math.round(Number(row.amount || row.amount_paid || 0))),
                payment_date: row.paymentDate || normalizeRevenuePaidDate(row.paymentDateRaw || row.payment_date_raw || ""),
                uploaded_date: row.uploaded_date || row.uploadedDate || uploadedDateStamp,
                source_type: row.sourceType || row.source_type || "",
                tariff_category: getRevenueUploadedPaidRowCategory(row, row.sourceType || row.source_type || "")
            })).filter((row) => row.ivrs_no && parseRevenuePaidAmount(row.amount_paid) && row.payment_date);
            revenueCategoryRawPaymentCache = [...retainedRows, ...compactRows];
            try {
                const db = await openRevenueCategoryRawPaymentDb();
                await new Promise((resolve, reject) => {
                    const transaction = db.transaction(revenueCategoryRawPaymentStoreName, "readwrite");
                    transaction.oncomplete = () => resolve();
                    transaction.onerror = () => reject(transaction.error || new Error("Payment database write failed"));
                    transaction.objectStore(revenueCategoryRawPaymentStoreName).put({ dc_name: normalizedDc, rows: compactRows });
                });
                db.close();
            } catch (_) {}
            try {
                localStorage.setItem(revenueCategoryRawPaymentStorageKey, JSON.stringify(revenueCategoryRawPaymentCache));
            } catch (_) {
                revenueCategoryRawPaymentCache = compactRows;
            }
        }

        // BUG FIX (2026-08-13): Device ke local IndexedDB "dc-payment-rows" cache
        // mein PURANE app.js version se save hui rows padi ho sakti hain, jinme
        // "uploaded_date" field hi nahi hai (yeh field is session ke fix se pehle
        // stamp hi nahi hoti thi). Aisi rows kabhi bhi isRevenueUploadedPaidIn-
        // CategoryPeriod() se match nahi hongi (uploaded_date khaali = match
        // hamesha false) - aur agar yeh purani local list, freshly backend se
        // aayi hui serverList se LAMBI ho (jaise SEONI (T) jaisi bade DC me,
        // jinki cash list is fix ke baad dobara upload nahi hui), to neeche wali
        // "jo zyada complete ho wahi use karo" logic galti se isi purani/kaam-
        // na-aane-wali list ko choose kar leti thi - Achieved hamesha 0 aata tha.
        // Fix: aisi untagged (uploaded_date-less) rows ko yahin ignore kar dete
        // hain, taaki woh DC apne aap sahi-tagged serverList (backend se, jismein
        // ab uploaded_date hamesha hoga) par fallback ho jaaye - kisi DC ki cash
        // list dobara upload karne ki zaroorat nahi padegi.
        // =====================================================================
        // USER RULE (2026-09-25) - "PAID DATE RULE": cash list ka koi bhugtan tabhi PAID
        // gina jaata hai jab uski tareekh us consumer ki MASTER "LAST PAYMENT DATE" ke
        // BARABAR ya BAAD ki ho (jaise master me last payment 05/09 aur cash list me 05/09
        // = PAID; purani cash list ka 20/08 wala bhugtan = PAID nahi). Sab reports (Live,
        // Freeze, Non-Payee, Top 20/50, Above 1 Lakh, Category Wise, Target, Pending DO,
        // search badge) isi ek helper se chalti hain. Master tareekh na mile / padhi na ja
        // sake, ya bhugtan ki tareekh samajh na aaye -> purana behaviour (bhugtan gina jaata hai).
        // =====================================================================
        function scPayDateKey_(value) {
            if (value === null || value === undefined || value === "") return "";
            if (value instanceof Date) {
                return isNaN(value.getTime()) ? "" : `${value.getFullYear()}${String(value.getMonth() + 1).padStart(2, "0")}${String(value.getDate()).padStart(2, "0")}`;
            }
            if (typeof value === "number" && value > 20000 && value < 80000) {
                const d = new Date(Math.round((value - 25569) * 86400000));
                return `${d.getUTCFullYear()}${String(d.getUTCMonth() + 1).padStart(2, "0")}${String(d.getUTCDate()).padStart(2, "0")}`;
            }
            const raw = String(value).trim();
            let m = raw.match(/^(\d{8})$/);
            if (m) return m[1];
            m = raw.match(/^(\d{4})[-\/.](\d{1,2})[-\/.](\d{1,2})/);
            if (m) return `${m[1]}${m[2].padStart(2, "0")}${m[3].padStart(2, "0")}`;
            m = raw.match(/^(\d{1,2})[-\/.](\d{1,2})[-\/.](\d{4})/); // cash list DD/MM/YYYY
            if (m) return `${m[3]}${m[2].padStart(2, "0")}${m[1].padStart(2, "0")}`;
            return "";
        }
        function scRowPayDateKey_(row) {
            return scPayDateKey_(row?.paymentDate || row?.payment_date) || scPayDateKey_(getRevenueUploadedPaidRowDate(row));
        }
        const scMasterLpdCache_ = new Map();
        function getMasterLastPayMapForDc_(dcName) {
            const dc = normalizeDcName(dcName || "");
            if (!dc) return new Map();
            const a = dcCacheRows[dc];
            const b = revenueCollectionRowsByDc[getRevenueCollectionDcKey(dc)];
            const cached = scMasterLpdCache_.get(dc);
            if (cached && cached.a === a && cached.b === b) return cached.map;
            const map = new Map();
            if ((a && a.length) || (b && b.length)) {
                const now = new Date();
                const todayKey = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}${String(now.getDate()).padStart(2, "0")}`;
                getRevenueMasterRowsForDc(dc).forEach((row) => {
                    const mm = String(row.lastPaymentDate || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
                    const key = mm ? `${mm[1]}${mm[2]}${mm[3]}` : "";
                    if (key && key <= todayKey) map.set(normalizeRevenueIvrs(row.ivrsNo), key); // aaj se aage ki (galat) master tareekh anadekhi
                });
            }
            scMasterLpdCache_.set(dc, { a, b, map });
            return map;
        }
        function scMasterLpdSignature_() {
            return Object.keys(dcCacheRows || {}).sort().map((k) => `${k}:${(dcCacheRows[k] || []).length}`).join(",");
        }
        function isCashPaymentCountable_(dcName, ivrsNo, payKey) {
            if (!payKey) return true;
            const lpd = getMasterLastPayMapForDc_(dcName).get(normalizeRevenueIvrs(ivrsNo));
            return !lpd || payKey >= lpd;
        }
        // USER RULE (2026-09-29): cash list me master ki LAST PAYMENT DATE ke barabar/baad ki payment
        // = PAID STHITI (pending list me nahi). PROGRESS (count/amount): NORMAL me cash list ki saari
        // aisi payment; AG (6 mahine me bill) me MONTHLY report me sirf chune mahine ki tareekh wali
        // payment. Ek consumer ki 2 payment = COUNT 2 (receipts).
        function scRevProgress_(dcName, ivrsNo, info, mode, filterValue) {
            const total = Number(info?.amount || 0);
            const list = Array.isArray(info?.payments) && info.payments.length ? info.payments : null;
            const lpd = getMasterLastPayMapForDc_(dcName).get(normalizeRevenueIvrs(ivrsNo));
            const src = String(info?.sourceType || "").toUpperCase();
            const isAg = /\bAG\b/.test(src) && !/NORMAL/.test(src);
            const monthKey = mode === "MONTHLY" ? String(filterValue || "").replace(/[^0-9]/g, "").slice(0, 6) : "";
            if (!(total > 0)) return { statusPaid: false, amount: 0, receipts: 0 };
            if (!list) return { statusPaid: true, amount: total, receipts: 1 };
            let droppedRule = 0, droppedAg = 0, receipts = 0;
            list.forEach((pm) => {
                const k = scPayDateKey_(Array.isArray(pm) ? pm[0] : pm?.date);
                const a = Number((Array.isArray(pm) ? pm[1] : pm?.amount) || 0);
                if (lpd && k && k < lpd) { droppedRule += a; return; }
                if (isAg && monthKey && k && k.slice(0, 6) !== monthKey) { droppedAg += a; return; }
                if (a > 0) receipts += 1;
            });
            const statusAmt = Math.max(0, total - droppedRule);
            const amount = Math.max(0, statusAmt - droppedAg);
            return { statusPaid: statusAmt > 0, amount, receipts: amount > 0 ? Math.max(1, receipts) : 0 };
        }
        function scCountableReconAmount_(dcName, ivrsNo, info) {
            const amount = Number(info?.amount || 0);
            const list = Array.isArray(info?.payments) ? info.payments : null;
            if (!(amount > 0) || !list || !list.length) return amount;
            const lpd = getMasterLastPayMapForDc_(dcName).get(normalizeRevenueIvrs(ivrsNo));
            if (!lpd) return amount;
            let dropped = 0;
            list.forEach((p) => {
                const k = scPayDateKey_(Array.isArray(p) ? p[0] : p?.date);
                if (k && k < lpd) dropped += Number((Array.isArray(p) ? p[1] : p?.amount) || 0);
            });
            return Math.max(0, amount - dropped);
        }
        function scFilterUploadedEntryByMaster_(entry, ivrsNo, dcName) {
            if (!entry) return entry;
            const lpd = getMasterLastPayMapForDc_(dcName).get(normalizeRevenueIvrs(ivrsNo));
            if (!lpd) return entry;
            const rows = getRevenueUploadedPaidPaymentRows(entry) || [];
            const keys = (rows.length ? rows : [entry]).map((r) => scRowPayDateKey_(r));
            if (keys.some((k) => !k || k >= lpd)) return entry;
            return null;
        }

        function getRevenueCategoryPaymentSourceRows() {
            const scRawRef_ = getRevenueCategoryRawPaymentRows();
            getRevenueUploadedPaidCache();
            const scPsKey_ = scArrId_(scRawRef_) + ":" + scRawRef_.length + "|" + scArrId_(revenueUploadedPaidCache) + ":" + revenueUploadedPaidVer_ + "|" + scTodayKey_() + "|"
                + Object.keys(dcCacheRows || {}).sort().map((k) => k + scArrId_(dcCacheRows[k]) + ":" + (dcCacheRows[k] || []).length).join(",") + "|"
                + Object.keys(revenueCollectionRowsByDc || {}).sort().map((k) => k + scArrId_(revenueCollectionRowsByDc[k]) + ":" + (revenueCollectionRowsByDc[k] || []).length).join(",");
            if (scPaySrcMemo_ && scPaySrcMemo_.key === scPsKey_) return scPaySrcMemo_.rows;
            const scPsOut_ = scBuildRevenueCategoryPaymentSourceRows_();
            scPaySrcMemo_ = { key: scPsKey_, rows: scPsOut_ };
            return scPsOut_;
        }
        function scBuildRevenueCategoryPaymentSourceRows_() {
            const rawRows = getRevenueCategoryRawPaymentRows().filter((row) => !!getRevenueUploadedPaidRowUploadedDate(row));
            const rawByDc = {};
            rawRows.forEach((row) => {
                const dcName = getRevenueUploadedPaidRowDcName(row);
                if (!dcName) return;
                if (!rawByDc[dcName]) rawByDc[dcName] = [];
                rawByDc[dcName].push(row);
            });

            const serverByDc = {};
            Object.values(getRevenueUploadedPaidCache() || {}).forEach((row) => {
                const dcName = getRevenueUploadedPaidRowDcName(row);
                if (!dcName) return;
                if (!serverByDc[dcName]) serverByDc[dcName] = [];
                getRevenueUploadedPaidPaymentRows(row).forEach((paymentRow) => {
                    serverByDc[dcName].push({
                        ...paymentRow,
                        dcName: getRevenueUploadedPaidRowDcName(paymentRow, dcName),
                        ivrsNo: getRevenueUploadedPaidRowIvrs(paymentRow) || getRevenueUploadedPaidRowIvrs(row)
                    });
                });
            });

            const allDcNames = new Set([...Object.keys(rawByDc), ...Object.keys(serverByDc)]);
            const rows = [];
            allDcNames.forEach((dcName) => {
                const rawList = rawByDc[dcName] || [];
                const serverList = serverByDc[dcName] || [];
                // Jo bhi source zyada complete ho (zyada rows) usi DC ke liye use karo -
                // taaki partial/adhoora local cache poore server data ko hide na kare.
                rows.push(...(serverList.length > rawList.length ? serverList : rawList));
            });
            // USER RULE (2026-09-25) PAID DATE RULE
            return rows.filter((row) => isCashPaymentCountable_(getRevenueUploadedPaidRowDcName(row), getRevenueUploadedPaidRowIvrs(row), scRowPayDateKey_(row)));
        }

        function getRevenueUploadedPaidCacheKey(ivrsNo, dcName = activeDC) {
            return `${normalizeLookupValue(dcName || "")}|${normalizeRevenueIvrs(ivrsNo)}`;
        }

        function getRevenueUploadedPaidEntryLocal(ivrsNo, dcName = activeDC) {
            const cache = getRevenueUploadedPaidCache();
            return cache[getRevenueUploadedPaidCacheKey(ivrsNo, dcName)] || null;
        }

        function saveRevenueUploadedPaidEntryLocal(entry, dcName = activeDC) {
            const ivrsNo = getRevenueUploadedPaidRowIvrs(entry);
            if (!ivrsNo) return;
            const cache = getRevenueUploadedPaidCache();
            const resolvedDcName = getRevenueUploadedPaidRowDcName(entry, dcName || activeDC || "");
            const paymentRows = getRevenueUploadedPaidPaymentRows(entry);
            cache[getRevenueUploadedPaidCacheKey(ivrsNo, resolvedDcName)] = {
                ivrsNo,
                dcName: resolvedDcName,
                amountPaid: getRevenueUploadedPaidRowAmount(entry),
                paymentDate: getRevenueUploadedPaidRowDate(entry),
                paymentDateRaw: entry.paymentDateRaw || entry.payment_date_raw || getRevenueUploadedPaidRowDate(entry),
                paymentCount: entry.payment_count || entry.paymentCount || entry.count || "",
                sourceType: entry.source_type || entry.sourceType || entry.type || "",
                tariffCategory: getRevenueUploadedPaidRowCategory(entry, entry.source_type || entry.sourceType || entry.type || ""),
                paymentRows,
                payment_rows: paymentRows
            };
            setRevenueUploadedPaidCache(cache);
        }

        function saveRevenueUploadedPaidEntriesLocalBulk(entries, dcName = activeDC, replaceDc = false) {
            const cache = getRevenueUploadedPaidCache();
            const dcKey = normalizeLookupValue(dcName || activeDC || "");
            if (replaceDc) {
                Object.keys(cache).forEach((key) => {
                    if (key.startsWith(`${dcKey}|`)) delete cache[key];
                });
            }
            (entries || []).forEach((entry) => {
                const ivrsNo = getRevenueUploadedPaidRowIvrs(entry);
                if (!ivrsNo) return;
                const resolvedDcName = getRevenueUploadedPaidRowDcName(entry, dcName || activeDC || "");
                let paymentRowsValue = entry.paymentRows || entry.payment_rows || entry.payments || entry.paymentDetails || [];
                if (typeof paymentRowsValue === "string") {
                    try { paymentRowsValue = JSON.parse(paymentRowsValue); } catch (_) { paymentRowsValue = []; }
                }
                cache[getRevenueUploadedPaidCacheKey(ivrsNo, resolvedDcName)] = {
                    ivrsNo,
                    dcName: resolvedDcName,
                    amountPaid: getRevenueUploadedPaidRowAmount(entry),
                    paymentDate: getRevenueUploadedPaidRowDate(entry),
                    paymentDateRaw: entry.paymentDateRaw || entry.payment_date_raw || getRevenueUploadedPaidRowDate(entry),
                    // BUG FIX (2026-08-13): yeh function backend se aaya hua entry
                    // dobara ek "saaf" object banakar cache me save karta hai - pehle
                    // isme "uploaded_date" field include hi nahi thi, isliye backend se
                    // sahi uploaded_date aane ke bawajood yahan cache me save karte
                    // waqt woh gir (drop ho) jaati thi. Isi wajah se upload ke turant
                    // baad (jab local raw IndexedDB cache use hoti thi) sahi dikhta
                    // tha, lekin thodi der baad jab yeh cache dobara backend se sync
                    // hoti thi to Achieved hamesha 0 aane lagta tha - ab yahan bhi
                    // uploaded_date save karte hain taaki isRevenueUploadedPaidIn-
                    // CategoryPeriod() ko yeh hamesha sahi mile.
                    uploadedDate: getRevenueUploadedPaidRowUploadedDate(entry),
                    paymentCount: entry.payment_count || entry.paymentCount || entry.count || "",
                    sourceType: entry.source_type || entry.sourceType || entry.type || "",
                    tariffCategory: entry.tariffCategory || entry.tariff_category || getRevenueUploadedPaidRowCategory(entry, entry.source_type || entry.sourceType || ""),
                    paymentRows: Array.isArray(paymentRowsValue) ? paymentRowsValue : []
                };
            });
            setRevenueUploadedPaidCache(cache);
        }

        function removeRevenueUploadedPaidEntryLocal(ivrsNo, dcName = activeDC) {
            const cache = getRevenueUploadedPaidCache();
            delete cache[getRevenueUploadedPaidCacheKey(ivrsNo, dcName)];
            setRevenueUploadedPaidCache(cache);
        }

        async function syncRevenueUploadedPaidStatus(record, searchedIvrs) {
            if (!revenueCollectionSubmitScriptUrl) return null;
            const ivrsNo = normalizeRevenueIvrs(record?.ivrsNo || searchedIvrs);
            if (!ivrsNo) return null;
            try {
                const dcName = activeDC || "";
                const url = `${revenueCollectionSubmitScriptUrl}?action=checkUploadedPaid&ivrs_no=${encodeURIComponent(ivrsNo)}&dc_name=${encodeURIComponent(dcName)}&t=${Date.now()}`;
                const response = await fetch(url);
                const parsed = await response.json();
                if (parsed && parsed.status === "success" && parsed.paid && parsed.data) {
                    saveRevenueUploadedPaidEntryLocal(parsed.data, dcName);
                    if (normalizeRevenueIvrs(currentRevenueRecord?.ivrsNo) === ivrsNo) {
                        renderRevenueConsumer(currentRevenueRecord || record, searchedIvrs);
                    }
                    return parsed.data;
                }
                removeRevenueUploadedPaidEntryLocal(ivrsNo, dcName);
                if (normalizeRevenueIvrs(currentRevenueRecord?.ivrsNo) === ivrsNo) {
                    renderRevenueConsumer(currentRevenueRecord || record, searchedIvrs);
                }
            } catch (_) {}
            return null;
        }

        function findRevenuePaidHeaderRow(rows) {
            for (let i = 0; i < Math.min(rows.length, 20); i++) {
                const normalized = (rows[i] || []).map((cell) => normalizeLookupValue(cell));
                if (normalized.some((cell) => cell.includes("CONSUMERNO")) && normalized.some((cell) => cell.includes("PAYMENTAMOUNT"))) {
                    return i;
                }
            }
            return -1;
        }

        function getRevenueHeaderIndex(headers, aliases) {
            const normalizedHeaders = headers.map((header) => normalizeLookupValue(header));
            for (const alias of aliases) {
                const normalizedAlias = normalizeLookupValue(alias);
                const exactIndex = normalizedHeaders.findIndex((header) => header === normalizedAlias);
                if (exactIndex > -1) return exactIndex;
                const includesIndex = normalizedHeaders.findIndex((header) => header.includes(normalizedAlias));
                if (includesIndex > -1) return includesIndex;
            }
            return -1;
        }

        function normalizeRevenuePaidDate(value, preferredMonthKey = "") {
            if (value instanceof Date && !isNaN(value.getTime())) {
                return [
                    String(value.getDate()).padStart(2, "0"),
                    String(value.getMonth() + 1).padStart(2, "0"),
                    value.getFullYear()
                ].join("/");
            }
            if (typeof value === "number" && window.XLSX && XLSX.SSF) {
                const parsed = XLSX.SSF.parse_date_code(value);
                if (parsed) {
                    return [
                        String(parsed.d).padStart(2, "0"),
                        String(parsed.m).padStart(2, "0"),
                        parsed.y
                    ].join("/");
                }
            }
            const raw = String(value || "").trim();
            if (/^\d{4}[-/]\d{1,2}[-/]\d{1,2}T/i.test(raw)) {
                const parsedIsoDate = new Date(raw);
                if (!isNaN(parsedIsoDate.getTime())) {
                    return [
                        String(parsedIsoDate.getDate()).padStart(2, "0"),
                        String(parsedIsoDate.getMonth() + 1).padStart(2, "0"),
                        parsedIsoDate.getFullYear()
                    ].join("/");
                }
            }
            if (/^\d{5,6}(\.\d+)?$/.test(raw) && window.XLSX && XLSX.SSF) {
                const parsed = XLSX.SSF.parse_date_code(Number(raw));
                if (parsed) {
                    return [
                        String(parsed.d).padStart(2, "0"),
                        String(parsed.m).padStart(2, "0"),
                        parsed.y
                    ].join("/");
                }
            }
            const iso = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
            if (iso) return `${iso[3].padStart(2, "0")}/${iso[2].padStart(2, "0")}/${iso[1]}`;
            const dateParts = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})/);
            if (dateParts) {
                const first = Number(dateParts[1]);
                const second = Number(dateParts[2]);
                const year = dateParts[3].length === 2 ? "20" + dateParts[3] : dateParts[3];
                const dmyValid = first >= 1 && first <= 31 && second >= 1 && second <= 12;
                const mdyValid = first >= 1 && first <= 12 && second >= 1 && second <= 31;
                const dmyDate = `${String(first).padStart(2, "0")}/${String(second).padStart(2, "0")}/${year}`;
                const mdyDate = `${String(second).padStart(2, "0")}/${String(first).padStart(2, "0")}/${year}`;

                if (dmyValid) return dmyDate;
                if (mdyValid) return mdyDate;
            }
            return raw;
        }

        function normalizeRevenuePaidDateForSource(value, sourceType) {
            if (value instanceof Date || typeof value === "number") {
                return normalizeRevenuePaidDate(value);
            }
            const raw = String(value || "").trim();
            const paidFileType = normalizeLookupValue(sourceType);
            if (paidFileType.includes("AG")) {
                const iso = raw.match(/^(\d{4})[-/](\d{1,2})[-/](\d{1,2})/);
                if (iso) return `${iso[3].padStart(2, "0")}/${iso[2].padStart(2, "0")}/${iso[1]}`;
            }
            if (paidFileType.includes("NORMAL")) {
                const dmy = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{2,4})/);
                if (dmy) {
                    const year = dmy[3].length === 2 ? `20${dmy[3]}` : dmy[3];
                    return `${dmy[1].padStart(2, "0")}/${dmy[2].padStart(2, "0")}/${year}`;
                }
            }
            return normalizeRevenuePaidDate(value);
        }

        function revenueDateToSortable(value) {
            const raw = normalizeRevenuePaidDate(value);
            const match = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
            return match ? `${match[3]}${match[2]}${match[1]}` : raw;
        }

        function parseRevenuePaidNumber(value) {
            const cleaned = String(value || "").replace(/[^0-9.-]/g, "");
            const numberValue = Number(cleaned);
            return Number.isFinite(numberValue) ? numberValue : 0;
        }

        function waitForUiBreath(ms = 30) {
            return new Promise((resolve) => setTimeout(resolve, ms));
        }

        async function fetchWithTimeout(url, options = {}, timeoutMs = 45000) {
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), timeoutMs);
            try {
                return await fetch(url, { ...options, signal: controller.signal });
            } finally {
                clearTimeout(timer);
            }
        }

        async function readRevenuePaidFile(file, sourceType) {
            if (!file) return [];
            if (!window.XLSX) throw new Error("Excel reader could not be loaded. Please check internet and refresh.");
            const buffer = await file.arrayBuffer();
            const workbook = XLSX.read(buffer, { type: "array", cellDates: true });
            const rows = scPickPaidSheetRows_(workbook); // 2026-09-28: jis sheet me header ho
            return readRevenuePaidRowsFromSheetRows_(rows, sourceType);
        }

        // 2026-09-25: readRevenuePaidFile ka parsing hissa alag function me (logic bilkul
        // wahi) taaki Division Cash List Upload bhi isi se har DC ke rows padh sake.
        // USER REQUEST (2026-09-28): Cash List ka format HEADER se pehchano - header kisi bhi row
        // (1, 10, 50...) par ho, column aage-peeche hon to bhi naam se padho. NORMAL/AG file
        // bhi header se pehchani jaati hai; galat file (ya NORMAL ki jagah AG) par upload yahin
        // ruk jaata hai aur yahi sandesh dikhta hai (galat data kabhi upload nahi hota).
        const SC_PAID_FORMAT_ERR_ = "The Cash List you uploaded is not in the correct format. Please contact Patidar Sir.";
        const SC_PAID_HDR_ = {
            consumer: ["CONSUMERNO", "CONSUMERNUMBER"],
            amount: ["PAYMENTAMOUNT", "PAIDAMOUNT"],
            date: ["PAYMENTDATE", "PAIDDATE", "COLLECTIONDATE", "PAYDATE"],
            source: ["SOURCE"],
            mode: ["PAYMODE", "PAYMENTMODE"],
            category: ["TARIFFCATEGORY", "TARRIFCATEGORY"]
        };
        const SC_PAID_AG_SIGNS_ = ["SANCTIONEDLOAD", "SANCTIONEDLOADUNIT", "POSTINGBILLMONTH", "OLDCONSUMERNO", "NETBILL", "CONSUMERNAME", "ADDRESS"];
        const SC_PAID_NORMAL_SIGNS_ = ["TARIFFCATEGORY", "TARRIFCATEGORY", "TARIFFCODE", "FEEDERNAME", "PAYMODE", "ISONLINE", "READINGDIARYNO", "CONSUMERSTATUS", "PUNCHINGDATE", "POSTED"];
        function scDetectPaidFormat_(rows) {
            const limit = Math.min((rows || []).length, 300);
            for (let i = 0; i < limit; i++) {
                const h = (rows[i] || []).map((c) => normalizeLookupValue(c));
                const find = (aliases) => { for (const a of aliases) { const k = h.indexOf(a); if (k > -1) return k; } return -1; };
                const consumer = find(SC_PAID_HDR_.consumer), amount = find(SC_PAID_HDR_.amount), date = find(SC_PAID_HDR_.date);
                if (consumer < 0 || amount < 0) continue;
                const ag = SC_PAID_AG_SIGNS_.filter((x) => h.includes(x)).length;
                const nm = SC_PAID_NORMAL_SIGNS_.filter((x) => h.includes(x)).length;
                const type = (ag >= 1 && nm === 0) ? "AG" : ((nm >= 2 && ag === 0) ? "NORMAL" : "");
                return { headerIndex: i, type, consumer, amount, date, source: find(SC_PAID_HDR_.source), mode: find(SC_PAID_HDR_.mode), category: find(SC_PAID_HDR_.category) };
            }
            return null;
        }
        // Expected type (NORMAL/AG) se mile to format, warna wahi ek sandesh (chhota karan saath me).
        function scRequirePaidFormat_(rows, sourceType) {
            const want = normalizeLookupValue(sourceType).includes("AG") ? "AG" : "NORMAL";
            const fmt = scDetectPaidFormat_(rows);
            if (!fmt || fmt.date < 0) throw new Error(`${SC_PAID_FORMAT_ERR_}\n(${want} file: Consumer No / Payment Amount / Payment Date column not found)`);
            if (!fmt.type) throw new Error(`${SC_PAID_FORMAT_ERR_}\n(${want} file could not be recognized)`);
            if (fmt.type !== want) throw new Error(`${SC_PAID_FORMAT_ERR_}\n(${fmt.type} file was selected instead of ${want})`);
            return fmt;
        }
        // Workbook ki jis sheet me Cash List header mile wahi (pehle sirf pehli sheet).
        function scPickPaidSheetRows_(workbook) {
            let first = null;
            for (const name of workbook.SheetNames || []) {
                const rows = XLSX.utils.sheet_to_json(workbook.Sheets[name], { header: 1, defval: "" });
                if (!first) first = rows;
                if (scDetectPaidFormat_(rows)) return rows;
            }
            return first || [];
        }

        function readRevenuePaidRowsFromSheetRows_(rows, sourceType, knownFmt) {
            const fmt = knownFmt || scRequirePaidFormat_(rows, sourceType);
            const paidFileType = normalizeLookupValue(sourceType);
            const isAg = paidFileType.includes("AG");
            // knownFmt (Division AG ke LOCATION blocks) me header pichhle block me ho sakta hai -
            // tab poora block padho; header/title rows me IVRS/amount nahi hota, apne aap chhoot jaati hain.
            const dataRows = knownFmt ? rows : rows.slice(fmt.headerIndex + 1);
            const parsed = dataRows.map((row) => {
                const ivrsNo = normalizeRevenueIvrs(row[fmt.consumer]);
                const amount = parseRevenuePaidNumber(row[fmt.amount]);
                if (!ivrsNo || !amount) return null;
                const paymentDateValue = fmt.date > -1 ? row[fmt.date] : "";
                const tariffCategory = isAg ? "LV5" : normalizeRevenueCategory(fmt.category > -1 ? row[fmt.category] : "");
                return {
                    ivrsNo,
                    amount,
                    paymentDate: normalizeRevenuePaidDateForSource(paymentDateValue, paidFileType),
                    paymentDateRaw: paymentDateValue,
                    source: fmt.source > -1 ? String(row[fmt.source] || "").trim() : "",
                    payMode: fmt.mode > -1 ? String(row[fmt.mode] || "").trim() : "",
                    tariffCategory,
                    sourceType
                };
            }).filter(Boolean);
            if (!knownFmt && !parsed.length) throw new Error(`${SC_PAID_FORMAT_ERR_}\n(no valid payment row found in the file)`);
            return parsed;
        }

        function getRevenuePaidDateIndexForSource_(headers, paidFileType) {
            if (paidFileType.includes("AG")) {
                return headers.length > 11 ? 11 : -1;
            }
            if (paidFileType.includes("NORMAL")) {
                return headers.length > 7 ? 7 : -1;
            }
            return -1;
        }

        function getRevenuePaidColumnIndexesForSource_(paidFileType) {
            if (paidFileType.includes("AG")) {
                return {
                    consumerIndex: 2, // C: Consumer No
                    amountIndex: 10,  // K: Payment Amount
                    dateIndex: 11     // L: Payment Date (YYYY-MM-DD)
                };
            }
            if (paidFileType.includes("NORMAL")) {
                return {
                    consumerIndex: 3, // D: Consumer No
                    amountIndex: 11,  // L: Payment Amount
                    dateIndex: 7      // H: Payment Date (DD/MM/YYYY)
                };
            }
            return {
                consumerIndex: -1,
                amountIndex: -1,
                dateIndex: -1
            };
        }

        // USER RULE (2026-09-26): NORMAL file ke sabhi IVRS upload hon; AG file ki jo row ka IVRS
        // NORMAL file me bhi hai (LV5 ke kuch consumer dono me aate hain) woh SKIP - sheet me ek
        // hi row jaaye (pehle dono jud kar "NORMAL+AG" ban jaate the, amount doguna).
        function scSplitAgRowsByNormal_(agRows, normalIvrsSet) {
            const keep = [];
            const skipped = [];
            (agRows || []).forEach((row) => {
                const iv = normalizeRevenueIvrs(row.ivrsNo);
                if (iv && normalIvrsSet.has(iv)) skipped.push(iv); else keep.push(row);
            });
            return { keep, skipped: Array.from(new Set(skipped)) };
        }

        function buildRevenuePaidUploadEntries(rows, dcName) {
            const grouped = {};
            rows.forEach((row) => {
                const key = normalizeRevenueIvrs(row.ivrsNo);
                if (!key) return;
                if (!grouped[key]) {
                    grouped[key] = {
                        ivrs_no: key,
                        dc_name: dcName || "",
                        amount_paid: 0,
                        payment_count: 0,
                        payment_date: row.paymentDate || "",
                        payment_date_raw: row.paymentDateRaw || row.paymentDate || "",
                        source_type: row.sourceType || "",
                        tariff_category: row.tariffCategory || "",
                        source: row.source || "",
                        pay_mode: row.payMode || "",
                        payment_rows: []
                    };
                }
                grouped[key].payment_rows.push({
                    ivrs_no: key,
                    dc_name: dcName || "",
                    amount_paid: Number(row.amount || 0),
                    payment_date: row.paymentDate || "",
                    payment_date_raw: row.paymentDateRaw || row.paymentDate || "",
                    source_type: row.sourceType || "",
                    tariff_category: row.tariffCategory || "",
                    source: row.source || "",
                    pay_mode: row.payMode || ""
                });
                grouped[key].amount_paid += Number(row.amount || 0);
                grouped[key].payment_count += 1;
                if (revenueDateToSortable(row.paymentDate) >= revenueDateToSortable(grouped[key].payment_date)) {
                    grouped[key].payment_date = row.paymentDate || grouped[key].payment_date;
                    grouped[key].payment_date_raw = row.paymentDateRaw || grouped[key].payment_date_raw || grouped[key].payment_date;
                }
                const sourceTypes = new Set(String(grouped[key].source_type || "").split("+").filter(Boolean));
                sourceTypes.add(row.sourceType || "");
                grouped[key].source_type = Array.from(sourceTypes).filter(Boolean).join("+");
            });
            return Object.values(grouped).map((entry) => ({
                ...entry,
                amount_paid: String(Math.round(entry.amount_paid)),
                payment_rows: entry.payment_rows.map((paymentRow) => ({
                    ...paymentRow,
                    amount_paid: String(Math.round(Number(paymentRow.amount_paid || 0)))
                }))
            }));
        }

        // USER REQUEST (2026-09-21): CHHAPARA-1 jaisi badi DC (jahan AG rows purane
        // upload ke saath merge hote hain aur Apps Script ko poora likhne/verify
        // karne me zyada time lagta hai) me pehle sirf 30 attempt x 3s = 90 second
        // ke andar backend confirm na ho paane par upload "99% - Verification
        // pending" par ruk jaata tha - chahe backend me data asal me thodi der baad
        // sahi save ho hi gaya ho. Baaki jagah (getUploadedPaidIvrsList) bhi isi
        // tarah ki badi DC ke liye already 150s tak wait karta hai, isliye yahan
        // bhi attempts badha kar 60 (~180 second) kar diya hai taaki badi DC ko
        // verify hone ka poora, fair mauka mile.
        // SPEED FIX (2026-09-24, USER-REPORTED "Cash List upload me bahut samay"):
        // Pehle har 3 sec par DO request jaati thi - (a) row-count (jo AG accumulate
        // hone ki wajah se kabhi upload ki unique-IVRS ginti ke BARABAR hota hi nahi,
        // isliye hamesha fail) aur (b) poori IVRS list (~300 KB) - yeh dono usi sheet
        // par chal rahe upload-write se takraate the aur use aur dheema karte the.
        // Aur (b) purane upload ke IVRS dekh kar bhi "verified" maan sakta tha.
        // Ab: sirf ek request, har 10 sec, aur tabhi "verified" jab saare IVRS ka
        // backend "UPLOADED DATE" is upload ke din (ya uske baad) ka ho.
        function revenueUploadDateKey_(value) {
            const raw = String(value || "").trim();
            let m = raw.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
            if (m) return `${m[3]}-${m[2].padStart(2, "0")}-${m[1].padStart(2, "0")}`;
            m = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
            return m ? `${m[1]}-${m[2]}-${m[3]}` : "";
        }

        async function verifyRevenuePaidBackendUpload(entries, dcName, maxAttempts = 60, minUploadedAt = null) {
            const expectedIvrs = Array.from(new Set((entries || [])
                .map((entry) => getRevenueUploadedPaidRowIvrs(entry))
                .filter(Boolean)));
            if (!expectedIvrs.length) return false;
            let minDateKey = "";
            if (minUploadedAt) {
                const d = new Date(minUploadedAt);
                if (!isNaN(d.getTime())) minDateKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
            }
            for (let attempt = 1; attempt <= maxAttempts; attempt++) {
                try {
                    const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getUploadedPaidIvrsList&dc_name=${encodeURIComponent(dcName || "")}&t=${Date.now()}`);
                    const parsed = await response.json();
                    if (parsed?.status === "success" && Array.isArray(parsed.entries)) {
                        const backendDateByIvrs = new Map();
                        parsed.entries.forEach((entry) => {
                            const ivrs = getRevenueUploadedPaidRowIvrs(entry);
                            if (ivrs) backendDateByIvrs.set(ivrs, revenueUploadDateKey_(entry.uploaded_date || entry.uploadedDate || ""));
                        });
                        const ok = expectedIvrs.every((ivrs) => backendDateByIvrs.has(ivrs)
                            && (!minDateKey || (backendDateByIvrs.get(ivrs) || "") >= minDateKey));
                        if (ok) return true;
                    }
                } catch (_) {}
                if (attempt < maxAttempts) {
                    const verificationPercent = 70 + Math.round((attempt / maxAttempts) * 29);
                    setRevenuePaidUploadProgress(verificationPercent, `Backend verification in progress... (${attempt}/${maxAttempts})`);
                    await new Promise((resolve) => setTimeout(resolve, 10000));
                }
            }
            return false;
        }

        // USER REQUEST (2026-09-22): "BACKEND VERIFICATION PENDING" (99%) dikhne
        // ke baad bhi chup-chaap, background me, thodi der aur try karte rehna -
        // badi DC (jaise CHHAPARA-1, 5000+ rows) ke liye backend ko likhne me
        // kabhi-kabhi 3 minute (verifyRevenuePaidBackendUpload ki poori window)
        // se bhi zyada lag jaata hai. Yeh function UI ko block nahi karta (fire-
        // and-forget), aur jab bhi confirm ho jaaye - abhi bhi wahi upload/DC
        // active ho to summary+button turant "Successfully Uploaded" me update
        // ho jaate hain, bina user ko kuch karna pade.
        async function continueRevenuePaidUploadBackgroundVerification_(entries, dcName, uploadMeta) {
            const confirmed = await verifyRevenuePaidBackendUpload(entries, dcName, 30 /* 30 x 10s = 5 min */, uploadMeta?.uploadedAt || null).catch(() => false);
            if (!confirmed) return;
            const latestMeta = getRevenuePaidUploadMeta(dcName);
            // Beech me koi naya upload shuru ho gaya ho (uniqueCount badal gaya)
            // to yeh purana confirmation ab uss par apply nahi karna - sirf tabhi
            // update karo jab abhi bhi wahi upload (record count match) pending hai.
            if (!latestMeta || latestMeta.backendSynced || Number(latestMeta.uniqueCount) !== Number(uploadMeta.uniqueCount)) return;
            const verifiedMeta = { ...latestMeta, backendSynced: true, backendConfirmedBy: "VERIFICATION", backendVerifiedAt: new Date().toISOString() };
            saveRevenuePaidUploadMeta(verifiedMeta);
            if (activeDC === dcName) {
                renderRevenuePaidUploadSummary(verifiedMeta);
                const uploadBtn = document.getElementById("revenue-paid-upload-btn");
                if (uploadBtn) setActionButtonState(uploadBtn, "done", "Upload Paid Data");
                showToast(`${dcName} - Cash List is now confirmed by the backend (Successfully Uploaded)`, true);
            }
            checkRevenueUploadFreshness();
        }

        // ISOLATED ADDITION (2026-09-24, USER REQUEST): "DC match check" - Cash List
        // (NORMAL / AG) file sahi DC ki hai ya nahi. Chuni hui DC ka master data na ho
        // (csvUrl khaali / load fail) to check skip - upload pehle jaisa chalta hai.
        // Kam match hone par, jin DC ka master data pehle se app me load hai unse
        // milakar andaza bhi batate hain ki file asal me kis DC ki hai.
        async function checkRevenuePaidFileBelongsToDc_(dcName, normalRows, agRows) {
            const dc = normalizeDcName(dcName || "");
            if (!dc) return;
            try { await ensureRevenueCategoryMasterDataLoaded([dc]); } catch (_) {}
            const masterSet = new Set(getRevenueMasterRowsForDc(dc).map((r) => normalizeRevenueIvrs(r.ivrsNo)).filter(Boolean));
            if (masterSet.size < 50) return; // master data nahi / bahut kam - check nahi kar sakte
            // SPEED PHASE 2: file galat DC ki lage tabhi (bahut kam) baaki DC ke master
            // laate hain taaki "shayad X DC ki hai" guess pehle jaisa hi bane.
            const scQuickMismatch = [normalRows, agRows].some((rows) => {
                const list = Array.from(new Set((rows || []).map((r) => normalizeRevenueIvrs(r.ivrsNo)).filter(Boolean)));
                if (list.length < 5) return false;
                return (list.filter((ivrs) => masterSet.has(ivrs)).length / list.length) < 0.5;
            });
            if (scQuickMismatch) {
                try { await ensureConsumerDataLoadedFor(getAllDcNames()); } catch (_) {}
            }
            const checkOne = (rows, label) => {
                const ivrsList = Array.from(new Set((rows || []).map((r) => normalizeRevenueIvrs(r.ivrsNo)).filter(Boolean)));
                if (ivrsList.length < 5) return;
                const matched = ivrsList.filter((ivrs) => masterSet.has(ivrs)).length;
                const pct = Math.round((matched / ivrsList.length) * 100);
                if (pct >= 50) return;
                let guess = "";
                let best = 0;
                getAllDcNames().forEach((other) => {
                    const o = normalizeDcName(other);
                    if (!o || o === dc || !getConsumerRows(other).length) return;
                    const oSet = new Set(getRevenueMasterRowsForDc(other).map((r) => normalizeRevenueIvrs(r.ivrsNo)));
                    const m = ivrsList.filter((ivrs) => oSet.has(ivrs)).length;
                    if (m > best) { best = m; guess = o; }
                });
                const guessText = guess && best / ivrsList.length >= 0.5 ? ` This file seems to belong to DC ${guess}.` : "";
                const err = new Error(`WRONG DC: ${label} Cash List does not seem to belong to ${dc} - only ${matched} (${pct}%) of ${ivrsList.length} IVRS in the file were found in the master of ${dc}.${guessText} Upload was stopped, no data was sent. Please select the correct DC and upload again.`);
                err.isExplicitBackendError = true;
                throw err;
            };
            checkOne(normalRows, "NORMAL");
            checkOne(agRows, "AG");
        }

        var revenuePaidUploadStartedAt_ = null;

        // =====================================================================
        // USER REQUEST (2026-09-25): DIVISION CASH LIST UPLOAD
        // Division dashboard (DC select screen) ke ⋮ menu se ek hi compiled file
        // (poore Division ki NORMAL + AG/Pump) upload. File ko har DC me baant kar
        // HAR DC ka upload BILKUL DC-upload wale tarike se hota hai (same backend
        // action uploadPaidMaster: NORMAL replace, AG accumulate) - bas
        // upload_scope=DIVISION + Division password (backend check). Us din DC se
        // dobara upload backend rok deta hai. DC wala alag upload pehle jaisa hi hai.
        // DC pehchan: NORMAL - DC master IVRS se (na mile to IVRS ke pehle 4 ank
        // se, jo us file me baaki rows se seekhe gaye); AG - "LOCATION (DC)" block.
        // =====================================================================
        let divisionPaidUploadPassword_ = "";
        let divisionPaidUploadInProgress_ = false;

        function initDivisionPaidUpload() {
            const label = document.getElementById("division-paid-upload-div");
            if (label) label.textContent = activeDiv || "";
            const lock = document.getElementById("division-paid-lock-box");
            const panel = document.getElementById("division-paid-upload-panel");
            if (lock) lock.style.display = divisionPaidUploadPassword_ ? "none" : "block";
            if (panel) panel.style.display = divisionPaidUploadPassword_ ? "block" : "none";
            if (scDivUploadCtx_ && scDivUploadCtx_.division !== (activeDiv || "")) scDivUploadCtx_ = null;
            if (divisionPaidUploadPassword_ && !divisionPaidUploadInProgress_) scDivShowLastUploads_(); // 30/09 har DC ki aakhri upload
        }
        async function unlockDivisionPaidUpload() {
            const input = document.getElementById("division-paid-password");
            const password = String(input?.value || "").trim();
            if (!password) return showToast("Enter password", false);
            // USER REQUEST (2026-09-26): sirf sahi password se khule
            const vr = await scVerifyAdminPassword_(revenueCollectionSubmitScriptUrl, { action: "verifyAdminPassword", type: "division", admin_password: password });
            if (vr === "wrong" || vr === "net") { scAdminPwdFailToast_(vr); if (vr === "wrong" && input) input.value = ""; return; }
            divisionPaidUploadPassword_ = password; // asli check backend par
            if (input) input.value = "";
            initDivisionPaidUpload();
        }
        function setDivisionPaidUploadStatus_(html, ok = true) {
            const box = document.getElementById("division-paid-upload-status");
            if (!box) return;
            box.style.display = html ? "block" : "none";
            box.style.background = ok ? "#ecfdf5" : "#fff1f2";
            box.style.border = `1.5px solid ${ok ? "#86efac" : "#fda4af"}`;
            box.style.color = ok ? "#14532d" : "#991b1b";
            box.innerHTML = html || "";
        }
        // USER REQUEST (2026-09-30): har DC ke saath aakhri upload date-time, aur jis DC ka upload
        // FAIL / confirm baaki ho sirf usi ke saamne "Try Again" (poori file dobara nahi).
        const scDivLastUp_ = {};
        function scDivLastUpText_(dc) {
            const ms = Number(scDivLastUp_[normalizeDcName(dc)] || 0);
            return ms ? `Last upload: ${scBriefDateOf_(ms)} ${scBriefHm_(ms)}` : "Last upload: -";
        }
        async function scDivLoadLastUploads_(dcs, force) {
            try {
                if (force) scPubPaidMetaAt_ = 0;
                const meta = await scPubPaidMeta_();
                if (!meta) return false;
                (dcs || []).forEach((dc) => {
                    const k = normalizeDcName(dc);
                    const sig = meta[k] ? String(meta[k].sig || "") : "";
                    const ts = Number(sig.replace(/^~/, "").split("|")[1] || 0) || 0;
                    if (ts > Number(scDivLastUp_[k] || 0)) scDivLastUp_[k] = ts;
                });
                return true;
            } catch (_) { return false; }
        }
        // USER REQUEST (2026-10-21): jis DC ki Master khaali ho uske saamne cash list table me warning.
        async function scDivMarkEmptyMasters_(dcs) {
            try {
                for (const dc of (dcs || [])) {
                    const st = await scBriefMasterState_(dc, false);
                    if (st !== "EMPTY") continue;
                    document.querySelectorAll('[data-mwarn]').forEach((el) => {
                        if (el.getAttribute("data-mwarn") !== dc || el.querySelector(".mwarn-flag")) return;
                        el.insertAdjacentHTML("beforeend", '<div class="mwarn-flag" style="font-size:0.56rem; font-weight:900; color:#b91c1c; margin-top:2px;">⚠ Master is empty</div>');
                    });
                }
            } catch (_) {}
        }
        let scDivUploadCtx_ = null;
        function scDivRenderLastOnly_(dcs) {
            const box = document.getElementById("division-paid-upload-table");
            if (!box) return;
            box.innerHTML = `<div style="display:grid; grid-template-columns:1.2fr 1.6fr; gap:4px; font-size:0.62rem; font-weight:950; color:#14532d; border-bottom:1.5px solid #bbf7d0; padding-bottom:4px;"><div>DC</div><div>LAST UPLOAD</div></div>` +
                dcs.map((dc) => { const ms = Number(scDivLastUp_[normalizeDcName(dc)] || 0); return `<div style="display:grid; grid-template-columns:1.2fr 1.6fr; gap:4px; font-size:0.64rem; font-weight:850; color:#0f172a; padding:4px 0; border-bottom:1px solid #f1f5f9;"><div data-mwarn="${escapeHtml(dc)}">${escapeHtml(dc)}</div><div style="color:${ms ? "#0f172a" : "#b91c1c"};">${ms ? `${scBriefDateOf_(ms)} ${scBriefHm_(ms)}` : "Never"}</div></div>`; }).join("");
            scDivMarkEmptyMasters_(dcs);
        }
        async function scDivShowLastUploads_() {
            if (scDivUploadCtx_ && scDivUploadCtx_.division === (activeDiv || "")) { renderDivisionPaidUploadTable_(scDivUploadCtx_.plan); return; }
            const dcs = getDivisionDcNames(activeDiv || "").map(normalizeDcName);
            if (!dcs.length) return;
            const box = document.getElementById("division-paid-upload-table");
            if (box) box.innerHTML = `<div style="font-size:0.66rem; font-weight:850; color:#64748b; text-align:center; padding:6px;">Checking the last upload of each DC...</div>`;
            await scDivLoadLastUploads_(dcs, true);
            if (scDivUploadCtx_ || divisionPaidUploadInProgress_) return;
            scDivRenderLastOnly_(dcs);
        }
        function renderDivisionPaidUploadTable_(plan) {
            const box = document.getElementById("division-paid-upload-table");
            if (!box) return;
            const colors = { WAITING: "#64748b", UPLOADING: "#b45309", DONE: "#15803d", PENDING: "#b45309", FAILED: "#b91c1c", SKIPPED: "#64748b" };
            const busy = divisionPaidUploadInProgress_;
            box.innerHTML = `<div style="display:grid; grid-template-columns:1.4fr 0.8fr 0.7fr 1.3fr; gap:4px; font-size:0.62rem; font-weight:950; color:#14532d; border-bottom:1.5px solid #bbf7d0; padding-bottom:4px;"><div>DC</div><div>NORMAL</div><div>AG</div><div>STATUS</div></div>` +
                plan.map((p, i) => {
                    const canRetry = (p.status === "FAILED" || p.status === "PENDING") && !busy;
                    const retryBtn = canRetry ? `<button onclick="scDivRetryDc_(${i})" style="display:block; margin-top:4px; border:none; border-radius:9px; background:#dc2626; color:#fff; font-size:0.62rem; font-weight:950; padding:5px 8px;">🔄 Try Again</button>` : "";
                    return `<div style="display:grid; grid-template-columns:1.4fr 0.8fr 0.7fr 1.3fr; gap:4px; font-size:0.64rem; font-weight:850; color:#0f172a; padding:4px 0; border-bottom:1px solid #f1f5f9;"><div data-mwarn="${escapeHtml(p.dc)}">${escapeHtml(p.dc)}<div style="font-size:0.56rem; font-weight:800; color:#64748b; margin-top:2px;">${escapeHtml(scDivLastUpText_(p.dc))}</div></div><div>${p.normal.length}</div><div>${p.ag.length}</div><div style="color:${colors[p.status] || "#0f172a"}; font-weight:950;">${escapeHtml(p.statusText || p.status)}${retryBtn}</div></div>`;
                }).join("");
            scDivMarkEmptyMasters_(plan.map((p) => p.dc));
        }
        function scDivSummaryText_(ctx) {
            const plan = ctx.plan;
            const done = plan.filter((p) => p.status === "DONE").length;
            const failed = plan.filter((p) => p.status === "FAILED").length;
            const pend = plan.filter((p) => p.status === "PENDING").length;
            return { ok: !failed, failed, html: `Cash list of ${done} DCs uploaded.${failed ? ` ${failed} DC FAILED - press "Try Again" next to them.` : ""}${pend ? ` ${pend} DC confirmation pending.` : ""}${ctx.note || ""}` };
        }
        // Ek DC ka upload (Division file se bani rows) - pehle loop ke andar tha, ab retry bhi isi se.
        async function scDivUploadOne_(p, ctx) {
            p.status = "UPLOADING"; p.statusText = "Uploading..."; renderDivisionPaidUploadTable_(ctx.plan);
            if (p.clearAgOnly) {
                // 2026-10-21: is DC ki AG file me koi row nahi - sirf purani AG rows hatao (NORMAL nahi chhuti)
                try {
                    const cp = new URLSearchParams();
                    cp.append("action", "clearPaidAg");
                    cp.append("division_name", ctx.division);
                    cp.append("division_password", divisionPaidUploadPassword_);
                    cp.append("dc_name", p.dc);
                    const cr = await fetchWithTimeout(revenueCollectionSubmitScriptUrl, { method: "POST", headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" }, body: cp.toString() }, 120000);
                    let pj = {};
                    try { pj = JSON.parse(await cr.text() || "{}"); } catch (_) {}
                    if (pj.status === "success") {
                        p.status = "DONE"; p.statusText = `✅ Old AG cleared (${Number(pj.ag_rows_removed || 0)} rows)`;
                        scPubPaidMetaAt_ = 0;
                    } else {
                        p.status = "FAILED"; p.statusText = pj.message || "AG clear failed";
                        if (/password/i.test(p.statusText)) throw Object.assign(new Error(p.statusText), { stopAll: true });
                    }
                } catch (err) {
                    if (err && err.stopAll) throw err;
                    if (p.status !== "DONE") { p.status = "FAILED"; p.statusText = "AG clear failed - press Try Again"; }
                }
                renderDivisionPaidUploadTable_(ctx.plan);
                return;
            }
            const allRows = [...p.normal, ...p.ag];
            const entries = buildRevenuePaidUploadEntries(allRows, p.dc);
            if (!entries.length) { p.status = "SKIPPED"; p.statusText = "No valid rows"; renderDivisionPaidUploadTable_(ctx.plan); return; }
            saveRevenueUploadedPaidEntriesLocalBulk(entries, p.dc, true);
            try { await saveRevenueCategoryRawPaymentRows(allRows, p.dc); } catch (_) {}
            const attemptAt = new Date().toISOString();
            const payload = new URLSearchParams();
            payload.append("action", "uploadPaidMaster");
            payload.append("upload_scope", "DIVISION");
            payload.append("division_name", ctx.division);
            payload.append("division_password", divisionPaidUploadPassword_);
            payload.append("dc_name", p.dc);
            payload.append("uploaded_at", new Date().toISOString());
            payload.append("entries_json", JSON.stringify(entries));
            payload.append("skip_ag_ivrs", JSON.stringify(p.skipAgIvrs || []));
            if (ctx.agFileSelected) payload.append("replace_ag", "1"); // 2026-10-21: AG file chuni thi - purani AG replace
            let result = null;
            let synced = false;
            try {
                const response = await fetchWithTimeout(revenueCollectionSubmitScriptUrl, {
                    method: "POST",
                    headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                    body: payload.toString()
                }, 300000);
                const text = await response.text();
                let parsed = {};
                try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                if (!response.ok || parsed.status === "error") {
                    const msg = parsed.message || "Upload failed";
                    p.status = "FAILED"; p.statusText = msg;
                    renderDivisionPaidUploadTable_(ctx.plan);
                    if (/password/i.test(msg)) throw Object.assign(new Error(msg), { stopAll: true });
                    return;
                }
                if (parsed.status === "success") {
                    synced = true;
                    result = parsed;
                }
            } catch (err) {
                if (err && err.stopAll) throw err;
            }
            if (!synced) {
                p.statusText = "Verifying..."; renderDivisionPaidUploadTable_(ctx.plan);
                synced = await verifyRevenuePaidBackendUpload(entries, p.dc, 30, attemptAt < ctx.startedAt ? attemptAt : ctx.startedAt);
            }
            const paymentRowCount = entries.reduce((t, e) => t + getRevenueUploadedPaidPaymentRows(e).length, 0);
            saveRevenuePaidUploadMeta({
                dcName: p.dc, uniqueCount: entries.length, paymentRowCount,
                normalRows: p.normal.length, agRows: p.ag.length,
                uploadedAt: new Date().toISOString(), oldDataReplaced: true,
                backendSynced: synced, backendConfirmedBy: synced ? (result ? "RESPONSE" : "VERIFICATION") : "",
                backendRowsSaved: result ? Number(result.rows_saved || 0) : null,
                backendNormalRows: result ? Number(result.normal_rows_this_upload || 0) : null,
                backendAgRowsUpdated: result ? Number(result.ag_rows_updated_this_upload || 0) : null
            });
            if (synced) {
                p.status = "DONE";
                p.statusText = result ? `✅ Normal ${result.normal_rows_this_upload || 0}, AG ${result.ag_rows_updated_this_upload || 0}` : "✅ Verified";
                try {
                    // 2026-10-21: file ki AG rows aur sheet me gayi AG rows me fark ho to wajah saaf likho
                    const agSaved_ = Number((result && result.ag_rows_updated_this_upload) || 0);
                    const agFileRows_ = p.ag.length;
                    if (result && agFileRows_ > agSaved_) {
                        const agUniq_ = new Set(p.ag.map((r) => normalizeRevenueIvrs(r.ivrsNo))).size;
                        const merged_ = agFileRows_ - agUniq_, inNormal_ = Math.max(0, agUniq_ - agSaved_);
                        const parts_ = [];
                        if (merged_ > 0) parts_.push(`${merged_} repeat payment merged`);
                        if (inNormal_ > 0) parts_.push(`${inNormal_} already in Normal`);
                        p.statusText += ` (file AG rows ${agFileRows_}: ${parts_.join(", ") || "duplicates removed"})`;
                    }
                } catch (_) {}
                scDivLastUp_[normalizeDcName(p.dc)] = Date.now();
            } else {
                p.status = "PENDING"; p.statusText = "Sent, confirmation pending";
            }
            renderDivisionPaidUploadTable_(ctx.plan);
        }
        async function scDivRetryDc_(i) {
            const ctx = scDivUploadCtx_;
            const p = ctx && ctx.plan && ctx.plan[i];
            if (!p) return;
            if (divisionPaidUploadInProgress_) return showToast("Upload in progress, please wait", false);
            if (!divisionPaidUploadPassword_) { showToast("Please enter the password again", false); initDivisionPaidUpload(); return; }
            if (!(p.status === "FAILED" || p.status === "PENDING")) return;
            const btn = document.getElementById("division-paid-upload-btn");
            divisionPaidUploadInProgress_ = true;
            if (btn) { btn.disabled = true; btn.textContent = "UPLOADING... PLEASE WAIT"; }
            try {
                setDivisionPaidUploadStatus_(`Upload of ${escapeHtml(p.dc)} is running again...`, true);
                await scDivUploadOne_(p, ctx);
                await scDivLoadLastUploads_([p.dc], true);
                const sm = scDivSummaryText_(ctx);
                setDivisionPaidUploadStatus_(sm.html, sm.ok);
                showToast(p.status === "DONE" ? `${p.dc} uploaded` : (p.status === "PENDING" ? `${p.dc}: sent, confirmation pending` : `${p.dc} still failing - press Try Again after some time`), p.status === "DONE");
                try { checkRevenueUploadFreshness(); } catch (_) {}
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionPaidUploadPassword_ = "";
                setDivisionPaidUploadStatus_(escapeHtml(error?.message || "Upload failed"), false);
                showToast(error?.message || "Upload failed", false);
                if (!divisionPaidUploadPassword_) setTimeout(initDivisionPaidUpload, 1500);
            } finally {
                divisionPaidUploadInProgress_ = false;
                if (btn) { btn.disabled = false; btn.textContent = "UPLOAD DIVISION CASH LIST"; }
                renderDivisionPaidUploadTable_(ctx.plan);
            }
        }
        // =====================================================================
        // DIVISION MASTER UPLOAD (2026-10-17, USER REQUEST)
        // Division dashboard ⋮ menu -> "Division Master Upload". Poore Division ki ek file
        // (12 column, fixed header) -> har DC me IVRS/pehle 4 ank se baant kar Division Master
        // sheet ke us DC tab me REPLACE (purana backup tab me). Pehle CHECK FILE (preview),
        // phir UPLOAD. Password = Division Upload password (wahi jo Division Cash List ka hai).
        // =====================================================================
        let scDivMasterCtx_ = null;
        let divisionMasterBusy_ = false;
        let divisionMasterPassword_ = "";

        function openDivisionMasterAdmin() {
            closeHeaderMenu();
            switchView("division-master-upload");
        }
        function initDivisionMasterUpload() {
            const lock = document.getElementById("divmaster-lock-box");
            const panel = document.getElementById("divmaster-panel");
            if (lock) lock.style.display = divisionMasterPassword_ ? "none" : "block";
            if (panel) panel.style.display = divisionMasterPassword_ ? "block" : "none";
            scDivMasterSyncChooser_();
            if (divisionMasterPassword_ && !divisionMasterBusy_) scDivMasterShowState_();
        }
        // Dono division ke button; ek chunne par dusra chhup jaata hai, upar chuni hui division ka naam likha rehta hai
        function scDivMasterSyncChooser_() {
            const key = scDivMasterKey_();
            const title = document.getElementById("divmaster-div");
            if (title) title.textContent = key ? `DIVISION ${key}` : "Select Division";
            ["SEONI", "LAKHNADON"].forEach((k) => {
                const b = document.getElementById(`divmaster-btn-${k}`);
                if (b) b.style.display = (!key || key === k) ? "block" : "none";
            });
            const choose = document.getElementById("divmaster-choose");
            if (choose) choose.style.display = key ? "none" : "flex";
            const change = document.getElementById("divmaster-change-btn");
            if (change) change.style.display = key ? "block" : "none";
        }
        function chooseDivMasterDivision(key) {
            if (divisionMasterBusy_) return;
            const inp = document.getElementById("divmaster-division");
            if (inp) inp.value = key;
            onDivMasterDivisionChange();
        }
        function changeDivMasterDivision() {
            if (divisionMasterBusy_) return showToast("Please wait, work in progress", false);
            const inp = document.getElementById("divmaster-division");
            if (inp) inp.value = "";
            onDivMasterDivisionChange();
        }
        function onDivMasterDivisionChange() {
            if (divisionMasterBusy_) return;
            scDivMasterSyncChooser_();
            scDivMasterCtx_ = null;
            setDivMasterPreview_("");
            setDivMasterStatus_("", true);
            const upBtn = document.getElementById("divmaster-upload-btn");
            if (upBtn) upBtn.style.display = "none";
            scDivMasterShowState_();
        }
        async function unlockDivisionMasterUpload() {
            const input = document.getElementById("divmaster-password");
            const password = String(input?.value || "").trim();
            if (!password) return showToast("Enter password", false);
            const vr = await scVerifyAdminPassword_(revenueCollectionSubmitScriptUrl, { action: "verifyAdminPassword", type: "divmaster", admin_password: password });
            if (vr === "wrong" || vr === "net") { scAdminPwdFailToast_(vr); if (vr === "wrong" && input) input.value = ""; return; }
            divisionMasterPassword_ = password;
            if (input) input.value = "";
            initDivisionMasterUpload();
        }
        function setDivMasterStatus_(html, ok = true) {
            const box = document.getElementById("divmaster-status");
            if (!box) return;
            box.style.display = html ? "block" : "none";
            box.style.background = ok ? "#eef2ff" : "#fff1f2";
            box.style.border = `1.5px solid ${ok ? "#a5b4fc" : "#fda4af"}`;
            box.style.color = ok ? "#312e81" : "#991b1b";
            box.innerHTML = html || "";
        }
        function setDivMasterPreview_(html) {
            const box = document.getElementById("divmaster-preview");
            if (box) box.innerHTML = html || "";
        }
        function scDivMasterAtText_(iso) {
            const ms = Date.parse(iso || "");
            return ms ? `${scBriefDateOf_(ms)} ${scBriefHm_(ms)}` : "-";
        }
        function scDivMasterKey_() {
            return String(document.getElementById("divmaster-division")?.value || "").trim().toUpperCase();
        }
        // Division ke har DC ki abhi ki sthiti (kaunsa source, kitni rows, kab upload)
        async function scDivMasterShowState_() {
            const box = document.getElementById("divmaster-state");
            if (!box) return;
            const dcs = getDivisionDcNames("DIVISION " + scDivMasterKey_()).map(normalizeDcName);
            if (!dcs.length) { box.innerHTML = `<div style="font-size:0.66rem; font-weight:850; color:#475569;">Select a Division to see the status of its DC.</div>`; return; }
            box.innerHTML = `<div style="font-size:0.66rem; font-weight:850; color:#475569;">Loading status...</div>`;
            const okNet = await scDivMasterRefresh_().catch(() => false);
            const head = `<div style="display:grid; grid-template-columns:1.2fr 0.9fr 0.7fr 1.3fr; gap:4px; font-size:0.6rem; font-weight:950; color:#312e81; border-bottom:1.5px solid #c7d2fe; padding-bottom:4px;"><div>DC</div><div>SOURCE</div><div style="text-align:right;">ROWS</div><div>LAST UPLOAD</div></div>`;
            const rows = dcs.map((dc) => {
                const m = scDivMasterMeta_[dc];
                const up = m && m.state === "UPLOADED";
                return `<div style="display:grid; grid-template-columns:1.2fr 0.9fr 0.7fr 1.3fr; gap:4px; font-size:0.62rem; font-weight:850; color:#0f172a; padding:4px 0; border-bottom:1px solid #e0e7ff;"><div>${escapeHtml(dc)}</div><div style="color:${up ? "#15803d" : "#b45309"}; font-weight:950;">${up ? "DIVISION" : "OLD SHEET"}</div><div style="text-align:right;">${up ? escapeHtml(m.rows) : "-"}</div><div>${up ? escapeHtml(scDivMasterAtText_(m.at)) : "-"}</div></div>`;
            }).join("");
            box.innerHTML = (okNet ? "" : `<div style="font-size:0.62rem; font-weight:850; color:#b45309; margin-bottom:4px;">Division Master sheet could not be read (not set up yet or no internet). Showing saved status.</div>`) + head + rows;
        }

        function scDivMasterCell_(v) {
            if (v === null || v === undefined) return "";
            if (v instanceof Date) {
                if (isNaN(v.getTime())) return "";
                return `${v.getFullYear()}-${String(v.getMonth() + 1).padStart(2, "0")}-${String(v.getDate()).padStart(2, "0")}`;
            }
            if (typeof v === "number") return Number.isInteger(v) ? v.toFixed(0) : String(v);
            return String(v).trim();
        }
        // File padho: header kisi bhi row (pehli 30 me) par ho, columns aage-peeche ho sakte hain (naam se); 12 column zaroori.
        // UPDATE 127 (2026-10-29, USER REQUEST): galat data (jaise HQ NAME me HQ ki jagah EZ0220... jaisa consumer/service number) upload se PEHLE warning.
        // Upload rokta nahi, sirf saaf dikhata hai + upload par extra confirm.
        function scDivMasterBadRows_(rows) {
            const hqIdx = SC_DIVMASTER_COLS_.findIndex((c) => c.name === "HQ NAME");
            const bad = [];
            (rows || []).forEach((r) => {
                const hq = String(r[hqIdx] ?? "").trim();
                if (hq && /\d{6,}/.test(hq)) bad.push({ iv: String(r[0] ?? ""), village: String(r[SC_DIVMASTER_COLS_.findIndex((c) => c.name === "VILLAGE")] ?? ""), hq });
            });
            return bad;
        }
        function scDivMasterBadHtml_(bad) {
            if (!bad || !bad.length) return "";
            const list = bad.slice(0, 12).map((b) => `<div>${escapeHtml(b.iv)} | ${escapeHtml(b.village || "-")} | HQ NAME = ${escapeHtml(b.hq)}</div>`).join("");
            return `<div style="margin-top:8px; background:#fff1f2; border:1.5px solid #fda4af; border-radius:12px; padding:8px; font-size:0.62rem; font-weight:900; color:#991b1b; line-height:1.45;">WARNING: ${bad.length} rows have a number/code in HQ NAME instead of an HQ name. In reports each such code will show as a separate HQ. Please correct the file before uploading.<div style="margin-top:4px; font-weight:850;">${list}${bad.length > 12 ? `<div>... and ${bad.length - 12} more</div>` : ""}</div></div>`;
        }
        function scDivMasterReadFile_(buffer) {
            const workbook = XLSX.read(buffer, { type: "array", cellDates: true });
            let best = null;
            for (const name of workbook.SheetNames) {
                const matrix = XLSX.utils.sheet_to_json(workbook.Sheets[name], { header: 1, raw: true, defval: "" });
                const limit = Math.min(matrix.length, 30);
                for (let i = 0; i < limit; i++) {
                    const norm = (matrix[i] || []).map((c) => normalizeLookupValue(c));
                    const hasIvrs = norm.some((c) => SC_DIVMASTER_COLS_[0].keys.includes(c));
                    const hasNet = norm.includes("NETBILL");
                    if (hasIvrs && hasNet) { best = { matrix, headerRow: i, norm, sheet: name }; break; }
                }
                if (best) break;
            }
            if (!best) throw new Error("The file is not in the correct format (IVRS NO / NET BILL header not found).");
            const idx = SC_DIVMASTER_COLS_.map((col) => best.norm.findIndex((c) => col.keys.includes(c)));
            const missing = SC_DIVMASTER_COLS_.filter((col, k) => idx[k] < 0 && !col.optional).map((col) => col.name);
            if (missing.length) throw new Error(`Column missing in the file: ${missing.join(", ")}. All columns are required (CONNECTION DATE, CONSUMER STATUS, BENEFICIARY, SANCTION LOAD and UNIT are optional).`);
            const rows = [];
            for (let r = best.headerRow + 1; r < best.matrix.length; r++) {
                const src = best.matrix[r] || [];
                const out = idx.map((ci, k) => {
                    const raw = ci < 0 ? "" : src[ci];
                    if (SC_DIVMASTER_COLS_[k].name === "ARREARS" || SC_DIVMASTER_COLS_[k].name === "NET BILL") { // ARREARS, NET BILL - number rahe
                        if (typeof raw === "number") return raw;
                        const t = String(raw === null || raw === undefined ? "" : raw).replace(/,/g, "").trim();
                        return (t !== "" && isFinite(Number(t))) ? Number(t) : t;
                    }
                    return scDivMasterCell_(raw);
                });
                if (out.every((v) => String(v).trim() === "")) continue;
                rows.push(out);
            }
            return { rows, sheet: best.sheet };
        }

        async function checkDivisionMasterFile() {
            if (divisionMasterBusy_) return showToast("Please wait, work in progress", false);
            if (!divisionMasterPassword_) { showToast("Please enter the password again", false); initDivisionMasterUpload(); return; }
            const file = document.getElementById("divmaster-file")?.files?.[0] || null;
            if (!file) return showToast("Please select the Division Master file", false);
            if (!window.XLSX) return showToast("Excel reader could not be loaded. Please check internet and refresh.", false);
            const key = scDivMasterKey_();
            const division = key ? "DIVISION " + key : "";
            const divisionDcs = getDivisionDcNames(division).map(normalizeDcName);
            if (!divisionDcs.length || !SC_DIVMASTER_SHEETS_[key]) return showToast("Please select the Division first", false);
            divisionMasterBusy_ = true;
            const checkBtn = document.getElementById("divmaster-check-btn");
            const upBtn = document.getElementById("divmaster-upload-btn");
            if (checkBtn) { checkBtn.disabled = true; checkBtn.textContent = "CHECKING... PLEASE WAIT"; }
            if (upBtn) upBtn.style.display = "none";
            scDivMasterCtx_ = null;
            setDivMasterPreview_("");
            try {
                setDivMasterStatus_("Checking backend and Division Master sheet...", true);
                let ping = null;
                try {
                    ping = await scDivMasterPost_({ action: "dvmPing", division: key, admin_password: divisionMasterPassword_ }, 2);
                } catch (pingErr) {
                    if (/password/i.test(pingErr?.message || "")) throw pingErr;
                    throw new Error("Backend is not updated yet or cannot be reached. Please deploy the new backend version first.");
                }
                if (!ping || ping.dvm !== true || ping.headers !== SC_DIVMASTER_COLS_.map((c) => c.name).join("|")) throw new Error("Backend is not updated yet. Please deploy the new backend version first.");
                if (!ping.ready) throw new Error("Division Master sheet is not set up yet. Please run DVM_setup once in the backend.");
                setDivMasterStatus_("Reading the file...", true);
                const parsed = scDivMasterReadFile_(await file.arrayBuffer());
                setDivMasterStatus_(`Reading DC masters of ${escapeHtml(division)}...`, true);
                await ensureRevenueCategoryMasterDataLoaded(divisionDcs);
                const ivrsToDc = {};
                divisionDcs.forEach((dc) => {
                    getRevenueMasterRowsForDc(dc).forEach((r) => {
                        const iv = normalizeRevenueIvrs(r.ivrsNo);
                        if (iv && !ivrsToDc[iv]) ivrsToDc[iv] = dc;
                    });
                });
                try {
                    const emptyMasterDcs = divisionDcs.filter((dc) => { try { return getRevenueMasterRowsForDc(dc).length === 0; } catch (_) { return false; } });
                    if (emptyMasterDcs.length) {
                        const pubMeta = await scPubPaidMeta_();
                        if (pubMeta) {
                            await runWithConcurrencyLimit_(emptyMasterDcs.slice(), 4, async (dc) => {
                                const prev = await scPubPaidRowsForDc_(pubMeta, dc);
                                (prev || []).forEach((r) => { const iv = normalizeRevenueIvrs(r.ivrs_no); if (iv && !ivrsToDc[iv]) ivrsToDc[iv] = dc; });
                            });
                        }
                    }
                } catch (_) {}
                // pehle 4 ank -> DC: (1) is file ki rows jo master se mili (98% ek hi DC), (2) pichhle Division Master uploads se yaad ki hui
                const votes = {};
                const seenIvrs = new Set();
                let dupCount = 0, invalidCount = 0;
                const entries = parsed.rows.map((row) => {
                    const iv = normalizeRevenueIvrs(row[0]);
                    const valid = /^\d{10}$/.test(iv);
                    if (!valid) invalidCount++;
                    else if (seenIvrs.has(iv)) dupCount++;
                    else seenIvrs.add(iv);
                    if (valid) row[0] = iv;
                    const dc = valid ? (ivrsToDc[iv] || "") : "";
                    if (dc) { const pre = iv.slice(0, 4); votes[pre] = votes[pre] || {}; votes[pre][dc] = (votes[pre][dc] || 0) + 1; }
                    return { row, iv, valid, dc };
                });
                const prefixDc = {};
                Object.entries(votes).forEach(([pre, v]) => {
                    const sorted = Object.entries(v).sort((a, b) => b[1] - a[1]);
                    const total = sorted.reduce((s, x) => s + x[1], 0);
                    if (sorted[0] && sorted[0][1] / total >= 0.98) prefixDc[pre] = sorted[0][0];
                });
                const metaPrefix = {};
                Object.keys(scDivMasterMeta_).forEach((dc) => {
                    const m = scDivMasterMeta_[dc];
                    if (!m || m.state !== "UPLOADED") return;
                    (m.prefixes || []).forEach((p) => { metaPrefix[p] = metaPrefix[p] === undefined ? dc : (metaPrefix[p] === dc ? dc : null); });
                });
                const plan = divisionDcs.map((dc) => ({ dc, rows: [], status: "WAITING", text: "" }));
                const planByDc = Object.fromEntries(plan.map((p) => [p.dc, p]));
                const unassigned = [];
                let wrongDivision = 0;
                entries.forEach((e) => {
                    if (!e.valid) { unassigned.push(e.row); return; }
                    let dc = e.dc || SC_DIVMASTER_PREFIX_[e.iv.slice(0, 4)] || prefixDc[e.iv.slice(0, 4)] || metaPrefix[e.iv.slice(0, 4)] || "";
                    if (dc && !planByDc[dc]) { wrongDivision++; dc = ""; }
                    if (dc) { e.row[SC_DIVMASTER_DCNAME_IDX_] = dc; planByDc[dc].rows.push(e.row); } else unassigned.push(e.row);
                });
                plan.forEach((p) => {
                    p.prefixes = Array.from(new Set(p.rows.map((r) => String(r[0]).slice(0, 4))));
                    p.before = (() => { try { return getRevenueMasterRowsForDc(p.dc).length; } catch (_) { return 0; } })();
                });
                scDivMasterCtx_ = { division, key, plan, unassigned, fileName: file.name, wrongDivision, invalidCount, dupCount, total: parsed.rows.length, badHq: scDivMasterBadRows_(parsed.rows) };
                renderDivMasterPlan_();
                const withRows = plan.filter((p) => p.rows.length).length;
                if (!parsed.rows.length) {
                    setDivMasterStatus_("The file has no data rows.", false);
                } else if (!withRows) {
                    setDivMasterStatus_("No row could be matched to any DC of this Division. Please check that this is the correct Division file.", false);
                } else {
                    const badN_ = (scDivMasterCtx_.badHq || []).length;
                    setDivMasterStatus_(badN_ ? `File checked: ${parsed.rows.length} rows. WARNING: ${badN_} rows have wrong HQ NAME (see below). Correct the file first, or upload only if you accept this.` : `File checked: ${parsed.rows.length} rows, ${withRows} DC will be replaced. Please check the table, then press UPLOAD.`, !badN_);
                    if (upBtn) upBtn.style.display = "block";
                }
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionMasterPassword_ = "";
                setDivMasterStatus_(escapeHtml(error?.message || "Could not read the file"), false);
                showToast(error?.message || "Could not read the file", false);
                if (!divisionMasterPassword_) setTimeout(initDivisionMasterUpload, 1500);
            } finally {
                divisionMasterBusy_ = false;
                if (checkBtn) { checkBtn.disabled = false; checkBtn.textContent = "1. CHECK FILE"; }
            }
        }

        function renderDivMasterPlan_() {
            const ctx = scDivMasterCtx_;
            if (!ctx) return setDivMasterPreview_("");
            const colr = { WAITING: "#475569", UPLOADING: "#1d4ed8", DONE: "#15803d", FAILED: "#b91c1c", KEPT: "#b45309" };
            const grid = "grid-template-columns:1.25fr 0.6fr 0.6fr 1.45fr;";
            const head = `<div style="display:grid; ${grid} gap:4px; font-size:0.6rem; font-weight:950; color:#312e81; border-bottom:1.5px solid #c7d2fe; padding-bottom:4px;"><div>DC</div><div style="text-align:right;">FILE</div><div style="text-align:right;">NOW</div><div>STATUS</div></div>`;
            const rows = ctx.plan.map((p) => {
                const status = p.status === "WAITING" && !p.rows.length ? "KEPT" : p.status;
                const text = p.text || (status === "KEPT" ? "No rows in file - old data kept" : (status === "WAITING" ? "Will be replaced" : status));
                const retry = p.status === "FAILED" ? ` <a href="#" onclick="scDivMasterRetry_('${escapeHtml(p.dc)}'); return false;" style="color:#1d4ed8; font-weight:950;">Try Again</a>` : "";
                return `<div style="display:grid; ${grid} gap:4px; font-size:0.62rem; font-weight:850; color:#0f172a; padding:4px 0; border-bottom:1px solid #e0e7ff;"><div>${escapeHtml(p.dc)}</div><div style="text-align:right;">${p.rows.length}</div><div style="text-align:right;">${p.before}</div><div style="color:${colr[status] || "#475569"}; font-weight:950;">${escapeHtml(text)}${retry}</div></div>`;
            }).join("");
            const un = ctx.unassigned.length;
            const notes = [
                un ? `<div style="font-size:0.62rem; font-weight:950; color:#b45309; margin-top:6px;">${un} rows could not be assigned to a DC${ctx.wrongDivision ? ` (${ctx.wrongDivision} belong to another Division)` : ""}${ctx.invalidCount ? ` (${ctx.invalidCount} with invalid IVRS)` : ""} - they will be saved in the UNASSIGNED tab, not in any DC.</div>` : "",
                ctx.dupCount ? `<div style="font-size:0.62rem; font-weight:950; color:#b45309; margin-top:4px;">${ctx.dupCount} duplicate IVRS rows found in the file.</div>` : "",
                scDivMasterBadHtml_(ctx.badHq)
            ].join("");
            setDivMasterPreview_(`<div style="font-size:0.66rem; font-weight:950; color:#312e81; margin-bottom:6px;">${escapeHtml(ctx.fileName)} - ${ctx.total} rows</div>${head}${rows}${notes}`);
        }

        async function scDivMasterPost_(body, tries = 3) {
            let last = null;
            for (let a = 0; a < tries; a++) {
                try {
                    const res = await fetchWithTimeout(revenueCollectionSubmitScriptUrl, {
                        method: "POST",
                        headers: { "Content-Type": "text/plain;charset=UTF-8" },
                        body: JSON.stringify(body)
                    }, 120000);
                    const text = await res.text();
                    let parsed = {};
                    try { parsed = JSON.parse(text || "{}"); } catch (_) {}
                    if (parsed.status === "success") return parsed;
                    const msg = parsed.message || "Upload failed";
                    if (/password|upload session|sequence mismatch|mismatch|not in this division|unknown division|not uploaded yet/i.test(msg)) throw Object.assign(new Error(msg), { fatal: true });
                    last = new Error(msg);
                } catch (e) {
                    if (e && e.fatal) throw e;
                    last = e;
                }
                if (a < tries - 1) await new Promise((r) => setTimeout(r, 1500 * (a + 1)));
            }
            throw last || new Error("Upload failed");
        }

        async function scDivMasterUploadOne_(ctx, item, isUnassigned) {
            const dcName = isUnassigned ? "UNASSIGNED" : item.dc;
            const rows = isUnassigned ? ctx.unassigned : item.rows;
            const prevAt = (scDivMasterMeta_[dcName] || {}).at || "";
            const startedAt = Date.now();
            const CH = 4000;
            const base = { division: ctx.key, admin_password: divisionMasterPassword_, dc_name: dcName };
            item.status = "UPLOADING";
            let sent = 0;
            try {
                if (!rows.length) {
                    await scDivMasterPost_({ ...base, action: "dvmPut", stage: "FIRST", rows_before: 0, rows: [] });
                }
                for (let i = 0; i < rows.length; i += CH) {
                    const part = rows.slice(i, i + CH);
                    item.text = `Sending ${Math.min(i + part.length, rows.length)}/${rows.length}`;
                    renderDivMasterPlan_();
                    await scDivMasterPost_({ ...base, action: "dvmPut", stage: i === 0 ? "FIRST" : "APPEND", rows_before: i, rows: part });
                    sent += part.length;
                }
                item.text = "Saving...";
                renderDivMasterPlan_();
                try {
                    await scDivMasterPost_({ ...base, action: "dvmCommit", total: rows.length, prefixes: item.prefixes || [] }, 2);
                } catch (err) {
                    if (err && err.fatal && /password|division/i.test(err.message || "")) throw err;
                    // commit chala ho sakta hai par jawab nahi aaya - META dekh kar tay karo
                    await scDivMasterRefresh_().catch(() => false);
                    const m = scDivMasterMeta_[dcName] || {};
                    const t = Date.parse(m.at || "");
                    if (!(m.at && m.at !== prevAt && t >= startedAt - 60000)) throw err;
                }
                item.status = "DONE";
                item.text = isUnassigned ? `Saved (${rows.length})` : `Replaced (${rows.length} rows)`;
            } catch (err) {
                item.status = "FAILED";
                item.text = String(err?.message || "Failed").slice(0, 90);
                if (/password/i.test(err?.message || "")) throw Object.assign(err, { stopAll: true });
            }
            renderDivMasterPlan_();
        }

        async function uploadDivisionMaster() {
            const ctx = scDivMasterCtx_;
            if (!ctx) return showToast("Please check the file first", false);
            if (divisionMasterBusy_) return showToast("Upload in progress, please wait", false);
            if (!divisionMasterPassword_) { showToast("Please enter the password again", false); initDivisionMasterUpload(); return; }
            const todo = ctx.plan.filter((p) => p.rows.length);
            if (!todo.length) return showToast("Nothing to upload", false);
            const badWarn_ = (ctx.badHq || []).length ? `\n\nWARNING: ${ctx.badHq.length} rows have a number/code in HQ NAME instead of an HQ name.` : "";
            if (!window.confirm(`Replace the master of ${todo.length} DC of ${ctx.division} with this file?\n\nThe old data of each DC is kept in its BK- tab.${badWarn_}`)) return;
            divisionMasterBusy_ = true;
            const btn = document.getElementById("divmaster-upload-btn");
            const checkBtn = document.getElementById("divmaster-check-btn");
            if (btn) { btn.disabled = true; btn.textContent = "UPLOADING... PLEASE WAIT"; }
            if (checkBtn) checkBtn.disabled = true;
            try {
                setDivMasterStatus_("Uploading... please keep this screen open.", true);
                for (const item of todo) {
                    await scDivMasterUploadOne_(ctx, item, false);
                }
                // UNASSIGNED log (khaali ho to bhi purani list saaf)
                const unItem = { dc: "UNASSIGNED", rows: ctx.unassigned, status: "WAITING", text: "" };
                try { await scDivMasterUploadOne_(ctx, unItem, true); } catch (_) {}
                await scDivMasterRefresh_().catch(() => false);
                const done = todo.filter((p) => p.status === "DONE").length;
                const failed = todo.filter((p) => p.status === "FAILED").length;
                setDivMasterStatus_(failed
                    ? `${done} DC uploaded, ${failed} FAILED - press "Try Again" in the table for the failed DC.`
                    : `Done. ${done} DC now use the Division Master.`, !failed);
                showToast(failed ? `${failed} DC failed - press Try Again` : "Division Master uploaded", !failed);
                scDivMasterShowState_();
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionMasterPassword_ = "";
                setDivMasterStatus_(escapeHtml(error?.message || "Upload failed"), false);
                showToast(error?.message || "Upload failed", false);
                if (!divisionMasterPassword_) setTimeout(initDivisionMasterUpload, 1500);
            } finally {
                divisionMasterBusy_ = false;
                if (btn) { btn.disabled = false; btn.textContent = "2. UPLOAD TO DIVISION MASTER"; }
                if (checkBtn) checkBtn.disabled = false;
                renderDivMasterPlan_();
            }
        }
        async function scDivMasterRetry_(dc) {
            const ctx = scDivMasterCtx_;
            if (!ctx || divisionMasterBusy_) return;
            const item = ctx.plan.find((p) => p.dc === dc);
            if (!item || item.status !== "FAILED") return;
            divisionMasterBusy_ = true;
            try {
                await scDivMasterUploadOne_(ctx, item, false);
                await scDivMasterRefresh_().catch(() => false);
                setDivMasterStatus_(item.status === "DONE" ? `${escapeHtml(dc)} uploaded.` : `${escapeHtml(dc)} failed again - try after some time.`, item.status === "DONE");
                scDivMasterShowState_();
            } catch (error) {
                if (/password/i.test(error?.message || "")) { divisionMasterPassword_ = ""; setTimeout(initDivisionMasterUpload, 1000); }
                setDivMasterStatus_(escapeHtml(error?.message || "Upload failed"), false);
            } finally {
                divisionMasterBusy_ = false;
                renderDivMasterPlan_();
            }
        }

        // =====================================================================
        // UPDATE 124 (2026-10-29, USER REQUEST): "Add New Consumers" - naye NSC / connection ki rows DC ke Division Master tab me
        // sabse niche jodna (poora master dobara upload kiye bina). Purani rows nahi chhui jaati; jo IVRS pehle se hai wo skip.
        // Backend: dvmAppend (Seoni_Master_Backend_Code.gs). META ka UPLOADED AT badalta hai, isliye sabhi phone me turant naya data.
        // =====================================================================
        let scDivAddCtx_ = null;
        function setDivAddStatus_(html, ok = true) {
            const box = document.getElementById("divmaster-add-status");
            if (!box) return;
            box.style.display = html ? "block" : "none";
            box.style.background = ok ? "#ecfdf5" : "#fff1f2";
            box.style.border = `1.5px solid ${ok ? "#86efac" : "#fda4af"}`;
            box.style.color = ok ? "#14532d" : "#991b1b";
            box.innerHTML = html || "";
        }
        function setDivAddPreview_(html) {
            const box = document.getElementById("divmaster-add-preview");
            if (box) box.innerHTML = html || "";
        }
        function renderDivAddPlan_() {
            const ctx = scDivAddCtx_;
            if (!ctx) return setDivAddPreview_("");
            const colr = { WAITING: "#475569", UPLOADING: "#1d4ed8", DONE: "#15803d", FAILED: "#b91c1c", BLOCKED: "#b45309", NONE: "#64748b" };
            const grid = "grid-template-columns:1.2fr 0.5fr 0.6fr 0.6fr 1.3fr;";
            const head = `<div style="display:grid; ${grid} gap:4px; font-size:0.58rem; font-weight:950; color:#14532d; border-bottom:1.5px solid #86efac; padding-bottom:4px;"><div>DC</div><div style="text-align:right;">NEW</div><div style="text-align:right;">IN SHEET</div><div style="text-align:right;">NOW</div><div>STATUS</div></div>`;
            const rows = ctx.plan.filter((p) => p.rows.length || p.exists).map((p) => {
                const status = p.blocked ? "BLOCKED" : (p.status === "WAITING" && !p.rows.length ? "NONE" : p.status);
                const text = p.text || (p.blocked ? "DC master not uploaded - use full upload" : (status === "NONE" ? "Nothing new" : "Will be added"));
                const retry = p.status === "FAILED" ? ` <a href="#" onclick="scDivAddRetry_('${escapeHtml(p.dc)}'); return false;" style="color:#1d4ed8; font-weight:950;">Try Again</a>` : "";
                return `<div style="display:grid; ${grid} gap:4px; font-size:0.62rem; font-weight:850; color:#0f172a; padding:4px 0; border-bottom:1px solid #dcfce7;"><div>${escapeHtml(p.dc)}</div><div style="text-align:right; font-weight:950;">${p.rows.length}</div><div style="text-align:right;">${p.exists}</div><div style="text-align:right;">${p.before}</div><div style="color:${colr[status] || "#475569"}; font-weight:950;">${escapeHtml(text)}${retry}</div></div>`;
            }).join("");
            const notes = [
                ctx.unassigned ? `<div style="font-size:0.62rem; font-weight:950; color:#b45309; margin-top:6px;">${ctx.unassigned} rows could not be assigned to a DC of this Division (IVRS prefix not known${ctx.wrongDivision ? `; ${ctx.wrongDivision} belong to another Division` : ""}) - they will NOT be added.</div>` : "",
                ctx.invalid ? `<div style="font-size:0.62rem; font-weight:950; color:#b45309; margin-top:4px;">${ctx.invalid} rows with invalid IVRS (not 10 digits) - will NOT be added.</div>` : "",
                ctx.dup ? `<div style="font-size:0.62rem; font-weight:950; color:#b45309; margin-top:4px;">${ctx.dup} duplicate IVRS rows inside the file - only one is used.</div>` : "",
                scDivMasterBadHtml_(ctx.badHq)
            ].join("");
            setDivAddPreview_(`<div style="font-size:0.66rem; font-weight:950; color:#14532d; margin-bottom:6px;">${escapeHtml(ctx.fileName)} - ${ctx.total} rows</div>${head}${rows || `<div style="font-size:0.62rem; font-weight:850; color:#64748b; padding:6px 0;">No new consumer found in this file.</div>`}${notes}`);
        }
        async function checkAddNewConsumers() {
            if (divisionMasterBusy_) return showToast("Please wait, work in progress", false);
            if (!divisionMasterPassword_) { showToast("Please enter the password again", false); initDivisionMasterUpload(); return; }
            const file = document.getElementById("divmaster-add-file")?.files?.[0] || null;
            if (!file) return showToast("Please select the new consumers file", false);
            if (!window.XLSX) return showToast("Excel reader could not be loaded. Please check internet and refresh.", false);
            const key = scDivMasterKey_();
            const division = key ? "DIVISION " + key : "";
            const divisionDcs = getDivisionDcNames(division).map(normalizeDcName);
            if (!divisionDcs.length || !SC_DIVMASTER_SHEETS_[key]) return showToast("Please select the Division first", false);
            divisionMasterBusy_ = true;
            const checkBtn = document.getElementById("divmaster-add-check-btn");
            const upBtn = document.getElementById("divmaster-add-upload-btn");
            if (checkBtn) { checkBtn.disabled = true; checkBtn.textContent = "CHECKING... PLEASE WAIT"; }
            if (upBtn) upBtn.style.display = "none";
            scDivAddCtx_ = null;
            setDivAddPreview_("");
            try {
                setDivAddStatus_("Checking backend...", true);
                let ping = null;
                try {
                    ping = await scDivMasterPost_({ action: "dvmPing", division: key, admin_password: divisionMasterPassword_ }, 2);
                } catch (pingErr) {
                    if (/password/i.test(pingErr?.message || "")) throw pingErr;
                    throw new Error("Backend is not updated yet or cannot be reached. Please deploy the new backend version first.");
                }
                if (!ping || ping.dvm !== true || ping.headers !== SC_DIVMASTER_COLS_.map((c) => c.name).join("|")) throw new Error("Backend is not updated yet. Please deploy the new backend version first.");
                if (ping.append !== true) throw new Error("Backend is not updated for Add New Consumers yet. Please deploy the new backend version first.");
                if (!ping.ready) throw new Error("Division Master sheet is not set up yet. Please run DVM_setup once in the backend.");
                setDivAddStatus_("Reading the file...", true);
                const parsed = scDivMasterReadFile_(await file.arrayBuffer());
                setDivAddStatus_(`Reading DC masters of ${escapeHtml(division)}...`, true);
                await scDivMasterRefresh_().catch(() => false);
                await ensureRevenueCategoryMasterDataLoaded(divisionDcs);
                const ivrsToDc = {};
                const votes = {};
                divisionDcs.forEach((dc) => {
                    getRevenueMasterRowsForDc(dc).forEach((r) => {
                        const iv = normalizeRevenueIvrs(r.ivrsNo);
                        if (!iv) return;
                        if (!ivrsToDc[iv]) ivrsToDc[iv] = dc;
                        const pre = iv.slice(0, 4);
                        votes[pre] = votes[pre] || {};
                        votes[pre][dc] = (votes[pre][dc] || 0) + 1;
                    });
                });
                const prefixDc = {};
                Object.entries(votes).forEach(([pre, v]) => {
                    const sorted = Object.entries(v).sort((a, b) => b[1] - a[1]);
                    const total = sorted.reduce((sum, x) => sum + x[1], 0);
                    if (sorted[0] && sorted[0][1] / total >= 0.98) prefixDc[pre] = sorted[0][0];
                });
                const plan = divisionDcs.map((dc) => {
                    const m = scDivMasterMeta_[dc];
                    return { dc, rows: [], exists: 0, status: "WAITING", text: "", blocked: !(m && m.state === "UPLOADED"), before: (() => { try { return getRevenueMasterRowsForDc(dc).length; } catch (_) { return 0; } })() };
                });
                const planByDc = Object.fromEntries(plan.map((p) => [p.dc, p]));
                const seen = new Set();
                let invalid = 0, dup = 0, unassigned = 0, wrongDivision = 0;
                parsed.rows.forEach((row) => {
                    const iv = normalizeRevenueIvrs(row[0]);
                    if (!/^\d{10}$/.test(iv)) { invalid++; return; }
                    if (seen.has(iv)) { dup++; return; }
                    seen.add(iv);
                    row[0] = iv;
                    if (ivrsToDc[iv]) { if (planByDc[ivrsToDc[iv]]) planByDc[ivrsToDc[iv]].exists++; return; }
                    let dc = SC_DIVMASTER_PREFIX_[iv.slice(0, 4)] || prefixDc[iv.slice(0, 4)] || "";
                    if (dc && !planByDc[dc]) { wrongDivision++; dc = ""; }
                    if (!dc) { unassigned++; return; }
                    row[SC_DIVMASTER_DCNAME_IDX_] = dc;
                    planByDc[dc].rows.push(row);
                });
                plan.forEach((p) => { p.prefixes = Array.from(new Set(p.rows.map((r) => String(r[0]).slice(0, 4)))); });
                scDivAddCtx_ = { division, key, plan, fileName: file.name, total: parsed.rows.length, invalid, dup, unassigned, wrongDivision, badHq: scDivMasterBadRows_(plan.flatMap((p) => p.rows)) };
                renderDivAddPlan_();
                const addable = plan.filter((p) => p.rows.length && !p.blocked);
                const totalNew = addable.reduce((sum, p) => sum + p.rows.length, 0);
                if (!parsed.rows.length) setDivAddStatus_("The file has no data rows.", false);
                else if (!totalNew) setDivAddStatus_("No new consumer found. All consumers of this file are already in the Division Master (or could not be assigned).", false);
                else {
                    const badA_ = (scDivAddCtx_.badHq || []).length;
                    setDivAddStatus_(badA_ ? `File checked: ${totalNew} new consumers. WARNING: ${badA_} of them have wrong HQ NAME (see below). Correct the file first, or add only if you accept this.` : `File checked: ${totalNew} new consumers for ${addable.length} DC. Old data is not changed. Press ADD to continue.`, !badA_);
                    if (upBtn) upBtn.style.display = "block";
                }
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionMasterPassword_ = "";
                setDivAddStatus_(escapeHtml(error?.message || "Could not read the file"), false);
                showToast(error?.message || "Could not read the file", false);
                if (!divisionMasterPassword_) setTimeout(initDivisionMasterUpload, 1500);
            } finally {
                divisionMasterBusy_ = false;
                if (checkBtn) { checkBtn.disabled = false; checkBtn.textContent = "A1. CHECK NEW CONSUMERS"; }
            }
        }
        async function scDivAddOne_(ctx, item) {
            const CH = 2000;
            let added = 0, skipped = 0;
            item.status = "UPLOADING";
            try {
                for (let i = 0; i < item.rows.length; i += CH) {
                    const part = item.rows.slice(i, i + CH);
                    item.text = `Sending ${Math.min(i + part.length, item.rows.length)}/${item.rows.length}`;
                    renderDivAddPlan_();
                    const res = await scDivMasterPost_({ action: "dvmAppend", division: ctx.key, admin_password: divisionMasterPassword_, dc_name: item.dc, rows: part, prefixes: item.prefixes || [] });
                    added += Number(res.added || 0);
                    skipped += Number(res.skipped || 0);
                }
                item.status = "DONE";
                item.added = added;
                item.text = `Added ${added}${skipped ? `, ${skipped} already there` : ""}`;
            } catch (err) {
                item.status = "FAILED";
                item.text = String(err?.message || "Failed").slice(0, 90);
                if (/password/i.test(err?.message || "")) throw Object.assign(err, { stopAll: true });
            }
            renderDivAddPlan_();
        }
        async function addNewConsumers() {
            const ctx = scDivAddCtx_;
            if (!ctx) return showToast("Please check the file first", false);
            if (divisionMasterBusy_) return showToast("Work in progress, please wait", false);
            if (!divisionMasterPassword_) { showToast("Please enter the password again", false); initDivisionMasterUpload(); return; }
            const todo = ctx.plan.filter((p) => p.rows.length && !p.blocked);
            if (!todo.length) return showToast("Nothing to add", false);
            const totalNew = todo.reduce((sum, p) => sum + p.rows.length, 0);
            const badWarnA_ = (ctx.badHq || []).length ? `\n\nWARNING: ${ctx.badHq.length} rows have a number/code in HQ NAME instead of an HQ name.` : "";
            if (!window.confirm(`Add ${totalNew} new consumers to ${todo.length} DC of ${ctx.division}?\n\nExisting consumers are not changed.${badWarnA_}`)) return;
            divisionMasterBusy_ = true;
            const btn = document.getElementById("divmaster-add-upload-btn");
            const checkBtn = document.getElementById("divmaster-add-check-btn");
            if (btn) { btn.disabled = true; btn.textContent = "ADDING... PLEASE WAIT"; }
            if (checkBtn) checkBtn.disabled = true;
            try {
                setDivAddStatus_("Adding... please keep this screen open.", true);
                for (const item of todo) await scDivAddOne_(ctx, item);
                await scDivMasterRefresh_().catch(() => false);
                const done = todo.filter((p) => p.status === "DONE");
                const failed = todo.filter((p) => p.status === "FAILED").length;
                const addedTotal = done.reduce((sum, p) => sum + Number(p.added || 0), 0);
                setDivAddStatus_(failed
                    ? `${addedTotal} consumers added, ${failed} DC FAILED - press "Try Again" in the table.`
                    : `Done. ${addedTotal} new consumers added to ${done.length} DC.`, !failed);
                showToast(failed ? `${failed} DC failed - press Try Again` : "New consumers added", !failed);
                scDivMasterShowState_();
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionMasterPassword_ = "";
                setDivAddStatus_(escapeHtml(error?.message || "Failed"), false);
                showToast(error?.message || "Failed", false);
                if (!divisionMasterPassword_) setTimeout(initDivisionMasterUpload, 1500);
            } finally {
                divisionMasterBusy_ = false;
                if (btn) { btn.disabled = false; btn.textContent = "A2. ADD TO DIVISION MASTER"; }
                if (checkBtn) checkBtn.disabled = false;
                renderDivAddPlan_();
            }
        }
        async function scDivAddRetry_(dc) {
            const ctx = scDivAddCtx_;
            if (!ctx || divisionMasterBusy_) return;
            const item = ctx.plan.find((p) => p.dc === dc);
            if (!item || item.status !== "FAILED") return;
            divisionMasterBusy_ = true;
            try {
                await scDivAddOne_(ctx, item);
                await scDivMasterRefresh_().catch(() => false);
                setDivAddStatus_(item.status === "DONE" ? `${escapeHtml(dc)}: ${escapeHtml(item.text)}` : `${escapeHtml(dc)} failed again - try after some time.`, item.status === "DONE");
                scDivMasterShowState_();
            } catch (error) {
                if (/password/i.test(error?.message || "")) { divisionMasterPassword_ = ""; setTimeout(initDivisionMasterUpload, 1000); }
                setDivAddStatus_(escapeHtml(error?.message || "Failed"), false);
            } finally {
                divisionMasterBusy_ = false;
                renderDivAddPlan_();
            }
        }

        // UPDATE 128 (2026-10-29): HQ CHECK - har DC ke HQ naam + consumer count; number/code wale ya bahut kam consumer wale HQ laal (spelling galti ka shak).
        async function checkDivisionHq() {
            const box = document.getElementById("divmaster-hq-result");
            const btn = document.getElementById("divmaster-hq-check-btn");
            if (!box) return;
            if (divisionMasterBusy_) return showToast("Please wait, work in progress", false);
            const key = scDivMasterKey_();
            const division = key ? "DIVISION " + key : "";
            const dcs = getDivisionDcNames(division).map(normalizeDcName);
            if (!dcs.length) return showToast("Please select the Division first", false);
            divisionMasterBusy_ = true;
            if (btn) { btn.disabled = true; btn.textContent = "CHECKING... PLEASE WAIT"; }
            box.innerHTML = `<div style="font-size:0.7rem; font-weight:900; color:#475569;">Reading DC masters...</div>`;
            try {
                await scDivMasterRefresh_().catch(() => false);
                await ensureRevenueCategoryMasterDataLoaded(dcs);
                let html = "";
                let suspectTotal = 0;
                dcs.forEach((dc) => {
                    let rows = [];
                    try { rows = getRevenueMasterRowsForDc(dc); } catch (_) {}
                    const map = new Map();
                    rows.forEach((r) => {
                        const hq = String(r.hqName ?? r["HQ NAME"] ?? "").trim().toUpperCase() || "(BLANK)";
                        const e = map.get(hq) || { n: 0, iv: "" };
                        e.n++; if (!e.iv) e.iv = r.ivrsNo || "";
                        map.set(hq, e);
                    });
                    const list = Array.from(map.entries()).sort((a, b) => b[1].n - a[1].n);
                    const suspect = list.filter(([hq, e]) => hq === "(BLANK)" || /\d{6,}/.test(hq) || e.n <= 5);
                    suspectTotal += suspect.length;
                    const chips = list.map(([hq, e]) => {
                        const bad = suspect.some((x) => x[0] === hq);
                        return `<span style="display:inline-block; margin:2px 3px 2px 0; padding:2px 7px; border-radius:10px; font-size:0.58rem; font-weight:900; background:${bad ? "#fee2e2" : "#e0f2fe"}; color:${bad ? "#991b1b" : "#075985"}; border:1px solid ${bad ? "#fca5a5" : "#bae6fd"};">${escapeHtml(hq)} (${e.n})${bad && e.iv ? ` - e.g. ${escapeHtml(e.iv)}` : ""}</span>`;
                    }).join("");
                    html += `<div style="padding:6px 0; border-bottom:1px solid #fed7aa;"><div style="font-size:0.66rem; font-weight:950; color:#7c2d12;">${escapeHtml(dc)} - ${rows.length} consumers, ${list.length} HQ${suspect.length ? ` - <span style="color:#b91c1c;">${suspect.length} to check</span>` : ` - <span style="color:#15803d;">OK</span>`}</div><div style="margin-top:3px;">${rows.length ? chips : `<span style="font-size:0.6rem; color:#64748b;">No master data</span>`}</div></div>`;
                });
                box.innerHTML = `<div style="font-size:0.7rem; font-weight:950; color:${suspectTotal ? "#b91c1c" : "#15803d"}; margin-bottom:6px;">${suspectTotal ? `${suspectTotal} HQ names need checking (red).` : "All HQ names look fine."} Red = number/code, blank, or 5 or fewer consumers.</div>${html}`;
            } catch (error) {
                box.innerHTML = `<div style="font-size:0.7rem; font-weight:900; color:#b91c1c;">${escapeHtml(error?.message || "Could not check")}</div>`;
            } finally {
                divisionMasterBusy_ = false;
                if (btn) { btn.disabled = false; btn.textContent = "CHECK HQ NAMES"; }
            }
        }

        function getSheetRowsFromFile_(buffer) {
            const workbook = XLSX.read(buffer, { type: "array", cellDates: true });
            return scPickPaidSheetRows_(workbook); // 2026-09-28: jis sheet me Cash List header ho
        }
        function matchDivisionDcFromLocationText_(text, divisionDcs) {
            const inner = String(text || "").match(/\(([^)]+)\)/);
            const raw = normalizeLookupValue(inner ? inner[1] : text).replace("LAKHNADAUN", "LAKHNADON");
            return divisionDcs.find((dc) => normalizeLookupValue(dc) === raw) || "";
        }
        async function uploadDivisionPaidFiles() {
            const normalFile = document.getElementById("division-paid-normal-file")?.files?.[0] || null;
            const agFile = document.getElementById("division-paid-ag-file")?.files?.[0] || null;
            const btn = document.getElementById("division-paid-upload-btn");
            if (divisionPaidUploadInProgress_) return showToast("Upload in progress, please wait", false);
            if (!normalFile && !agFile) return showToast("Please select at least one file", false);
            if (!window.XLSX) return showToast("Excel reader could not be loaded. Please check internet and refresh.", false);
            const division = activeDiv || "";
            const divisionDcs = getDivisionDcNames(division).map(normalizeDcName);
            if (!divisionDcs.length) return showToast("Division is not selected", false);
            divisionPaidUploadInProgress_ = true;
            if (btn) { btn.disabled = true; btn.textContent = "UPLOADING... PLEASE WAIT"; }
            const startedAt = new Date().toISOString();
            try {
                setDivisionPaidUploadStatus_("Reading files and loading DC masters...", true);
                await ensureRevenueCategoryMasterDataLoaded(divisionDcs);
                const ivrsToDc = {};
                divisionDcs.forEach((dc) => {
                    getRevenueMasterRowsForDc(dc).forEach((r) => {
                        const iv = normalizeRevenueIvrs(r.ivrsNo);
                        if (iv && !ivrsToDc[iv]) ivrsToDc[iv] = dc;
                    });
                });
                // 2026-10-12 (USER REQUEST): jis DC ka master abhi khaali hai (naya master shaam ko aata hai) uske consumers
                // master se nahi mil sakte - uski PICHHLI upload hui paid list ke IVRS se DC pehchano (sirf khaali-master DC ke liye,
                // aur sirf wahi IVRS jo kisi aur DC ke master me nahi). Prefix wala purana tareeka is par apne-aap chalega.
                try {
                    const emptyMasterDcs = divisionDcs.filter((dc) => { try { return getRevenueMasterRowsForDc(dc).length === 0; } catch (_) { return false; } });
                    if (emptyMasterDcs.length) {
                        const scPubFb = await scPubPaidMeta_();
                        if (scPubFb) {
                            await runWithConcurrencyLimit_(emptyMasterDcs.slice(), 4, async (dc) => {
                                const prev = await scPubPaidRowsForDc_(scPubFb, dc);
                                (prev || []).forEach((r) => { const iv = normalizeRevenueIvrs(r.ivrs_no); if (iv && !ivrsToDc[iv]) ivrsToDc[iv] = dc; });
                            });
                        }
                    }
                } catch (_) {}
                const plan = divisionDcs.map((dc) => ({ dc, normal: [], ag: [], status: "WAITING", statusText: "" }));
                const planByDc = Object.fromEntries(plan.map((p) => [p.dc, p]));
                let normalUnassigned = 0;
                let agUnassigned = 0;
                if (normalFile) {
                    const rows = getSheetRowsFromFile_(await normalFile.arrayBuffer());
                    const parsed = readRevenuePaidRowsFromSheetRows_(rows, "NORMAL");
                    const prefixVotes = {};
                    const pending = [];
                    parsed.forEach((row) => {
                        const dc = ivrsToDc[row.ivrsNo];
                        if (dc) {
                            planByDc[dc].normal.push(row);
                            const pre = row.ivrsNo.slice(0, 4);
                            prefixVotes[pre] = prefixVotes[pre] || {};
                            prefixVotes[pre][dc] = (prefixVotes[pre][dc] || 0) + 1;
                        } else {
                            pending.push(row);
                        }
                    });
                    const prefixDc = {};
                    Object.entries(prefixVotes).forEach(([pre, votes]) => {
                        const sorted = Object.entries(votes).sort((a, b) => b[1] - a[1]);
                        const total = sorted.reduce((s, x) => s + x[1], 0);
                        if (sorted[0] && sorted[0][1] / total >= 0.98) prefixDc[pre] = sorted[0][0];
                    });
                    pending.forEach((row) => {
                        const dc = prefixDc[row.ivrsNo.slice(0, 4)];
                        if (dc) planByDc[dc].normal.push(row); else normalUnassigned++;
                    });
                }
                if (agFile) {
                    const rows = getSheetRowsFromFile_(await agFile.arrayBuffer());
                    const agFmt = scRequirePaidFormat_(rows, "AG"); // 2026-09-28: poori file se ek baar format
                    let currentDc = "";
                    let blockRows = [];
                    const flush = () => {
                        if (!blockRows.length) return;
                        const parsed = readRevenuePaidRowsFromSheetRows_(blockRows, "AG", agFmt);
                        parsed.forEach((row) => {
                            // FIX (2026-09-26, user-reported): 26/09 ki AG file me saari 6,945 rows
                            // ADEGAON me chali gayi (LOCATION block pehchan nahi hua). Ab consumer ki
                            // DC master se (sabse pakka), master me na ho tabhi LOCATION block.
                            const masterDc = ivrsToDc[row.ivrsNo];
                            const dc = masterDc || currentDc;
                            if (masterDc && currentDc && masterDc !== currentDc && planByDc[currentDc]) {
                                const iv = normalizeRevenueIvrs(row.ivrsNo);
                                if (iv) (planByDc[currentDc].foreignAgIvrs = planByDc[currentDc].foreignAgIvrs || new Set()).add(iv);
                            }
                            if (dc && planByDc[dc]) planByDc[dc].ag.push(row); else agUnassigned++;
                        });
                        blockRows = [];
                    };
                    rows.forEach((r) => {
                        if (normalizeLookupValue(r[0]) === "LOCATION") {
                            flush();
                            currentDc = matchDivisionDcFromLocationText_(r[1], divisionDcs);
                            return;
                        }
                        blockRows.push(r);
                    });
                    flush();
                }
                // USER RULE (2026-09-26): poori NORMAL file me jo IVRS hai (kisi bhi DC ka), woh AG se skip
                const scNormalAll = new Set();
                plan.forEach((p) => p.normal.forEach((r) => { const iv = normalizeRevenueIvrs(r.ivrsNo); if (iv) scNormalAll.add(iv); }));
                let scAgSkippedTotal = 0;
                plan.forEach((p) => {
                    const split = scSplitAgRowsByNormal_(p.ag, scNormalAll);
                    p.ag = split.keep;
                    // doosri DC ke consumer jo is DC ke LOCATION block me aaye the - is DC ki sheet se
                    // unki (galti se pehle judi) AG rows bhi hatengi
                    const ownIvrs = new Set(p.ag.map((r) => normalizeRevenueIvrs(r.ivrsNo)));
                    const foreign = Array.from(p.foreignAgIvrs || []).filter((iv) => !ownIvrs.has(iv));
                    p.skipAgIvrs = Array.from(new Set([...split.skipped, ...foreign]));
                    scAgSkippedTotal += split.skipped.length;
                });
                // FIX (2026-09-26): sheet me pehle se padi DOOSRI DC ke consumer ki AG rows (jaise 26/09 ko
                // ADEGAON me 6,343, 24/09 CHHAPARA-1 me CHHAPARA-2 ki 727) - master se pehchan kar hatao.
                // Asli DC me woh consumer pehle se hai (26/09 jaanch), isliye sirf duplicate hatta hai.
                let scForeignAgTotal = 0;
                try {
                    const scPubPaidNow = await scPubPaidMeta_();
                    if (scPubPaidNow) {
                        await runWithConcurrencyLimit_(plan.slice(), 4, async (p) => {
                            const rows = await scPubPaidRowsForDc_(scPubPaidNow, p.dc);
                            if (!rows) return;
                            const extra = Array.from(new Set(rows
                                .filter((r) => String(r.source_type || "").toUpperCase().includes("AG"))
                                .map((r) => normalizeRevenueIvrs(r.ivrs_no))
                                .filter((iv) => iv && ivrsToDc[iv] && ivrsToDc[iv] !== p.dc)));
                            if (!extra.length) return;
                            p.skipAgIvrs = Array.from(new Set([...(p.skipAgIvrs || []), ...extra]));
                            scForeignAgTotal += extra.length;
                        });
                    }
                } catch (_) {}
                // 2026-10-21: AG file chuni ho aur is DC ki koi row na ho - purani AG rows saaf (AG ab replace hoti hai)
                plan.forEach((p) => {
                    if (!p.normal.length && !p.ag.length) {
                        if (agFile) { p.clearAgOnly = true; p.status = "WAITING"; p.statusText = "No AG rows - old AG will be cleared"; }
                        else { p.status = "SKIPPED"; p.statusText = "No data in file"; }
                    }
                });
                await scDivLoadLastUploads_(divisionDcs, true); // 30/09 har DC ki aakhri upload
                renderDivisionPaidUploadTable_(plan);
                const note = ((normalUnassigned || agUnassigned)
                    ? `<br>⚠️ Not matched with any DC (will not be uploaded): NORMAL ${normalUnassigned}, AG ${agUnassigned}`
                    : "") + (scAgSkippedTotal ? `<br>ℹ️ ${scAgSkippedTotal} consumers of the AG file were also in the NORMAL file - skipped from AG (they will go only once)` : "") + (scForeignAgTotal ? `<br>🧹 Wrong AG rows of ${scForeignAgTotal} consumers of another DC will be removed (they exist in the actual DC)` : "");
                setDivisionPaidUploadStatus_(`Files read. Now upload of each DC is running one by one (same as DC upload)...${note}`, true);

                const ctx = { plan, division, startedAt, note, agFileSelected: !!agFile };
                scDivUploadCtx_ = ctx;
                for (const p of plan) {
                    if (p.status === "SKIPPED") continue;
                    await scDivUploadOne_(p, ctx);
                }
                await scDivLoadLastUploads_(divisionDcs, true);
                renderDivisionPaidUploadTable_(plan);
                const sm = scDivSummaryText_(ctx);
                const failed = sm.failed;
                setDivisionPaidUploadStatus_(sm.html, sm.ok);
                showToast(failed ? "Upload of some DCs failed - press Try Again next to them" : "Division cash list uploaded", !failed);
                try { checkRevenueUploadFreshness(); } catch (_) {}
            } catch (error) {
                if (/password/i.test(error?.message || "")) divisionPaidUploadPassword_ = "";
                setDivisionPaidUploadStatus_(escapeHtml(error?.message || "Upload failed"), false);
                showToast(error?.message || "Upload failed", false);
                if (!divisionPaidUploadPassword_) setTimeout(initDivisionPaidUpload, 1500);
            } finally {
                divisionPaidUploadInProgress_ = false;
                if (btn) { btn.disabled = false; btn.textContent = "UPLOAD DIVISION CASH LIST"; }
                if (scDivUploadCtx_ && scDivUploadCtx_.division === division) renderDivisionPaidUploadTable_(scDivUploadCtx_.plan); // Try Again button dikhe
            }
        }

        // DC upload se pehle: aaj Division ne is DC ki list upload ki ho to wahi message.
        async function getDivisionUploadMarkForDc_(dcName) {
            try {
                const res = await fetchWithTimeout(`${revenueCollectionSubmitScriptUrl}?action=getDivisionUploadMark&dc_name=${encodeURIComponent(dcName)}&t=${Date.now()}`, { cache: "no-store" }, 30000);
                const j = await res.json();
                return j && j.status === "success" ? j : null;
            } catch (_) { return null; }
        }

        async function uploadRevenuePaidFiles() {
            const normalFile = document.getElementById("revenue-paid-normal-file")?.files?.[0] || null;
            const agFile = document.getElementById("revenue-paid-ag-file")?.files?.[0] || null;
            const uploadBtn = document.getElementById("revenue-paid-upload-btn");
            if (revenuePaidUploadInProgress) {
                showToast("Upload in progress, please wait", false);
                return;
            }
            if (!normalFile && !agFile) {
                showToast("Please select at least one paid file", false);
                return;
            }
            if (!revenueCollectionSubmitScriptUrl) {
                showToast("Revenue script URL is missing", false);
                return;
            }
            // USER REQUEST (2026-09-25): aaj Division ne upload kar di ho to DC se nahi.
            {
                setRevenuePaidUploadStatus("Checking...", true, true);
                const divMark = await getDivisionUploadMarkForDc_(activeDC || "");
                if (divMark && divMark.marked_today) {
                    const msg = `Cash list has been uploaded by ${divMark.division} Division (${divMark.date} ${divMark.time}). There is no need to upload again from DC today.`;
                    setRevenuePaidUploadStatus(msg, false, true);
                    showToast(msg, false);
                    return;
                }
                setRevenuePaidUploadStatus("", true, false);
            }
            try {
                revenuePaidUploadInProgress = true;
                revenuePaidUploadStartedAt_ = new Date().toISOString(); // SPEED FIX (2026-09-24): verification isi samay ke baad ka upload dhoondhta hai
                setActionButtonState(uploadBtn, "processing", "Upload Paid Data");
                renderRevenuePaidUploadSummary(null);
                setRevenuePaidUploadProgress(5, "Reading paid files...");
                await waitForUiBreath();
                const normalRows = await readRevenuePaidFile(normalFile, "NORMAL");
                setRevenuePaidUploadProgress(
                    18,
                    normalFile
                        ? `Normal file read (${normalRows.length} rows).${agFile ? " Processing AG file..." : ""}`
                        : "Normal file is not selected. Processing AG file...",
                    true
                );
                await waitForUiBreath();
                const agRows = await readRevenuePaidFile(agFile, "AG");
                setRevenuePaidUploadProgress(
                    32,
                    agFile
                        ? `AG file read (${agRows.length} rows). Preparing paid data...`
                        : "AG file is not selected. Preparing paid data...",
                    true
                );
                await waitForUiBreath();
                // USER REQUEST (2026-09-24): galti se DOOSRI DC chun kar Cash List upload
                // na ho - backend par bhejne SE PEHLE file ke IVRS ko chuni hui DC ki
                // master list se milate hain; aadhe se kam mile to upload yahin ruk jaata hai.
                await checkRevenuePaidFileBelongsToDc_(activeDC || "", normalRows, agRows);
                const scAgSplit = scSplitAgRowsByNormal_(agRows, new Set(normalRows.map((r) => normalizeRevenueIvrs(r.ivrsNo)).filter(Boolean)));
                agRows.length = 0;
                agRows.push(...scAgSplit.keep);
                const entries = buildRevenuePaidUploadEntries([...normalRows, ...agRows], activeDC || "");
                if (!entries.length) throw new Error("No valid rows found in paid data file");
                const paymentRowCount = entries.reduce((total, entry) => total + getRevenueUploadedPaidPaymentRows(entry).length, 0);

                setRevenuePaidUploadProgress(45, `Paid data prepared. Unique IVRS: ${entries.length} | Payment Rows: ${paymentRowCount}`);
                await waitForUiBreath();
                saveRevenueUploadedPaidEntriesLocalBulk(entries, activeDC || "", true);
                await saveRevenueCategoryRawPaymentRows([...normalRows, ...agRows], activeDC || "");
                setRevenuePaidUploadProgress(60, "Local payment data has been saved safely.");

                const payload = new URLSearchParams();
                payload.append("action", "uploadPaidMaster");
                payload.append("admin_password", revenuePaidUploadPasswordEntered);
                payload.append("dc_name", activeDC || "");
                payload.append("uploaded_at", new Date().toISOString());
                payload.append("entries_json", JSON.stringify(entries));
                payload.append("skip_ag_ivrs", JSON.stringify(scAgSplit.skipped));

                setRevenuePaidUploadProgress(70, `Backend upload in progress... Unique IVRS: ${entries.length} | Payment Rows: ${paymentRowCount}`);
                let backendSynced = false;
                let backendUploadResult_ = null;
                try {
                    const response = await fetchWithTimeout(revenueCollectionSubmitScriptUrl, {
                        method: "POST",
                        headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                        body: payload.toString()
                    }, 300000); // SPEED FIX (2026-09-24): 20 sec -> 5 min. Badi DC me backend ko 20 sec se zyada lagta hai; pehle 20 sec par hi abort hokar poora data DOBARA bheja jaata tha (backend par do baar kaam).
                    const responseText = await response.text();
                    let parsed = {};
                    try { parsed = JSON.parse(responseText || "{}"); } catch (_) {}
                    if (!response.ok || parsed.status === "error") {
                        // USER REQUEST (2026-09-22): backend ne yahan SAAF SAAF error
                        // diya hai (jaise galat admin password, invalid/corrupt data) -
                        // yeh "shayad ho jayega" wala pending case nahi hai, yeh PAKKA
                        // fail hai - dobara verify try karne se bhi kabhi theek nahi
                        // hoga. Isko alag marker deke aage bhej dete hain taaki yeh
                        // "99% Verification Pending" me na chhup jaaye, balki turant
                        // FAILED dikhe (neeche outer catch handle karta hai).
                        const err = new Error(parsed.message || "Paid data upload failed");
                        err.isExplicitBackendError = true;
                        throw err;
                    }
                    // SAFETY FIX (2026-09-24, USER REQUEST "99 par galat success na
                    // dikhe"): pehle response.ok ho aur body JSON na ho (jaise Apps
                    // Script ka HTML error/"time limit" page, jo 200 status ke saath
                    // aata hai) to bhi "SUCCESSFULLY UPLOADED" maan liya jaata tha.
                    // Ab sirf backend ka saaf `status: "success"` hi success hai; warna
                    // backend tak request pahunch chuki hai isliye dobara nahi bhejte,
                    // seedha asli verification (upload-date ke saath) chalti hai.
                    if (parsed.status !== "success") {
                        const unsureErr = new Error("No clear response received from backend");
                        unsureErr.backendReached = true;
                        throw unsureErr;
                    }
                    backendUploadResult_ = {
                        rowsSaved: Number(parsed.rows_saved || 0),
                        normalRowsThisUpload: Number(parsed.normal_rows_this_upload || 0),
                        agRowsUpdatedThisUpload: Number(parsed.ag_rows_updated_this_upload || 0)
                    };
                    backendSynced = true;
                } catch (syncError) {
                    // Explicit backend error (upar wala) ko yahin turant aage (outer
                    // catch tak) bhej dete hain - fallback POST ya verification-loop
                    // me time barbaad nahi karna, kyunki wo kabhi pass nahi hogi.
                    if (syncError && syncError.isExplicitBackendError) throw syncError;
                    // Sirf GENUINE network/timeout wale case me hi fallback + background
                    // verification try karte hain - ho sakta hai backend ne asal me
                    // process kar liya ho, sirf response client tak na pahuncha ho.
                    // SPEED FIX (2026-09-24): timeout (AbortError) ka matlab request
                    // backend tak pahunch chuki hai aur wahan abhi chal rahi hai - use
                    // dobara bhejna usi kaam ko DUBARA karwata tha (lock ka intezaar +
                    // poori sheet dobara likhna). Ab sirf asli network-failure par hi
                    // dobara bhejte hain; timeout par seedha verification.
                    if (syncError && syncError.name !== "AbortError" && !syncError.backendReached) try {
                        await fetch(revenueCollectionSubmitScriptUrl, {
                            method: "POST",
                            mode: "no-cors",
                            keepalive: true,
                            headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8" },
                            body: payload.toString()
                        });
                    } catch (_) {}
                }

                if (!backendSynced) {
                    setRevenuePaidUploadProgress(72, "Backend sync has been sent. Verification in progress...");
                    backendSynced = await verifyRevenuePaidBackendUpload(entries, activeDC || "", 60, revenuePaidUploadStartedAt_);
                }

                setRevenuePaidUploadProgress(
                    backendSynced ? 100 : 99,
                    backendSynced
                        ? "SUCCESSFULLY UPLOADED — Backend data is verified."
                        : "BACKEND VERIFICATION PENDING — Data is saved locally.",
                    true
                );
                const uploadMeta = {
                    dcName: activeDC || "",
                    uniqueCount: entries.length,
                    paymentRowCount,
                    normalRows: normalRows.length,
                    agRows: agRows.length,
                    uploadedAt: new Date().toISOString(),
                    oldDataReplaced: true,
                    backendSynced: backendSynced,
                    // USER REQUEST (2026-09-24): summary me backend ka ASLI hisaab bhi
                    backendConfirmedBy: backendSynced ? (backendUploadResult_ ? "RESPONSE" : "VERIFICATION") : "",
                    backendRowsSaved: backendUploadResult_ ? backendUploadResult_.rowsSaved : null,
                    backendNormalRows: backendUploadResult_ ? backendUploadResult_.normalRowsThisUpload : null,
                    backendAgRowsUpdated: backendUploadResult_ ? backendUploadResult_.agRowsUpdatedThisUpload : null
                };
                saveRevenuePaidUploadMeta(uploadMeta);
                renderRevenuePaidUploadSummary(uploadMeta);
                // USER REQUEST (2026-09-21): pehle backend verification pending (99%)
                // hone par bhi button "Done" dikhata tha aur toast "Paid data upload
                // ho gaya" (success/green) bolta tha - yeh jhooti "success" feeling
                // deta tha, jabki asal me backend se confirm hi nahi hua tha. Ab
                // dono cheezein sach ke hisaab se dikhti hain.
                if (backendSynced) {
                    setActionButtonState(uploadBtn, "done", "Upload Paid Data");
                    showToast("Paid data uploaded (confirmed by backend)", true);
                } else {
                    setActionButtonState(uploadBtn, "pending", "Upload Paid Data");
                    showToast("Data has been sent, but backend confirmation is not received yet (99%) - see the status in the summary below", false);
                    // USER REQUEST (2026-09-22, USER-REPORTED - CHHAPARA-1 jaisi badi DC
                    // baar-baar 99% par atakti thi): pehle 180s (3 min) ki verification
                    // window khatam hone ke baad koi aur koshish nahi hoti thi - jab tak
                    // user khud panel band-khol na kare, tab tak "pending" hi dikhta
                    // rehta tha, chahe backend ne 3-4 minute baad hi asal me likh liya ho
                    // (badi DC me hazaron rows likhne me itna time lagna normal hai). Ab
                    // background me KHUD-BA-KHUD aur 5 minute tak (30 koshish x 10s) chup-
                    // chaap check hote rehte hain - jaise hi backend confirm kare, status
                    // apne aap "Successfully Uploaded" me badal jaata hai, user ko panel
                    // dobara kholne ki zaroorat nahi padti.
                    continueRevenuePaidUploadBackgroundVerification_(entries, activeDC || "", uploadMeta);
                }
                // Freshness ticker (DC dashboard wali red patti) pehle sirf tab check hoti
                // thi jab dc-dashboard screen par navigate karte the - upload ke turant
                // baad, jab tak user wapas dc-dashboard par na jaaye, ticker purani hi
                // dikhti rehti thi chahe upload sahi ho chuka ho. Ab upload complete hote
                // hi turant bhi check kar lete hain, taaki agli baar dc-dashboard par
                // jaate hi (ya turant, agar wahi screen abhi active hai) sahi status mile.
                checkRevenueUploadFreshness();
            } catch (error) {
                const message = error?.name === "AbortError"
                    ? "Backend response timed out. Please check internet / Apps Script deployment and try again."
                    : (error?.message || "Paid data upload failed");
                setRevenuePaidUploadStatus(`${getActionStatusText("failed")}<br>${message}`, false, true);
                setActionButtonState(uploadBtn, "failed", "Upload Paid Data");
                showToast(message, false);
            } finally {
                revenuePaidUploadInProgress = false;
                setTimeout(() => setActionButtonState(uploadBtn, "idle", "Upload Paid Data"), 900);
            }
        }

        let revenueLiveEntriesMemory = null;

        function getRevenueLiveEntries() {
            if (Array.isArray(revenueLiveEntriesMemory)) return revenueLiveEntriesMemory;
            try {
                const rows = JSON.parse(localStorage.getItem("seoni-revenue-live-progress") || "[]");
                revenueLiveEntriesMemory = Array.isArray(rows) ? rows : [];
                return revenueLiveEntriesMemory;
            } catch (_) {
                revenueLiveEntriesMemory = [];
                return [];
            }
        }

        function setRevenueLiveEntries(rows) {
            const safeRows = Array.isArray(rows) ? rows : [];
            revenueLiveEntriesMemory = safeRows;
            try {
                localStorage.setItem("seoni-revenue-live-progress", JSON.stringify(safeRows));
            } catch (_) {
                // Full circle/division data memory me rahega. Mobile local storage me
                // current DC ka compact fallback hi rakhen, taki Paid submit fail na ho.
                const activeDcKey = normalizeLookupValue(activeDC || "");
                const compactRows = safeRows
                    .filter((row) => !activeDcKey || normalizeLookupValue(row.dcName || "") === activeDcKey)
                    .slice(0, 2500);
                try {
                    localStorage.removeItem("seoni-revenue-live-progress");
                    localStorage.setItem("seoni-revenue-live-progress", JSON.stringify(compactRows));
                } catch (_) {
                    try { localStorage.removeItem("seoni-revenue-live-progress"); } catch (_) {}
                }
            }
        }

        function saveRevenueLiveEntry(entry) {
            const rows = getRevenueLiveEntries();
            const entryKey = normalizeRevenueIvrs(entry.ivrsNo);
            const dcKey = normalizeLookupValue(entry.dcName || activeDC || "");
            const paymentKey = `${entryKey}|${dcKey}|${entry.paidAmount || ""}|${entry.paidDate || ""}|${entry.paidTime || ""}`;
            const filteredRows = rows.filter((row) => {
                const rowKey = `${normalizeRevenueIvrs(row.ivrsNo)}|${normalizeLookupValue(row.dcName || "")}|${row.paidAmount || ""}|${row.paidDate || ""}|${row.paidTime || ""}`;
                return rowKey !== paymentKey;
            });
            filteredRows.unshift(entry);
            setRevenueLiveEntries(filteredRows);
        }

        function removeRevenueLiveEntry(ivrsNo, dcName = activeDC) {
            const entryKey = normalizeRevenueIvrs(ivrsNo);
            const dcKey = normalizeLookupValue(dcName || "");
            const filteredRows = getRevenueLiveEntries().filter((row) => {
                return !(normalizeRevenueIvrs(row.ivrsNo) === entryKey && normalizeLookupValue(row.dcName || "") === dcKey);
            });
            setRevenueLiveEntries(filteredRows);
        }

        // BUG FIX (2026-08-22): "2 baar Paid Amount" wala limit pehle HAMESHA KE
        // LIYE (lifetime) count hota tha - ab backend (submitRevenuePayment_) me
        // yeh limit sirf CURRENT MONTH ke liye hai, isliye yahan bhi wahi current-
        // month filter lagaya hai, taaki app ka "X/2" display aur submit-cap check
        // dono backend ke naye (monthly) rule se match karein.
        function getRevenuePaidEntries(ivrsNo) {
            const entryKey = normalizeRevenueIvrs(ivrsNo);
            const dcKey = normalizeLookupValue(activeDC || "");
            const currentMonthKey = getRevenueMonthKey(getCurrentDateDDMMYYYY());
            const seenPayments = new Set();
            return getRevenueLiveEntries().filter((row) => {
                const paymentKey = `${normalizeRevenueIvrs(row.ivrsNo)}|${normalizeLookupValue(row.dcName || "")}|${row.paidAmount || ""}|${row.paidDate || ""}|${row.paidTime || ""}`;
                if (seenPayments.has(paymentKey)) return false;
                seenPayments.add(paymentKey);
                return normalizeRevenueIvrs(row.ivrsNo) === entryKey
                    && normalizeLookupValue(row.dcName || "") === dcKey
                    && getRevenueMonthKey(row.paidDate) === currentMonthKey;
            }).sort((a, b) => String(b.paidAt || "").localeCompare(String(a.paidAt || "")));
        }

        function getRevenuePaidEntry(ivrsNo) {
            return getRevenuePaidEntries(ivrsNo)[0] || null;
        }

        function mapRevenueSheetEntry(row) {
            return {
                ivrsNo: row.ivrs_no || row.ivrsNo || row["IVRS NO"] || "",
                consumerName: row.consumer_name || row.consumerName || row["CONSUMER NAME"] || "",
                fatherName: row.father_name || row.fatherName || row["FATHER NAME"] || "",
                village: row.village || row["VILLAGE"] || "",
                hqName: row.hq_name || row.hqName || row["HQ NAME"] || "",
                tariffCategory: row.tarrif_category || row.tariffCategory || row["TARRIF CATEGORY"] || "",
                mobileNo: row.mobile_no || row.mobileNo || row["MOBILE NO"] || "",
                arrears: row.arrears || row["ARREARS"] || "",
                netBill: row.net_bill || row.netBill || row["NET BILL"] || "",
                paidAmount: row.amount_paid || row.paidAmount || row["AMOUNT PAID"] || "",
                paidDate: row.date || row.paidDate || row["DATE"] || "",
                paidTime: formatRevenuePaidTime(row.time || row.paidTime || row["TIME"] || ""),
                dcName: row.dc_name || row.dcName || row["DC NAME"] || activeDC || "",
                paidAt: `${row.date || row.paidDate || row["DATE"] || ""} ${formatRevenuePaidTime(row.time || row.paidTime || row["TIME"] || "")}`.trim(),
                paymentId: row.payment_id || row.paymentId || ""
            };
        }

        // Live Progress, Cash Reconcile aur Pending DO List - teeno reports isi ek
        // function se "paid entries" laate hain. Pehle har report apna alag timer
        // rakhta tha, isliye ek report me sync ho jaane ke baad bhi dusri report
        // par jaane par dobara poora network sync ho jaata tha. Ab yahan hi ek
        // SHARED 60-second TTL cache hai - jis bhi report ne pehle sync kiya ho,
        // baaki sabhi report usi cache ko turant reuse karenge jab tak app se
        // bahar nahi jaate / 60 second se zyada time nahi beetta.
        let revenueLiveEntriesSyncedAt = 0;
        // RESTORED (user confirmed root cause tha NGB Cash List upload data
        // replace kar deta tha, is caching me koi dikkat nahi thi) - shared
        // 60-second TTL cache wapas ON hai.
        const REVENUE_LIVE_ENTRIES_SYNC_TTL_MS = 60000;
        // In-flight fetch dedupe (ensureDcDataLoaded jaisa pattern): agar DC-select
        // ke turant baad background prefetchRevenueBackgroundDataForDc() ne is sync
        // ko already shuru kar diya ho, aur usi beech user khud koi report khol de
        // jo yahi function call kare, to naya alag parallel fetch shuru NAHI hota -
        // dono ek hi chal rahi request ka result share karte hain. Isse background
        // warming ki wajah se pehla report kabhi slow nahi hota, sirf fast/same hota hai.
        let revenueLiveEntriesSyncFetchPromises = {};
        // PERF FIX (2026-08-20, Point 1): cache abhi kis scope ka data rakhti hai -
        // null/undefined = SABHI DC ka poora data (kisi bhi scope ke liye safe hai).
        // "<DC NAME>" = sirf usi ek DC ka poora data (sirf usi DC ke liye safe hai,
        // Circle/Division ke liye NAHI). Isse background prefetch DC-scoped fetch
        // kar sakta hai bina Circle/Division report ko galat/adhoora data dikhaye -
        // scope match na ho to neeche wala function khud fresh (sahi scope wali)
        // fetch kar leta hai.
        let revenueLiveEntriesCachedScopeDc = null;

        // LIVE REVENUE PUBLIC CACHE (USER REQUEST 2026-09-26, "15 minute purana, bahut tez"):
        // Circle/Division Revenue report me staff entries + TD backend ki 15-min public copy se
        // (screen par samay + "Live Refresh" button); reconciliation (cash list se bana) public
        // copy se tabhi jab paid SIG same ho - woh bilkul sahi hota hai. DC level pehle jaisa live.
        let scRevenueForceLive_ = false;
        let scRevenueLiveFromPublicAt_ = 0;
        const SC_PUB_LIVE_MAX_AGE_MS = 20 * 60 * 1000;
        async function scPubLiveJson_(key) {
            try {
                if (scRevenueForceLive_) return null;
                const meta = await scPubPaidMeta_();
                const info = meta && meta[key];
                if (!info) return null;
                const at = Number(info.sig);
                if (!at || Date.now() - at > SC_PUB_LIVE_MAX_AGE_MS) return null;
                const rows = await scPubFetchCsv_(SC_PUB_PAID_SHEET_ID, info.gid, 60000);
                const parts = rows.slice(1).filter((r) => r[0] !== "" && r[0] !== undefined).map((r) => [Number(r[0]), scPubStrip_(r[1])]);
                if (!parts.length) return null;
                const obj = scPubJoinChunks_(parts);
                if (!obj || obj.status !== "success" || !Array.isArray(obj.entries)) return null;
                return { obj, at };
            } catch (_) { return null; }
        }
        const scPubReconTabMem_ = {};
        async function scPubReconForBatch_(batch, periodMode, periodValue) {
            try {
                const meta = await scPubPaidMeta_();
                if (!meta) return null;
                const key = `${periodMode}|${periodValue}`;
                const out = [];
                const infos = [];
                for (const dcRaw of batch) {
                    const dc = normalizeDcName(dcRaw);
                    const info = meta["RECON:" + dc];
                    const paid = meta[dc];
                    if (!info || !paid || !paid.sig) return null;
                    let sigMap = {};
                    try { sigMap = JSON.parse(info.sig); } catch (_) { return null; }
                    if (sigMap[key] !== paid.sig) return null;
                    infos.push(info);
                }
                // saare DC ek saath (parallel) - order wahi rakha
                const lists = await Promise.all(infos.map(async (info) => {
                    const memKey = `${info.gid}|${info.sig}`;
                    if (!scPubReconTabMem_[memKey]) {
                        scPubReconTabMem_[memKey] = scPubFetchCsv_(SC_PUB_PAID_SHEET_ID, info.gid).then((rows) => {
                            const parts = {};
                            rows.slice(1).forEach((r) => { if (!r[0]) return; (parts[r[0]] = parts[r[0]] || []).push([Number(r[1]), scPubStrip_(r[2])]); });
                            const byPeriod = {};
                            Object.keys(parts).forEach((k) => { byPeriod[k] = scPubJoinChunks_(parts[k]); });
                            return byPeriod;
                        });
                        scPubReconTabMem_[memKey].catch(() => { delete scPubReconTabMem_[memKey]; });
                    }
                    const byPeriod = await scPubReconTabMem_[memKey];
                    return Array.isArray(byPeriod[key]) ? byPeriod[key] : null;
                }));
                for (const list of lists) {
                    if (!list) return null;
                    list.forEach((e) => out.push(e));
                }
                return out;
            } catch (_) { return null; }
        }
        function scRevenueLiveNoteHtml_() {
            if (!scRevenueLiveFromPublicAt_) return "";
            const d = new Date(scRevenueLiveFromPublicAt_);
            const hh = String(d.getHours()).padStart(2, "0"), mm = String(d.getMinutes()).padStart(2, "0");
            return `<div style="display:flex; align-items:center; justify-content:space-between; gap:8px; background:#fffbeb; border:1px solid #fcd34d; color:#92400e; border-radius:12px; padding:6px 10px; font-size:0.66rem; font-weight:800; margin:4px 0 8px;"><span>⏱ Display Report Before 15 Min</span><button onclick="scRevenueLiveRefresh_()" style="border:none; background:#d97706; color:#fff; border-radius:9px; padding:5px 9px; font-size:0.64rem; font-weight:900;">🔄 Live Refresh</button></div>`;
        }
        function scRevenueLiveRefresh_() {
            scRevenueForceLive_ = true;
            revenueLiveEntriesSyncedAt = 0;
            revenueTdEntriesSyncedAt = 0;
            Promise.resolve(refreshSummary()).finally(() => { scRevenueForceLive_ = false; });
        }

        let scLiveEntriesFromPub_ = false;
        var scLivePubAt_ = 0, scTdPubAt_ = 0; // public copy ka samay (29/09)
        async function syncRevenueLiveEntriesFromSheet(attempts = 3, forceRefresh = false, scopeDc = null, allowPublic = false) {
            const cacheSatisfiesScope = (revenueLiveEntriesCachedScopeDc === null || (scopeDc && revenueLiveEntriesCachedScopeDc === scopeDc)) && !(scLiveEntriesFromPub_ && (!allowPublic || scRevenueForceLive_)); // LIVE CACHE: public copy sirf Live Revenue summary (Circle/Division/DC) ke liye
            if (!forceRefresh && cacheSatisfiesScope && revenueLiveEntriesSyncedAt && Date.now() - revenueLiveEntriesSyncedAt < REVENUE_LIVE_ENTRIES_SYNC_TTL_MS) {
                if (scLiveEntriesFromPub_ && scLivePubAt_) scRevenueLiveFromPublicAt_ = scRevenueLiveFromPublicAt_ ? Math.min(scRevenueLiveFromPublicAt_, scLivePubAt_) : scLivePubAt_; // 29/09
                return getRevenueLiveEntries();
            }
            if (!revenueCollectionSubmitScriptUrl) return getRevenueLiveEntries();
            const dedupeKey = scopeDc || "__ALL__";
            if (!forceRefresh && revenueLiveEntriesSyncFetchPromises[dedupeKey]) return revenueLiveEntriesSyncFetchPromises[dedupeKey];
            revenueLiveEntriesSyncFetchPromises[dedupeKey] = syncRevenueLiveEntriesFromSheetInner_(attempts, scopeDc, allowPublic).finally(() => {
                delete revenueLiveEntriesSyncFetchPromises[dedupeKey];
            });
            return revenueLiveEntriesSyncFetchPromises[dedupeKey];
        }

        async function syncRevenueLiveEntriesFromSheetInner_(attempts, scopeDc = null, allowPublic = false) {
            const scopeParam = scopeDc ? `&dc_name=${encodeURIComponent(scopeDc)}` : "";
            if (allowPublic) { // LIVE CACHE 2026-09-26 (29/09: DC level bhi - public copy me sabhi DC)
                const pubE = await scPubLiveJson_("__LIVE_ENTRIES__");
                if (pubE) {
                    const freshRows = pubE.obj.entries.map(mapRevenueSheetEntry).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
                    setRevenueLiveEntries(freshRows);
                    revenueLiveEntriesCachedScopeDc = null;
                    revenueLiveEntriesSyncedAt = Date.now();
                    scLiveEntriesFromPub_ = true; scLivePubAt_ = pubE.at;
                    scRevenueLiveFromPublicAt_ = scRevenueLiveFromPublicAt_ ? Math.min(scRevenueLiveFromPublicAt_, pubE.at) : pubE.at;
                    return getRevenueLiveEntries();
                }
            }
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getEntries${scopeParam}&t=${Date.now()}`);
                        return await response.json();
                    });
                    const sourceRows = Array.isArray(parsed?.entries)
                        ? parsed.entries
                        : (Array.isArray(parsed?.rows) ? parsed.rows : (Array.isArray(parsed?.data) ? parsed.data : []));
                    if (parsed && parsed.status === "success" && Array.isArray(sourceRows)) {
                        // Agar yeh DC-scoped fetch tha, to shared cache me sirf usi DC ka
                        // purana data replace karo (baaki DC ka jo pehle se cache me tha
                        // wahi rehne do) - warna Circle/Division scope ka data corrupt ho
                        // jaata. Full (unscoped) fetch me poori cache replace hoti hai jaisa
                        // pehle hota tha.
                        const freshRows = sourceRows.map(mapRevenueSheetEntry).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
                        if (scopeDc) {
                            const others = getRevenueLiveEntries().filter((row) => normalizeDcName(row.dcName || "") !== normalizeDcName(scopeDc));
                            setRevenueLiveEntries([...others, ...freshRows]);
                            // Poori (sabhi-DC) cache abhi bhi COMPLETE nahi hai - agla koi
                            // Circle/Division wala caller isi variable ko dekh kar fresh
                            // full-fetch khud kar lega.
                            revenueLiveEntriesCachedScopeDc = scopeDc;
                        } else {
                            setRevenueLiveEntries(freshRows);
                            revenueLiveEntriesCachedScopeDc = null;
                            scLiveEntriesFromPub_ = false;
                        }
                        revenueLiveEntriesSyncedAt = Date.now();
                        return getRevenueLiveEntries();
                    }
                } catch (_) {}
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
            }
            return getRevenueLiveEntries();
        }

        // PERF FIX (2026-08-20): Live Progress screen ko sirf AAJ ki, sirf ACTIVE DC
        // ki entries chahiye hoti hain - lekin ab tak yeh screen bhi
        // syncRevenueLiveEntriesFromSheet()/syncRevenueTdEntriesFromSheet() hi use
        // karti thi, jo SABHI 24 DC ki PURI history ek sath fetch karte hain (kyoki
        // yeh shared cache Circle/Division/Cash-Reconcile/Report-Download jaisi
        // doosri screens ke liye zaroori hai jinhe sach me sabhi DC/sabhi date ka
        // data chahiye). Data dheere-dheere badhta gaya, isliye yeh full fetch bhi
        // utna hi slow hota gaya (3-5 minute tak) - yeh koi naya code-bug nahi tha,
        // sirf data-volume badhne se time bhi badh gaya.
        //
        // Neeche wala function ek ALAG, ISOLATED fast path hai - sirf DC-scope Live
        // Progress ke liye. Yeh:
        //   1) Sirf ACTIVE DC ka data maangta hai (dc_name param - backend pehle se
        //      support karta hai, 1 DC sheet padhta hai 24 ki jagah).
        //   2) Sirf AAJ ki date ka data maangta hai (naya date param, .gs me add
        //      kiya gaya - backward compatible, param na ho to purana behavior).
        //   3) Shared cache (revenueLiveEntriesMemory / TD entries local) ko BILKUL
        //      NAHI CHHEDTA - taaki Cash Reconcile / Pending DO List / Report
        //      Download / Progress Report jaisi doosri screens (jinhe sabhi DC ka
        //      data chahiye) par koi asar na ho.
        // Agar yeh fast fetch kisi bhi wajah se fail ho jaaye (ya .gs abhi redeploy
        // na hua ho), to null return karta hai - caller (renderRevenueLiveProgress)
        // tab purani (poori) sync method par fallback kar leta hai, taaki report
        // kabhi bhi khaali/galat na dikhe.
        // SPEED FIX (2026-09-15): `dcName` ab OPTIONAL hai. Backend (.gs) ka
        // getEntries/getTDEntries pehle se hi bina `dc_name` ke bhi `date` filter
        // support karta hai (sirf DC-scope ke liye nahi likha gaya tha, general
        // hai) - `dc_name` khaali chhodne par backend sabhi 24 DC ka data padhta
        // hai lekin RESPONSE me sirf maangi hui date ki rows bhejta hai (poori
        // history nahi) - Division/Circle Live Progress ab isi tarah "aaj ki"
        // chhoti list turant paa sakte hain, bina 24-DC/poori-history wali slow
        // shared sync (jo Cash Reconcile/Pending DO List/Report Download ke liye
        // zaroori hai, usko bilkul nahi chheda) par fallback kiye.
        async function fetchRevenueLiveProgressFastRows_(dcName, dateStr, dcNames = [], attempts = 2) {
            if (!revenueCollectionSubmitScriptUrl) return null;
            // DC view me ek DC, Division view me sirf us Division ke DCs, aur
            // Circle view me koi scope parameter nahi. Backend ka existing
            // dc_names support Division ke bekaar Circle-wide sheet-read ko
            // rokta hai; Circle behavior jaan-boojhkar unchanged hai.
            const normalizedDcNames = Array.from(new Set((dcNames || [])
                .map((name) => normalizeDcName(name))
                .filter(Boolean)));
            const scopeParam = dcName
                ? `&dc_name=${encodeURIComponent(dcName)}`
                : (normalizedDcNames.length ? `&dc_names=${encodeURIComponent(normalizedDcNames.join(","))}` : "");
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    const [paidParsed, tdParsed] = await Promise.all([
                        withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                            const paidResponse = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getEntries${scopeParam}&date=${encodeURIComponent(dateStr)}&t=${Date.now()}`);
                            return await paidResponse.json();
                        }),
                        withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                            const tdResponse = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getTDEntries${scopeParam}&date=${encodeURIComponent(dateStr)}&t=${Date.now()}`);
                            return await tdResponse.json();
                        })
                    ]);
                    const paidSourceRows = Array.isArray(paidParsed?.entries) ? paidParsed.entries : null;
                    const tdSourceRows = Array.isArray(tdParsed?.entries) ? tdParsed.entries : null;
                    if (paidParsed && paidParsed.status === "success" && Array.isArray(paidSourceRows) &&
                        tdParsed && tdParsed.status === "success" && Array.isArray(tdSourceRows)) {
                        const paidRows = paidSourceRows.map(mapRevenueSheetEntry)
                            .filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                            .map((row) => ({ ...row, reportType: "PAID" }));
                        const tdRows = tdSourceRows.map(mapRevenueTdSheetEntry).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
                        return [...paidRows, ...tdRows];
                    }
                } catch (_) {}
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
            }
            return null;
        }

        // Circle/Division Daily Live-Revenue ke liye compact server aggregate.
        // Naya backend available na ho, marker mismatch ho, ya network fail ho to
        // null return hota hai aur neeche wala existing raw-row fast path chalti hai.
        async function fetchRevenueLiveProgressDailySummary_(dcNames, dateStr, attempts = 2) {
            if (!revenueCollectionSubmitScriptUrl) return null;
            const requestedNames = Array.from(new Set((dcNames || [])
                .map((name) => normalizeDcName(name))
                .filter(Boolean)));
            const expectedNames = requestedNames.length
                ? requestedNames
                : getAllDcNames().map((name) => normalizeDcName(name)).filter(Boolean);
            const scopeParam = requestedNames.length
                ? `&dc_names=${encodeURIComponent(requestedNames.join(","))}`
                : "";
            for (let attempt = 1; attempt <= attempts; attempt++) {
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getLiveRevenueDailySummary${scopeParam}&date=${encodeURIComponent(dateStr)}&t=${Date.now()}`);
                        return await response.json();
                    });
                    const returnedNames = Array.isArray(parsed?.requested_dc_names)
                        ? parsed.requested_dc_names.map((name) => normalizeDcName(name)).filter(Boolean)
                        : [];
                    const exactScope = returnedNames.length === expectedNames.length
                        && expectedNames.every((name) => returnedNames.includes(name));
                    const expectedMode = requestedNames.length ? "batch" : "all";
                    if (parsed?.status === "success" && parsed.scope_mode === expectedMode
                        && parsed.period_mode === "date" && parsed.period_value === dateStr
                        && exactScope && Array.isArray(parsed.rows)) {
                        return parsed.rows.map((row) => ({
                            dcName: normalizeDcName(row.dc_name || row.dcName || ""),
                            paidCount: Number(row.paid_count || row.paidCount || 0),
                            paidAmount: Number(row.paid_amount || row.paidAmount || 0),
                            tdCount: Number(row.td_count || row.tdCount || 0),
                            tdAmount: Number(row.td_amount || row.tdAmount || 0),
                            __liveRevenueDailySummary: true
                        })).filter((row) => row.dcName);
                    }
                } catch (_) {}
                if (attempt < attempts) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
            }
            return null;
        }

        async function getRevenuePaidEntryFromSheet(record, searchedIvrs) {
            if (!revenueCollectionSubmitScriptUrl) return getRevenuePaidEntry(searchedIvrs);
            try {
                const ivrsNo = normalizeRevenueIvrs(record?.ivrsNo || searchedIvrs);
                const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=checkPaid&ivrs_no=${encodeURIComponent(ivrsNo)}&dc_name=${encodeURIComponent(activeDC || "")}&t=${Date.now()}`);
                const parsed = await response.json();
                if (parsed && parsed.status === "success" && Array.isArray(parsed.payments)) {
                    removeRevenueLiveEntry(ivrsNo, activeDC);
                    parsed.payments.forEach((paidData, index) => {
                        saveRevenueLiveEntry({
                            ...record,
                            ivrsNo: paidData.ivrs_no || record.ivrsNo,
                            consumerName: paidData.consumer_name || record.consumerName,
                            fatherName: paidData.father_name || record.fatherName,
                            village: paidData.village || record.village,
                            hqName: paidData.hq_name || record.hqName,
                            tariffCategory: paidData.tarrif_category || record.tariffCategory,
                            mobileNo: paidData.mobile_no || record.mobileNo,
                            arrears: paidData.arrears || record.arrears,
                            netBill: paidData.net_bill || record.netBill,
                            dcName: activeDC || "",
                            paidAmount: paidData.amount_paid || "",
                            paidDate: paidData.date || "",
                            paidTime: formatRevenuePaidTime(paidData.time || ""),
                            paidAt: `${paidData.date || ""} ${formatRevenuePaidTime(paidData.time || "")}`.trim(),
                            paymentId: paidData.payment_id || `sheet-${ivrsNo}-${index + 1}`
                        });
                    });
                    return getRevenuePaidEntry(ivrsNo);
                }
                if (parsed && parsed.status === "success" && parsed.paid && parsed.data) {
                    const paidData = parsed.data;
                    removeRevenueLiveEntry(ivrsNo, activeDC);
                    return {
                        ...record,
                        ivrsNo: paidData.ivrs_no || record.ivrsNo,
                        consumerName: paidData.consumer_name || record.consumerName,
                        fatherName: paidData.father_name || record.fatherName,
                        village: paidData.village || record.village,
                        hqName: paidData.hq_name || record.hqName,
                        tariffCategory: paidData.tarrif_category || record.tariffCategory,
                        mobileNo: paidData.mobile_no || record.mobileNo,
                        arrears: paidData.arrears || record.arrears,
                        netBill: paidData.net_bill || record.netBill,
                        dcName: activeDC || "",
                        paidAmount: paidData.amount_paid || "",
                        paidDate: paidData.date || "",
                        paidTime: formatRevenuePaidTime(paidData.time || ""),
                        paidAt: `${paidData.date || ""} ${formatRevenuePaidTime(paidData.time || "")}`.trim(),
                        paymentId: paidData.payment_id || `sheet-${ivrsNo}-1`
                    };
                }
                removeRevenueLiveEntry(ivrsNo, activeDC);
                return null;
            } catch (_) {
                return getRevenuePaidEntry(record?.ivrsNo || searchedIvrs);
            }
        }

        function normalizeRevenueReportDate(value) {
            const raw = String(value || "").trim();
            const isoMatch = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
            if (isoMatch) {
                return [
                    isoMatch[3].padStart(2, "0"),
                    isoMatch[2].padStart(2, "0"),
                    isoMatch[1]
                ].join("-");
            }
            const localMatch = raw.match(/^(\d{1,2})[-/](\d{1,2})[-/](\d{4})$/);
            if (localMatch) {
                return [
                    localMatch[1].padStart(2, "0"),
                    localMatch[2].padStart(2, "0"),
                    localMatch[3]
                ].join("-");
            }
            return raw;
        }

        function getRevenueMonthKey(value) {
            const normalized = normalizeRevenueReportDate(value);
            const match = normalized.match(/^(\d{2})-(\d{2})-(\d{4})$/);
            return match ? `${match[3]}-${match[2]}` : "";
        }

        function parseRevenuePaidAmount(value) {
            return Number(String(value || "").replace(/[^\d.]/g, "")) || 0;
        }

        // NET BILL / arrears source data kabhi-kabhi CSV column-misalignment ki wajah se
        // 2-3 columns ke digits aapas me jud ke ek hi field me aa jaate hain (jaise IVRS+
        // mobile+bill milke ek 20+ digit ka number ban jaana) - jo ek asli consumer bill se
        // kayi guna bada hota hai aur JS me bade number "9.88e+22" jaisi scientific notation
        // me dikhne lagte hain, plus Top Defaulters list me sabse upar aa jaate hain (sirf
        // isliye ki wo number galti se sabse "bada" hai). Koi bhi genuine bill/arrears kabhi
        // ~1 crore se upar nahi hota, isliye usse zyada ko garbage maan kar 0 (yani list se
        // bahar) kar dete hain - sabhi 24 DC ke Defaulters/Non-Payee reports isi ek function
        // se pending amount nikalte hain, isliye fix sab jagah ek saath lagu hoga.
        function parseRevenuePendingAmount(value) {
            const amount = parseRevenuePaidAmount(value);
            if (!Number.isFinite(amount) || Math.abs(amount) > 1e7) return 0;
            if (scRevIsCreditAmount_(value)) return 0; // USER RULE 2026-09-29: minus NET BILL = jama/advance, bakaya nahi
            return amount;
        }
        // USER RULE (2026-09-29): NET BILL minus (jaise "-300", "300 CR", "(300)") = jama/advance.
        // Pehle minus ka nishan hat kar ise 300 bakaya maana jaata tha (Top 20/50, Non-Payee,
        // Arrears 1L, Freeze Now me galat consumer aate the).
        function scRevIsCreditAmount_(value) {
            if (typeof value === "number") return value < 0;
            const raw = String(value ?? "").trim();
            if (!raw) return false;
            if (/^\(.*\)$/.test(raw) || /\bCR\b/i.test(raw)) return true;
            const n = Number(raw.replace(/,/g, "").replace(/[^0-9.+-]/g, ""));
            return Number.isFinite(n) && n < 0;
        }
        // Total consumer = PAID + PENDING (NET BILL > 0) + NO DUES (NET BILL 0/-, bina payment)
        function scRevTot_(r) {
            if (r && r.masterCount != null) return Number(r.masterCount) || 0; // TOTAL = master (29/09)
            if (r && r.__uniqueMasterCount != null) return Number(r.__uniqueMasterCount) || 0;
            return Number(r?.paidTotal || 0) + Number(r?.unpaidTotal || 0) + Number(r?.noDuesTotal || 0);
        }

        function getRevenueTdAmount(row) {
            return parseRevenuePaidAmount(row.tdAmount || row.netBill || row.arrears);
        }

        function isRevenueRowInCurrentScope(row) {
            const rowDc = normalizeDcName(row?.dcName || "");
            if (!rowDc) return false;
            const isRevenueDcScreen = [
                "revenue-collection",
                "revenue-live-progress",
                "revenue-report-download",
                "revenue-pending-list",
                "revenue-paid-upload"
            ].some((viewId) => document.getElementById(viewId)?.classList.contains("active"));
            if (isRevenueDcScreen && activeDC) return rowDc === normalizeDcName(activeDC);
            if (activeViewLevel === "DC") return rowDc === normalizeDcName(activeDC);
            if (activeViewLevel === "DIVISION") {
                return getDivisionDcNames(activeDiv).some((dc) => normalizeDcName(dc) === rowDc);
            }
            if (activeViewLevel === "CIRCLE") {
                return getAllDcNames().some((dc) => normalizeDcName(dc) === rowDc);
            }
            if (activeDC) return rowDc === normalizeDcName(activeDC);
            return true;
        }

        function getRevenueFilteredEntries(mode, filterValue) {
            const rows = getRevenueLiveEntries().filter(isRevenueRowInCurrentScope);
            if (mode === "MONTHLY") {
                const monthKey = String(filterValue || "").trim();
                return rows.filter((row) => getRevenueMonthKey(row.paidDate) === monthKey);
            }
            const targetDate = normalizeRevenueReportDate(filterValue || getCurrentDateDDMMYYYY());
            return rows.filter((row) => normalizeRevenueReportDate(row.paidDate) === targetDate);
        }

        function getRevenueTdFilteredEntries(mode, filterValue) {
            const rows = getRevenueTdEntriesLocal()
                .map((row) => ({ ...row, reportType: "TD" }))
                .filter(isRevenueRowInCurrentScope);
            if (mode === "MONTHLY") {
                const monthKey = String(filterValue || "").trim();
                return rows.filter((row) => getRevenueMonthKey(row.tdDate) === monthKey);
            }
            const targetDate = normalizeRevenueReportDate(filterValue || getCurrentDateDDMMYYYY());
            return rows.filter((row) => normalizeRevenueReportDate(row.tdDate) === targetDate);
        }

        function getRevenueCombinedFilteredEntries(mode, filterValue) {
            const paidRows = getRevenueFilteredEntries(mode, filterValue).map((row) => ({ ...row, reportType: "PAID" }));
            const tdRows = getRevenueTdFilteredEntries(mode, filterValue);
            return [...paidRows, ...tdRows].sort((a, b) => {
                const aDate = normalizeRevenueReportDate(a.paidDate || a.tdDate || "");
                const bDate = normalizeRevenueReportDate(b.paidDate || b.tdDate || "");
                const aTime = formatRevenuePaidTime(a.paidTime || a.tdTime || "");
                const bTime = formatRevenuePaidTime(b.paidTime || b.tdTime || "");
                return `${bDate} ${bTime}`.localeCompare(`${aDate} ${aTime}`);
            });
        }

        function filterRevenueRowsBySelectedHq(rows) {
            const hqValue = document.getElementById("revenue-report-hq")?.value || "";
            if (!hqValue) return rows || [];
            const hqKey = normalizeLookupValue(hqValue);
            return (rows || []).filter((row) => normalizeLookupValue(row.hqName || "") === hqKey);
        }

        function populateRevenueReportHqOptions(rows) {
            const hqSelect = document.getElementById("revenue-report-hq");
            if (!hqSelect) return;
            const selected = hqSelect.value || "";
            const hqNames = getRevenueUniqueValues(rows || [], "hqName");
            const allHqLabel = `All ${revenueHqLabel()}`;
            populateRevenueSelect(hqSelect, hqNames, allHqLabel);
            hqSelect.options[0].text = allHqLabel;
            if (selected && hqNames.some((name) => normalizeLookupValue(name) === normalizeLookupValue(selected))) {
                hqSelect.value = selected;
            }
        }

        function buildRevenueSummaryRows(rows) {
            const groups = {};
            rows.forEach((row) => {
                const dcName = row.dcName || activeDC || "-";
                const hqName = row.hqName || "-";
                const key = `${normalizeLookupValue(dcName)}||${normalizeLookupValue(hqName)}`;
                if (!groups[key]) {
                    groups[key] = {
                        dcName: dcName,
                        hqName: hqName,
                        count: 0,
                        amount: 0,
                        tdCount: 0,
                        tdAmount: 0
                    };
                }
                if (row.reportType === "TD") {
                    groups[key].tdCount += 1;
                    groups[key].tdAmount += getRevenueTdAmount(row);
                } else {
                    groups[key].count += 1;
                    groups[key].amount += parseRevenuePaidAmount(row.paidAmount);
                }
            });
            return Object.values(groups).sort((a, b) => {
                return String(a.dcName).localeCompare(String(b.dcName)) || String(a.hqName).localeCompare(String(b.hqName));
            });
        }

        function renderRevenueSummaryTable(rows) {
            const summaryRows = buildRevenueSummaryRows(rows);
            if (!summaryRows.length) return "";
            const totalCount = summaryRows.reduce((sum, row) => sum + row.count, 0);
            const totalAmount = summaryRows.reduce((sum, row) => sum + row.amount, 0);
            const totalTdCount = summaryRows.reduce((sum, row) => sum + row.tdCount, 0);
            const totalTdAmount = summaryRows.reduce((sum, row) => sum + row.tdAmount, 0);
            const bodyRows = summaryRows.map((row) => `
                <tr>
                    <td style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">${escapeHtml(row.dcName || "-")}</td>
                    <td style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">${escapeHtml(row.hqName || "-")}</td>
                    <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(row.count)}</td>
                    <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(formatProgressReportDisplayAmount(row.amount))}</td>
                    <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(row.tdCount)}</td>
                    <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(formatProgressReportDisplayAmount(row.tdAmount))}</td>
                </tr>
            `).join("");
            return `
                <div style="background:#ffffff; border:1.5px solid #bfdbfe; border-radius:16px; padding:10px; margin-bottom:12px; overflow:hidden;">
                    <div style="font-size:0.78rem; font-weight:950; color:#1d4ed8; text-align:center; text-transform:uppercase; margin-bottom:8px;">Summary</div>
                    <table style="width:100%; table-layout:fixed; border-collapse:collapse; font-size:0.52rem; font-weight:850; color:#1e293b;">
                        <thead>
                            <tr style="background:#dbeafe; color:#1e3a8a;">
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">DC Name</th>
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">HQ Name</th>
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">No of Consumer Paid</th>
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">TOTAL AMT (LAKH)</th>
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">No of Line TD</th>
                                <th style="border:1px solid #93c5fd; padding:4px; word-break:break-word;">TD AMT (LAKH)</th>
                            </tr>
                        </thead>
                        <tbody>${bodyRows}</tbody>
                        <tfoot>
                            <tr style="background:#eff6ff; color:#0f172a; font-weight:950;">
                                <td style="border:1px solid #93c5fd; padding:4px;" colspan="2">TOTAL</td>
                                <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(totalCount)}</td>
                                <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(formatProgressReportDisplayAmount(totalAmount))}</td>
                                <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(totalTdCount)}</td>
                                <td style="border:1px solid #93c5fd; padding:4px;">${escapeHtml(formatProgressReportDisplayAmount(totalTdAmount))}</td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            `;
        }

        function renderRevenueReportHtml(rows, emptyMessage) {
            if (!rows.length) {
                return `
                    <div style="background:#fff7ed; border:1.5px dashed #fdba74; border-radius:16px; padding:16px; color:#9a3412; font-weight:900; font-size:0.8rem; line-height:1.45; text-align:center;">
                        ${escapeHtml(emptyMessage)}
                    </div>
                `;
            }
            return renderRevenueSummaryTable(rows);
        }

        function getRevenueReportHeaders() {
            return ["S.NO", "TYPE", "IVRS NO", "CONSUMER NAME", "FATHER NAME", revenueVillageLabelUpper(), revenueHqLabelUpper(), "TARRIF CATEGORY", "MOBILE NO", "ARREARS", "NET BILL", "PAID DATE", "PAID TIME", "PAID AMOUNT", "TD DATE", "TD TIME", "TD AMOUNT", "TD REMARK"];
        }

        // LINE TD rows: show NGB cash-list payment (not staff "Paid By Staff" entries) in PAID DATE / PAID AMOUNT.
        function scTdCashlistPaid_(row) {
            if (!row || row.reportType !== "TD") return { date: "", amount: "" };
            const m = String(row.paidStatus || "").match(/^\s*NGB\s*Cashlist\s*:\s*Rs\.?\s*([\d.,]+)\s*\|\s*Date\s*:\s*([^|]+)/i);
            if (!m) return { date: "", amount: "" };
            return { date: String(m[2]).trim(), amount: String(m[1]).replace(/,/g, "") };
        }

        // 2026-10-26 (USER RULE): pichhle mahine ke TD me - master ki Last Payment Date TD date (ya uske baad) ki ho
        // to PAID maana jaye; TD se pehle ki ho to UNPAID. Current mahine ke TD me sirf NGB cash list chalegi.
        function scTdMasterPaidDate_(row) {
            try {
                if (!row || row.reportType !== "TD") return "";
                const tdKey = scPayDateKey_(row.tdDate);
                if (!tdKey) return "";
                const now = new Date();
                const curYm = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}`;
                if (tdKey.slice(0, 6) >= curYm) return "";
                const dc = normalizeDcName(row.dcName || activeDC || "");
                const lpd = getMasterLastPayMapForDc_(dc).get(normalizeRevenueIvrs(row.ivrsNo));
                if (!lpd || lpd < tdKey) return "";
                return `${lpd.slice(6, 8)}-${lpd.slice(4, 6)}-${lpd.slice(0, 4)}`;
            } catch (e) { return ""; }
        }
        // TD report chalane se pehle un DC ka Master load karo jinke pichhle mahine ke TD hain (taaki Last Payment Date mile).
        const scTdMasterLoaded_ = new Set();
        async function scRevTdEnsureMaster_() {
            const now = new Date();
            const curYm = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, "0")}`;
            const dcs = new Set();
            getRevenueTdEntriesLocal().forEach((r) => {
                try {
                    const k = scPayDateKey_(r.tdDate);
                    if (!k || k.slice(0, 6) >= curYm) return;
                    if (!isRevenueRowInCurrentScope({ ...r, reportType: "TD" })) return;
                    const dc = normalizeDcName(r.dcName || activeDC || "");
                    if (dc && !scTdMasterLoaded_.has(dc)) dcs.add(dc);
                } catch (_) {}
            });
            const list = Array.from(dcs);
            if (!list.length) return;
            await ensureRevenueCategoryMasterDataLoaded(list);
            list.forEach((d) => { if (getMasterLastPayMapForDc_(d).size) scTdMasterLoaded_.add(d); });
        }
        function scTdIsPaid_(row) {
            return !!scTdCashlistPaid_(row).amount || !!scTdMasterPaidDate_(row);
        }

        function getRevenueReportRows(rows) {
            return rows.map((row, index) => [
                index + 1, row.reportType === "TD" ? "LINE TD" : "PAID",
                row.ivrsNo,
                row.consumerName,
                row.fatherName,
                row.village,
                row.hqName,
                row.tariffCategory,
                row.mobileNo,
                row.arrears,
                row.netBill,
                row.reportType === "TD" ? (scTdCashlistPaid_(row).date || scTdMasterPaidDate_(row)) : row.paidDate,
                row.reportType === "TD" ? "" : formatRevenuePaidTime(row.paidTime),
                row.reportType === "TD" ? scTdCashlistPaid_(row).amount : row.paidAmount,
                row.reportType === "TD" ? row.tdDate : "",
                row.reportType === "TD" ? formatRevenuePaidTime(row.tdTime) : "",
                row.reportType === "TD" ? getRevenueTdAmount(row) : "",
                row.reportType === "TD" ? (row.remark || "") : ""
            ]);
        }

        let revenueLiveProgressToken = 0;
        // syncRevenueLiveEntriesFromSheet aur syncRevenueTdEntriesFromSheet dono
        // ab apna-apna shared 60-second TTL rakhte hain (dekhein unki definition).
        // Ye helper dono ke fresh-hone ka combined check deta hai, taaki Live
        // Progress aur baaki reports ek hi cache-state par bharosa kar saken.
        function isRevenueLiveAndTdDataFresh(scopeDc = null) {
            const now = Date.now();
            // Circle-scope cache (null) har view ke liye kaafi hai. Lekin ek
            // DC-only cache ko Division/Circle me kabhi reuse nahi kar sakte;
            // warna 60-second TTL ke andar partial data dikh sakta tha.
            const requestedScope = scopeDc ? normalizeDcName(scopeDc) : null;
            const liveScope = revenueLiveEntriesCachedScopeDc ? normalizeDcName(revenueLiveEntriesCachedScopeDc) : null;
            const tdScope = revenueTdEntriesCachedScopeDc ? normalizeDcName(revenueTdEntriesCachedScopeDc) : null;
            const liveScopeMatches = liveScope === null || (requestedScope && liveScope === requestedScope);
            const tdScopeMatches = tdScope === null || (requestedScope && tdScope === requestedScope);
            return !!revenueLiveEntriesSyncedAt && (now - revenueLiveEntriesSyncedAt < REVENUE_LIVE_ENTRIES_SYNC_TTL_MS)
                && !!revenueTdEntriesSyncedAt && (now - revenueTdEntriesSyncedAt < REVENUE_TD_ENTRIES_SYNC_TTL_MS)
                && liveScopeMatches && tdScopeMatches;
        }
        async function renderRevenueLiveProgress() {
            const tableBox = document.getElementById("revenue-live-table");
            if (!tableBox) return;
            const myToken = ++revenueLiveProgressToken;
            // Race-condition safety: activeViewLevel kabhi-kabhi stale ho sakta hai jab tak
            // ye view render ho, isliye activeDC/activeDiv se turant dobara confirm kar lo.
            if (activeDC) activeViewLevel = "DC";
            else if (activeDiv) activeViewLevel = "DIVISION";
            else activeViewLevel = "CIRCLE";
            const dcLabelBox = document.getElementById("revenue-live-dc-label");
            if (dcLabelBox) dcLabelBox.innerText = activeDC ? `DC: ${activeDC}` : getRevenueReportScopeLabel();
            // syncRevenueLiveEntriesFromSheet/syncRevenueTdEntriesFromSheet ab khud
            // ek shared 60-second cache rakhte hain (Cash Reconcile/Pending DO List
            // jaisi kisi bhi report ne pehle hi sync kiya ho to bhi). Yahan check kar
            // lete hain ki dono fresh hain kya - agar haan to progress-bar UI bhi
            // dikhaye bina turant re-render kar dete hain.
            const cacheScopeDc = activeViewLevel === "DC" && activeDC ? activeDC : null;
            const needsSync = !isRevenueLiveAndTdDataFresh(cacheScopeDc);
            if (!needsSync) {
                const rows = getRevenueCombinedFilteredEntries("DAILY", getCurrentDateDDMMYYYY());
                const groupedRows = buildProgressRevenueSummaryRows(rows);
                tableBox.innerHTML = renderRevenueLiveSummaryTable(groupedRows);
                return;
            }
            const progress = renderSyncingProgress(tableBox, () => myToken === revenueLiveProgressToken, "SYNCING DATA... PLEASE WAIT");
            if (activeDC) activeViewLevel = "DC";
            else if (activeDiv) activeViewLevel = "DIVISION";
            else activeViewLevel = "CIRCLE";
            // PERF FIX (2026-08-20, extended 2026-09-15): DC-scope par pehle FAST,
            // isolated path try karo (sirf is DC + sirf aaj ki date) - dekhein
            // fetchRevenueLiveProgressFastRows_ ke upar wala detailed comment.
            // SPEED FIX (2026-09-15, refined 2026-09-18): Division me `dc_names`
            // bhejte hain, isliye backend sirf us Division ke DC padhta hai;
            // Circle me aaj ki date ka chhota response aata hai. Kisi bhi scope
            // me fast path fail ho jaaye to purani
            // (poori) sync method par turant fallback - taaki behavior kabhi pehle
            // se KHARAB na ho, sirf FAST ho.
            let rows = null;
            if (activeViewLevel === "DC" && activeDC) {
                rows = await fetchRevenueLiveProgressFastRows_(activeDC, getCurrentDateDDMMYYYY());
                if (myToken !== revenueLiveProgressToken) { progress.stop(); return; }
            } else if (activeViewLevel === "DIVISION" || activeViewLevel === "CIRCLE") {
                const divisionDcNames = activeViewLevel === "DIVISION" && activeDiv
                    ? getDivisionDcNames(activeDiv)
                    : [];
                // Naya compact summary endpoint pehle try hota hai. Circle me bhi
                // raw consumer rows browser tak nahi aate; sirf per-DC totals aate hain.
                const dailySummaryRows = await fetchRevenueLiveProgressDailySummary_(divisionDcNames, getCurrentDateDDMMYYYY());
                const todayRows = dailySummaryRows || await fetchRevenueLiveProgressFastRows_("", getCurrentDateDDMMYYYY(), divisionDcNames);
                if (myToken !== revenueLiveProgressToken) { progress.stop(); return; }
                if (todayRows) {
                    if (activeViewLevel === "DIVISION" && activeDiv) {
                        const dcSet = new Set(getDivisionDcNames(activeDiv).map((n) => normalizeDcName(n)));
                        rows = todayRows.filter((r) => dcSet.has(normalizeDcName(r.dcName)));
                    } else {
                        rows = todayRows;
                    }
                }
            }
            if (!rows) {
                await Promise.all([syncRevenueLiveEntriesFromSheet(), syncRevenueTdEntriesFromSheet()]);
                if (myToken !== revenueLiveProgressToken) { progress.stop(); return; }
                rows = getRevenueCombinedFilteredEntries("DAILY", getCurrentDateDDMMYYYY());
            }
            const groupedRows = buildProgressRevenueSummaryRows(rows);
            await progress.finish();
            if (myToken !== revenueLiveProgressToken) return;
            tableBox.innerHTML = renderRevenueLiveSummaryTable(groupedRows);
        }

        function renderRevenueLiveSummaryTable(rows) {
            const colLabel = getRevenueProgressColumnLabel();
            const totals = getRevenueProgressTotals(rows);
            const totalEntries = totals.paidCount + totals.tdCount;
            const totalAmount = totals.paidAmount + totals.tdAmount;
            // ISOLATED ADDITION (2026-10-03, USER REQUEST): Freeze report jaisa hi
            // professional 2-row card summary - Row1 COUNT (Total Entries/Paid/
            // Line TD), Row2 AMOUNT (Lakh) - ekdum same column sequence/colour
            // jaisa Freeze cards me (teal=Total, green=Paid, red=TD/Pending).
            let html = `
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:0 auto 8px;">
                    <div style="background:#f0fdfa; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#0e7490; text-transform:uppercase;">Total Entries</div><div style="font-size:0.95rem; font-weight:950; color:#0e7490; margin-top:2px;">${totalEntries}</div></div>
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid</div><div style="font-size:0.95rem; font-weight:950; color:#166534; margin-top:2px;">${totals.paidCount}</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Line TD</div><div style="font-size:0.95rem; font-weight:950; color:#9f1239; margin-top:2px;">${totals.tdCount}</div></div>
                </div>
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; margin:0 auto 10px;">
                    <div style="background:#f0fdfa; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#0e7490; text-transform:uppercase;">Total Amt</div><div style="font-size:0.85rem; font-weight:950; color:#0e7490; margin-top:2px;">${formatProgressReportDisplayAmount(totalAmount)}</div></div>
                    <div style="background:#ecfdf5; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid Amt</div><div style="font-size:0.85rem; font-weight:950; color:#166534; margin-top:2px;">${formatProgressReportDisplayAmount(totals.paidAmount)}</div></div>
                    <div style="background:#fff1f2; border-radius:12px; padding:8px 4px; text-align:center;"><div style="font-size:0.54rem; font-weight:850; color:#9f1239; text-transform:uppercase;">TD Amt</div><div style="font-size:0.85rem; font-weight:950; color:#9f1239; margin-top:2px;">${formatProgressReportDisplayAmount(totals.tdAmount)}</div></div>
                </div>
                <div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: 1.15fr 0.75fr 0.95fr 0.75fr 0.95fr;"><div>${colLabel}</div><div>PAID</div><div>PAID AMT</div><div>LINE TD</div><div>TD AMT</div></div>`;
            if (!rows.length) {
                html += `${scEmptyState_(`No revenue entry for today's date.`)}`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: 1.15fr 0.75fr 0.95fr 0.75fr 0.95fr;"><div>${row.name}</div><div>${row.paidCount}</div><div class="text-emerald-700 font-black">${formatProgressReportDisplayAmount(row.paidAmount)}</div><div>${row.tdCount}</div><div class="text-rose-700 font-black">${formatProgressReportDisplayAmount(row.tdAmount)}</div></div>`;
                });
            }
            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">GRAND TOTAL (Today)</div><div class="mt-2 grid grid-cols-2 gap-2 text-center text-[11px] font-black"><div class="rounded-xl bg-emerald-50 border border-emerald-200 p-2">Paid: ${totals.paidCount}<br>${formatProgressReportDisplayAmount(totals.paidAmount)}</div><div class="rounded-xl bg-rose-50 border border-rose-200 p-2">Line TD: ${totals.tdCount}<br>${formatProgressReportDisplayAmount(totals.tdAmount)}</div></div></div>`;
            return html;
        }

        function getRevenueReportScopeLabel() {
            if (activeViewLevel === "DC" && activeDC) return `DC: ${activeDC}`;
            if (activeViewLevel === "DIVISION" && activeDiv) return `Division: ${activeDiv}`;
            return "Circle: SEONI CIRCLE";
        }

        function getRevenueReportGeneratedAt() {
            return `${getCurrentDateDDMMYYYY()} ${getCurrentTimeHHMM()}`;
        }

        function getRevenueReportMeta(title, periodLabel, filterLabel) {
            return {
                title: title || "Revenue Collection Report",
                periodLabel: periodLabel || `Date: ${getCurrentDateDDMMYYYY()}`,
                scopeLabel: getRevenueReportScopeLabel(),
                filterLabel: filterLabel || "HQ Filter: All HQ",
                generatedAt: getRevenueReportGeneratedAt()
            };
        }

        function downloadRevenueRowsReport(type, rows, title, fileName, meta = null) {
            if (!rows.length) return showToast("No data available for the report right now", false);
            const reportMeta = meta || getRevenueReportMeta(title);
            const headers = getRevenueReportHeaders();
            const reportRows = getRevenueReportRows(rows);
            const summaryHeaders = ["DC Name", "HQ Name", "No of Consumer Paid", "Total Paid Amount", "No of Line TD", "TD Amount"];
            const summaryDataRows = buildRevenueSummaryRows(rows);
            const summaryRows = summaryDataRows.map((row) => [
                row.dcName,
                row.hqName,
                row.count,
                formatRevenueAmount(row.amount),
                row.tdCount,
                formatRevenueAmount(row.tdAmount)
            ]);
            const summaryTotal = summaryDataRows.reduce((total, row) => {
                total.count += Number(row.count || 0);
                total.amount += Number(row.amount || 0);
                total.tdCount += Number(row.tdCount || 0);
                total.tdAmount += Number(row.tdAmount || 0);
                return total;
            }, { count: 0, amount: 0, tdCount: 0, tdAmount: 0 });
            summaryRows.push([
                "TOTAL",
                "",
                summaryTotal.count,
                formatRevenueAmount(summaryTotal.amount),
                summaryTotal.tdCount,
                formatRevenueAmount(summaryTotal.tdAmount)
            ]);

            if (type === "PDF") {
                if (!window.jspdf || !window.jspdf.jsPDF) {
                    return showToast("PDF library could not be loaded", false);
                }
                const pdfText = (value) => String(value ?? "-").replace(/₹/g, "Rs");
                const { jsPDF } = window.jspdf;
                const doc = new jsPDF("l", "mm", "a4");
                scPdfHeader_(doc, { title: reportMeta.title, lines: [reportMeta.periodLabel, `${reportMeta.scopeLabel} | ${reportMeta.filterLabel}`], focus: { hq: document.getElementById("revenue-report-download-view")?.classList.contains("active") ? (document.getElementById("revenue-report-hq")?.value || "") : "" } }); // SC PDF KIT
                // NOTE (user request): "Report Diagnostics" table (Total Records/Total
                // Paid Amount/Total Line TD Entries/Report Period/Scope) yahan se hata
                // di gayi hai - ab report sirf Summary + Consumer List ke saath bante
                // hai. Diagnostics table hatne se Summary table seedhe upar (startY 40)
                // se shuru hoti hai.
                const summaryTitleY = 40;
                doc.setFontSize(11);
                doc.setTextColor(30, 58, 138);
                doc.text("Summary", 14, summaryTitleY - 2);
                doc.autoTable({
                    startY: summaryTitleY + 2,
                    head: [summaryHeaders],
                    body: summaryRows.map((items) => items.map(pdfText)),
                    theme: "grid",
                    headStyles: { fillColor: [219, 234, 254], textColor: [30, 58, 138], halign: "center" },
                    styles: { fontSize: 7, cellPadding: 1.7, halign: "center", overflow: "linebreak" }
                });
                const listStartY = (doc.lastAutoTable?.finalY || 45) + 10;
                doc.setFontSize(11);
                doc.setTextColor(30, 58, 138);
                doc.text("Consumer List", 14, listStartY - 2);
                doc.autoTable({
                    startY: listStartY + 2,
                    head: [headers],
                    body: reportRows.map((items) => items.map(pdfText)),
                    theme: "grid",
                    headStyles: { fillColor: [17, 24, 39], textColor: 255, halign: "center" },
                    styles: { fontSize: 5.2, cellPadding: 1.1, halign: "center", overflow: "linebreak" },
                    columnStyles: {
                        3: { halign: "left" },
                        4: { halign: "left" },
                        5: { halign: "left" },
                        17: { halign: "left" }
                    },
                    // 2026-10-26 (USER REPORT - TD REMARK me ajeeb akshar): jis cell me Hindi (Devanagari) text ho, usko Meter Checking wale
                    // tareeke se image bana kar lagate hain (jsPDF Hindi nahi dikha sakta) - size English text ke barabar rehta hai.
                    didParseCell: (cd) => {
                        if (cd.section === "body" && meterCheckingCellHasDevanagari_(cd.cell.raw)) scHindiProxyText_(cd);
                    },
                    didDrawCell: (cd) => {
                        if (cd.section === "body" && meterCheckingCellHasDevanagari_(cd.cell.raw)) {
                            drawMeterCheckingHindiCell_(doc, cd, [3, 4, 5, 17].includes(cd.column.index) ? "left" : "center");
                        }
                    }
                });
                const safePdfName = (fileName || "revenue-report.csv").replace(/\.csv$/i, ".pdf").replace(/[\\/:*?"<>|]+/g, "_");
                savePdfDocumentForDevice(doc, safePdfName);
                showToast("PDF report downloaded", true);
                return;
            }

            const csv = [
                [scPdfFocusTitle_(reportMeta.title, { hq: document.getElementById("revenue-report-download-view")?.classList.contains("active") ? (document.getElementById("revenue-report-hq")?.value || "") : "" })], // 2026-09-27: PDF jaisa title
                [reportMeta.periodLabel],
                [`${reportMeta.scopeLabel} | ${reportMeta.filterLabel}`],
                [],
                ["SUMMARY"],
                summaryHeaders,
                ...summaryRows,
                [],
                ["CONSUMER LIST"],
                headers,
                ...reportRows
            ]
                .map((items) => items.map((item) => `"${String(item || "").replace(/"/g, '""')}"`).join(","))
                .join("\n");
            const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
            const link = document.createElement("a");
            link.href = URL.createObjectURL(blob);
            link.download = fileName || "revenue-report.csv";
            link.click();
            setTimeout(() => URL.revokeObjectURL(link.href), 1000);
            showToast("Excel report downloaded", true);
        }

        async function downloadRevenueLiveReport(type) {
            if (revenueLiveDownloadInProgress) return showToast("Download in progress, please wait", false);
            setRevenueLiveDownloadState(true, "Download in progress... please wait", true);
            try {
                await Promise.all([syncRevenueLiveEntriesFromSheet(), syncRevenueTdEntriesFromSheet()]);
                const rows = getRevenueCombinedFilteredEntries("DAILY", getCurrentDateDDMMYYYY());
                if (!rows.length) {
                    setRevenueLiveDownloadState(false, "No data available for the report", false);
                    return showToast("No data available for the report right now", false);
                }
                const todayLabel = getCurrentDateDDMMYYYY();
                downloadRevenueRowsReport(type, rows, "Revenue Live Progress", "revenue-live-progress-today.csv", getRevenueReportMeta(
                    "Revenue Live Progress",
                    `Today: ${todayLabel}`,
                    activeViewLevel === "DC" ? `${revenueHqLabel()} Filter: ${revenueHqAllLabel()}` : "HQ Filter: All HQ"
                ));
                setRevenueLiveDownloadState(false, `${type === "PDF" ? "PDF" : "Excel"} downloaded`, true);
            } catch (error) {
                setRevenueLiveDownloadState(false, "Download failed, please try again", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        function setRevenueLiveDownloadState(isLoading, message = "", ok = true) {
            revenueLiveDownloadInProgress = isLoading;
            scApplyDownloadBoxState_("revenue-live", isLoading, message, ok);
        }

        let revenueReportMode = "DAILY";
        let revenueCashReconcileMode = "DAILY";
        let revenueCashReconcileRows = [];
        let revenueCashReconcileRenderToken = 0;
        // Pehle date/month/HQ/status dropdown me kuch bhi change karte hi poori
        // report dobara poore network se sync ho jaati thi, chahe kuch second
        // pehle hi wahi data aa chuka ho (ya Live Progress/Pending DO List me
        // pehle hi sync ho chuka ho) - isse anaawashyak time lagta tha. Ab
        // syncRevenueLiveEntriesFromSheet/getRevenueUploadedPaidMasterRows dono
        // apna shared 60-second cache khud rakhte hain (dekhein unki definition),
        // isliye yahan sirf check karte hain ki dono is DC ke liye fresh hain ya
        // nahi - agar haan to network call/progress-bar UI dikhaye bina turant
        // re-render karte hain.
        function isRevenueCashReconcileDataFresh() {
            const dcKey = normalizeLookupValue(activeDC || "");
            return !!revenueLiveEntriesSyncedAt && (Date.now() - revenueLiveEntriesSyncedAt < REVENUE_LIVE_ENTRIES_SYNC_TTL_MS)
                && !!revenueUploadedPaidMasterRowsCache && revenueUploadedPaidMasterRowsCache.dcKey === dcKey
                && !!revenueUploadedPaidMasterRowsCache.backendSynced
                && (Date.now() - revenueUploadedPaidMasterRowsCache.syncedAt < REVENUE_UPLOADED_PAID_MASTER_SYNC_TTL_MS);
        }

        function initRevenueReportDownload() {
            revenueReportLoadedScopeKey = null;
            const dateInput = document.getElementById("revenue-report-date");
            const monthInput = document.getElementById("revenue-report-month");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            if (monthInput && !monthInput.value) monthInput.value = getTodayIsoDate().slice(0, 7);
            setRevenueReportMode(revenueReportMode || "DAILY");
        }

        function setRevenueReportMode(mode) {
            revenueReportMode = mode === "MONTHLY" ? "MONTHLY" : "DAILY";
            const dateInput = document.getElementById("revenue-report-date");
            const monthInput = document.getElementById("revenue-report-month");
            const dateBtn = document.getElementById("revenue-report-date-mode-btn");
            const monthBtn = document.getElementById("revenue-report-month-mode-btn");
            if (dateInput) dateInput.style.display = revenueReportMode === "DAILY" ? "block" : "none";
            if (monthInput) monthInput.style.display = revenueReportMode === "MONTHLY" ? "block" : "none";
            if (dateBtn) {
                dateBtn.style.background = revenueReportMode === "DAILY" ? "#1d4ed8" : "#dbeafe";
                dateBtn.style.color = revenueReportMode === "DAILY" ? "#ffffff" : "#1d4ed8";
            }
            if (monthBtn) {
                monthBtn.style.background = revenueReportMode === "MONTHLY" ? "#1d4ed8" : "#dbeafe";
                monthBtn.style.color = revenueReportMode === "MONTHLY" ? "#ffffff" : "#1d4ed8";
            }
            renderRevenueReportDownload();
        }

        function filterRevenueRowsBySelectedType(rows) {
            const typeValue = document.getElementById("revenue-report-type")?.value || "";
            if (!typeValue) return rows || [];
            let out = (rows || []).filter((row) => (typeValue === "TD" ? row.reportType === "TD" : row.reportType !== "TD"));
            // 2026-10-26 (USER REQUEST): TD by Staff me - TD ke baad paid hue / abhi tak unpaid, alag list.
            const tdSt = typeValue === "TD" ? (document.getElementById("revenue-report-td-status")?.value || "") : "";
            if (tdSt) out = out.filter((row) => { const paid = scTdIsPaid_(row); return tdSt === "PAID" ? paid : !paid; });
            return out;
        }
        function scRevTdStatusToggle_() {
            const isTd = (document.getElementById("revenue-report-type")?.value || "") === "TD";
            const sel = document.getElementById("revenue-report-td-status");
            if (!sel) return;
            sel.style.display = isTd ? "block" : "none";
            if (!isTd) sel.value = "";
        }

        function getRevenueSelectedReportRows() {
            let rows = [];
            if (revenueReportMode === "MONTHLY") {
                const monthValue = document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7);
                rows = getRevenueCombinedFilteredEntries("MONTHLY", monthValue);
            } else {
                const dateValue = document.getElementById("revenue-report-date")?.value || getTodayIsoDate();
                rows = getRevenueCombinedFilteredEntries("DAILY", dateValue);
            }
            return filterRevenueRowsBySelectedType(filterRevenueRowsBySelectedHq(rows));
        }

        function getRevenueSelectedReportTypeLabel() {
            const typeValue = document.getElementById("revenue-report-type")?.value || "";
            if (typeValue === "PAID") return "Paid by Staff";
            if (typeValue === "TD") {
                const st = document.getElementById("revenue-report-td-status")?.value || "";
                return st === "PAID" ? "TD by Staff - Paid after TD" : (st === "UNPAID" ? "TD by Staff - Unpaid (pending)" : "TD by Staff");
            }
            return "Paid + TD Both";
        }

        function getRevenueSelectedReportTitle() {
            const hqValue = document.getElementById("revenue-report-hq")?.value || "";
            const hqSuffix = hqValue ? ` - ${hqValue}` : " - All HQ";
            const typeValue = document.getElementById("revenue-report-type")?.value || "";
            const typeSuffix = typeValue ? ` - ${getRevenueSelectedReportTypeLabel()}` : "";
            if (revenueReportMode === "MONTHLY") {
                const monthValue = document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7);
                return `Revenue Collection Month Report - ${formatRevenueMonthYear(monthValue)}${hqSuffix}${typeSuffix}`;
            }
            const dateValue = normalizeRevenueReportDate(document.getElementById("revenue-report-date")?.value || getCurrentDateDDMMYYYY());
            return `Revenue Collection Date Report - ${dateValue}${hqSuffix}${typeSuffix}`;
        }

        // ============================================================
        // REVENUE REPORT DOWNLOAD - Division/Circle ISOLATED fast path
        // (2026-09-16 speed fix). DC-level scope (activeDC set) ISSE BILKUL
        // TOUCH NAHI hota - woh neeche renderRevenueReportDownload() ke
        // pehle if(activeDC) branch me purane hi shared-cache scopeDc path
        // se chalta hai, byte-for-byte unchanged. Yeh naya path SIRF
        // Division/Circle (activeDC khaali) ke liye hai, aur Stock fix,
        // O&M/VIG, Daily Progress "Paid by Staff" Live Revenue tile
        // (fetchRevenueLiveProgressFastRows_), ya kisi aur Revenue screen
        // (Cash Reconcile/Pending DO List/Progress Report) ko bilkul nahi
        // chhedta - woh sab apne purane getRevenueLiveEntries()/
        // getRevenueTdEntriesLocal() shared-cache par hi chalte rehte hain.
        //
        // User-approved corrections (9) is design me:
        //  1) PAID (per-DC sheets) 6-DC batches me fetch hoti hai; TD
        //     (ek hi SHARED sheet, sabhi DC ke liye) poore scope ke liye
        //     sirf EK request - kabhi bhi per-PAID-batch nahi.
        //  2) dc_names backend ke requireDcName_() se validate hote hain -
        //     koi bhi failure silently drop nahi hoti, saaf error milta hai.
        //  3) date/month filtering backend-side hoti hai, matchesMonthFilter_
        //     normalizeDateDigits_ (normalizeRevenueReportDate/
        //     getRevenueMonthKey jaisa hi parsing) par based hai - parity
        //     alag se /tmp/parity_test.js me verify ki gayi.
        //  4) Yeh apna ALAG isolated cache (revenueReportScopedCacheMap_)
        //     rakhta hai - shared Live/TD cache ko kabhi READ ya WRITE
        //     nahi karta.
        //  5) Cache/request key = normalized DC list + DAILY/MONTHLY mode +
        //     selected date/month (buildRevenueReportScopeKey_). Render-
        //     token (revenueReportRenderToken) ke saath milkar ek purani/
        //     stale response kabhi bhi naye selection ko overwrite nahi
        //     kar sakti.
        //  6) Capability sirf api_version se nahi - response ke
        //     scope_mode/period_mode/period_value/requested_dc_count
        //     marker fields se confirm hoti hai
        //     (revenueReportHasCapabilityMarkers_). Marker missing = purana
        //     backend = silent fallback purane unscoped path par
        //     (renderRevenueReportDownloadLegacyScoped_) - koi error nahi.
        //  7) Download button isi loadRevenueReportScopedRows_() cache ko
        //     reuse karta hai - fresh cache par dobara fetch nahi.
        //  8) Partial PAID-batch failure ya TD-failure par poori report
        //     silently partial/khaali nahi dikhti - failed DC naam ke
        //     saath clear error throw hoti hai (fetchRevenueReportPaidBatch_/
        //     fetchRevenueReportTdSingle_), jo render/download dono jagah
        //     user ko saaf dikhta hai.
        //  9) PAID 6-DC batches me fetch hoti hai (per-DC sheets), par ab
        //     PARALLEL (existing withAppsScriptConcurrencyGate_ ke 2-concurrent
        //     limit ke andar) - sequential nahi (round-2 fix, neeche note).
        //     TD ek hi shared sheet ke liye poore scope me sirf EK request.
        //
        // ROUND-2 CORRECTIONS (user review ke baad):
        //  a) Sequential-batch bug fix: pehle PAID ke 6-DC batches ek-ek karke
        //     (for-loop + await) chalte the - isse total backend read-cost me
        //     koi kami nahi thi (same total cells), sirf alag-alag script
        //     invocations ka overhead JUD raha tha (har request ka apna
        //     latency/auth/JSON overhead), jo user ne sahi pakda. Ab batches
        //     Promise.all() se ek saath chhodi jaati hain - app ka existing
        //     withAppsScriptConcurrencyGate_ (2 concurrent/script-URL) unhe
        //     khud hi 2-at-a-time serialize karta hai, jo poori app me already
        //     istemal ho raha hai (kahin naya risk nahi). Isse real-world
        //     latency sequential se kam hogi, kyunki gate allow karte hi agla
        //     batch turant shuru ho jaata hai, purane ke poora khatam hone ka
        //     wait nahi karta.
        //  b) HONEST NOTE (backend Sheets-API read-cost par): scoping se
        //     RESPONSE PAYLOAD (jo browser tak aata hai) chhota hota hai -
        //     kyunki filtering backend par hi ho jaati hai, poori history
        //     browser tak nahi aati. Division scope me READ-COST bhi kam hota
        //     hai (sirf us division ki DC sheets padhi jaati hain, sabhi 24
        //     ki nahi). Circle scope me saari 24 DC sheets ab bhi utni hi
        //     padhi jaati hain jitni pehle unscoped call me padhti thi (same
        //     total data) - isliye Circle ke liye "backend read-cost drastically
        //     kam hua" jaisa claim GALAT tha, maine pehle overstate kiya - woh
        //     claim yahan se hata diya gaya hai. Circle ka genuine fayda:
        //     (i) chhota response payload/JSON-parse (sirf maangi hui date/
        //     month ki rows), (ii) browser me poori history hold/filter nahi
        //     karni padti, (iii) 6-DC parallel-batching se ek hi mega-request
        //     (jisme 24 sheets ka pura data ek script-execution me process ho)
        //     ke bajaye kaam chhote hisso me bant'ta hai, jo Apps Script ki
        //     6-minute execution-limit ke against ek safety margin deta hai
        //     bade/purane data-volume me.
        //     ASLI backend-execution-time/latency measurement sirf ek REAL
        //     Apps Script deployment (test/staging URL) par actual timed
        //     HTTP calls se hi possible hai - yeh sandbox environment se
        //     production Google Sheet tak connect nahi kar sakta. Isliye yeh
        //     naya code STILL 6-DC batching istemal karta hai (memory/exec-
        //     time-limit ke against safety ke liye) lekin ab PARALLEL hai
        //     (fix a upar) - agar user chahen to deploy hone ke baad ek chhoti
        //     real-timing A/B run (purana unscoped vs naya batched-parallel vs
        //     ek single-mega-request) karke confirm kar sakte hain ki konsa
        //     genuinely fastest hai; is stage par main sirf structurally sahi
        //     aur verifiably-non-regressive design de sakta hoon, real ms
        //     timing evidence nahi.
        //  c) Marker validation ab sirf existence/type nahi, VALUES bhi verify
        //     karta hai - scope_mode==="batch", period_mode expected ke barabar,
        //     period_value expected periodValue ke barabar, requested_dc_count
        //     is batch/scope ki length ke barabar, aur `requested_dc_names`
        //     (naya backend field, upar .gs me joda gaya) is batch/scope ki
        //     normalized+sorted DC list se EXACT match. Mismatch hone par
        //     response ko "invalid" maan kar reject karte hain (retry hota
        //     hai, silently accept nahi karte) - taaki kisi race/bug se galat
        //     scope ka data kabhi report me na chala jaaye.
        //  d) In-flight Promise dedupe: agar render chal hi raha ho (fetch
        //     pending) aur usi beech Download button dabaya jaaye (ya HQ/Type
        //     dropdown badal kar render dobara call ho), to same scope-key
        //     ka doosra call ussi chal rahi Promise ko reuse karta hai - naya
        //     parallel fetch shuru nahi hota (isliye total request count
        //     kabhi 2x nahi hota).
        //  e) Cache ab single object nahi, scope-key se keyed Map hai - agar
        //     koi PURANI (slow) request der se complete ho jaaye jab tak user
        //     dusre date/division par ja chuka ho, to woh apne hi (ab
        //     irrelevant) key ke against store hoti hai - current selection
        //     ki cache-entry kabhi overwrite/corrupt nahi hoti. Map bounded
        //     hai (max 8 entries, sabse purani hata di jaati hai) taaki
        //     memory unbounded na badhe.
        const revenueReportScopedCacheMap_ = new Map(); // scopeKey -> { rows, loadedAt }
        const REVENUE_REPORT_SCOPED_CACHE_TTL_MS = 60000;
        const REVENUE_REPORT_SCOPED_CACHE_MAX_ENTRIES = 8;
        const revenueReportInFlightFetches_ = new Map(); // scopeKey -> Promise

        function buildRevenueReportScopeKey_(dcList, mode, periodValue) {
            const normalizedDcs = (dcList || []).map((dc) => normalizeDcName(dc || "")).filter(Boolean).sort();
            return `${normalizedDcs.join(",")}::${mode}::${String(periodValue || "")}`;
        }

        function revenueReportPeriodParam_(mode, periodValue) {
            return mode === "MONTHLY" ? `&month=${encodeURIComponent(periodValue || "")}` : `&date=${encodeURIComponent(periodValue || "")}`;
        }

        function revenueReportChunkDcList_(list, size) {
            const out = [];
            for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
            return out;
        }

        function revenueReportSetScopedCache_(scopeKey, rows) {
            revenueReportScopedCacheMap_.set(scopeKey, { rows, loadedAt: Date.now() });
            if (revenueReportScopedCacheMap_.size > REVENUE_REPORT_SCOPED_CACHE_MAX_ENTRIES) {
                const oldestKey = revenueReportScopedCacheMap_.keys().next().value;
                revenueReportScopedCacheMap_.delete(oldestKey);
            }
        }

        // ROUND-2 (correction #c): sirf marker existence/type nahi, expected
        // VALUES ke against exact validate karte hain - jo DC list yeh
        // request cover kar rahi thi wahi backend ne echo ki ho, aur
        // scope_mode/period_mode/period_value/requested_dc_count bhi is
        // exact request se match karte hon. Ek bhi mismatch = response ko
        // reject (retry-able failure maana jaata hai, capability-mismatch
        // NAHI - kyunki agar markers hi maujood hain to backend naya hai,
        // bas is response ka data galat/stale scope ka lag raha hai).
        function revenueReportValidateMarkers_(parsed, expectedDcList, expectedPeriodMode, expectedPeriodValue) {
            // ROUND-3 FIX: scope_mode check missing tha - comment me claim ki gayi
            // thi lekin code me likha hi nahi gaya tha (user ne pakda). Is naye
            // isolated path me hum kabhi bhi `dc_name` (single) nahi bhejte, hamesha
            // `dc_names` (list) bhejte hain - isliye ek genuine naye backend ka
            // scope_mode YAHAN hamesha "batch" hi hona chahiye (PAID batches aur
            // Division/Circle TD request, dono). Kuch aur (jaise "all"/"single")
            // maane ki backend ne humari scoped request ko sahi tarike se resolve
            // nahi kiya - reject.
            if (parsed.scope_mode !== "batch") return false;
            const expectedNames = (expectedDcList || []).map((dc) => normalizeDcName(dc || "")).filter(Boolean).sort();
            const gotNames = Array.isArray(parsed?.requested_dc_names)
                ? parsed.requested_dc_names.map((dc) => normalizeDcName(dc || "")).filter(Boolean).sort()
                : null;
            if (!gotNames || gotNames.length !== expectedNames.length || gotNames.join("|") !== expectedNames.join("|")) return false;
            if (parsed.period_mode !== expectedPeriodMode) return false;
            if (String(parsed.period_value || "") !== String(expectedPeriodValue || "")) return false;
            if (Number(parsed.requested_dc_count) !== expectedDcList.length) return false;
            return true;
        }

        // Naye backend ke zaroori markers - agar yeh missing hain to purana
        // (redeploy na hua) backend hai, caller silently purane unscoped
        // path par fallback karega (api_version akela kaafi nahi maana
        // jaata - correction #6).
        function revenueReportHasCapabilityMarkers_(parsed) {
            return !!parsed && typeof parsed.scope_mode === "string" && typeof parsed.period_mode === "string"
                && typeof parsed.period_value === "string" && typeof parsed.requested_dc_count === "number";
        }

        // "capability mismatch" (purana backend) aur "genuine failure" (naya
        // backend hi hai, par is ek request ka jawab fail/error ya
        // galat-scope aaya) do ALAG cheezein hain (correction #6 aur #8). Ek
        // "status: error" response me bhi naye markers nahi hote - isliye
        // capability sirf tab decide karte hain jab response `status:
        // "success"` ho - tabhi marker missing hone ka matlab "purana
        // backend" hota hai. Markers maujood hon par exact-scope validation
        // (revenueReportValidateMarkers_) fail ho jaaye, to bhi "error"
        // (retry-able) maante hain, capability-mismatch nahi - kyunki backend
        // to naya hi hai, bas is response ka data trust nahi kar sakte.
        function revenueReportResponseCapability_(parsed, expectedDcList, expectedPeriodMode, expectedPeriodValue) {
            if (!parsed || parsed.status !== "success") return "error";
            if (!revenueReportHasCapabilityMarkers_(parsed)) return "old";
            if (!revenueReportValidateMarkers_(parsed, expectedDcList, expectedPeriodMode, expectedPeriodValue)) return "error";
            return "new";
        }

        // PAID - per-DC sheets, 6-DC batches, PARALLEL fetch (round-2 fix a) -
        // existing withAppsScriptConcurrencyGate_ khud 2-at-a-time serialize
        // karta hai. Ek batch (final retry ke baad bhi) fail ho to us batch
        // ke DC naam collect karke throw karte hain (caller ko saaf, named
        // error milta hai - kabhi bhi silent partial report nahi).
        async function fetchRevenueReportPaidBatch_(dcList, mode, periodValue) {
            if (!revenueCollectionSubmitScriptUrl) return { rows: [], capabilityMismatch: true };
            const batches = revenueReportChunkDcList_(dcList, 6);
            const periodParam = revenueReportPeriodParam_(mode, periodValue);
            const expectedPeriodMode = mode === "MONTHLY" ? "month" : "date";
            let capabilityMismatch = false;

            async function runBatch(batch) {
                const dcNamesParam = `&dc_names=${encodeURIComponent(batch.join(","))}`;
                for (let attempt = 1; attempt <= 2; attempt++) {
                    try {
                        const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                            const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getEntries${dcNamesParam}${periodParam}&t=${Date.now()}`);
                            return await response.json();
                        });
                        const capability = revenueReportResponseCapability_(parsed, batch, expectedPeriodMode, periodValue);
                        if (capability === "old") {
                            capabilityMismatch = true;
                            return { ok: true, rows: [] };
                        }
                        if (capability === "new") {
                            const sourceRows = Array.isArray(parsed?.entries) ? parsed.entries : [];
                            const rows = sourceRows.map(mapRevenueSheetEntry)
                                .filter((row) => normalizeRevenueIvrs(row.ivrsNo))
                                .map((row) => ({ ...row, reportType: "PAID" }));
                            return { ok: true, rows };
                        }
                        // capability === "error" -> genuine/validation failure, neeche retry.
                    } catch (_) {}
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
                }
                return { ok: false, dcs: batch };
            }

            const batchResults = await Promise.all(batches.map(runBatch));
            if (capabilityMismatch) return { rows: [], capabilityMismatch: true };
            const failedBatches = batchResults.filter((r) => !r.ok).flatMap((r) => r.dcs);
            if (failedBatches.length) {
                const error = new Error(`PAID data could not be loaded for these DCs: ${failedBatches.join(", ")}`);
                error.failedDcs = failedBatches;
                throw error;
            }
            const allRows = batchResults.flatMap((r) => r.rows || []);
            return { rows: allRows, capabilityMismatch: false };
        }

        // TD - ek hi shared sheet sabhi DC ke liye, isliye poore scope ke
        // DC list ke saath sirf EK request (kabhi bhi per-PAID-batch nahi -
        // correction #1). Fail hone par (final retry ke baad) poora report
        // "incomplete" maan kar clear error throw karte hain.
        async function fetchRevenueReportTdSingle_(dcList, mode, periodValue) {
            if (!revenueCollectionSubmitScriptUrl) return { rows: [], capabilityMismatch: true };
            const periodParam = revenueReportPeriodParam_(mode, periodValue);
            const expectedPeriodMode = mode === "MONTHLY" ? "month" : "date";
            const dcNamesParam = `&dc_names=${encodeURIComponent(dcList.join(","))}`;
            for (let attempt = 1; attempt <= 2; attempt++) {
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getTDEntries${dcNamesParam}${periodParam}&t=${Date.now()}`);
                        return await response.json();
                    });
                    const capability = revenueReportResponseCapability_(parsed, dcList, expectedPeriodMode, periodValue);
                    if (capability === "old") return { rows: [], capabilityMismatch: true };
                    if (capability === "new") {
                        const sourceRows = Array.isArray(parsed?.entries) ? parsed.entries : [];
                        const rows = sourceRows.map(mapRevenueTdSheetEntry).filter((row) => normalizeRevenueIvrs(row.ivrsNo));
                        return { rows, capabilityMismatch: false };
                    }
                    // capability === "error" -> genuine/validation failure, retry neeche.
                } catch (_) {}
                if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
            }
            const error = new Error("TD data could not be loaded (full scope) - error shown because the report would be incomplete");
            error.tdFailed = true;
            throw error;
        }

        // =====================================================================
        // ISOLATED ADDITION (2026-09-17, USER-APPROVED corrections): Revenue
        // Category reports (Category Wise / HQ-Village Wise / Target vs
        // Achievement / Paid Consumer Count / Particular Consumer List) ke
        // Paid/Unpaid ko naye backend "getRevenueCategoryReconciliation" action
        // (revenue-submit-script-dc-wise.gs, isolated addition) se EXACT-DATE-
        // capable per-consumer (DC+IVRS) aggregate se reconcile karne ke liye.
        // Isi existing fetchRevenueReportPaidBatch_/fetchRevenueReportTdSingle_
        // pattern (6-DC batches, revenueReportChunkDcList_, withAppsScript-
        // ConcurrencyGate_, 2 attempt/600ms*attempt retry, scope/period marker
        // validation) ko REUSE karta hai - koi existing helper modify nahi hua.
        // SCOPE: sirf naye function/state, revenue-category reports ke
        // call-sites me hi consume hote hain - baaki kisi module/report ko
        // yeh code chhoo tak nahi raha.
        // =====================================================================
        const revenueCategoryReconciliationCache_ = new Map();
        const REVENUE_CATEGORY_RECONCILIATION_TTL_MS = 60000;

        function revenueReconciliationPeriodParams_(mode, periodValue) {
            const periodMode = mode === "MONTHLY" ? "month" : "date";
            return `&period_mode=${encodeURIComponent(periodMode)}&period_value=${encodeURIComponent(periodValue || "")}`;
        }

        // USER-APPROVED correction #4: backend response ke `failed_dcs` (kisi
        // ek DC ki PAID MASTER sheet read karte waqt error) ko kabhi bhi
        // "silent partial" maan kar accept nahi karte - retry karte hain, aur
        // final retry ke baad bhi fail ho to un DC ke naam ke saath saaf error
        // throw karte hain (jaisa fetchRevenueReportPaidBatch_ already karta
        // hai apne batch-level failures ke liye).
        async function fetchRevenueCategoryReconciliationBatch_(dcList, mode, periodValue) {
            if (!revenueCollectionSubmitScriptUrl || !dcList.length) return { supported: false };
            const batches = revenueReportChunkDcList_(dcList, 6);
            const periodParams = revenueReconciliationPeriodParams_(mode, periodValue);
            const expectedPeriodMode = mode === "MONTHLY" ? "month" : "date";
            let capabilityMismatch = false;

            async function runBatch(batch) {
                const scPubRecon = await scPubReconForBatch_(batch, expectedPeriodMode, periodValue); // LIVE CACHE 2026-09-26 (paid SIG same = bilkul sahi)
                if (scPubRecon) return { ok: true, entries: scPubRecon };
                const dcNamesParam = `&dc_names=${encodeURIComponent(batch.join(","))}`;
                for (let attempt = 1; attempt <= 2; attempt++) {
                    try {
                        const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                            const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getRevenueCategoryReconciliation${dcNamesParam}${periodParams}&t=${Date.now()}`);
                            return await response.json();
                        });
                        const capability = revenueReportResponseCapability_(parsed, batch, expectedPeriodMode, periodValue);
                        if (capability === "old") { capabilityMismatch = true; return { ok: true, entries: [] }; }
                        if (capability === "new") {
                            const failedInResponse = Array.isArray(parsed.failed_dcs) ? parsed.failed_dcs.filter(Boolean) : [];
                            if (failedInResponse.length) {
                                if (attempt < 2) { await new Promise((resolve) => setTimeout(resolve, 600 * attempt)); continue; }
                                return { ok: false, dcs: failedInResponse };
                            }
                            return { ok: true, entries: Array.isArray(parsed.entries) ? parsed.entries : [] };
                        }
                        // capability === "error" -> genuine/validation failure, retry neeche.
                    } catch (_) {}
                    if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 600 * attempt));
                }
                return { ok: false, dcs: batch };
            }

            const batchResults = await Promise.all(batches.map(runBatch));
            if (capabilityMismatch) return { supported: false };
            const failedDcs = batchResults.filter((r) => !r.ok).flatMap((r) => r.dcs);
            if (failedDcs.length) {
                const error = new Error(`Revenue reconciliation data could not be loaded for these DCs: ${failedDcs.join(", ")}`);
                error.failedDcs = failedDcs;
                throw error;
            }

            // USER-APPROVED correction #5: backend already exactly-ek-entry-per-
            // unique-(DC+IVRS) deta hai, par yahan bhi defensively merge karte
            // hain - agar kabhi duplicate mile to amount sum ho, PAID COUNT
            // hamesha max 1 hi rahega (byKey Map me ek IVRS ki ek hi entry).
            const byKey = new Map();
            batchResults.forEach((result) => {
                (result.entries || []).forEach((entry) => {
                    const dcName = normalizeDcName(entry.dc_name || "");
                    const ivrs = normalizeRevenueIvrs(entry.ivrs_no);
                    if (!dcName || !ivrs) return;
                    const key = `${dcName}|${ivrs}`;
                    const amount = Number(entry.matched_paid_amount || 0);
                    const existing = byKey.get(key);
                    if (existing) {
                        existing.amount += amount;
                        if (Array.isArray(entry.payments)) existing.payments = (existing.payments || []).concat(entry.payments); // PAID DATE RULE
                        if (!existing.category && entry.tariff_category) existing.category = entry.tariff_category;
                        existing.legacyAmbiguous = existing.legacyAmbiguous || !!entry.legacy_ambiguous;
                        if (entry.source_type && String(existing.sourceType || "").indexOf(String(entry.source_type)) < 0) existing.sourceType = `${existing.sourceType || ""} ${entry.source_type}`.trim(); // AG rule 29/09
                    } else {
                        byKey.set(key, {
                            amount,
                            category: entry.tariff_category || "",
                            sourceType: entry.source_type || "", // AG rule 29/09
                            legacyAmbiguous: !!entry.legacy_ambiguous,
                            payments: Array.isArray(entry.payments) ? entry.payments.slice() : null // PAID DATE RULE
                        });
                    }
                });
            });
            return { supported: true, byKey };
        }

        // Caller (Category Wise / HQ-Village Wise / Target vs Achievement /
        // Top Defaulters render+download functions) is function ko report ke
        // exact mode+filterValue maloom hote hi await karta hai, USE PEHLE
        // buildRevenueCategorySummaryRows/buildRevenueCategoryUploadedPaidInfo
        // (dono SYNC hain) ko call kare - taaki woh is TTL-cached, already-
        // resolve-ho-chuke Map se seedhe (bina await ke) padh sakein, jaisa
        // is app me warmRevenueCategoryUploadedPaidCache/revenueCategoryCache-
        // WarmedAt ka existing pattern hai.
        // BUG FIX (2026-09-23, USER-REPORTED): cacheKey pehle sirf "mode|filterValue"
        // tha - DC-scope (DC/Division/Circle, ya kaunsi DC) bilkul shamil nahi tha.
        // Isse yeh hota tha: DC-level "ARI" ka Category Wise/Target/HQ-Village/Top-
        // Defaulters kholte hi is key ke against SIRF ARI ka reconciliation cache
        // ho jaata (60 second TTL) - agar 60 second ke andar hi wapas jaakar Circle
        // (ya kisi DOOSRI DC/Division) ka wahi report (SAME date) khola jaaye, to
        // yeh scope-blind cache HIT ho jaata tha aur SIRF ARI wala (bahut chhota)
        // reconciliation data poori Circle (23 DC) par apply ho jaata - baaki sabhi
        // DC ke consumer "byKey" Map me match hi nahi karte the, isliye unka
        // PAID/UNPAID bilkul galat (zyada tar UNPAID) dikhta tha - bina kisi error
        // ke, kyunki "supported: true" hi reh jaata tha. Yehi wajah thi ki DC->
        // Division->Circle (ya ulta) bar-bar aana-jaana karne par "kahi na kahi
        // kisi report me paid/unpaid data sahi nahi aata tha", jabki syncing bhi
        // ho rahi thi (cache hit hone par bhi progress bar dikhta hai, sirf network
        // call skip hoti hai - isliye galti turant pakad me nahi aati thi). Fix:
        // cacheKey me ab exact DC-list (jo is waqt request ho rahi hai) bhi shamil
        // hai - DC-level "ARI" aur Circle-level (jisme ARI bhi shamil hai) ab do
        // ALAG cache entries banate hain, kabhi cross-contaminate nahi honge.
        async function ensureRevenueCategoryReconciliationLoaded(mode, filterValue) {
            const dcList = Array.from(new Set(getRevenueCategoryTargetDcs().map((dcName) => normalizeDcName(dcName)).filter(Boolean))).sort();
            const cacheKey = `${mode}|${filterValue}|${dcList.join(",")}`;
            const cached = revenueCategoryReconciliationCache_.get(cacheKey);
            if (cached && Date.now() - cached.loadedAt < REVENUE_CATEGORY_RECONCILIATION_TTL_MS) return cached;
            if (!dcList.length) {
                const empty = { supported: false, byKey: new Map(), loadedAt: Date.now() };
                revenueCategoryReconciliationCache_.set(cacheKey, empty);
                return empty;
            }
            const result = await fetchRevenueCategoryReconciliationBatch_(dcList, mode, filterValue);
            const record = { supported: result.supported === true, byKey: result.byKey || new Map(), loadedAt: Date.now() };
            revenueCategoryReconciliationCache_.set(cacheKey, record);
            return record;
        }

        // Fast path for every report that uses the canonical Cash List
        // reconciliation. New backend present ho to report ko raw Cash List ka
        // per-DC warm-up nahi chahiye: reconciliation response hi authoritative
        // data deta hai. Old backend par existing legacy cache path hi chalti hai.
        async function prepareRevenueCategoryReportData_(dcNames, mode, filterValue) {
            const [_, reconciliation] = await Promise.all([
                ensureRevenueCategoryMasterDataLoadedStrict_(dcNames),
                ensureRevenueCategoryReconciliationLoaded(mode, filterValue)
            ]);
            if (reconciliation?.supported) return reconciliation;
            await Promise.all([
                ensureRevenueCategoryRawPaymentRowsLoaded(),
                warmRevenueCategoryUploadedPaidCache()
            ]);
            return reconciliation;
        }

        // USER-APPROVED correction #8: Unique Master Consumer = Paid Consumer +
        // Unpaid Consumer - har row (DC ya HQ) par. Mismatch mile to Excel/PDF
        // download silently nahi niklegi.
        function checkRevenueCategorySummaryInvariant_(rows) {
            const mismatches = [];
            (rows || []).forEach((row) => {
                if (row.type === "SUB_TOTAL" || row.type === "SUBDN_TOTAL") return;
                const uniqueMaster = Number(row.__uniqueMasterCount || 0);
                const paidPlusUnpaid = Number(row.paidConsumerTotal != null ? row.paidConsumerTotal : (row.paidTotal || 0)) + Number(row.unpaidTotal || 0) + Number(row.noDuesTotal || 0) + Number(row.agOldPaidTotal || 0); // + NO DUES + AG purane (29/09)
                if (paidPlusUnpaid !== uniqueMaster) {
                    mismatches.push({ name: row.name, uniqueMaster, paidPlusUnpaid, diff: paidPlusUnpaid - uniqueMaster });
                }
            });
            return mismatches;
        }

        // ISOLATED ADDITION (2026-09-17, USER-APPROVED condition): dedicated
        // Revenue Category report screens (HQ-Village Wise / Target vs Achievement /
        // Top Defaulters) ke liye - agar reconciliation backend abhi purana/
        // unavailable hai aur legacy fallback data dikhaya jaa raha hai, to yeh
        // ek chhota, saaf, amber "STALE/LEGACY" warning statusBox me dikhata hai
        // (non-blocking - report data neeche normal dikhta rehta hai). isStale
        // false ho to statusBox ko chhedta nahi (existing "hide on start"
        // behaviour jaisa hi rehta hai, caller display:none kar chuka hota hai).
        function showRevenueCategoryStaleLegacyWarning_(statusBox, isStale) {
            if (!statusBox || !isStale) return;
            statusBox.style.display = "block";
            statusBox.style.background = "#fffbeb";
            statusBox.style.borderColor = "#fcd34d";
            statusBox.style.color = "#92400e";
            statusBox.innerText = "STALE/LEGACY - totals may be inaccurate (backend update pending)";
        }

        // ROUND-3 CORRECTION: pehle jaisa design tha usme PAID ke 4 batches
        // aur TD request SEEDHE Promise.all() me ek saath fire ho jaate the -
        // agar backend PURANA ho (dc_names/month ignore kar deta hai, jaisa
        // ek genuinely backward-compatible old backend karega), to yeh sabhi
        // requests SHURU ho chuki hoti (Monthly Circle jaisi heavy scope me
        // har PAID batch 24-DC ki poori history laut sakta tha, TD bhi
        // unscoped poori sheet) - fir bhi CAPABILITY MISMATCH detect hone ke
        // baad legacy fallback ek ALAG poora (unscoped) sync bhi chalata,
        // matlab double heavy load, timeout risk, aur wahi slowness jo yeh
        // fix rokna chahta tha (user ne sahi pakda).
        //
        // Fix: naya, lightweight, READ-ONLY-OF-NO-SHEET `getCapabilities`
        // backend action (upar .gs me) - koi bhi PAID/TD request tabhi shuru
        // hoti hai jab yeh EK chhota probe confirm kar de ki backend naya
        // hai. Purana backend is action ko jaanta hi nahi (doGet() ke default
        // "Script Live Hai" branch par girta hai, jo koi bhi data-sheet nahi
        // chhoota) - is se turant, bina kisi PAID/TD request shuru kiye,
        // capabilityMismatch:true mil jaata hai aur legacy fallback SAAF,
        // bina kisi already-in-flight heavy request ke shuru hota hai.
        // ROUND-4 RELIABILITY FIX (user review): `supported:true` result 5
        // minute tak cache karna theek hai (backend deploy hone ke baad
        // itni jaldi wapas "purana" nahi banega). Lekin `supported:false`
        // (ya probe khud fail/timeout ho jaaye - jo network glitch se bhi ho
        // sakta hai, zaroori nahi backend hi purana ho) ko 5 minute cache
        // karna galat tha - ek CHHOTI temporary network hiccup bhi 5 minute
        // tak app ko purane heavy legacy path par force kar deta. Ab
        // `false`/error result sirf 20 second (15-30s range) cache hota hai
        // - taaki repeated re-renders (jaise dropdown filter change) turant
        // ek ke baad ek naye probe na dagen, lekin real recovery bhi jaldi
        // detect ho jaaye.
        let revenueReportCapabilityProbeCache_ = null; // { supported, checkedAt }
        const REVENUE_REPORT_CAPABILITY_PROBE_TTL_TRUE_MS = 300000; // 5 min - naya backend confirm
        const REVENUE_REPORT_CAPABILITY_PROBE_TTL_FALSE_MS = 20000; // 20 sec - purana/error/timeout
        // In-flight dedupe: agar render aur Download (ya kisi filter-change se
        // dobara render) ek hi samay par probe maang rahe hon, to sirf EK
        // network call jaaye - baaki sabhi usi chal rahi Promise ko reuse
        // karein (jaisa PAID/TD fetch ke liye pehle se hai).
        let revenueReportCapabilityProbeInFlight_ = null;

        async function revenueReportProbeCapability_() {
            if (!revenueCollectionSubmitScriptUrl) return false;
            if (revenueReportCapabilityProbeCache_) {
                const ttl = revenueReportCapabilityProbeCache_.supported
                    ? REVENUE_REPORT_CAPABILITY_PROBE_TTL_TRUE_MS
                    : REVENUE_REPORT_CAPABILITY_PROBE_TTL_FALSE_MS;
                if (Date.now() - revenueReportCapabilityProbeCache_.checkedAt < ttl) {
                    return revenueReportCapabilityProbeCache_.supported;
                }
            }
            if (revenueReportCapabilityProbeInFlight_) return revenueReportCapabilityProbeInFlight_;
            revenueReportCapabilityProbeInFlight_ = (async () => {
                let supported = false;
                try {
                    const parsed = await withAppsScriptConcurrencyGate_(revenueCollectionSubmitScriptUrl, async () => {
                        const response = await fetch(`${revenueCollectionSubmitScriptUrl}?action=getCapabilities&t=${Date.now()}`);
                        return await response.json();
                    });
                    supported = !!parsed && parsed.status === "success" && parsed.supports_report_scoping === true;
                } catch (_) {
                    supported = false;
                }
                revenueReportCapabilityProbeCache_ = { supported, checkedAt: Date.now() };
                return supported;
            })();
            try {
                return await revenueReportCapabilityProbeInFlight_;
            } finally {
                revenueReportCapabilityProbeInFlight_ = null;
            }
        }

        // PAID (batched-parallel) aur TD (single) dono ek saath (Promise.all)
        // chalte hain - TD ki request count kabhi bhi PAID batch count se
        // multiply nahi hoti (correction #1), aur PAID batches khud bhi
        // aapas me parallel hain (correction round-2/a) - PAR sirf capability
        // probe confirm hone ke BAAD (correction round-3).
        async function fetchRevenueReportPeriodScopedRows_(dcList, mode, periodValue) {
            const capable = await revenueReportProbeCapability_();
            if (!capable) return { rows: null, capabilityMismatch: true };
            const [paidResult, tdResult] = await Promise.all([
                fetchRevenueReportPaidBatch_(dcList, mode, periodValue),
                fetchRevenueReportTdSingle_(dcList, mode, periodValue)
            ]);
            if (paidResult.capabilityMismatch || tdResult.capabilityMismatch) {
                return { rows: null, capabilityMismatch: true };
            }
            return { rows: [...paidResult.rows, ...tdResult.rows], capabilityMismatch: false };
        }

        // Cache se turant (bina fetch) fresh rows dete hain agar scope+mode+
        // period match karta ho (0-row result bhi VALID cache-hit hai, ek
        // khaali array truthy hai isliye normal check hi kaafi hai), warna
        // null - render ke shuru me "loading" flicker se bachne ke liye peek
        // karne ke kaam aata hai.
        function peekRevenueReportScopedCache_(dcList, mode, periodValue) {
            const scopeKey = buildRevenueReportScopeKey_(dcList, mode, periodValue);
            const entry = revenueReportScopedCacheMap_.get(scopeKey);
            if (entry && (Date.now() - entry.loadedAt) < REVENUE_REPORT_SCOPED_CACHE_TTL_MS) {
                return entry.rows;
            }
            return null;
        }

        // Cache-aware wrapper - on-screen render aur Download button DONO
        // isi function se hokar guzarte hain (correction #7) - fresh cache
        // hote hue Download click par dobara PAID+TD fetch nahi hoti. Round-2
        // correction #d: agar isi scope-key ke liye ek fetch already chal
        // rahi hai (render abhi loading hi hai), to Download (ya koi bhi
        // doosra caller) usi in-flight Promise ko reuse karta hai - naya
        // parallel fetch kabhi shuru nahi hota, total request count doubled
        // nahi hota.
        async function loadRevenueReportScopedRows_(dcList, mode, periodValue) {
            const scopeKey = buildRevenueReportScopeKey_(dcList, mode, periodValue);
            const cached = peekRevenueReportScopedCache_(dcList, mode, periodValue);
            if (cached) return { rows: cached, capabilityMismatch: false, scopeKey };
            if (revenueReportInFlightFetches_.has(scopeKey)) {
                return revenueReportInFlightFetches_.get(scopeKey);
            }
            const fetchPromise = (async () => {
                const result = await fetchRevenueReportPeriodScopedRows_(dcList, mode, periodValue);
                if (result.capabilityMismatch) return { rows: null, capabilityMismatch: true, scopeKey };
                revenueReportSetScopedCache_(scopeKey, result.rows);
                return { rows: result.rows, capabilityMismatch: false, scopeKey };
            })();
            revenueReportInFlightFetches_.set(scopeKey, fetchPromise);
            try {
                return await fetchPromise;
            } finally {
                revenueReportInFlightFetches_.delete(scopeKey);
            }
        }

        // scopedRows backend se already period+scope-filtered aa chuki hain -
        // yahan sirf HQ/Type dropdown ka local filter lagta hai (jaisa
        // getRevenueSelectedReportRows shared-cache path ke liye karta hai).
        function getRevenueScopedSelectedReportRows_(scopedRows) {
            return filterRevenueRowsBySelectedType(filterRevenueRowsBySelectedHq(scopedRows || []));
        }

        function getRevenueReportScopeDcList_() {
            return activeViewLevel === "DIVISION" ? getDivisionDcNames(activeDiv) : getAllDcNames();
        }

        // Purana (pre-speed-fix) Division/Circle unscoped shared-cache path -
        // sirf tab call hota hai jab naya backend abhi redeploy nahi hua
        // (capability markers missing) - taaki purana backend hone par bhi
        // report kabhi khaali/galat na dikhe, bas naye jitni fast na sahi.
        async function renderRevenueReportDownloadLegacyScoped_(renderToken) {
            const tableBox = document.getElementById("revenue-report-table");
            if (!tableBox) return;
            const baseRows = revenueReportMode === "MONTHLY"
                ? getRevenueCombinedFilteredEntries("MONTHLY", document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                : getRevenueCombinedFilteredEntries("DAILY", document.getElementById("revenue-report-date")?.value || getTodayIsoDate());
            populateRevenueReportHqOptions(baseRows);
            tableBox.innerHTML = renderRevenueReportHtml(getRevenueSelectedReportRows(), "No paid/TD entry in the selected date/month.");

            const scopeKey = activeDiv || "CIRCLE";
            if (revenueReportLoadedScopeKey === scopeKey) return;

            Promise.all([syncRevenueLiveEntriesFromSheet(3, false, null), syncRevenueTdEntriesFromSheet(3, false, null)]).then(() => {
                revenueReportLoadedScopeKey = scopeKey;
                if (renderToken !== revenueReportRenderToken || !document.getElementById("revenue-report-download-view")?.classList.contains("active")) return;
                const refreshedBaseRows = revenueReportMode === "MONTHLY"
                    ? getRevenueCombinedFilteredEntries("MONTHLY", document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                    : getRevenueCombinedFilteredEntries("DAILY", document.getElementById("revenue-report-date")?.value || getTodayIsoDate());
                populateRevenueReportHqOptions(refreshedBaseRows);
                tableBox.innerHTML = renderRevenueReportHtml(getRevenueSelectedReportRows(), "No paid/TD entry in the selected date/month.");
            }).catch(() => {});
        }

        async function renderRevenueReportDownload() {
            const tableBox = document.getElementById("revenue-report-table");
            if (!tableBox) return;
            const renderToken = ++revenueReportRenderToken;
            setRevenueReportDownloadState(false, "", true);
            if ((document.getElementById("revenue-report-type")?.value || "") === "TD") {
                try { await scRevTdEnsureMaster_(); } catch (_) {}
                if (renderToken !== revenueReportRenderToken) return;
            }

            // DC-level scope. USER REQUEST (2026-09-27): pehle page khulte hi sirf local (TD)
            // entries dikhti thi aur Paid data chupchap baad me aata tha - ab baaki reports jaisa
            // SYNCING progress (%, stage text, timer) dikhta hai, sync poora hone par hi table.
            const scReportViewValid_ = () => renderToken === revenueReportRenderToken && !!document.getElementById("revenue-report-download-view")?.classList.contains("active");
            if (activeDC) {
                const renderDcNow = () => {
                    const baseRows = revenueReportMode === "MONTHLY"
                        ? getRevenueCombinedFilteredEntries("MONTHLY", document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                        : getRevenueCombinedFilteredEntries("DAILY", document.getElementById("revenue-report-date")?.value || getTodayIsoDate());
                    populateRevenueReportHqOptions(baseRows);
                    tableBox.innerHTML = renderRevenueReportHtml(getRevenueSelectedReportRows(), "No paid/TD entry in the selected date/month.");
                };
                const scopeKey = activeDC;
                if (revenueReportLoadedScopeKey === scopeKey) { renderDcNow(); return; }
                const progress = renderSyncingProgress(tableBox, scReportViewValid_);
                try {
                    await Promise.all([syncRevenueLiveEntriesFromSheet(3, false, activeDC), syncRevenueTdEntriesFromSheet(3, false, activeDC)]);
                    revenueReportLoadedScopeKey = scopeKey;
                } catch (_) {}
                if (!scReportViewValid_()) { progress.stop(); return; }
                await progress.finish();
                if (!scReportViewValid_()) return;
                renderDcNow();
                return;
            }

            // Division/Circle scope: NAYA isolated fast path.
            const dcList = getRevenueReportScopeDcList_();
            const periodValue = revenueReportMode === "MONTHLY"
                ? (document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                : (document.getElementById("revenue-report-date")?.value || getTodayIsoDate());
            const cachedRows = peekRevenueReportScopedCache_(dcList, revenueReportMode, periodValue);
            if (cachedRows) {
                populateRevenueReportHqOptions(cachedRows);
                tableBox.innerHTML = renderRevenueReportHtml(getRevenueScopedSelectedReportRows_(cachedRows), "No paid/TD entry in the selected date/month.");
            }
            // Cache na ho to Division/Circle par bhi wahi SYNCING progress (pehle sirf "load ho raha hai" text).
            const scDivProgress = cachedRows ? null : renderSyncingProgress(tableBox, scReportViewValid_);
            try {
                const result = await loadRevenueReportScopedRows_(dcList, revenueReportMode, periodValue);
                if (renderToken !== revenueReportRenderToken) { if (scDivProgress) scDivProgress.stop(); return; }
                if (scDivProgress) await scDivProgress.finish();
                if (result.capabilityMismatch) {
                    return renderRevenueReportDownloadLegacyScoped_(renderToken);
                }
                populateRevenueReportHqOptions(result.rows);
                tableBox.innerHTML = renderRevenueReportHtml(getRevenueScopedSelectedReportRows_(result.rows), "No paid/TD entry in the selected date/month.");
            } catch (error) {
                if (scDivProgress) scDivProgress.stop();
                if (renderToken !== revenueReportRenderToken) return;
                tableBox.innerHTML = renderRevenueReportHtml([], error?.message || "Report could not be loaded, please try again.");
            }
        }

        function setRevenueReportDownloadState(isLoading, message = "", ok = true) {
            revenueReportDownloadInProgress = isLoading;
            scApplyDownloadBoxState_("revenue-report", isLoading, message, ok);
        }

        async function downloadRevenueSelectedReport(type) {
            if (revenueReportDownloadInProgress) return showToast("Download in progress, please wait", false);
            setRevenueReportDownloadState(true, "Download in progress... please wait", true);
            try {
                let rows;
                if (activeDC) {
                    // DC-level scope: BILKUL UNCHANGED - purana shared-cache scopeDc
                    // fast path (2026-09-15 fix) jaisa tha waisa hi rehta hai.
                    await Promise.all([syncRevenueLiveEntriesFromSheet(3, false, activeDC), syncRevenueTdEntriesFromSheet(3, false, activeDC)]);
                    rows = getRevenueSelectedReportRows();
                } else {
                    // Division/Circle scope: NAYA isolated fast path - isi cache ko
                    // reuse karta hai jo render ne already load kiya ho (correction #7),
                    // warna khud fetch karta hai. Capability-mismatch (purana backend)
                    // par purane unscoped shared-cache path par silently fallback.
                    const dcList = getRevenueReportScopeDcList_();
                    const periodValue = revenueReportMode === "MONTHLY"
                        ? (document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                        : (document.getElementById("revenue-report-date")?.value || getTodayIsoDate());
                    const result = await loadRevenueReportScopedRows_(dcList, revenueReportMode, periodValue);
                    if (result.capabilityMismatch) {
                        await Promise.all([syncRevenueLiveEntriesFromSheet(3, false, null), syncRevenueTdEntriesFromSheet(3, false, null)]);
                        rows = getRevenueSelectedReportRows();
                    } else {
                        rows = getRevenueScopedSelectedReportRows_(result.rows);
                    }
                }
                if (!rows.length) {
                    setRevenueReportDownloadState(false, "No data available for the report", false);
                    return showToast("No data available for the report right now", false);
                }
                const title = getRevenueSelectedReportTitle();
                const hqValue = document.getElementById("revenue-report-hq")?.value || "all-hq";
                const suffix = revenueReportMode === "MONTHLY"
                    ? (document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))
                    : normalizeRevenueReportDate(document.getElementById("revenue-report-date")?.value || getCurrentDateDDMMYYYY());
                const hqSuffix = String(hqValue).replace(/[\\/:*?"<>|]+/g, "_");
                const typeValue = document.getElementById("revenue-report-type")?.value || "";
                const tdStFile_ = typeValue === "TD" ? (document.getElementById("revenue-report-td-status")?.value || "") : "";
                const typeFileSuffix = (typeValue ? `-${typeValue.toLowerCase()}` : "") + (tdStFile_ ? `-${tdStFile_.toLowerCase()}` : "");
                const periodLabel = revenueReportMode === "MONTHLY"
                    ? `Month: ${formatRevenueMonthYear(document.getElementById("revenue-report-month")?.value || getTodayIsoDate().slice(0, 7))}`
                    : `Date: ${normalizeRevenueReportDate(document.getElementById("revenue-report-date")?.value || getCurrentDateDDMMYYYY())}`;
                const filterLabel = `${hqValue && hqValue !== "all-hq" ? `${revenueHqLabel()} Filter: ${hqValue}` : `${revenueHqLabel()} Filter: ${revenueHqAllLabel()}`}  |  Type: ${getRevenueSelectedReportTypeLabel()}`;
                const reportTitle = revenueReportMode === "MONTHLY" ? "Revenue Collection Month Report" : "Revenue Collection Date Report";
                downloadRevenueRowsReport(type, rows, title, `revenue-${revenueReportMode.toLowerCase()}-${suffix}-${hqSuffix}${typeFileSuffix}.csv`, getRevenueReportMeta(
                    reportTitle,
                    periodLabel,
                    filterLabel
                ));
                setRevenueReportDownloadState(false, `${type === "PDF" ? "PDF" : "Excel"} downloaded`, true);
            } catch (error) {
                setRevenueReportDownloadState(false, "Download failed, please try again", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        // Ek baar is view me kisi DC ke liye poora sync/render ho jaaye, uske baad
        // usi view-session ke andar date/month/HQ/status dropdown sirf local
        // filter hain - dobara sync ki koi zaroorat nahi. Pehle yeh decision
        // sirf cross-report shared TTL cache (isRevenueCashReconcileDataFresh)
        // par depend karta tha, jo bade DC (jaise SEONI (T)) me kabhi-kabhi
        // backendSynced:false ho jaata to dropdown badalte hi dobara poora sync
        // shuru ho jaata - user ko irritate karta tha. Ab yeh alag, simple flag
        // hai jo sirf "is DC ke liye is view me ek baar poora load ho chuka"
        // track karta hai - jab tak view se bahar jaakar dobara na aayein, dropdown
        // change par kabhi resync nahi hoga.
        let revenueCashReconcileLoadedDcKey = null;

        function initRevenueCashReconcile() {
            revenueCashReconcileLoadedDcKey = null;
            const dateInput = document.getElementById("revenue-cash-date");
            const monthInput = document.getElementById("revenue-cash-month");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            if (monthInput && !monthInput.value) monthInput.value = getTodayIsoDate().slice(0, 7);
            setRevenueCashReconcileMode(revenueCashReconcileMode || "DAILY");
        }

        function setRevenueCashReconcileMode(mode) {
            revenueCashReconcileMode = mode === "MONTHLY" ? "MONTHLY" : "DAILY";
            const dateInput = document.getElementById("revenue-cash-date");
            const monthInput = document.getElementById("revenue-cash-month");
            const dateBtn = document.getElementById("revenue-cash-date-mode-btn");
            const monthBtn = document.getElementById("revenue-cash-month-mode-btn");
            if (dateInput) dateInput.style.display = revenueCashReconcileMode === "DAILY" ? "block" : "none";
            if (monthInput) monthInput.style.display = revenueCashReconcileMode === "MONTHLY" ? "block" : "none";
            if (dateBtn) {
                dateBtn.style.background = revenueCashReconcileMode === "DAILY" ? "#c2410c" : "#ffedd5";
                dateBtn.style.color = revenueCashReconcileMode === "DAILY" ? "#ffffff" : "#c2410c";
            }
            if (monthBtn) {
                monthBtn.style.background = revenueCashReconcileMode === "MONTHLY" ? "#c2410c" : "#ffedd5";
                monthBtn.style.color = revenueCashReconcileMode === "MONTHLY" ? "#ffffff" : "#c2410c";
            }
            renderRevenueCashReconcile();
        }

        function getRevenueCashUploadedIvrsSet() {
            const set = new Set();
            // BUG FIX: yeh function pehle SIRF do purane local-only cache
            // (getRevenueUploadedPaidCache / getRevenueCategoryRawPaymentRows) se
            // data leta tha - dono sirf tabhi bharte hain jab is DEVICE par kabhi
            // Admin Upload ya Category Wise/Defaulters jaisi report chali ho.
            // renderRevenueCashReconcile() jo asli network sync karta hai
            // (syncRevenueLiveEntriesFromSheet + getRevenueUploadedPaidMasterRows),
            // uska result kahin bhi is function tak nahi pahunch raha tha - matlab
            // "sync" ho jaane ke baad bhi NGB-matching purane/khali data se hi ho
            // rahi thi, isliye "Paid by Staff vs NGB Cash List" me galat count
            // (jaise sab "Balance/Not Updated" dikhna) aata tha. Ab sabse pehle
            // wahi taaza, sahi-sync hui revenueUploadedPaidMasterRowsCache (jo
            // getRevenueUploadedPaidMasterRows abhi-abhi backend se laaya) use
            // karte hain, baaki purane local cache extra safety ke liye union
            // me jode rehte hain.
            const dcKey = normalizeLookupValue(activeDC || "");
            if (revenueUploadedPaidMasterRowsCache && revenueUploadedPaidMasterRowsCache.dcKey === dcKey) {
                (revenueUploadedPaidMasterRowsCache.rows || []).forEach((row) => {
                    const ivrs = normalizeRevenueIvrs(row.ivrs_no || row.ivrsNo || row.consumerNo);
                    if (ivrs) set.add(ivrs);
                });
            }
            const addRow = (row) => {
                const ivrs = getRevenueUploadedPaidRowIvrs(row);
                if (ivrs) set.add(ivrs);
                getRevenueUploadedPaidPaymentRows(row).forEach((paymentRow) => {
                    const paymentIvrs = getRevenueUploadedPaidRowIvrs(paymentRow) || ivrs;
                    if (paymentIvrs) set.add(paymentIvrs);
                });
            };
            Object.values(getRevenueUploadedPaidCache() || {}).forEach((row) => {
                const dcName = getRevenueUploadedPaidRowDcName(row, activeDC || "");
                if (normalizeLookupValue(dcName || "") === normalizeLookupValue(activeDC || "")) addRow(row);
            });
            getRevenueCategoryRawPaymentRows().forEach((row) => {
                const dcName = getRevenueUploadedPaidRowDcName(row, activeDC || "");
                if (normalizeLookupValue(dcName || "") === normalizeLookupValue(activeDC || "")) addRow(row);
            });
            return set;
        }

        function getRevenueCashStaffRows() {
            const rows = getRevenueLiveEntries().filter(isRevenueRowInCurrentScope);
            if (revenueCashReconcileMode === "MONTHLY") {
                const monthValue = document.getElementById("revenue-cash-month")?.value || getTodayIsoDate().slice(0, 7);
                return rows.filter((row) => getRevenueMonthKey(row.paidDate) === monthValue);
            }
            const dateValue = normalizeRevenueReportDate(document.getElementById("revenue-cash-date")?.value || getCurrentDateDDMMYYYY());
            return rows.filter((row) => normalizeRevenueReportDate(row.paidDate) === dateValue);
        }

        function buildRevenueCashReconcileRows() {
            const uploadedIvrsSet = getRevenueCashUploadedIvrsSet();
            return getRevenueCashStaffRows().map((row) => {
                const ivrs = normalizeRevenueIvrs(row.ivrsNo);
                const ngbUpdated = !!ivrs && uploadedIvrsSet.has(ivrs);
                return { ...row, ngbStatus: ngbUpdated ? "NGB Updated" : "Balance / Not Updated", ngbUpdated };
            });
        }

        function getRevenueCashFilteredRows() {
            const hqValue = document.getElementById("revenue-cash-hq")?.value || "";
            const statusValue = document.getElementById("revenue-cash-status")?.value || "ALL";
            return revenueCashReconcileRows.filter((row) => (!hqValue || normalizeLookupValue(row.hqName || "") === normalizeLookupValue(hqValue))
                && (statusValue === "ALL" || (statusValue === "NGB" ? row.ngbUpdated : !row.ngbUpdated)));
        }

        function populateRevenueCashHqOptions(rows) {
            const hqSelect = document.getElementById("revenue-cash-hq");
            if (!hqSelect) return;
            const selected = hqSelect.value || "";
            const hqNames = getRevenueUniqueValues(rows || [], "hqName");
            populateRevenueSelect(hqSelect, hqNames, `All ${revenueHqLabel()}`);
            if (selected && hqNames.some((name) => normalizeLookupValue(name) === normalizeLookupValue(selected))) hqSelect.value = selected;
        }

        function buildRevenueCashSummaryRows(rows) {
            const groups = {};
            (rows || []).forEach((row) => {
                const hqName = row.hqName || "-";
                const key = normalizeLookupValue(hqName) || "GENERAL";
                if (!groups[key]) groups[key] = { hqName, staffCount: 0, staffAmount: 0, ngbCount: 0, ngbAmount: 0, balanceCount: 0, balanceAmount: 0 };
                const amount = parseRevenuePaidAmount(row.paidAmount);
                groups[key].staffCount += 1;
                groups[key].staffAmount += amount;
                if (row.ngbUpdated) {
                    groups[key].ngbCount += 1;
                    groups[key].ngbAmount += amount;
                } else {
                    groups[key].balanceCount += 1;
                    groups[key].balanceAmount += amount;
                }
            });
            return Object.values(groups).sort((a, b) => String(a.hqName).localeCompare(String(b.hqName)));
        }

        function renderRevenueCashSummary(rows) {
            const summaryRows = buildRevenueCashSummaryRows(rows);
            if (!summaryRows.length) return `<div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.78rem; font-weight:900; text-align:center;">No staff paid data found in this filter.</div>`;
            const totals = summaryRows.reduce((acc, row) => {
                acc.staffCount += row.staffCount; acc.staffAmount += row.staffAmount; acc.ngbCount += row.ngbCount; acc.ngbAmount += row.ngbAmount; acc.balanceCount += row.balanceCount; acc.balanceAmount += row.balanceAmount;
                return acc;
            }, { staffCount: 0, staffAmount: 0, ngbCount: 0, ngbAmount: 0, balanceCount: 0, balanceAmount: 0 });
            const body = summaryRows.map((row) => `<tr><td style="border:1px solid #fdba74; padding:5px; word-break:break-word;">${escapeHtml(row.hqName)}</td><td style="border:1px solid #fdba74; padding:5px;">${row.staffCount}<br>${escapeHtml(formatProgressReportDisplayAmount(row.staffAmount))}</td><td style="border:1px solid #fdba74; padding:5px; color:#047857;">${row.ngbCount}<br>${escapeHtml(formatProgressReportDisplayAmount(row.ngbAmount))}</td><td style="border:1px solid #fdba74; padding:5px; color:#b91c1c;">${row.balanceCount}<br>${escapeHtml(formatProgressReportDisplayAmount(row.balanceAmount))}</td></tr>`).join("");
            return `<div style="background:#ffffff; border:1.5px solid #fdba74; border-radius:16px; padding:10px; overflow:hidden;"><div style="font-size:0.72rem; font-weight:950; color:#c2410c; text-align:center; margin-bottom:8px;">IVRS Matching Only | DC: ${escapeHtml(activeDC || "-")}</div><table style="width:100%; table-layout:fixed; border-collapse:collapse; font-size:0.55rem; font-weight:850; color:#1e293b; text-align:center;"><thead><tr style="background:#fed7aa; color:#7c2d12;"><th style="border:1px solid #fdba74; padding:5px;">${escapeHtml(revenueHqLabel())}</th><th style="border:1px solid #fdba74; padding:5px;">Paid by Staff (L)</th><th style="border:1px solid #fdba74; padding:5px;">NGB Update (L)</th><th style="border:1px solid #fdba74; padding:5px;">Balance (L)</th></tr></thead><tbody>${body}</tbody><tfoot><tr style="background:#fff7ed; font-weight:950;"><td style="border:1px solid #fdba74; padding:5px;">TOTAL</td><td style="border:1px solid #fdba74; padding:5px;">${totals.staffCount}<br>${escapeHtml(formatProgressReportDisplayAmount(totals.staffAmount))}</td><td style="border:1px solid #fdba74; padding:5px; color:#047857;">${totals.ngbCount}<br>${escapeHtml(formatProgressReportDisplayAmount(totals.ngbAmount))}</td><td style="border:1px solid #fdba74; padding:5px; color:#b91c1c;">${totals.balanceCount}<br>${escapeHtml(formatProgressReportDisplayAmount(totals.balanceAmount))}</td></tr></tfoot></table></div>`;
        }

        function getRevenueCashDataIncompleteWarningHtml() {
            const dcKey = normalizeLookupValue(activeDC || "");
            const incomplete = !revenueUploadedPaidMasterRowsCache
                || revenueUploadedPaidMasterRowsCache.dcKey !== dcKey
                || !revenueUploadedPaidMasterRowsCache.backendSynced;
            if (!incomplete) return "";
            return `<div style="background:#fff1f2; border:1.5px solid #fda4af; border-radius:12px; padding:10px; color:#991b1b; font-size:0.74rem; font-weight:900; text-align:center; margin-bottom:8px;">⚠️ NGB Cash List data could not be fully synced - "NGB Update"/"Balance" numbers may be wrong. Please check internet and return to this report.</div>`;
        }

        async function renderRevenueCashReconcile() {
            const tableBox = document.getElementById("revenue-cash-table");
            const statusBox = document.getElementById("revenue-cash-download-status");
            if (!tableBox) return;
            const renderToken = ++revenueCashReconcileRenderToken;
            if (statusBox) statusBox.style.display = "none";
            const isRenderValid = () => renderToken === revenueCashReconcileRenderToken && document.getElementById("revenue-cash-reconcile-view")?.classList.contains("active");
            const dcKey = normalizeLookupValue(activeDC || "");
            if (revenueCashReconcileLoadedDcKey === dcKey && revenueCashReconcileRows.length) {
                // Is DC ke liye is view-session me ek baar poora load ho chuka hai -
                // date/month/HQ/status dropdown sirf local filter hai, kabhi resync
                // nahi hoga jab tak view se bahar jaakar dobara na aayein.
                tableBox.innerHTML = getRevenueCashDataIncompleteWarningHtml() + renderRevenueCashSummary(getRevenueCashFilteredRows());
                if (statusBox) statusBox.style.display = "none";
                return;
            }
            const dataFresh = isRevenueCashReconcileDataFresh();
            if (dataFresh && revenueCashReconcileRows.length) {
                // Data pehle se fresh hai (isi report me ya Live Progress/Pending DO
                // List me pehle hi sync ho chuka hai) - date/month/HQ/status dropdown
                // change sirf local filter hai, network re-fetch skip karke turant
                // re-render ho jaata hai.
                revenueCashReconcileLoadedDcKey = dcKey;
                tableBox.innerHTML = getRevenueCashDataIncompleteWarningHtml() + renderRevenueCashSummary(getRevenueCashFilteredRows());
                if (statusBox) statusBox.style.display = "none";
                return;
            }
            if (dataFresh) {
                // Dusri report ne pehle hi network sync kar diya hai, is view ke
                // liye sirf pehli baar rows build karne hain - network call nahi.
                revenueCashReconcileRows = buildRevenueCashReconcileRows();
                populateRevenueCashHqOptions(revenueCashReconcileRows);
                revenueCashReconcileLoadedDcKey = dcKey;
                tableBox.innerHTML = getRevenueCashDataIncompleteWarningHtml() + renderRevenueCashSummary(getRevenueCashFilteredRows());
                if (statusBox) statusBox.style.display = "none";
                return;
            }
            // Ab baaki sabhi reports jaisa hi shared renderSyncingProgress use karte hain
            // (pehle iski apni alag copy-paste ki hui orange-themed progress bar thi -
            // renderRevenueCashSyncingProgress - jo hata di gayi hai).
            const progress = renderSyncingProgress(tableBox, isRenderValid, "SYNCING DATA... PLEASE WAIT");
            try {
                // SPEED FIX (2026-09-15, USER-REPORTED slowness): Cash Reconcile
                // hamesha ek `activeDC` ke liye hi hai (NGB Cash List side -
                // getRevenueUploadedPaidMasterRows - pehle se hi DC-scoped hai) -
                // sirf yeh "Paid by Staff" live entries wali call bina scope ke
                // poori Circle fetch karti thi. Daily Progress jaisa hi safe
                // `scopeDc` pattern (empty activeDC par khud purana unscoped
                // behavior par fallback ho jaata hai, koi regression nahi).
                await Promise.all([syncRevenueLiveEntriesFromSheet(3, false, activeDC || null), getRevenueUploadedPaidMasterRows()]);
                if (renderToken !== revenueCashReconcileRenderToken) { progress.stop(); return; }
                revenueCashReconcileRows = buildRevenueCashReconcileRows();
                populateRevenueCashHqOptions(revenueCashReconcileRows);
                revenueCashReconcileLoadedDcKey = dcKey;
                await progress.finish();
                if (renderToken !== revenueCashReconcileRenderToken) return;
                tableBox.innerHTML = getRevenueCashDataIncompleteWarningHtml() + renderRevenueCashSummary(getRevenueCashFilteredRows());
                if (statusBox) statusBox.style.display = "none";
            } catch (_) {
                progress.stop();
                if (statusBox) { statusBox.style.display = "block"; statusBox.innerText = "Report could not be loaded"; }
            }
        }

        function getRevenueCashExportRows() {
            return getRevenueCashFilteredRows().map((row, index) => [index + 1, row.ngbStatus || "", row.ivrsNo || "", row.consumerName || "", row.fatherName || "", row.village || "", row.hqName || "", row.tariffCategory || "", row.mobileNo || "", row.paidDate || "", formatRevenuePaidTime(row.paidTime || ""), row.paidAmount || "", row.dcName || activeDC || ""]);
        }

        function getRevenueCashReportTitle() {
            const statusValue = document.getElementById("revenue-cash-status")?.value || "ALL";
            const dcName = activeDC || "";
            if (statusValue === "BALANCE") return `"Paid by staff" Amount not updated in NGB Cash List-${dcName}`;
            if (statusValue === "NGB") return `"Paid by staff" Amount updated in NGB Cash List-${dcName}`;
            return `"Paid by staff" Amount All Paid/Balance in NGB Cash List-${dcName}`;
        }

        function setRevenueCashDownloadState(isLoading, message = "", ok = true) {
            scApplyDownloadBoxState_("revenue-cash", isLoading, message, ok);
        }

        function downloadRevenueCashReconcile(type) {
            const rows = getRevenueCashExportRows();
            if (!rows.length) return showToast("No data available for the report", false);
            setRevenueCashDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download in progress... please wait`, true);
            try {
            const headers = ["S.NO", "STATUS", "IVRS NO", "CONSUMER NAME", "FATHER NAME", revenueVillageLabelUpper(), revenueHqLabelUpper(), "CATEGORY", "MOBILE NO", "STAFF PAID DATE", "STAFF PAID TIME", "STAFF PAID AMOUNT", "DC NAME"];
                // Baaki reports jaisa hi Indian/readable period label - monthly me
                // "YYYY-MM" raw ISO ki jagah ab formatRevenueMonthYear se "Month YYYY" banta hai.
                const periodDisplay = revenueCashReconcileMode === "MONTHLY"
                    ? formatRevenueMonthYear(document.getElementById("revenue-cash-month")?.value || getTodayIsoDate().slice(0, 7))
                    : formatRevenueDateIndian(normalizeRevenueReportDate(document.getElementById("revenue-cash-date")?.value || getCurrentDateDDMMYYYY()));
                const fileSuffix = revenueCashReconcileMode === "MONTHLY"
                    ? (document.getElementById("revenue-cash-month")?.value || getTodayIsoDate().slice(0, 7))
                    : normalizeRevenueReportDate(document.getElementById("revenue-cash-date")?.value || getCurrentDateDDMMYYYY());
                const reportTitle = getRevenueCashReportTitle();
                const fileName = `${reportTitle}-${fileSuffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setRevenueCashDownloadState(false, "PDF library could not be loaded", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    scPdfHeader_(doc, { title: reportTitle, lines: [`Matching: IVRS only | ${periodDisplay}`], focus: { hq: (document.getElementById("revenue-cash-hq")?.value || "") } });
                    doc.autoTable({ startY: 26, head: [headers], body: rows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [194, 65, 12] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setRevenueCashDownloadState(false, "PDF downloaded", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[scPdfFocusTitle_(reportTitle, { hq: (document.getElementById("revenue-cash-hq")?.value || "") })], [`Matching: IVRS only | ${periodDisplay}`], [], headers, ...rows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setRevenueCashDownloadState(false, "Excel downloaded", true);
            } catch (error) {
                setRevenueCashDownloadState(false, "Download failed", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        // =====================================================================
        // HQ / VILLAGE WISE PAID-UNPAID REPORT
        // Existing "Category Wise Paid/Unpaid Summary" ke paid/unpaid classification
        // logic (createRevenueCategoryGroup + addRevenueCategoryConsumer +
        // buildRevenueCategoryUploadedPaidInfo) ko hi reuse kiya hai - bas grouping
        // dimension category ki jagah HQ -> Village hai. DC level par top rows HQ
        // hain (tap karke Village khulta hai); Division/Circle par top rows DC hain
        // (tap -> HQ -> tap -> Village), subtotal rows kabhi clickable nahi hote.
        // =====================================================================
        let revenueHqVillageMode = "DAILY";
        let revenueHqVillageRenderToken = 0;
        let revenueHqVillageTree = [];
        let revenueHqVillageDrillPath = [];
        // BUG FIX (user report): pehle DATE WISE/MONTH WISE toggle badalte hi
        // (setRevenueHqVillageMode -> renderRevenueHqVillageReport) har baar
        // "SYNCING LATEST REPORT..." dobara chal jaata tha, chahe usi view-visit
        // me thodi der pehle hi is scope (DC/Division/Circle) ka data poora sync
        // ho chuka ho. Cash Reconcile/Report Download jaisa hi simple "is scope
        // ke liye is visit me ek baar load ho chuka" flag - jab tak view se bahar
        // jaakar dobara na aayein, DATE/MONTH toggle sirf local recompute karega.
        let revenueHqVillageLoadedScopeKey = null;

        function initRevenueHqVillageReport() {
            revenueHqVillageLoadedScopeKey = null;
            const dateInput = document.getElementById("revenue-hq-village-date");
            const monthInput = document.getElementById("revenue-hq-village-month");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            if (monthInput && !monthInput.value) monthInput.value = getTodayIsoDate().slice(0, 7);
            revenueHqVillageDrillPath = [];
            setRevenueHqVillageMode(revenueHqVillageMode || "DAILY");
        }

        function setRevenueHqVillageMode(mode) {
            revenueHqVillageMode = mode === "MONTHLY" ? "MONTHLY" : "DAILY";
            const dateInput = document.getElementById("revenue-hq-village-date");
            const monthInput = document.getElementById("revenue-hq-village-month");
            const dateBtn = document.getElementById("revenue-hq-village-date-mode-btn");
            const monthBtn = document.getElementById("revenue-hq-village-month-mode-btn");
            if (dateInput) dateInput.style.display = revenueHqVillageMode === "DAILY" ? "block" : "none";
            if (monthInput) monthInput.style.display = revenueHqVillageMode === "MONTHLY" ? "block" : "none";
            if (dateBtn) {
                dateBtn.style.background = revenueHqVillageMode === "DAILY" ? "#15803d" : "#dcfce7";
                dateBtn.style.color = revenueHqVillageMode === "DAILY" ? "#ffffff" : "#15803d";
            }
            if (monthBtn) {
                monthBtn.style.background = revenueHqVillageMode === "MONTHLY" ? "#15803d" : "#dcfce7";
                monthBtn.style.color = revenueHqVillageMode === "MONTHLY" ? "#ffffff" : "#15803d";
            }
            revenueHqVillageDrillPath = [];
            renderRevenueHqVillageReport();
        }

        function buildRevenueHqVillagePaidUnpaidTree(mode, filterValue, govtFilter) {
            const paidInfoByDc = buildRevenueCategoryUploadedPaidInfo(mode, filterValue);

            const leafTotals = (name) => ({ name, paidTotal: 0, unpaidTotal: 0, paidAmountTotal: 0, unpaidAmountTotal: 0, noDuesTotal: 0, noDuesAmountTotal: 0, masterNetTotal: 0, masterCount: 0, children: null });
            const addTotals = (target, src) => {
                target.paidTotal += Number(src.paidTotal || 0);
                target.unpaidTotal += Number(src.unpaidTotal || 0);
                target.paidAmountTotal += Number(src.paidAmountTotal || 0);
                target.unpaidAmountTotal += Number(src.unpaidAmountTotal || 0);
                target.noDuesTotal += Number(src.noDuesTotal || 0);
                target.noDuesAmountTotal += Number(src.noDuesAmountTotal || 0);
                target.masterNetTotal += Number(src.masterNetTotal || 0);
                target.masterCount += Number(src.masterCount || 0);
            };

            const buildDcNode = (dcName) => {
                const normalizedDc = normalizeDcName(dcName);
                const paidInfo = paidInfoByDc[normalizedDc] || {};
                const paidCountedIvrsSet = new Set();
                const hqMap = {};
                getRevenueMasterRowsForDc(dcName).forEach((row) => {
                    if (govtFilter === "GOVT" && !row.govtFlag) return;
                    if (govtFilter === "NONGOVT" && row.govtFlag) return;
                    const hqName = String(row.hqName || "GENERAL").trim().toUpperCase() || "GENERAL";
                    const village = String(row.village || "UNKNOWN").trim().toUpperCase() || "UNKNOWN";
                    if (!hqMap[hqName]) hqMap[hqName] = {};
                    if (!hqMap[hqName][village]) hqMap[hqName][village] = createRevenueCategoryGroup(village);
                    addRevenueCategoryConsumer(hqMap[hqName][village], row, paidInfo, paidCountedIvrsSet, true); // NO DUES alag bucket (2026-09-29)
                });
                const hqNodes = Object.keys(hqMap).sort((a, b) => a.localeCompare(b)).map((hqName) => {
                    const villageMap = hqMap[hqName];
                    const villageNodes = Object.keys(villageMap).sort((a, b) => a.localeCompare(b)).map((villageName) => {
                        const g = villageMap[villageName];
                        return { name: villageName, paidTotal: g.paidTotal, unpaidTotal: g.unpaidTotal, paidAmountTotal: g.paidAmountTotal, unpaidAmountTotal: g.unpaidAmountTotal, noDuesTotal: g.noDuesTotal || 0, noDuesAmountTotal: g.noDuesAmountTotal || 0, masterNetTotal: g.masterNetTotal || 0, masterCount: g.__uniqueMasterCount || 0, children: null };
                    });
                    const hqNode = leafTotals(hqName);
                    villageNodes.forEach((v) => addTotals(hqNode, v));
                    hqNode.children = villageNodes;
                    return hqNode;
                });
                const dcNode = leafTotals(normalizedDc);
                hqNodes.forEach((h) => addTotals(dcNode, h));
                dcNode.children = hqNodes;
                return dcNode;
            };

            if (activeViewLevel === "DC") {
                const dcNode = buildDcNode(activeDC);
                return dcNode.children || [];
            }

            if (activeViewLevel === "DIVISION") {
                const rows = [];
                getDivisionSubDnGroups(activeDiv).forEach((group) => {
                    const dcNodes = group.dcs.map((dcName) => buildDcNode(dcName));
                    rows.push(...dcNodes);
                    const subTotal = leafTotals(`${group.subDn} SUB DIVISION SUB TOTAL`);
                    subTotal.type = "SUBDN_TOTAL";
                    dcNodes.forEach((d) => addTotals(subTotal, d));
                    rows.push(subTotal);
                });
                return rows;
            }

            const rows = [];
            Object.keys(divisionConfigs).forEach((divisionName) => {
                const divisionRows = [];
                getDivisionSubDnGroups(divisionName).forEach((group) => {
                    const dcNodes = group.dcs.map((dcName) => buildDcNode(dcName));
                    divisionRows.push(...dcNodes);
                    rows.push(...dcNodes);
                    const subTotal = leafTotals(`${group.subDn} SUB DIVISION SUB TOTAL`);
                    subTotal.type = "SUBDN_TOTAL";
                    dcNodes.forEach((d) => addTotals(subTotal, d));
                    rows.push(subTotal);
                });
                const divTotal = leafTotals(getDivisionTotalLabel(divisionName));
                divTotal.type = "SUB_TOTAL";
                divisionRows.forEach((d) => addTotals(divTotal, d));
                rows.push(divTotal);
            });
            return rows;
        }

        function findRevenueHqVillageNode(nodes, name) {
            return (nodes || []).find((n) => n.name === name && n.type !== "SUB_TOTAL" && n.type !== "SUBDN_TOTAL");
        }

        function getRevenueHqVillageCurrentRows() {
            let nodes = revenueHqVillageTree;
            for (const step of revenueHqVillageDrillPath) {
                const node = findRevenueHqVillageNode(nodes, step);
                if (!node || !node.children) return [];
                nodes = node.children;
            }
            return nodes;
        }

        function getRevenueHqVillageColumnLabel() {
            const depth = revenueHqVillageDrillPath.length;
            if (activeViewLevel === "DC") return depth === 0 ? revenueHqLabelUpper() : revenueVillageLabelUpper();
            if (depth === 0) return "DC NAME";
            if (depth === 1) return "HQ NAME";
            return "VILLAGE";
        }

        function pushRevenueHqVillageDrill(el) {
            const name = el?.dataset?.drillName;
            if (!name) return;
            revenueHqVillageDrillPath.push(name);
            const tableBox = document.getElementById("revenue-hq-village-table");
            if (tableBox) tableBox.innerHTML = renderRevenueHqVillageTable();
        }

        function popRevenueHqVillageDrill() {
            revenueHqVillageDrillPath.pop();
            const tableBox = document.getElementById("revenue-hq-village-table");
            if (tableBox) tableBox.innerHTML = renderRevenueHqVillageTable();
        }

        function renderRevenueHqVillageTable() {
            const rows = getRevenueHqVillageCurrentRows();
            const colLabel = getRevenueHqVillageColumnLabel();
            const depth = revenueHqVillageDrillPath.length;
            const canDrillDeeper = activeViewLevel === "DC" ? depth < 1 : depth < 2;

            let breadcrumbHtml = "";
            if (depth > 0) {
                const crumbLabel = revenueHqVillageDrillPath.join(" › ");
                breadcrumbHtml = `<div onclick="popRevenueHqVillageDrill()" style="display:flex; align-items:center; gap:6px; padding:9px 10px; margin-bottom:6px; background:#f0fdf4; border:1.2px solid #bbf7d0; border-radius:10px; font-size:0.68rem; font-weight:900; color:#15803d; cursor:pointer;">⬅ ${escapeHtml(crumbLabel)} - Back</div>`;
            }

            // Counts-only (Total -> Paid -> Unpaid): amount wise detail summary cards +
            // category table me pehle se hai, yahan sirf compact HQ/Village drill list hai.
            const g5 = "grid-template-columns: 1.3fr 0.8fr 0.75fr 0.8fr 0.75fr;";
            let html = `<div class="summary-wrapper">${breadcrumbHtml}<div class="summary-table-header" style="${g5}"><div>${colLabel}</div><div>TOTAL CONSUMER</div><div>PAID</div><div>UNPAID</div><div>NO DUES</div></div>`;

            if (!rows || !rows.length) {
                html += `${scEmptyState_(`No data found in this scope.`)}`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    const clickable = canDrillDeeper && !row.type && row.children && row.children.length;
                    const attrs = clickable ? ` data-drill-name="${escapeHtml(row.name)}" onclick="pushRevenueHqVillageDrill(this)" style="cursor:pointer;"` : "";
                    const nameCell = clickable ? `${escapeHtml(row.name)} ›` : escapeHtml(row.name);
                    const totalCount = scRevTot_(row);
                    html += `<div class="summary-table-row${rowClass}" style="${g5}"${attrs}><div>${nameCell}</div><div class="font-black">${totalCount}</div><div class="text-emerald-700 font-black">${row.paidTotal}</div><div class="text-rose-700 font-black">${row.unpaidTotal}</div><div style="color:#64748b; font-weight:900;">${Number(row.noDuesTotal || 0)}</div></div>`;
                });
            }

            const totals = (rows || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").reduce((acc, row) => {
                acc.paidTotal += Number(row.paidTotal || 0);
                acc.unpaidTotal += Number(row.unpaidTotal || 0);
                acc.noDuesTotal += Number(row.noDuesTotal || 0);
                acc.masterCount += scRevTot_(row);
                return acc;
            }, { paidTotal: 0, unpaidTotal: 0, noDuesTotal: 0, masterCount: 0 });
            const totalCount = scRevTot_(totals);

            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL (${colLabel} SCOPE)</div><div class="mt-2 grid grid-cols-4 gap-2 text-center text-[11px] font-black"><div class="rounded-xl bg-slate-100 border border-slate-200 p-2">Total<br>${totalCount}</div><div class="rounded-xl bg-emerald-50 border border-emerald-200 p-2">Paid<br>${totals.paidTotal}</div><div class="rounded-xl bg-rose-50 border border-rose-200 p-2">Unpaid<br>${totals.unpaidTotal}</div><div class="rounded-xl bg-slate-50 border border-slate-200 p-2">No Dues<br>${totals.noDuesTotal}</div></div></div>`;
            return html;
        }

        // govtFilter optional param (2026-08-13 addition) - defaults to "" (no
        // filter, old behaviour unchanged for existing callers like Category Wise
        // / HQ-Village Report). Progress Report's "Target vs Achievement" dropdown
        // passes this through when its own Govt/Non-Govt filter is set.
        function buildRevenueHqVillageSummaryData(mode, filterValue, govtFilter = "") {
            const tree = buildRevenueHqVillagePaidUnpaidTree(mode, filterValue, govtFilter);
            const totals = (tree || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").reduce((acc, row) => {
                acc.paidTotal += Number(row.paidTotal || 0);
                acc.unpaidTotal += Number(row.unpaidTotal || 0);
                acc.paidAmountTotal += Number(row.paidAmountTotal || 0);
                acc.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0);
                acc.noDuesTotal += Number(row.noDuesTotal || 0);
                acc.noDuesAmountTotal += Number(row.noDuesAmountTotal || 0);
                acc.masterNetTotal += Number(row.masterNetTotal || 0);
                acc.masterCount += Number(row.masterCount || 0);
                return acc;
            }, { paidTotal: 0, unpaidTotal: 0, paidAmountTotal: 0, unpaidAmountTotal: 0, noDuesTotal: 0, noDuesAmountTotal: 0, masterNetTotal: 0, masterCount: 0 });
            totals.totalConsumer = scRevTot_(totals);

            // Category-wise bifurcation existing "Category Wise Paid/Unpaid Summary" ke
            // proven functions se hi liya hai - alag se koi nayi classification nahi likhi.
            const categoryRows = buildRevenueCategorySummaryRows(mode, filterValue, govtFilter);
            const categoryGrand = getRevenueCategoryGrandTotals(categoryRows);

            return { tree, totals, categoryGrand, categoryRows };
        }

        // Paid Count Summary needs a stricter classification than the normal
        // paid/unpaid report: only a consumer whose current bill is fully covered
        // is PAID. Any remaining balance (including part payment) is PENDING.
        // This builder is local-only: it uses the already-loaded master/cash-list
        // cache, makes no extra backend request, and returns the same tree shape
        // consumed by the existing screen and PDF/Excel download code.
        function buildProgressPaidCountSummaryData(mode, filterValue, govtFilter = "", paymentFilter = "") {
            const paidInfoByDc = buildRevenueCategoryUploadedPaidInfo(mode, filterValue);
            const leaf = (name) => ({ name, paidTotal: 0, unpaidTotal: 0, paidAmountTotal: 0, unpaidAmountTotal: 0, noDuesTotal: 0, noDuesAmountTotal: 0, masterCount: 0, children: null });
            const add = (target, row) => {
                target.masterCount += Number(row.masterCount || 0);
                target.paidTotal += Number(row.paidTotal || 0);
                target.unpaidTotal += Number(row.unpaidTotal || 0);
                target.paidAmountTotal += Number(row.paidAmountTotal || 0);
                target.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0);
                target.noDuesTotal += Number(row.noDuesTotal || 0);
                target.noDuesAmountTotal += Number(row.noDuesAmountTotal || 0);
            };
            const buildDcNode = (dcName) => {
                const dc = normalizeDcName(dcName);
                const paidInfo = paidInfoByDc[dc] || {};
                const seenIvrs = new Set();
                const hqMap = {};
                getRevenueMasterRowsForDc(dcName).forEach((row) => {
                    if (govtFilter === "GOVT" && !row.govtFlag) return;
                    if (govtFilter === "NONGOVT" && row.govtFlag) return;
                    const ivrs = normalizeRevenueIvrs(row.ivrsNo);
                    if (!ivrs || seenIvrs.has(ivrs)) return;
                    seenIvrs.add(ivrs);
                    // USER RULE (2026-09-29): PAID = cash list me payment (part paid bhi), PENDING = bina
                    // payment NET BILL > 0, NO DUES = bina payment NET BILL 0/minus. (Pehle "Full Payment Only".)
                    const pInf_ = paidInfo[ivrs];
                    const paidAmount = getRevenueMasterConsumerPaidAmount(pInf_);
                    const signedNet = getRevenuePendingNetBillAmount(row);
                    const dueAmount = parseRevenuePendingAmount(row.netBill || 0);
                    const isFullPaid = paidAmount > 0;
                    const isAgOld = !isFullPaid && !!(pInf_ && pInf_.statusPaid); // AG pichhle mahine (29/09)
                    const isNoDues = !isFullPaid && !isAgOld && !(signedNet > 0);
                    if (paymentFilter === "PAID" && !isFullPaid) return;
                    if (paymentFilter === "PENDING" && (isFullPaid || isNoDues || isAgOld)) return;
                    const hq = String(row.hqName || "GENERAL").trim().toUpperCase() || "GENERAL";
                    const village = String(row.village || "UNKNOWN").trim().toUpperCase() || "UNKNOWN";
                    if (!hqMap[hq]) hqMap[hq] = {};
                    if (!hqMap[hq][village]) hqMap[hq][village] = leaf(village);
                    const target = hqMap[hq][village];
                    target.masterCount = Number(target.masterCount || 0) + 1;
                    if (isFullPaid) { target.paidTotal += Number((pInf_ && pInf_.receipts) || 1); target.paidAmountTotal += paidAmount; }
                    else if (isAgOld) { /* AG pichhle mahine: kahin nahi */ }
                    else if (isNoDues) { target.noDuesTotal = Number(target.noDuesTotal || 0) + 1; target.noDuesAmountTotal = Number(target.noDuesAmountTotal || 0) + Math.min(0, signedNet); }
                    else { target.unpaidTotal += 1; target.unpaidAmountTotal += dueAmount; }
                });
                const hqNodes = Object.keys(hqMap).sort((a, b) => a.localeCompare(b)).map((hq) => {
                    const hqNode = leaf(hq);
                    hqNode.children = Object.keys(hqMap[hq]).sort((a, b) => a.localeCompare(b)).map((village) => hqMap[hq][village]);
                    hqNode.children.forEach((child) => add(hqNode, child));
                    return hqNode;
                });
                const dcNode = leaf(dc);
                dcNode.children = hqNodes;
                hqNodes.forEach((child) => add(dcNode, child));
                return dcNode;
            };
            const dcs = activeViewLevel === "DC" ? [activeDC] : (activeViewLevel === "DIVISION" ? getDivisionDcNames(activeDiv) : getRevenueCategoryTargetDcs());
            const dcNodes = dcs.map(buildDcNode).filter((node) => node.children && node.children.length);
            const tree = activeViewLevel === "DC" ? ((dcNodes[0] && dcNodes[0].children) || []) : dcNodes;
            const totals = tree.reduce((acc, row) => { add(acc, row); return acc; }, leaf("TOTAL"));
            totals.totalConsumer = scRevTot_(totals);
            return { tree, totals };
        }

        // NO DUES (2026-09-27): cards me Unpaid = sirf bakayadar (Category report jaisa) + alag No Dues -
        // sirf tab jab dono data (tree + category) ek hi consumer set ke hon (govt filter wagairah na ho).
        function scNoDuesCardInfo_(data) {
            const t = data?.totals || {};
            const cg = data?.categoryGrand;
            const nd = Number(cg?.noDuesTotal || 0);
            const ok = !!cg && nd > 0 && (Number(cg.paidTotal || 0) + Number(cg.unpaidTotal || 0) + nd) === Number(t.totalConsumer || 0);
            return { ok, nd, unpaid: ok ? Number(t.unpaidTotal || 0) - nd : Number(t.unpaidTotal || 0) };
        }
        // MASTER BAKAYA (plus-minus): sabhi consumers ke master NET BILL ka jod (29/09)
        function scRevMasterNetHtml_(t) {
            const pend = Number(t?.unpaidAmountTotal || 0), nd = Number(t?.noDuesAmountTotal || 0), paidAmt = Number(t?.paidAmountTotal || 0);
            return `<div style="max-width:380px; margin:8px auto 0; padding:7px 9px; background:#f8fafc; border:1px solid #e2e8f0; border-radius:10px; text-align:center; font-size:0.62rem; font-weight:800; color:#334155;">Master Arrears (plus-minus): <span style="font-weight:950; color:#0f172a;">₹ ${scLakhS_(t?.masterNetTotal || 0)} L</span><br><span style="color:#166534;">Paid (cash list) ₹ ${scLakhS_(paidAmt)} L</span> · <span style="color:#9f1239;">Pending (&gt;0) ₹ ${scLakhS_(pend)} L</span> · <span style="color:#64748b;">No Dues ₹ ${scLakhS_(nd)} L</span></div>`;
        }
        function scLakhS_(v) { const n = Number(v) || 0; return n < 0 ? `-${formatRevenueLakhValue(-n)}` : formatRevenueLakhValue(n); } // minus sahit lakh
        function scNoDuesCardHtml_(nd, big) {
            return `<div style="background:#f8fafc; border:1px dashed #cbd5e1; border-radius:${big ? 14 : 12}px; padding:${big ? "10px 6px" : "8px 4px"}; text-align:center;"><div style="font-size:${big ? 0.56 : 0.54}rem; font-weight:850; color:#64748b; text-transform:uppercase;">No Dues</div><div style="font-size:${big ? 1.05 : 0.95}rem; font-weight:950; color:#475569; margin-top:${big ? 3 : 2}px;">${nd}</div></div>`;
        }

        function renderRevenueHqVillageSummaryCardsHtml(data) {
            const t = data.totals;
            const catRows = revenueCategoryList.map((cat) => {
                const c = data.categoryGrand.categories[cat] || { paid: 0, unpaid: 0 };
                const total = c.master != null ? Number(c.master || 0) : (Number(c.paid || 0) + Number(c.unpaid || 0) + Number(c.noDues || 0));
                if (!total) return "";
                return `<div class="summary-table-row" style="grid-template-columns: 1.2fr 0.9fr 0.8fr 0.8fr 0.8fr;"><div>${escapeHtml(getRevenueCategoryDisplayLabel(cat))}</div><div class="font-black">${total}</div><div class="text-emerald-700 font-black">${c.paid || 0}</div><div class="text-rose-700 font-black">${c.unpaid || 0}</div><div style="color:#64748b; font-weight:900;">${c.noDues || 0}</div></div>`;
            }).join("");
            // HQ/Village report: neeche ka drill-down tree pehle jaisa (Unpaid me No Dues shamil), isliye
            // cards bhi pehle jaise - sirf Category table me alag NO DUES column.
            const ndInfo = { ok: true, nd: Number(t.noDuesTotal || 0), unpaid: Number(t.unpaidTotal || 0) }; // 29/09: alag NO DUES card
            return `
                <div style="display:grid; grid-template-columns: ${ndInfo.ok ? "1fr 1fr 1fr 1fr" : "1fr 1fr 1fr"}; gap:8px; width:100%; max-width:360px; margin:12px auto 0;">
                    <div style="background:#f1f5f9; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#64748b; text-transform:uppercase;">Total Consumer</div><div style="font-size:1.05rem; font-weight:950; color:#0f172a; margin-top:3px;">${t.totalConsumer}</div></div>
                    <div style="background:#ecfdf5; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#166534; text-transform:uppercase;">Paid</div><div style="font-size:1.05rem; font-weight:950; color:#166534; margin-top:3px;">${t.paidTotal}</div></div>
                    <div style="background:#fff1f2; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#9f1239; text-transform:uppercase;">Unpaid</div><div style="font-size:1.05rem; font-weight:950; color:#9f1239; margin-top:3px;">${ndInfo.unpaid}</div></div>
                    ${ndInfo.ok ? scNoDuesCardHtml_(ndInfo.nd, true) : ""}
                </div>
                ${scRevMasterNetHtml_(t)}
                <div style="font-size:0.6rem; font-weight:950; color:#166534; text-align:center; margin:12px auto 0; max-width:360px; text-transform:uppercase;">Category Wise</div>
                <div class="summary-wrapper" style="max-width:360px; margin:6px auto 0;">
                    <div class="summary-table-header" style="grid-template-columns: 1.2fr 0.9fr 0.8fr 0.8fr 0.8fr;"><div>CATEGORY</div><div>TOTAL CONSUMER</div><div>PAID</div><div>UNPAID</div><div>NO DUES</div></div>
                    ${catRows || `${scEmptyState_(`Category data not found.`)}`}
                </div>
                <div style="font-size:0.6rem; font-weight:950; color:#166534; text-align:center; margin:14px auto 0; max-width:360px; text-transform:uppercase;">${activeViewLevel === "DC" ? "HQ Wise" : "DC Wise"} (tap to drill down further)</div>
            `;
        }

        async function renderRevenueHqVillageReport() {
            const tableBox = document.getElementById("revenue-hq-village-table");
            const summaryBox = document.getElementById("revenue-hq-village-summary");
            const statusBox = document.getElementById("revenue-hq-village-download-status");
            const listSection = document.getElementById("revenue-hq-village-list-section");
            if (!tableBox) return;
            const renderToken = ++revenueHqVillageRenderToken;
            if (statusBox) statusBox.style.display = "none";
            if (listSection) listSection.style.display = "none";
            // Purana DC/Division ka summary + consumer list turant hata do - warna jab tak
            // naye DC ka data load ho raha hai tab tak purani screen hi dikhti rehti hai aur
            // aisa lagta hai ki "reset" nahi hua (jaise koi purani DC ka hi report dikh raha ho).
            if (summaryBox) summaryBox.innerHTML = "";
            revenueHqVillageTree = [];
            revenueHqVillageDrillPath = [];
            revenueHqVillageConsumerRows = [];
            // Race-condition safety: activeViewLevel kabhi-kabhi stale ho sakta hai (jaise DC
            // dashboard se seedhe is report par aane par), isliye activeDC/activeDiv se turant
            // dobara confirm kar lo - warna DC ka report bhi Division/Circle ki tarah sabhi
            // DC ka data dikhane lagta hai.
            if (activeDC) activeViewLevel = "DC";
            else if (activeDiv) activeViewLevel = "DIVISION";
            else activeViewLevel = "CIRCLE";
            const isRenderValid = () => renderToken === revenueHqVillageRenderToken && document.getElementById("revenue-hq-village-view")?.classList.contains("active");
            const scopeKey = activeDC || activeDiv || "CIRCLE";
            const alreadyLoaded = revenueHqVillageLoadedScopeKey === scopeKey;
            const progress = alreadyLoaded ? null : renderSyncingProgress(tableBox, isRenderValid, "SYNCING DATA... PLEASE WAIT");
            try {
                const mode = revenueHqVillageMode === "MONTHLY" ? "MONTHLY" : "DAILY";
                const filterValue = mode === "MONTHLY"
                    ? (document.getElementById("revenue-hq-village-month")?.value || getTodayIsoDate().slice(0, 7))
                    : (document.getElementById("revenue-hq-village-date")?.value || getTodayIsoDate());
                let reconciliation;
                if (!alreadyLoaded) {
                    reconciliation = await prepareRevenueCategoryReportData_(
                        getRevenueCategoryTargetDcs(), mode, filterValue
                    );
                    if (!isRenderValid()) { progress.stop(); return; }
                    revenueHqVillageLoadedScopeKey = scopeKey;
                } else {
                    reconciliation = await ensureRevenueCategoryReconciliationLoaded(mode, filterValue);
                }
                if (!isRenderValid()) { if (progress) progress.stop(); return; }
                const summaryData = buildRevenueHqVillageSummaryData(mode, filterValue);
                revenueHqVillageTree = summaryData.tree;
                revenueHqVillageDrillPath = [];
                revenueHqVillageConsumerRows = buildRevenueHqVillageConsumerRows(mode, filterValue);
                if (progress) await progress.finish();
                if (!isRenderValid()) return;
                if (summaryBox) summaryBox.innerHTML = renderRevenueHqVillageSummaryCardsHtml(summaryData);
                tableBox.innerHTML = renderRevenueHqVillageTable();
                initRevenueHqVillageListDropdowns();
                if (listSection) listSection.style.display = "block";
                showRevenueCategoryStaleLegacyWarning_(statusBox, reconciliation && reconciliation.supported === false);
            } catch (error) {
                if (progress) progress.stop();
                if (statusBox) {
                    statusBox.style.display = "block";
                    statusBox.style.background = "#fff1f2";
                    statusBox.style.borderColor = "#fda4af";
                    statusBox.style.color = "#991b1b";
                    // ISOLATED FIX (2026-09-17, correction #4): failed_dcs wala naam-
                    // wala error ab yahan bhi dikhta hai (pehle generic "Report load
                    // nahi ho payi" hi hamesha dikhta tha).
                    statusBox.innerText = error?.message || "Report could not be loaded";
                }
            }
        }

        function flattenRevenueHqVillageRows() {
            const output = [];
            const walk = (nodes, path) => {
                (nodes || []).forEach((node) => {
                    if (node.type === "SUB_TOTAL" || node.type === "SUBDN_TOTAL") return;
                    const currentPath = [...path, node.name];
                    if (node.children && node.children.length) {
                        walk(node.children, currentPath);
                    } else {
                        output.push({ path: currentPath, paidTotal: node.paidTotal, unpaidTotal: node.unpaidTotal, paidAmountTotal: node.paidAmountTotal, unpaidAmountTotal: node.unpaidAmountTotal, noDuesTotal: node.noDuesTotal || 0, noDuesAmountTotal: node.noDuesAmountTotal || 0, masterNetTotal: node.masterNetTotal || 0, masterCount: node.masterCount || 0 });
                    }
                });
            };
            walk(revenueHqVillageTree, []);
            return output;
        }

        function getRevenueHqVillageReportTitle() {
            const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
            return `HQ Village Wise Paid-Unpaid Summary - ${scope}`;
        }

        // Date/Month ko hamesha DD/MM/YYYY (Indian) format me display karne ke liye - filename
        // me dash hi rakhte hain (filesystem-safe), sirf header/period display me slash.
        function formatRevenueDateIndian(value) {
            const raw = String(value || "").trim();
            const dashMatch = raw.match(/^(\d{2})-(\d{2})-(\d{4})$/);
            if (dashMatch) return `${dashMatch[1]}/${dashMatch[2]}/${dashMatch[3]}`;
            return raw.replace(/-/g, "/");
        }

        function getRevenueHqVillagePeriodDisplay() {
            if (revenueHqVillageMode === "MONTHLY") {
                return formatRevenueMonthYear(document.getElementById("revenue-hq-village-month")?.value || getTodayIsoDate().slice(0, 7));
            }
            return formatRevenueDateIndian(normalizeRevenueReportDate(document.getElementById("revenue-hq-village-date")?.value || getCurrentDateDDMMYYYY()));
        }

        function setRevenueHqVillageDownloadState(isLoading, message = "", ok = true) {
            scApplyDownloadBoxState_("revenue-hq-village", isLoading, message, ok);
        }

        function downloadRevenueHqVillageReport(type) {
            const flatRows = flattenRevenueHqVillageRows();
            if (!flatRows.length) return showToast("No data available for the report", false);
            setRevenueHqVillageDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download in progress... please wait`, true);
            try {
                const headers = activeViewLevel === "DC"
                    ? [revenueHqLabelUpper(), revenueVillageLabelUpper(), "TOTAL CONSUMER", "PAID", "PAID AMT", "UNPAID", "UNPAID AMT", "NO DUES", "NO DUES AMT", "MASTER ARREARS (+/-)"]
                    : ["DC NAME", "HQ NAME", "VILLAGE", "TOTAL CONSUMER", "PAID", "PAID AMT", "UNPAID", "UNPAID AMT", "NO DUES", "NO DUES AMT", "MASTER ARREARS (+/-)"];
                const scAmt_ = (v) => { const n = Number(v) || 0; return n < 0 ? `-${formatProgressReportAmount(-n)}` : formatProgressReportAmount(n); };
                const rows = flatRows.map((r) => [...r.path, scRevTot_(r), r.paidTotal, formatProgressReportAmount(r.paidAmountTotal), r.unpaidTotal, formatProgressReportAmount(r.unpaidAmountTotal), r.noDuesTotal || 0, scAmt_(r.noDuesAmountTotal), scAmt_(r.masterNetTotal)]);
                const grand = flatRows.reduce((acc, r) => {
                    acc.total += scRevTot_(r);
                    acc.paid += Number(r.paidTotal || 0);
                    acc.paidAmount += Number(r.paidAmountTotal || 0);
                    acc.unpaid += Number(r.unpaidTotal || 0);
                    acc.unpaidAmount += Number(r.unpaidAmountTotal || 0);
                    acc.noDues += Number(r.noDuesTotal || 0);
                    acc.noDuesAmount += Number(r.noDuesAmountTotal || 0);
                    acc.masterNet += Number(r.masterNetTotal || 0);
                    return acc;
                }, { total: 0, paid: 0, paidAmount: 0, unpaid: 0, unpaidAmount: 0, noDues: 0, noDuesAmount: 0, masterNet: 0 });
                const grandPath = activeViewLevel === "DC" ? ["GRAND TOTAL", ""] : ["GRAND TOTAL", "", ""];
                rows.push([...grandPath, grand.total, grand.paid, formatProgressReportAmount(grand.paidAmount), grand.unpaid, formatProgressReportAmount(grand.unpaidAmount), grand.noDues, scAmt_(grand.noDuesAmount), scAmt_(grand.masterNet)]);
                const reportTitle = getRevenueHqVillageReportTitle();
                const scopeLine = `Scope: ${activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? `Division - ${activeDiv}` : "Circle - SEONI CIRCLE")}`;
                const periodLine = `Period: ${getRevenueHqVillagePeriodDisplay()}`;
                const suffix = revenueHqVillageMode === "MONTHLY"
                    ? (document.getElementById("revenue-hq-village-month")?.value || getTodayIsoDate().slice(0, 7))
                    : normalizeRevenueReportDate(document.getElementById("revenue-hq-village-date")?.value || getCurrentDateDDMMYYYY());
                const fileName = `${reportTitle}-${suffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setRevenueHqVillageDownloadState(false, "PDF library could not be loaded", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    scPdfHeader_(doc, { title: reportTitle, lines: [scopeLine, periodLine] });
                    doc.autoTable({ startY: 34, head: [headers], body: rows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [21, 128, 61] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setRevenueHqVillageDownloadState(false, "PDF downloaded", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[reportTitle], [scopeLine], [periodLine], [], headers, ...rows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setRevenueHqVillageDownloadState(false, "Excel downloaded", true);
            } catch (error) {
                setRevenueHqVillageDownloadState(false, "Download failed", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        // =====================================================================
        // TARGET VS ACHIEVEMENT % (Target = Net Bill, Achievement = Paid via Cash
        // List). Existing buildRevenueHqVillagePaidUnpaidTree() ka hi paidAmountTotal/
        // unpaidAmountTotal reuse karte hain - Target = paidAmountTotal + unpaidAmountTotal,
        // Achievement = paidAmountTotal. Sirf summary chahiye, koi consumer list nahi.
        // =====================================================================
        let revenueTargetMode = "DAILY";
        let revenueTargetTree = [];
        let revenueTargetDrillPath = [];
        let revenueTargetRenderToken = 0;
        // View-by: DC scope me natural top level "HQ" hai, Division/Circle scope me "DC".
        // Dropdown se seedha "HQ WISE" ya "VILLAGE WISE" flat/sorted comparison bhi mil jata
        // hai - tap-drill kiye bina - taaki DC ke andar sabhi HQ (ya sabhi Village) ek sath
        // achievement % ke hisab se compare ho sake (jaise kaunsi HQ ne accha kaam kiya).
        let revenueTargetViewBy = "HQ";

        function getRevenueTargetNaturalLevel() {
            return activeViewLevel === "DC" ? "HQ" : "DC";
        }

        function refreshRevenueTargetViewByOptions() {
            const select = document.getElementById("revenue-target-viewby");
            if (!select) return;
            const isDc = activeViewLevel === "DC";
            select.innerHTML = isDc
                ? `<option value="HQ">HQ WISE</option><option value="VILLAGE">VILLAGE WISE</option>`
                : `<option value="DC">DC WISE</option><option value="HQ">HQ WISE</option><option value="VILLAGE">VILLAGE WISE</option>`;
            const validValues = isDc ? ["HQ", "VILLAGE"] : ["DC", "HQ", "VILLAGE"];
            if (!validValues.includes(revenueTargetViewBy)) revenueTargetViewBy = getRevenueTargetNaturalLevel();
            select.value = revenueTargetViewBy;
        }

        function setRevenueTargetViewBy(value) {
            revenueTargetViewBy = ["DC", "HQ", "VILLAGE"].includes(value) ? value : getRevenueTargetNaturalLevel();
            revenueTargetDrillPath = [];
            const tableBox = document.getElementById("revenue-target-table");
            if (tableBox) tableBox.innerHTML = renderRevenueTargetTable();
        }

        // Same "ek baar is scope ke liye is visit me load ho jaaye to DATE/MONTH
        // toggle sirf local recompute kare" fix jo HQ Village report me kiya -
        // Target Achievement bhi wahi ensureRevenueCategoryMasterDataLoaded/
        // warmRevenueCategoryUploadedPaidCache use karta hai, isliye same pattern.
        let revenueTargetLoadedScopeKey = null;

        function initRevenueTargetAchievement() {
            revenueTargetLoadedScopeKey = null;
            const dateInput = document.getElementById("revenue-target-date");
            const monthInput = document.getElementById("revenue-target-month");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            if (monthInput && !monthInput.value) monthInput.value = getTodayIsoDate().slice(0, 7);
            revenueTargetDrillPath = [];
            setRevenueTargetMode(revenueTargetMode || "DAILY");
        }

        function setRevenueTargetMode(mode) {
            revenueTargetMode = mode === "MONTHLY" ? "MONTHLY" : "DAILY";
            const dateInput = document.getElementById("revenue-target-date");
            const monthInput = document.getElementById("revenue-target-month");
            const dateBtn = document.getElementById("revenue-target-date-mode-btn");
            const monthBtn = document.getElementById("revenue-target-month-mode-btn");
            if (dateInput) dateInput.style.display = revenueTargetMode === "DAILY" ? "block" : "none";
            if (monthInput) monthInput.style.display = revenueTargetMode === "MONTHLY" ? "block" : "none";
            if (dateBtn) {
                dateBtn.style.background = revenueTargetMode === "DAILY" ? "#1d4ed8" : "#dbeafe";
                dateBtn.style.color = revenueTargetMode === "DAILY" ? "#ffffff" : "#1d4ed8";
            }
            if (monthBtn) {
                monthBtn.style.background = revenueTargetMode === "MONTHLY" ? "#1d4ed8" : "#dbeafe";
                monthBtn.style.color = revenueTargetMode === "MONTHLY" ? "#ffffff" : "#1d4ed8";
            }
            revenueTargetDrillPath = [];
            renderRevenueTargetAchievement();
        }

        function getRevenueAchievementPct(paidAmount, target) {
            if (!target) return 0;
            return Math.round((paidAmount / target) * 1000) / 10;
        }

        function findRevenueTargetNode(nodes, name) {
            return (nodes || []).find((n) => n.name === name && n.type !== "SUB_TOTAL" && n.type !== "SUBDN_TOTAL");
        }

        function getRevenueTargetCurrentRows() {
            let nodes = revenueTargetTree;
            for (const step of revenueTargetDrillPath) {
                const node = findRevenueTargetNode(nodes, step);
                if (!node || !node.children) return [];
                nodes = node.children;
            }
            return nodes;
        }

        function getRevenueTargetColumnLabel() {
            const depth = revenueTargetDrillPath.length;
            if (activeViewLevel === "DC") return depth === 0 ? revenueHqLabelUpper() : revenueVillageLabelUpper();
            if (depth === 0) return "DC NAME";
            if (depth === 1) return "HQ NAME";
            return "VILLAGE";
        }

        function pushRevenueTargetDrill(el) {
            const name = el?.dataset?.drillName;
            if (!name) return;
            revenueTargetDrillPath.push(name);
            const tableBox = document.getElementById("revenue-target-table");
            if (tableBox) tableBox.innerHTML = renderRevenueTargetTable();
        }

        function popRevenueTargetDrill() {
            revenueTargetDrillPath.pop();
            const tableBox = document.getElementById("revenue-target-table");
            if (tableBox) tableBox.innerHTML = renderRevenueTargetTable();
        }

        // DC scope me root tree hi HQ nodes hain (children = village leaves).
        // Division/Circle scope me root tree DC nodes hain (SUB_TOTAL/SUBDN_TOTAL rows
        // ke saath mixed) jinke children HQ nodes, unke children village leaves.
        // Yeh function jo bhi "level" chuna gaya hai (HQ ya VILLAGE) uska ek FLAT,
        // achievement % ke hisab se sorted list bana deta hai - taaki DC ke andar sabhi
        // HQ (ya sabhi Village) ek sath compare ho sakein, tap-drill kiye bina.
        function buildRevenueTargetFlatRows(level) {
            const rows = [];
            if (activeViewLevel === "DC") {
                (revenueTargetTree || []).forEach((hq) => {
                    if (hq.type) return;
                    if (level === "HQ") {
                        rows.push({ name: hq.name, paidAmountTotal: hq.paidAmountTotal, unpaidAmountTotal: hq.unpaidAmountTotal, noDuesAmountTotal: hq.noDuesAmountTotal || 0 });
                    } else {
                        (hq.children || []).forEach((v) => {
                            rows.push({ name: `${v.name} (${hq.name})`, paidAmountTotal: v.paidAmountTotal, unpaidAmountTotal: v.unpaidAmountTotal, noDuesAmountTotal: v.noDuesAmountTotal || 0 });
                        });
                    }
                });
            } else if (level === "DC") {
                (revenueTargetTree || []).forEach((dc) => {
                    if (dc.type) return;
                    rows.push({ name: dc.name, paidAmountTotal: dc.paidAmountTotal, unpaidAmountTotal: dc.unpaidAmountTotal, noDuesAmountTotal: dc.noDuesAmountTotal || 0 });
                });
            } else {
                (revenueTargetTree || []).forEach((dc) => {
                    if (dc.type) return;
                    if (level === "HQ") {
                        (dc.children || []).forEach((hq) => {
                            rows.push({ name: `${hq.name} (${dc.name})`, paidAmountTotal: hq.paidAmountTotal, unpaidAmountTotal: hq.unpaidAmountTotal, noDuesAmountTotal: hq.noDuesAmountTotal || 0 });
                        });
                    } else {
                        (dc.children || []).forEach((hq) => {
                            (hq.children || []).forEach((v) => {
                                rows.push({ name: `${v.name} (${hq.name}/${dc.name})`, paidAmountTotal: v.paidAmountTotal, unpaidAmountTotal: v.unpaidAmountTotal, noDuesAmountTotal: v.noDuesAmountTotal || 0 });
                            });
                        });
                    }
                });
            }
            rows.forEach((row) => {
                row.target = Number(row.paidAmountTotal || 0) + Number(row.unpaidAmountTotal || 0) + Number(row.noDuesAmountTotal || 0);
                row.pct = getRevenueAchievementPct(row.paidAmountTotal, row.target);
            });
            rows.sort((a, b) => b.pct - a.pct);
            return rows;
        }

        function renderRevenueTargetFlatTable(level) {
            const rows = buildRevenueTargetFlatRows(level);
            const colLabel = level === "HQ" ? (activeViewLevel === "DC" ? revenueHqLabelUpper() : "HQ NAME") : (activeViewLevel === "DC" ? revenueVillageLabelUpper() : "VILLAGE");
            const colLabelFriendly = level === "HQ" ? (activeViewLevel === "DC" ? revenueHqLabel() : "HQ") : (activeViewLevel === "DC" ? revenueVillageLabel() : "Village");
            // USER REQUEST (2026-09-23): screen + download dono me amount ab poore Rs
            // ki jagah LAKH me (jaise 50000 -> "0.50") - DC/Division/Circle teeno scope,
            // isi "Target vs Achievement %" (header 3-dot menu wale) screen ke saare
            // views (flat/sorted table, drill-down tree, summary cards, download) me.
            let html = `<div class="summary-wrapper"><div style="padding:9px 10px; margin-bottom:6px; background:#eff6ff; border:1.2px solid #93c5fd; border-radius:10px; font-size:0.64rem; font-weight:900; color:#1d4ed8; text-align:center;">All ${colLabelFriendly} - sorted by Achievement % (best to worst)</div><div class="summary-table-header" style="grid-template-columns: 1.5fr 0.9fr 0.9fr 0.6fr;"><div>${colLabel}</div><div>TARGET (LAKH)</div><div>ACHIEVED (LAKH)</div><div>%</div></div>`;
            if (!rows.length) {
                html += `${scEmptyState_(`No data found in this scope.`)}`;
            } else {
                rows.forEach((row, index) => {
                    const pctColor = row.pct >= 75 ? "#166534" : (row.pct >= 40 ? "#b45309" : "#9f1239");
                    html += `<div class="summary-table-row" style="grid-template-columns: 1.5fr 0.9fr 0.9fr 0.6fr;"><div><span style="color:#94a3b8; font-weight:900;">${index + 1}.</span> ${escapeHtml(row.name)}</div><div class="font-black">${formatRevenueLakhValue(row.target)}</div><div class="text-emerald-700 font-black">${formatRevenueLakhValue(row.paidAmountTotal)}</div><div style="color:${pctColor}; font-weight:950;">${row.pct}%</div></div>`;
                });
            }
            const totals = rows.reduce((acc, row) => { acc.paidAmountTotal += row.paidAmountTotal; acc.target += row.target; return acc; }, { paidAmountTotal: 0, target: 0 });
            const grandPct = getRevenueAchievementPct(totals.paidAmountTotal, totals.target);
            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL (${colLabel} SCOPE)</div><div class="mt-2 grid grid-cols-3 gap-2 text-center text-[11px] font-black"><div class="rounded-xl bg-slate-100 border border-slate-200 p-2">Target (Lakh)<br>${formatRevenueLakhValue(totals.target)}</div><div class="rounded-xl bg-emerald-50 border border-emerald-200 p-2">Achieved (Lakh)<br>${formatRevenueLakhValue(totals.paidAmountTotal)}</div><div class="rounded-xl bg-blue-50 border border-blue-200 p-2">%<br>${grandPct}%</div></div></div>`;
            return html;
        }

        function renderRevenueTargetTable() {
            if (revenueTargetViewBy !== getRevenueTargetNaturalLevel()) {
                return renderRevenueTargetFlatTable(revenueTargetViewBy);
            }
            const rows = getRevenueTargetCurrentRows();
            const colLabel = getRevenueTargetColumnLabel();
            const depth = revenueTargetDrillPath.length;
            const canDrillDeeper = activeViewLevel === "DC" ? depth < 1 : depth < 2;

            let breadcrumbHtml = "";
            if (depth > 0) {
                const crumbLabel = revenueTargetDrillPath.join(" › ");
                breadcrumbHtml = `<div onclick="popRevenueTargetDrill()" style="display:flex; align-items:center; gap:6px; padding:9px 10px; margin-bottom:6px; background:#eff6ff; border:1.2px solid #93c5fd; border-radius:10px; font-size:0.68rem; font-weight:900; color:#1d4ed8; cursor:pointer;">⬅ ${escapeHtml(crumbLabel)} - Back</div>`;
            }

            let html = `<div class="summary-wrapper">${breadcrumbHtml}<div class="summary-table-header" style="grid-template-columns: 1.2fr 0.95fr 0.95fr 0.7fr;"><div>${colLabel}</div><div>TARGET (LAKH)</div><div>ACHIEVED (LAKH)</div><div>%</div></div>`;

            if (!rows || !rows.length) {
                html += `${scEmptyState_(`No data found in this scope.`)}`;
            } else {
                rows.forEach((row) => {
                    const rowClass = row.type === "SUB_TOTAL" ? " blue-bold" : (row.type === "SUBDN_TOTAL" ? " subdn-bold" : "");
                    const clickable = canDrillDeeper && !row.type && row.children && row.children.length;
                    const attrs = clickable ? ` data-drill-name="${escapeHtml(row.name)}" onclick="pushRevenueTargetDrill(this)" style="cursor:pointer;"` : "";
                    const nameCell = clickable ? `${escapeHtml(row.name)} ›` : escapeHtml(row.name);
                    const target = Number(row.paidAmountTotal || 0) + Number(row.unpaidAmountTotal || 0) + Number(row.noDuesAmountTotal || 0);
                    const pct = getRevenueAchievementPct(row.paidAmountTotal, target);
                    const pctColor = pct >= 75 ? "#166534" : (pct >= 40 ? "#b45309" : "#9f1239");
                    html += `<div class="summary-table-row${rowClass}" style="grid-template-columns: 1.2fr 0.95fr 0.95fr 0.7fr;"${attrs}><div>${nameCell}</div><div class="font-black">${formatRevenueLakhValue(target)}</div><div class="text-emerald-700 font-black">${formatRevenueLakhValue(row.paidAmountTotal)}</div><div style="color:${pctColor}; font-weight:950;">${pct}%</div></div>`;
                });
            }

            const totals = (rows || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").reduce((acc, row) => {
                acc.paidAmountTotal += Number(row.paidAmountTotal || 0);
                acc.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0) + Number(row.noDuesAmountTotal || 0); // target = net (29/09)
                return acc;
            }, { paidAmountTotal: 0, unpaidAmountTotal: 0 });
            const grandTarget = totals.paidAmountTotal + totals.unpaidAmountTotal;
            const grandPct = getRevenueAchievementPct(totals.paidAmountTotal, grandTarget);

            html += `</div><div class="summary-footer"><div class="font-black text-slate-800 text-center">TOTAL (${colLabel} SCOPE)</div><div class="mt-2 grid grid-cols-3 gap-2 text-center text-[11px] font-black"><div class="rounded-xl bg-slate-100 border border-slate-200 p-2">Target (Lakh)<br>${formatRevenueLakhValue(grandTarget)}</div><div class="rounded-xl bg-emerald-50 border border-emerald-200 p-2">Achieved (Lakh)<br>${formatRevenueLakhValue(totals.paidAmountTotal)}</div><div class="rounded-xl bg-blue-50 border border-blue-200 p-2">%<br>${grandPct}%</div></div></div>`;
            return html;
        }

        function renderRevenueTargetSummaryCardsHtml(totals) {
            const target = totals.paidAmountTotal + totals.unpaidAmountTotal;
            const pct = getRevenueAchievementPct(totals.paidAmountTotal, target);
            const pctColor = pct >= 75 ? "#166534" : (pct >= 40 ? "#b45309" : "#9f1239");
            return `
                <div style="display:grid; grid-template-columns: 1fr 1fr 1fr; gap:8px; width:100%; max-width:360px; margin:12px auto 0;">
                    <div style="background:#f1f5f9; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#64748b; text-transform:uppercase;">Target (Net Bill, Lakh)</div><div style="font-size:0.9rem; font-weight:950; color:#0f172a; margin-top:3px;">${formatRevenueLakhValue(target)}</div></div>
                    <div style="background:#ecfdf5; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#166534; text-transform:uppercase;">Achieved (Lakh)</div><div style="font-size:0.9rem; font-weight:950; color:#166534; margin-top:3px;">${formatRevenueLakhValue(totals.paidAmountTotal)}</div></div>
                    <div style="background:#eff6ff; border-radius:14px; padding:10px 6px; text-align:center;"><div style="font-size:0.56rem; font-weight:850; color:#1d4ed8; text-transform:uppercase;">Achievement</div><div style="font-size:1.05rem; font-weight:950; color:${pctColor}; margin-top:3px;">${pct}%</div></div>
                </div>
                <div style="font-size:0.6rem; font-weight:950; color:#1d4ed8; text-align:center; margin:14px auto 0; max-width:360px; text-transform:uppercase;">${activeViewLevel === "DC" ? "HQ Wise" : "DC Wise"} (tap to drill down further)</div>
            `;
        }

        async function renderRevenueTargetAchievement() {
            const tableBox = document.getElementById("revenue-target-table");
            const summaryBox = document.getElementById("revenue-target-summary");
            const statusBox = document.getElementById("revenue-target-download-status");
            if (!tableBox) return;
            const renderToken = ++revenueTargetRenderToken;
            if (statusBox) statusBox.style.display = "none";
            if (summaryBox) summaryBox.innerHTML = "";
            revenueTargetTree = [];
            revenueTargetDrillPath = [];
            if (activeDC) activeViewLevel = "DC";
            else if (activeDiv) activeViewLevel = "DIVISION";
            else activeViewLevel = "CIRCLE";
            const isRenderValid = () => renderToken === revenueTargetRenderToken && document.getElementById("revenue-target-achievement-view")?.classList.contains("active");
            const scopeKey = activeDC || activeDiv || "CIRCLE";
            const alreadyLoaded = revenueTargetLoadedScopeKey === scopeKey;
            const progress = alreadyLoaded ? null : renderSyncingProgress(tableBox, isRenderValid, "SYNCING DATA... PLEASE WAIT");
            try {
                const mode = revenueTargetMode === "MONTHLY" ? "MONTHLY" : "DAILY";
                const filterValue = mode === "MONTHLY"
                    ? (document.getElementById("revenue-target-month")?.value || getTodayIsoDate().slice(0, 7))
                    : (document.getElementById("revenue-target-date")?.value || getTodayIsoDate());
                let reconciliation;
                if (!alreadyLoaded) {
                    reconciliation = await prepareRevenueCategoryReportData_(
                        getRevenueCategoryTargetDcs(), mode, filterValue
                    );
                    if (!isRenderValid()) { progress.stop(); return; }
                    revenueTargetLoadedScopeKey = scopeKey;
                } else {
                    reconciliation = await ensureRevenueCategoryReconciliationLoaded(mode, filterValue);
                }
                if (!isRenderValid()) { if (progress) progress.stop(); return; }
                const govtFilter = document.getElementById("revenue-target-govt")?.value || "";
                const tree = buildRevenueHqVillagePaidUnpaidTree(mode, filterValue, govtFilter);
                revenueTargetTree = tree;
                revenueTargetDrillPath = [];
                const totals = (tree || []).filter((row) => row.type !== "SUB_TOTAL" && row.type !== "SUBDN_TOTAL").reduce((acc, row) => {
                    acc.paidAmountTotal += Number(row.paidAmountTotal || 0);
                    acc.unpaidAmountTotal += Number(row.unpaidAmountTotal || 0) + Number(row.noDuesAmountTotal || 0); // target = net (29/09)
                    return acc;
                }, { paidAmountTotal: 0, unpaidAmountTotal: 0 });
                if (progress) await progress.finish();
                if (!isRenderValid()) return;
                refreshRevenueTargetViewByOptions();
                if (summaryBox) summaryBox.innerHTML = renderRevenueTargetSummaryCardsHtml(totals);
                tableBox.innerHTML = renderRevenueTargetTable();
                showRevenueCategoryStaleLegacyWarning_(statusBox, reconciliation && reconciliation.supported === false);
            } catch (error) {
                if (progress) progress.stop();
                if (statusBox) {
                    statusBox.style.display = "block";
                    statusBox.style.background = "#fff1f2";
                    statusBox.style.borderColor = "#fda4af";
                    statusBox.style.color = "#991b1b";
                    statusBox.innerText = error?.message || "Report could not be loaded";
                }
            }
        }

        function getRevenueTargetReportTitle() {
            const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
            return `Target vs Achievement Summary - ${scope}`;
        }

        function getRevenueTargetPeriodDisplay() {
            if (revenueTargetMode === "MONTHLY") {
                return formatRevenueMonthYear(document.getElementById("revenue-target-month")?.value || getTodayIsoDate().slice(0, 7));
            }
            return formatRevenueDateIndian(normalizeRevenueReportDate(document.getElementById("revenue-target-date")?.value || getCurrentDateDDMMYYYY()));
        }

        function setRevenueTargetDownloadState(isLoading, message = "", ok = true) {
            scApplyDownloadBoxState_("revenue-target", isLoading, message, ok);
        }

        function downloadRevenueTargetAchievement(type) {
            // Download hamesha usi granularity par ho jo abhi screen par select hai
            // (revenueTargetViewBy) - HQ select hai to sirf HQ-level summary, VILLAGE
            // select hai to village-level, DC select hai to DC-level. Pehle yahan
            // "natural level" par purani flattenRevenueTargetRows() (jo hamesha leaf/
            // village tak flatten karti thi) use ho rahi thi - isi wajah se HQ WISE
            // select karne par bhi PDF me saari village aa rahi thi. Ab hamesha
            // buildRevenueTargetFlatRows() hi use hoga, jo screen ke summary jaisa
            // hi granularity rakhta hai.
            const flatRows = buildRevenueTargetFlatRows(revenueTargetViewBy);
            if (!flatRows.length) return showToast("No data available for the report", false);
            setRevenueTargetDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download in progress... please wait`, true);
            try {
                const colLabel = revenueTargetViewBy === "DC" ? "DC NAME" : (revenueTargetViewBy === "HQ" ? (activeViewLevel === "DC" ? revenueHqLabelUpper() : "HQ NAME") : (activeViewLevel === "DC" ? revenueVillageLabelUpper() : "VILLAGE"));
                const headers = [colLabel, "TARGET (LAKH)", "ACHIEVED (LAKH)", "%"];
                const rows = flatRows.map((r) => [r.name, formatRevenueLakhValue(r.target), formatRevenueLakhValue(r.paidAmountTotal), `${r.pct}%`]);
                const grandTarget = flatRows.reduce((sum, r) => sum + Number(r.target || 0), 0);
                const grandAchieved = flatRows.reduce((sum, r) => sum + Number(r.paidAmountTotal || 0), 0);
                rows.push(["GRAND TOTAL", formatRevenueLakhValue(grandTarget), formatRevenueLakhValue(grandAchieved), `${getRevenueAchievementPct(grandAchieved, grandTarget)}%`]);
                const reportTitle = getRevenueTargetReportTitle();
                const govtFilterValue = document.getElementById("revenue-target-govt")?.value || "";
                const govtFilterLabel = govtFilterValue === "GOVT" ? "Govt Only" : (govtFilterValue === "NONGOVT" ? "Non Govt Only" : "All (Govt + Non Govt)");
                const scopeLine = `Scope: ${activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? `Division - ${activeDiv}` : "Circle - SEONI CIRCLE")}  |  Type: ${govtFilterLabel}`;
                const periodLine = `Period: ${getRevenueTargetPeriodDisplay()}`;
                const suffix = revenueTargetMode === "MONTHLY"
                    ? (document.getElementById("revenue-target-month")?.value || getTodayIsoDate().slice(0, 7))
                    : normalizeRevenueReportDate(document.getElementById("revenue-target-date")?.value || getCurrentDateDDMMYYYY());
                const fileName = `${reportTitle}-${suffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setRevenueTargetDownloadState(false, "PDF library could not be loaded", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    scPdfHeader_(doc, { title: reportTitle, lines: [scopeLine, periodLine] });
                    doc.autoTable({ startY: 34, head: [headers], body: rows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [29, 78, 216] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setRevenueTargetDownloadState(false, "PDF downloaded", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[reportTitle], [scopeLine], [periodLine], [], headers, ...rows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setRevenueTargetDownloadState(false, "Excel downloaded", true);
            } catch (error) {
                setRevenueTargetDownloadState(false, "Download failed", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        // =====================================================================
        // TOP DEFAULTERS (Top 20 / Top 50) - Cash List ke baad jo balance/pending
        // reh gaya (Net Bill, jo consumer abhi tak unpaid hai), usi ko sabse zyada
        // bakaya wale order me sort karke dikhate hain. Same buildRevenueHqVillage-
        // ConsumerRows() data reuse karte hain jo particular-list section use karta hai.
        // =====================================================================
        let revenueDefaultersLimit = 20;
        let revenueDefaultersRows = [];
        let revenueDefaultersRenderToken = 0;
        // Same fix as HQ Village/Target Achievement - Top20/Top50 toggle aur date
        // change bhi pehle har baar poora "SYNCING..." resync kar dete the, chahe
        // is scope ka category data isi visit me pehle hi load ho chuka ho.
        let revenueDefaultersLoadedScopeKey = null;

        function initRevenueTopDefaulters() {
            revenueDefaultersLoadedScopeKey = null;
            const dateInput = document.getElementById("revenue-defaulters-date");
            if (dateInput && !dateInput.value) dateInput.value = getTodayIsoDate();
            setRevenueDefaultersButtonState();
            renderRevenueTopDefaulters();
        }

        function setRevenueDefaultersButtonState() {
            const top20Btn = document.getElementById("revenue-defaulters-top20-btn");
            const top50Btn = document.getElementById("revenue-defaulters-top50-btn");
            if (top20Btn) {
                top20Btn.style.background = revenueDefaultersLimit === 20 ? "#9f1239" : "#ffe4e6";
                top20Btn.style.color = revenueDefaultersLimit === 20 ? "#ffffff" : "#9f1239";
            }
            if (top50Btn) {
                top50Btn.style.background = revenueDefaultersLimit === 50 ? "#9f1239" : "#ffe4e6";
                top50Btn.style.color = revenueDefaultersLimit === 50 ? "#ffffff" : "#9f1239";
            }
        }

        function setRevenueDefaultersLimit(limit) {
            revenueDefaultersLimit = limit === 50 ? 50 : 20;
            setRevenueDefaultersButtonState();
            renderRevenueTopDefaulters();
        }

        function onRevenueDefaultersHqChange() {
            const hqValue = document.getElementById("revenue-defaulters-hq")?.value || "";
            const allRows = revenueDefaultersRows;
            const scoped = allRows.filter((row) => !hqValue || normalizeLookupValue(row.hqName) === normalizeLookupValue(hqValue));
            populateRevenueSelect(document.getElementById("revenue-defaulters-village"), getRevenueUniqueValues(scoped, "village"), revenueVillageAllLabel());
            renderRevenueDefaultersTable();
        }

        function getRevenueDefaultersFilteredRows() {
            const hqValue = document.getElementById("revenue-defaulters-hq")?.value || "";
            const villageValue = document.getElementById("revenue-defaulters-village")?.value || "";
            const govtValue = document.getElementById("revenue-defaulters-govt")?.value || "";
            return revenueDefaultersRows
                .filter((row) => (
                    (!hqValue || normalizeLookupValue(row.hqName) === normalizeLookupValue(hqValue))
                    && (!villageValue || normalizeLookupValue(row.village) === normalizeLookupValue(villageValue))
                    && (!govtValue || (govtValue === "GOVT" ? !!row.govtFlag : !row.govtFlag))
                ))
                .sort((a, b) => b.pendingAmount - a.pendingAmount)
                .slice(0, revenueDefaultersLimit);
        }

        function renderRevenueDefaultersTable() {
            const statusBox = document.getElementById("revenue-defaulters-status-box");
            const tableBox = document.getElementById("revenue-defaulters-table");
            if (!statusBox || !tableBox) return;
            const rows = getRevenueDefaultersFilteredRows();
            const hqValue = document.getElementById("revenue-defaulters-hq")?.value || "";
            const villageValue = document.getElementById("revenue-defaulters-village")?.value || "";
            const govtValue = document.getElementById("revenue-defaulters-govt")?.value || "";
            const govtLabel = govtValue === "GOVT" ? "Govt Only" : (govtValue === "NONGOVT" ? "Non Govt Only" : "All");
            statusBox.innerHTML = `Showing: <strong>Top ${revenueDefaultersLimit}</strong> | ${escapeHtml(revenueHqLabel())}: ${escapeHtml(hqValue || revenueHqAllLabel())} | ${escapeHtml(revenueVillageLabel())}: ${escapeHtml(villageValue || revenueVillageAllLabel())} | Type: ${escapeHtml(govtLabel)} | Found: ${rows.length}`;
            if (!rows.length) {
                tableBox.innerHTML = `<div style="background:#ecfdf5; border:1.5px solid #86efac; border-radius:14px; padding:14px; color:#047857; font-size:0.8rem; font-weight:900; text-align:center; margin-top:10px;">No consumer with arrears found in this filter.</div>`;
                return;
            }
            // USER REQUEST (2026-09-12): Freeze Report (Division/Circle scope) me
            // DC NAME column dikhta hai - Live Top 20/50 Defaulters report me bhi
            // Division/Circle scope par wahi DC NAME column dikhna chahiye (DC
            // scope par pehle jaisa hi, koi DC column nahi - us DC ke andar hi to
            // ho, dobara likhna fizool hai).
            const showDcColumn = activeViewLevel !== "DC";
            const gridCols = showDcColumn ? "0.4fr 0.75fr 1.15fr 0.75fr 0.9fr" : "0.4fr 1.3fr 0.85fr 1fr";
            let html = `<div class="summary-wrapper"><div class="summary-table-header" style="grid-template-columns: ${gridCols};"><div>#</div>${showDcColumn ? "<div>DC</div>" : ""}<div>CONSUMER</div><div>MOBILE</div><div>PENDING</div></div>`;
            rows.forEach((row, index) => {
                const dcCell = showDcColumn ? `<div style="font-size:0.62rem; font-weight:850;">${escapeHtml(row.dcName || "-")}</div>` : "";
                html += `<div class="summary-table-row" style="grid-template-columns: ${gridCols};"><div class="font-black">${index + 1}</div>${dcCell}<div>${escapeHtml(row.consumerName || "-")}<br><span style="font-size:0.58rem; color:#64748b;">${escapeHtml(row.hqName)} / ${escapeHtml(row.village)}</span></div><div style="font-size:0.68rem;">${escapeHtml(row.mobileNo || "-")}</div><div class="text-rose-700 font-black">${formatProgressReportAmount(row.pendingAmount)}</div></div>`;
            });
            html += `</div>`;
            tableBox.innerHTML = html;
        }

        async function renderRevenueTopDefaulters() {
            const tableBox = document.getElementById("revenue-defaulters-table");
            const statusBox = document.getElementById("revenue-defaulters-status-box");
            const downloadStatusBox = document.getElementById("revenue-defaulters-download-status");
            if (!tableBox) return;
            const renderToken = ++revenueDefaultersRenderToken;
            if (downloadStatusBox) downloadStatusBox.style.display = "none";
            revenueDefaultersRows = [];
            if (activeDC) activeViewLevel = "DC";
            else if (activeDiv) activeViewLevel = "DIVISION";
            else activeViewLevel = "CIRCLE";
            const isRenderValid = () => renderToken === revenueDefaultersRenderToken && document.getElementById("revenue-top-defaulters-view")?.classList.contains("active");
            const scopeKey = activeDC || activeDiv || "CIRCLE";
            const alreadyLoaded = revenueDefaultersLoadedScopeKey === scopeKey;
            const progress = alreadyLoaded ? null : renderSyncingProgress(tableBox, isRenderValid, "SYNCING DATA... PLEASE WAIT");
            try {
                const dateValue = document.getElementById("revenue-defaulters-date")?.value || getTodayIsoDate();
                let reconciliation;
                if (!alreadyLoaded) {
                    reconciliation = await prepareRevenueCategoryReportData_(
                        getRevenueCategoryTargetDcs(), "DAILY", dateValue
                    );
                    if (!isRenderValid()) { progress.stop(); return; }
                    revenueDefaultersLoadedScopeKey = scopeKey;
                } else {
                    reconciliation = await ensureRevenueCategoryReconciliationLoaded("DAILY", dateValue);
                }
                if (!isRenderValid()) { if (progress) progress.stop(); return; }
                // USER REQUEST (2026-08-13): row.pendingAmount (buildRevenueHqVillage-
                // ConsumerRows me pehle se Net Bill - Paid, sirf positive) use karte
                // hain, "!row.paid" filter hata diya - taaki partial payment wale
                // consumer bhi apne bache hue bakaya amount ke saath Top Defaulters
                // me sahi se dikhein (pehle wo poori tarah list se bahar ho jaate the).
                try { await warmRevenueFreezePaidSummaryCache_(); } catch (_) {} // USER RULE 2026-09-26: cash list (Freeze jaisa)
                if (!isRenderValid()) { if (progress) progress.stop(); return; }
                const consumerRows = buildRevenueHqVillageConsumerRows("DAILY", dateValue, true);
                revenueDefaultersRows = consumerRows.filter((row) => row.pendingAmount > 0);
                if (progress) await progress.finish();
                if (!isRenderValid()) return;
                const hqSelect = document.getElementById("revenue-defaulters-hq");
                const villageSelect = document.getElementById("revenue-defaulters-village");
                populateRevenueSelect(hqSelect, getRevenueUniqueValues(revenueDefaultersRows, "hqName"), revenueHqAllLabel());
                populateRevenueSelect(villageSelect, getRevenueUniqueValues(revenueDefaultersRows, "village"), revenueVillageAllLabel());
                if (hqSelect) hqSelect.value = "";
                if (villageSelect) villageSelect.value = "";
                const govtSelect = document.getElementById("revenue-defaulters-govt");
                if (govtSelect) govtSelect.value = "";
                renderRevenueDefaultersTable();
                showRevenueCategoryStaleLegacyWarning_(statusBox, reconciliation && reconciliation.supported === false);
            } catch (error) {
                if (progress) progress.stop();
                if (statusBox) statusBox.innerText = error?.message || "Report could not be loaded";
            }
        }

        function getRevenueDefaultersReportTitle() {
            const scope = activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE");
            return `Top ${revenueDefaultersLimit} Defaulters - ${scope}`;
        }

        function setRevenueDefaultersDownloadState(isLoading, message = "", ok = true) {
            scApplyDownloadBoxState_("revenue-defaulters", isLoading, message, ok);
        }

        function downloadRevenueTopDefaulters(type) {
            const rows = getRevenueDefaultersFilteredRows();
            if (!rows.length) return showToast("No data available for download", false);
            setRevenueDefaultersDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download in progress... please wait`, true);
            try {
                // USER REQUEST (2026-09-12): Freeze Report ke Excel/PDF me Division/
                // Circle scope par DC NAME column hota hai - Live Top 20/50
                // Defaulters ke download me bhi wahi DC NAME column honi chahiye.
                const showDcColumn = activeViewLevel !== "DC";
                const headers = [
                    "S.NO", ...(showDcColumn ? ["DC NAME"] : []), "IVRS NO", "CONSUMER NAME",
                    revenueHqLabelUpper(), revenueVillageLabelUpper(), "GOVT/NON GOVT", "MOBILE NO", "PENDING AMOUNT"
                ];
                const bodyRows = rows.map((row, index) => [
                    index + 1, ...(showDcColumn ? [row.dcName || ""] : []), row.ivrsNo || "", row.consumerName || "",
                    row.hqName || "", row.village || "", row.govtFlag ? "GOVT" : "NON GOVT", row.mobileNo || "", formatProgressReportAmount(row.pendingAmount)
                ]);
                const reportTitle = getRevenueDefaultersReportTitle();
                const scopeLine = `Scope: ${activeViewLevel === "DC" ? `DC - ${activeDC}` : (activeViewLevel === "DIVISION" ? `Division - ${activeDiv}` : "Circle - SEONI CIRCLE")}`;
                const periodLine = `Date: ${formatRevenueDateIndian(normalizeRevenueReportDate(document.getElementById("revenue-defaulters-date")?.value || getCurrentDateDDMMYYYY()))}`;
                const suffix = normalizeRevenueReportDate(document.getElementById("revenue-defaulters-date")?.value || getCurrentDateDDMMYYYY());
                const fileName = `${reportTitle}-${suffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setRevenueDefaultersDownloadState(false, "PDF library could not be loaded", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    scPdfHeader_(doc, { title: reportTitle, lines: [scopeLine, periodLine], focus: { hq: (document.getElementById("revenue-defaulters-hq")?.value || "") } });
                    doc.autoTable({ startY: 34, head: [headers], body: bodyRows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [159, 18, 57] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setRevenueDefaultersDownloadState(false, "PDF downloaded", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[scPdfFocusTitle_(reportTitle, { hq: (document.getElementById("revenue-defaulters-hq")?.value || "") })], [scopeLine], [periodLine], [], headers, ...bodyRows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setRevenueDefaultersDownloadState(false, "Excel downloaded", true);
            } catch (error) {
                setRevenueDefaultersDownloadState(false, "Download failed", false);
                showToast(error?.message || "Report download failed", false);
            }
        }

        // =====================================================================
        // PARTICULAR LIST (HQ -> Village -> Category -> Paid/Unpaid dropdown pull)
        // Same paid-detection data (buildRevenueCategoryUploadedPaidInfo) jo summary
        // banata hai usi se ek flat per-consumer list bhi bana lete hain, taaki dropdown
        // se select karke kisi bhi combination ka exact consumer list mil sake.
        // =====================================================================
        let revenueHqVillageConsumerRows = [];

        function isRevenueMasterConsumerPaid(paidInfo) {
            if (!paidInfo) return false;
            const total = Number(paidInfo.normalCount || 0) + Number(paidInfo.agCount || 0) + Number(paidInfo.mixedCount || 0) + Number(paidInfo.unknownCount || 0);
            return total > 0;
        }

        function getRevenueMasterConsumerPaidAmount(paidInfo) {
            if (!paidInfo) return 0;
            return Number(paidInfo.normalAmount || 0) + Number(paidInfo.agAmount || 0) + Number(paidInfo.mixedAmount || 0) + Number(paidInfo.unknownAmount || 0);
        }

        // USER RULE (2026-09-26, BARGHAT 1303033740): consumer ki "status" wali report (Top 20/50
        // Defaulters, Live Non-Payee) me paid/pending Freeze aur Arrears 1 Lakh jaisa hi - poori
        // cash list (PAID DATE RULE ke saath), chuni hui date/mahina nahi. Pehle Top 20/50 sirf
        // "usi din" ke payment ko paid maanta tha, isliye 16/09 ko paid consumer 26/09 ko pending dikhta.
        function scCashListPaidInfoByDc_() {
            const idx = buildRevenueFreezePaidIndex("");
            const out = {};
            Object.keys(idx).forEach((key) => {
                const sep = key.indexOf("|");
                if (sep < 0) return;
                const dc = key.slice(0, sep), ivrs = key.slice(sep + 1);
                const amount = Number(idx[key].paidAmount || 0);
                if (!(amount > 0)) return;
                if (!out[dc]) out[dc] = {};
                out[dc][ivrs] = { normalAmount: amount, normalCount: 1, agAmount: 0, agCount: 0, mixedAmount: 0, mixedCount: 0, unknownAmount: 0, unknownCount: 0, categoryTotals: {} };
            });
            return out;
        }

        function buildRevenueHqVillageConsumerRows(mode, filterValue, useCashList = false) {
            const paidInfoByDc = useCashList ? scCashListPaidInfoByDc_() : buildRevenueCategoryUploadedPaidInfo(mode, filterValue);
            const targetDcs = getRevenueCategoryTargetDcs();
            const rows = [];
            targetDcs.forEach((dcName) => {
                const normalizedDc = normalizeDcName(dcName);
                const paidInfoForDc = paidInfoByDc[normalizedDc] || {};
                getRevenueMasterRowsForDc(dcName).forEach((row) => {
                    const ivrs = normalizeRevenueIvrs(row.ivrsNo);
                    if (!ivrs) return;
                    const info = paidInfoForDc[ivrs];
                    const paid = isRevenueMasterConsumerPaid(info);
                    const paidAmount = paid ? getRevenueMasterConsumerPaidAmount(info) : 0;
                    // USER REQUEST (2026-08-13): partial payment wale consumer ka bacha
                    // hua bakaya (Net Bill - Paid, sirf positive) - poora Net Bill nahi.
                    // Fully/over-paid (paidAmount >= netBill) ho to pendingAmount 0 rahega.
                    // BUG FIX (2026-08-20): pehle yahan seedha parseRevenuePaidAmount() use
                    // hota tha (koi garbage-number cap nahi) - CSV column-misalignment ki
                    // wajah se kisi ek-do consumer ka netBill kabhi-kabhi 15-20 digit ka
                    // "garbage" (asambhav bada) number ban jaata hai (jaise IVRS+mobile+bill
                    // aapas me jud jaana). DC-level scope me aisa ek DC ke thode consumers
                    // tak simit rehta tha, lekin DIVISION/CIRCLE scope me jab kai DC ka data
                    // ek sath jud kar sort hota hai, to ye garbage (astronomically bada)
                    // number descending sort me sabse UPAR aa jaata - Top 20/50 Defaulters
                    // ki poori list hi in garbage rows se bhar jaati thi. Aur display ke
                    // waqt formatProgressReportAmount() 1e12 se bade number ko "0" dikhata
                    // hai - isi wajah se Division/Circle ke Top Defaulters me sab "0"
                    // dikhte the (garbage rows list top par thi, jinka display 0 tha),
                    // jabki DC scope me aisa garbage row shayad hi kabhi top tak pahunchta.
                    // parseRevenuePendingAmount() (jo Non-Payee reports me pehle se use hoti
                    // hai) yehi garbage (>1 crore) ko 0 maan kar sahi tarah discard kar deti
                    // hai - ab yahan bhi wahi use karte hain, taaki asli defaulters upar aayein.
                    const dueAmountForRow = parseRevenuePendingAmount(row.netBill || 0);
                    const pendingAmount = paid ? 0 : dueAmountForRow; // USER RULE 2026-09-29: cash list me koi bhi payment = PAID (part paid bhi), pending list me nahi
                    rows.push({
                        ivrsNo: row.ivrsNo || "",
                        consumerName: row.consumerName || "",
                        fatherName: row.fatherName || "",
                        village: String(row.village || "UNKNOWN").trim().toUpperCase() || "UNKNOWN",
                        hqName: String(row.hqName || "GENERAL").trim().toUpperCase() || "GENERAL",
                        tariffCategory: normalizeRevenueCategory(row.tariffCategory || row.category || ""),
                        mobileNo: row.mobileNo || "",
                        netBill: row.netBill || "",
                        dcName: normalizedDc,
                        paid,
                        paidAmount,
                        pendingAmount,
                        govtFlag: !!row.govtFlag,
                        lastPaymentDate: row.lastPaymentDate || "",
                        connectionDate: row.connectionDate || "",
                        neverPaid: !!row.neverPaid,
                        hasPaymentDateData: !!row.hasPaymentDateData
                    });
                });
            });
            return rows;
        }

        // =====================================================================
        // NON PAYEE (aging) reports - "LAST PAYMENT DATE" master-data column ke
        // aadhar par. Sirf un DC ke consumers is report me aate hain jinki sheet me
        // yeh column maujood hai (hasPaymentDateData true) - baaki DC (jinki sheet
        // abhi update nahi hui) automatically is report se bahar rehte hain, taaki
        // galat "sabhi never-paid" jaisa data kabhi na dikhe.
        // Net Bill zero ya negative wale consumers hamesha ignore honge (koi bhi
        // bucket ho) - unke paas asal me koi bakaya hi nahi hai.
        // =====================================================================
        // USER RULE (2026-09-25): NP3/NP6 ke mahine AAJ ki tareekh se nahi, balki us DC ke
        // MASTER DATA ki tareekh se gine jaate hain - master jitni tareekh tak ka hai (us DC
        // ke master ki sabse nayi LAST PAYMENT DATE, aaj se aage ki galat tareekh chhod kar).
        // Isse naya master aane tak NP3/NP6 list poore mahine ek jaisi rehti hai (Live + Freeze).
        // refIso na mile to purana behaviour (aaj ki tareekh).
        function getRevenueMasterReferenceDateByDc_(consumerRows) {
            const now = new Date();
            const todayKey = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
            const refByDc = {};
            (consumerRows || []).forEach((row) => {
                const m = String(row.lastPaymentDate || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})/);
                if (!m) return;
                const key = `${m[1]}-${m[2]}-${m[3]}`;
                if (key > todayKey) return;
                const dc = normalizeDcName(row.dcName);
                if (!refByDc[dc] || key > refByDc[dc]) refByDc[dc] = key;
            });
            // USER RULE (2026-10-14, NGB master 10 tareekh ko banta hai): aadhar = us master ke MAHINE ki 10 tareekh
            // (master ki sabse nayi LAST PAYMENT DATE jis mahine ki ho, uski 10). Naya master aane tak purani 10 hi chalti
            // hai; freeze kisi bhi din ho, aadhar wahi rehta hai. NP3 = payment 10 Jul ya usse pehle (10 Oct aadhar par),
            // NP6 = 10 Apr ya usse pehle. 10 ke baad ki payment wale consumer apne aap bahar.
            Object.keys(refByDc).forEach((dc) => { refByDc[dc] = refByDc[dc].slice(0, 7) + "-10"; });
            return refByDc;
        }

        function getRevenueMonthsSincePaymentDate(dateStr, refIso) {
            const raw = String(dateStr || "").trim();
            const match = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (!match) return null;
            const paymentDate = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
            if (isNaN(paymentDate.getTime())) return null;
            const refMatch = String(refIso || "").match(/^(\d{4})-(\d{2})-(\d{2})/);
            const today = refMatch ? new Date(Number(refMatch[1]), Number(refMatch[2]) - 1, Number(refMatch[3])) : new Date();
            let months = (today.getFullYear() - paymentDate.getFullYear()) * 12 + (today.getMonth() - paymentDate.getMonth());
            if (today.getDate() < paymentDate.getDate()) months -= 1;
            return Math.max(0, months);
        }

        function buildRevenueNonPayeeRows(mode, filterValue, bucket, hidePaidByCashList = false, noDuesOnly = false) {
            // 2026-10-23: noDuesOnly=true -> usi category ke wahi consumer jinka bakaya 0/minus hai (NO DUES) - Freeze summary ke liye.
            // hidePaidByCashList: sirf Live Non-Payee report (Freeze Now ke liye pehle jaisa - sabhi consumer)
            const consumerRows = buildRevenueHqVillageConsumerRows(mode, filterValue, hidePaidByCashList);
            const withPendingAmount = hidePaidByCashList
                ? (row) => ({ ...row })
                : (row) => ({ ...row, pendingAmount: parseRevenuePendingAmount(row.netBill || 0) });
            if (bucket === "SINCE_CONNECTION") {
                // USER REQUEST (2026-10-20): 3 mahine se kam purane connection (CONNECTION DATE se, master ki 10 tarikh aadhar par) is list me nahi aayenge;
                // baaki sabhi (3+ mahine, ya jinki connection date khaali/galat hai) aayenge. Jis DC me CONNECTION DATE bhari hi nahi wahan koi farak nahi.
                const scRefByDc = getRevenueMasterReferenceDateByDc_(consumerRows);
                const connDcsSc = new Set();
                consumerRows.forEach((r) => { if (r.connectionDate) connDcsSc.add(normalizeDcName(r.dcName)); });
                const notTooNew = (row) => {
                    const dc = normalizeDcName(row.dcName);
                    if (!row.connectionDate || !connDcsSc.has(dc)) return true;
                    const m = getRevenueMonthsSincePaymentDate(row.connectionDate, scRefByDc[dc]);
                    return m === null || m >= 3;
                };
                return consumerRows
                    .filter((row) => row.hasPaymentDateData && row.neverPaid)
                    .filter(notTooNew)
                    .map(withPendingAmount)
                    .filter((row) => (noDuesOnly ? !(row.pendingAmount > 0) : row.pendingAmount > 0))
                    .sort((a, b) => b.pendingAmount - a.pendingAmount);
            }
            const monthThreshold = bucket === "5Y" ? 60 : (bucket === "6M" ? 6 : 3);
            const masterRefByDc = getRevenueMasterReferenceDateByDc_(consumerRows); // USER RULE 2026-09-25
            if (bucket === "5Y") {
                // USER REQUEST (2026-10-14): Non Payee From 5 Years = (last payment date blank/never paid) YA (60+ mahine, NP3/NP6 jaisa hi 10 tarikh wala base rule)
                // USER REQUEST (2026-10-20): never-paid consumer tabhi aaye jab CONNECTION DATE se bhi 60+ mahine (usi master-10-tarikh aadhar par) ho.
                // Jis DC ke master me CONNECTION DATE bhari hi nahi (purani sheet / column khaali) uske liye purana tareeka jyon ka tyon (koi consumer gayab nahi).
                const connDcs = new Set();
                consumerRows.forEach((r) => { if (r.connectionDate) connDcs.add(normalizeDcName(r.dcName)); });
                const connOk = (row) => {
                    const dc = normalizeDcName(row.dcName);
                    if (!connDcs.has(dc)) return true;
                    if (!row.connectionDate) return false;
                    const m = getRevenueMonthsSincePaymentDate(row.connectionDate, masterRefByDc[dc]);
                    return m !== null && m >= monthThreshold;
                };
                return consumerRows
                    .filter((row) => row.hasPaymentDateData && (row.neverPaid || row.lastPaymentDate))
                    .filter((row) => !row.neverPaid || connOk(row))
                    .map((row) => (row.neverPaid
                        ? { ...withPendingAmount(row), monthsSincePayment: null }
                        : { ...withPendingAmount(row), monthsSincePayment: getRevenueMonthsSincePaymentDate(row.lastPaymentDate, masterRefByDc[normalizeDcName(row.dcName)]) }))
                    .filter((row) => row.neverPaid || (row.monthsSincePayment !== null && row.monthsSincePayment >= monthThreshold))
                    .filter((row) => (noDuesOnly ? !(row.pendingAmount > 0) : row.pendingAmount > 0))
                    .sort((a, b) => b.pendingAmount - a.pendingAmount);
            }
            return consumerRows
                .filter((row) => row.hasPaymentDateData && !row.neverPaid && row.lastPaymentDate)
                .map((row) => ({ ...withPendingAmount(row), monthsSincePayment: getRevenueMonthsSincePaymentDate(row.lastPaymentDate, masterRefByDc[normalizeDcName(row.dcName)]) }))
                .filter((row) => row.monthsSincePayment !== null && row.monthsSincePayment >= monthThreshold)
                .filter((row) => (noDuesOnly ? !(row.pendingAmount > 0) : row.pendingAmount > 0))
                .sort((a, b) => (b.monthsSincePayment - a.monthsSincePayment) || (b.pendingAmount - a.pendingAmount));
        }

        function getRevenueNonPayeeBucketLabel(bucket) {
            if (bucket === "6M") return "Non Payee From 6 Month";
            if (bucket === "5Y") return "Non Payee From 5 Years";
            if (bucket === "SINCE_CONNECTION") return "Non Payee From Date of Connection";
            return "Non Payee From 3 Month";
        }

