        function downloadRevenueHqVillageList(type) {
            const filteredRows = getRevenueHqVillageListFilteredRows();
            if (!filteredRows.length) return showToast("No data available for the list", false);
            setRevenueHqVillageListDownloadState(true, `${type === "PDF" ? "PDF" : "Excel"} download in progress... please wait`, true);
            try {
                const headers = getRevenueHqVillageListExportHeaders();
                const rows = getRevenueHqVillageListExportRows(filteredRows);
                const hqValue = document.getElementById("revenue-hq-village-list-hq")?.value || "";
                const villageValue = document.getElementById("revenue-hq-village-list-village")?.value || "";
                const categoryValue = document.getElementById("revenue-hq-village-list-category")?.value || "";
                const statusValue = document.getElementById("revenue-hq-village-list-status")?.value || "ALL";
                const govtValue = document.getElementById("revenue-hq-village-list-govt")?.value || "";
                const categoryLabel = categoryValue ? getRevenueCategoryDisplayLabel(categoryValue) : "All Categories";
                const statusLabel = statusValue === "PAID" ? "Paid Only" : (statusValue === "UNPAID" ? "Unpaid Only" : "All (Paid + Unpaid)");
                const govtLabel = govtValue === "GOVT" ? "Govt Only" : (govtValue === "NONGOVT" ? "Non Govt Only" : "All");
                const reportTitle = "Consumer List - HQ/Village/Category Wise";
                const filterLine1 = `${revenueHqLabel()}: ${hqValue || "All " + revenueHqLabel()}  |  ${revenueVillageLabel()}: ${villageValue || "All " + revenueVillageLabel()}`;
                const filterLine2 = `Category: ${categoryLabel}  |  Status: ${statusLabel}  |  Type: ${govtLabel}`;
                const periodLine = `Period: ${getRevenueHqVillagePeriodDisplay()}`;
                const suffix = revenueHqVillageMode === "MONTHLY"
                    ? (document.getElementById("revenue-hq-village-month")?.value || getTodayIsoDate().slice(0, 7))
                    : normalizeRevenueReportDate(document.getElementById("revenue-hq-village-date")?.value || getCurrentDateDDMMYYYY());
                const fileNameParts = [hqValue || "ALL-HQ", villageValue || "ALL-VILLAGE", categoryValue || "ALL-CATEGORY", statusValue, govtValue || "ALL-TYPE"];
                const fileName = `Consumer-List-${fileNameParts.join("-")}-${suffix}`.replace(/[\\/:*?"<>|]+/g, "_");
                if (type === "PDF") {
                    if (!window.jspdf?.jsPDF) { setRevenueHqVillageListDownloadState(false, "PDF library could not be loaded", false); return; }
                    const { jsPDF } = window.jspdf;
                    const doc = new jsPDF({ orientation: "landscape" });
                    scPdfHeader_(doc, { title: `${reportTitle} - ${activeViewLevel === "DC" ? `DC ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE")}`, lines: [filterLine1, filterLine2, periodLine], focus: { hq: (document.getElementById("revenue-hq-village-list-hq")?.value || "") } });
                    doc.autoTable({ startY: 35, head: [headers], body: rows, theme: "grid", styles: { fontSize: 6, cellPadding: 1, overflow: "linebreak" }, headStyles: { fillColor: [21, 128, 61] } });
                    savePdfDocumentForDevice(doc, `${fileName}.pdf`);
                    setRevenueHqVillageListDownloadState(false, "PDF downloaded", true);
                    return;
                }
                const csvSafe = (value) => { const text = String(value ?? ""); return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text; };
                const csv = [[scPdfFocusTitle_(`${reportTitle} - ${activeViewLevel === "DC" ? `DC ${activeDC}` : (activeViewLevel === "DIVISION" ? activeDiv : "SEONI CIRCLE")}`, { hq: (document.getElementById("revenue-hq-village-list-hq")?.value || "") })], [filterLine1], [filterLine2], [periodLine], [], headers, ...rows].map((row) => row.map(csvSafe).join(",")).join("\n");
                const link = document.createElement("a");
                link.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
                link.download = `${fileName}.csv`;
                link.click();
                setRevenueHqVillageListDownloadState(false, "Excel downloaded", true);
            } catch (error) {
                setRevenueHqVillageListDownloadState(false, "Download failed", false);
                showToast(error?.message || "List download failed", false);
            }
        }

