        function goBack() {
            const activeNode = document.querySelector(".view.active");
            if (!activeNode) return;
            const act = activeNode.id;
            if (act === "dc-selection-view") {
                activeDC = "";
                document.getElementById("selected-dc-label").innerText = "Choose DC Name...";
                switchView("home");
            } else if (act === "subdn-chhapara-view") {
                switchView("dc-selection");
            } else if (act === "staff-admin-view" || act === "data-health-view") {
                switchView("subdn-chhapara");
            } else if (act === "stock-material-view" || act === "shms-entry-view" || act === "shms-progress-view" || act === "shms-pending-view" || act === "feeder-reading-view" || act === "daily-hourly-peak-load-view" || act === "vehicle-reading-view" || act === "stm-complaint-view") {
                if (act === "shms-entry-view") {
                    resetShmsForm();
                }
                if (act === "feeder-reading-view") {
                    resetFeederReading();
                }
                if (act === "daily-hourly-peak-load-view") {
                    resetPeakLoadSelection();
                }
                switchView("subdn-chhapara");
            } else if (act === "court-case-view") {
                resetCourtCaseForm();
                switchView("dc-dashboard");
            } else if (act === "division-master-upload-view") {
                switchView("subdn-chhapara");
            } else if (act === "division-paid-upload-view") {
                switchView("dc-selection");
            } else if (act === "bill-calculator-view" || act === "staff-contact-view") {
                switchView("dc-dashboard");
            } else if (act === "material-list-view" || act === "material-receive-view" || act === "material-issue-view" || act === "live-stock-view" || act === "low-stock-view" || act === "stock-report-view") {
                switchView("stock-material");
            } else if (act === "revenue-pending-list-view" && revenueMessageSelectionMode) {
                revenueMessageSelectionMode = false;
                revenueMessageQueue = [];
                revenueMessageSelectedRows = new Map();
                switchView("revenue-message-login");
            } else if (act === "revenue-message-login-view") {
                revenueMessageSelectionMode = false;
                switchView("revenue-collection");
            } else if (act === "revenue-hq-village-view" && revenueHqVillageDrillPath.length) {
                popRevenueHqVillageDrill();
            } else if (act === "revenue-target-achievement-view" && revenueTargetDrillPath.length) {
                popRevenueTargetDrill();
            } else if (act === "revenue-live-progress-view" || act === "revenue-report-download-view" || act === "revenue-hq-village-view" || act === "revenue-target-achievement-view" || act === "revenue-top-defaulters-view" || act === "revenue-cash-reconcile-view" || act === "revenue-pending-list-view" || act === "revenue-paid-upload-view") {
                switchView("revenue-collection");
            } else if (act === "vr-download-log-view") {
                switchView("vr-calculation");
            } else if (act === "meter-checking-view") {
                switchView("dc-dashboard");
            } else if (act === "meter-checking-report-view" || act === "meter-checking-live-progress-view") {
                switchView("meter-checking");
            } else if (act === "mobile-update-report-view" || act === "mobile-update-wrong-list-view") {
                switchView("mobile-update");
            } else if (act === "dc-dashboard-view" || act === "mobile-update-view" || act === "revenue-collection-view") {
                if (act === "mobile-update-view") {
                    resetForm(true);
                    switchView("dc-dashboard");
                } else if (act === "revenue-collection-view") {
                    initRevenueCollection();
                    switchView("dc-dashboard");
                } else {
                    activeDC = "";
                    document.getElementById("selected-dc-label").innerText = "Choose DC Name...";
                    switchView("dc-selection");
                }
            } else if (act === "help-chat-view") {
                helpChatBack_(); // USER REQUEST (2026-10-06) Help / Chat with Admin
            } else if (act === "summary-view") {
                if (activeViewLevel === "DC") switchView("dc-dashboard");
                else if (activeViewLevel === "DIVISION") switchView("dc-selection");
                else switchView("home");
            } else {
                switchView("home");
            }
        }

        function changeTheme(c) {
            document.documentElement.style.setProperty("--theme-color", c);
            document.getElementById("welcomeText").style.color = c;
        }

        function setMode(m) {
            summaryMode = m;
            const input = document.getElementById("report-date");
            document.getElementById("opt-daily").classList.toggle("active", m === "DAILY");
            document.getElementById("opt-monthly").classList.toggle("active", m === "MONTHLY");
            if (m === "MONTHLY") {
                input.type = "month";
                input.value = `${new Date().getFullYear()}-${String(new Date().getMonth() + 1).padStart(2, "0")}`;
            } else {
                input.type = "date";
                input.value = getTodayIsoDate();
            }
            refreshSummary();
        }


        // =====================================================================
        // BIJLEE BILL CALCULATOR (DC Dashboard, "Revenue Collection" ke turant
        // niche) - MPERC Retail Supply Tariff Order FY 2026-27 (Annexure-2,
        // Tariff Schedule LV-1 se LV-6, source PDF "TERRIFF ORDER.pdf" pages
        // 200-214) ke tariff-code-wise slabs par based APPROXIMATE monthly
        // bill estimator. Category chunne ke baad "Tariff Code" (jaise LV1.2
        // Urban, LV2.1 Institution, LV4.1 <=20HP wagera) alag se chunna hota
        // hai - taaki sahi rate lage.
        //
        // NGB_CONSUMER_LEDGER_CHHAPARA-2_JUNE-2026.xlsx (10,100 rows) se
        // reverse-engineer/verify kiya gaya hai:
        //   - Net Bill = Month Bill + Arrear + SurchargeDemanded (100% exact).
        //   - Month Bill = Energy Charge + F.C.A. + Fixed Charge + Electricity
        //     Duty + PF Charge + CCB Adjustment + Other & TOD Adjustment +
        //     Employee Rebate + Prompt Payment Incentive + Meter Rent
        //     - Subsidy - Load Factor Incentive - S.D. Interest - Lock Credit
        //     - Online Payment Rebate - Advance Payment Incentive, round-off
        //     nearest रुपया (>=50 paisa upar).
        //   - Energy Charge TELESCOPIC hai (LV1.2/LV5.1) - har slab apni rate
        //     par charge hoke judता hai, na ki poori consumption top-slab
        //     rate par (jaise pehle galti se implement hua tha).
        //   - Fixed Charge har tariff-code me alag tarike se: LV1.2 me 0-50/
        //     51-150 slab ek FLAT per-connection amount hai, 151+ slab me
        //     "har 15 unit (ya uska hissa) = 0.1kW" wale virtual-load-block se
        //     (Tariff Order ka apna illustration) - ye ledger ke 3 alag
        //     consumers (0/184/310/142 units) par bilkul EXACT match hui.
        //     LV2/LV3/LV4/LV5 me Fixed Charge load(kW)/HP x per-kW/HP rate hai.
        //   - Electricity Duty (ED) category ke hisaab se ALAG hai - ledger
        //     check karne par pata chala:
        //       LV1 (Domestic): duty lagti hai, EC ka % units badhne ke saath
        //         8.5% se 11.6% tak dheere-dheere badhta hai (progressive).
        //       LV2.2 (Commercial): duty lagti hai, ~9.35% flat.
        //       LV4 (Industry): duty lagti hai, ~9.3% flat.
        //       LV2.1 (Institution/School/Hospital), LV3 (Water Works/Street
        //         Light), LV5 (Agriculture): ledger me 1350+ rows check karne
        //         par ED हमेशा 0 mila - poori tarah EXEMPT.
        //   - F.C.A. (Fuel Cost Adjustment) tariff order me nahi hoti (DISCOM
        //     har mahine alag notify karta hai) - ledger se hi khud-ba-khud
        //     nikala: Energy Charge ka ~1.65% (NGB_CONSUMER_LEDGER_CHHAPARA1_
        //     JUL2026.xlsx me sabse zyada rows wali bill-date, 30-Jul-2026,
        //     us din ka ratio - [UPDATE Aug-2026: pehle ye 2.81% tha, pichle
        //     ledger/mahine ka; naye ledger se dobara nikala to 1.65% nikla]).
        //     Bill-date badalte hi ye ratio ledger me 1.1% se 2.2% ke beech
        //     ghatta-badhta paya gaya - matlab DISCOM ye dar bar-bar update
        //     karta hai, isliye ye ek approximation hai, aage DISCOM rate
        //     badalne par is constant ko bhi ledger se dobara nikalna padega.
        //   - LV3.1 (Municipal) aur kuch LV4 rows me billing-cycle ki exact
        //     lambai (30 din se kam/zyada) ki wajah se chhoti si proration
        //     गैप bhi mili - ye calculator poore-mahine ka maan kar chalta
        //     hai, isliye 1-3% tak ka farq aa sakta hai.
        //
        // LIMITATIONS (v1 me jaan-boojh kar chhoda gaya hai):
        //   - Power Factor surcharge/incentive shamil nahi hai.
        //   - Demand-based tariff me "Maximum Demand vs Contract Demand,
        //     jo bhi zyada ho" wali exact billing-demand logic simplify karke
        //     seedhe Contract/Sanctioned load use kiya hai.
        //   - LV-4 Seasonal (4.2), DTR-metered LV5.1(c) jaise special cases
        //     shamil nahi hain.
        //   - Griha Jyoti Subsidy (LV1) MP Govt circular ke anusar SIRF 150
        //     units tak hai, aur SIRF LV1 category me - isliye ye ek MANUAL
        //     "Subsidy Applicable?" toggle hai (sirf LV1 me dikhta hai).
        //     Amount ledger ki 8,700+ subsidy>0 wali LV1.2 rows se nikala
        //     gaya empirical interpolation-table hai (0-150 units).
        // =====================================================================

        function billRoundOff(value) {
            return Math.floor(Number(value || 0) + 0.5);
        }

        function billCalcRoundLoad(load) {
            return Math.max(1, Math.round(Number(load || 0)));
        }

        function billCalcFloorLoad(load) {
            return Math.max(1, Math.floor(Number(load || 0)));
        }

        function billTelescopicSum(units, slabs) {
            let remaining = Math.max(0, Number(units || 0));
            let prevLimit = 0;
            let totalRupees = 0;
            for (const [upto, paise] of slabs) {
                if (remaining <= 0) break;
                const slabSize = upto - prevLimit;
                const unitsInSlab = Math.min(remaining, slabSize);
                totalRupees += unitsInSlab * paise / 100;
                remaining -= unitsInSlab;
                prevLimit = upto;
            }
            return totalRupees;
        }

        // ============ "Calculation kaise hui" summary box (user-facing) ============
        // Har computeBillXxx() function apne result.explain me plain-Hindi lines
        // deta hai jisme MPERC Tariff Order FY 2026-27 ke exact rate/slab quote
        // karke, is consumer ke input-numbers substitute karke dikhaya jata hai -
        // taaki user ko pata chale ki total kaise nikla, bina code padhe.
        function billFmtRs(v) {
            const n = Math.round(Number(v || 0) * 100) / 100;
            return "₹" + n.toLocaleString("en-IN", { maximumFractionDigits: 2 });
        }
        function billTelescopicExplain(units, slabs) {
            let remaining = Math.max(0, Number(units || 0));
            let prevLimit = 0;
            let total = 0;
            const lines = [];
            for (const [upto, paise] of slabs) {
                if (remaining <= 0) break;
                const slabSize = upto - prevLimit;
                const unitsInSlab = Math.min(remaining, slabSize);
                const subtotal = unitsInSlab * paise / 100;
                total += subtotal;
                const rangeLabel = upto === Infinity ? `in the ${prevLimit}+ units slab` : `in the ${prevLimit === 0 ? 0 : prevLimit + 1}-${upto} units slab`;
                lines.push(`${(Math.round(unitsInSlab * 100) / 100).toLocaleString("en-IN")} unit ${rangeLabel} × ₹${(paise / 100).toFixed(2)}/unit = ${billFmtRs(subtotal)}`);
                remaining -= unitsInSlab;
                prevLimit = upto;
            }
            return { total, lines };
        }
        function billCiteLine(schedule) {
            return `Based on rates of MPERC Retail Supply Tariff Order FY 2026-27, Annexure-2, Tariff Schedule ${schedule}.`;
        }

        // NGB_CONSUMER_LEDGER_CHHAPARA1_JUL2026.xlsx (JUL-2026 bill month) se
        // dobara nikala gaya: sabse zyada rows wali bill-date (30-Jul-2026,
        // 1406 rows) par F.C.A./Energy Charge ratio ~1.65% mila, na ki purana
        // 2.81% (wo pichle ledger/mahine ka tha). DISCOM ye rate har mahine
        // badalta hai (1.1% se 2.2% tak ghatta-badhta paya gaya isi ledger me
        // alag-alag bill-dates par) - isliye ye sirf latest-known approximation
        // hai, agla mahina aane par ledger se dobara nikalna hoga.
        const BILL_FCA_RATIO_OF_ENERGY_CHARGE = 0.0165;
        function billCalcFcaAuto(energyCharge) {
            return Number(energyCharge || 0) * BILL_FCA_RATIO_OF_ENERGY_CHARGE;
        }

        const BILL_ED_RATIO_TABLE_LV1 = [
            [0, 0.085], [10, 0.085], [20, 0.0955], [30, 0.092], [40, 0.0902],
            [50, 0.0934], [70, 0.093], [100, 0.0928], [110, 0.096], [120, 0.0985],
            [130, 0.1004], [140, 0.1024], [150, 0.1038], [160, 0.1053], [170, 0.1068],
            [180, 0.1082], [200, 0.1105], [220, 0.111], [250, 0.1134], [280, 0.1143],
            [300, 0.1153], [320, 0.1159], [400, 0.1175]
        ];
        function lookupBillEdRatioLv1(units) {
            const u = Math.max(0, Number(units || 0));
            const table = BILL_ED_RATIO_TABLE_LV1;
            if (u <= table[0][0]) return table[0][1];
            for (let i = 0; i < table.length - 1; i++) {
                const u1 = table[i][0], r1 = table[i][1], u2 = table[i + 1][0], r2 = table[i + 1][1];
                if (u >= u1 && u <= u2) return u2 === u1 ? r1 : r1 + (r2 - r1) * (u - u1) / (u2 - u1);
            }
            return table[table.length - 1][1];
        }
        function billCalcEdAuto(energyCharge, units, edMode) {
            const ec = Number(energyCharge || 0);
            if (edMode === "EXEMPT") return 0;
            if (edMode === "FLAT") return ec * 0.0935;
            return ec * lookupBillEdRatioLv1(units);
        }

        // MP Govt circular ke anusar Griha Jyoti subsidy ka pravdhan SIRF LV1
        // category me aur SIRF 150 units tak hai (150 se upar koi subsidy
        // nahi, chahe purane bills me average-consumption-based eligibility
        // ki wajah se ledger me kabhi 150+ unit wale bill me bhi subsidy
        // dikhi ho - wo sirf capped/carry-over amount tha, official rule
        // 150-unit cutoff hi hai). Amount ledger ki 8,700+ subsidy>0 wali
        // LV1.2 rows se nikala gaya empirical interpolation-table hai.
        const BILL_LV1_SUBSIDY_TABLE = [
            [0, 0], [10, 20], [20, 73], [30, 126], [40, 178], [50, 232],
            [60, 340], [70, 402], [80, 465], [90, 531], [100, 594],
            [110, 592], [120, 592], [130, 596], [140, 593], [150, 593]
        ];
        function lookupBillLv1Subsidy(units) {
            const u = Math.max(0, Number(units || 0));
            if (u > 150) return 0;
            const table = BILL_LV1_SUBSIDY_TABLE;
            for (let i = 0; i < table.length - 1; i++) {
                const u1 = table[i][0], s1 = table[i][1], u2 = table[i + 1][0], s2 = table[i + 1][1];
                if (u >= u1 && u <= u2) return u2 === u1 ? s1 : s1 + (s2 - s1) * (u - u1) / (u2 - u1);
            }
            return table[table.length - 1][1];
        }

        const BILL_TARIFF_CODES = {
            LV1: [
                { code: "LV1.2U", label: "LV1.2 - Domestic Urban (Urban, Metered)" },
                { code: "LV1.2R", label: "LV1.2 - Domestic Rural (Rural, Metered)" },
                { code: "LV1.1", label: "LV1.1 - B.P.L / Very Low Consumption (0-30 U)" },
                { code: "LV1.UM", label: "LV1 - Unmetered Rural (Unmetered, up to 500W)" }
            ],
            LV2: [
                { code: "LV2.1", label: "LV2.1 - Institution / School / Hospital (<=10kW)" },
                { code: "LV2.1D", label: "LV2.1 - Institution Demand Based (>10kW Demand)" },
                { code: "LV2.2", label: "LV2.2 - Non-Domestic Shop/Office (<=10kW)" },
                { code: "LV2.2D", label: "LV2.2 - Non-Domestic Demand Based (>10kW Demand)" }
            ],
            LV3: [
                { code: "LV3.1", label: "LV3.1 - Municipal Corporation / Municipality / Cantonment" },
                { code: "LV3.2", label: "LV3.2 - Gram Panchayat Water Supply / Street Light" }
            ],
            LV4: [
                { code: "LV4.1A", label: "LV4.1 - LT Micro Industry (<=20HP/15kW, 30% rebate)" },
                { code: "LV4.1B", label: "LV4.1 - LT Industry General (>20HP)" }
            ],
            LV5: [
                { code: "LV5.1", label: "LV5.1 - Agriculture - Metered (Pump/Irrigation)" },
                { code: "LV5.3", label: "LV5.3 - Agriculture Related (Dairy/Poultry/Fishery)" },
                { code: "LV5.4", label: "LV5.4 - Flat Rate (Unmetered Agriculture Pump)" }
            ],
            LV6: [
                { code: "LV6.0", label: "LV6.0 - E-Vehicle / E-Rickshaw Charging Station" }
            ]
        };

        function resetBillCalculator() {
            const catSelect = document.getElementById("bc-category");
            if (catSelect) catSelect.value = "";
            const codeWrap = document.getElementById("bc-tariffcode-wrap");
            if (codeWrap) codeWrap.style.display = "none";
            const codeSelect = document.getElementById("bc-tariffcode");
            if (codeSelect) codeSelect.innerHTML = "";
            const fieldsBox = document.getElementById("bc-fields");
            if (fieldsBox) fieldsBox.innerHTML = "";
            const resultBox = document.getElementById("bc-result");
            if (resultBox) resultBox.innerHTML = "";
            lastBillCalcResult = null;
            lastBillCalcMeta = null;
            const introDesc = document.getElementById("bc-intro-desc");
            if (introDesc) introDesc.style.display = "block";
        }

        function onBillCalculatorCategoryChange() {
            const category = document.getElementById("bc-category")?.value || "";
            const codeWrap = document.getElementById("bc-tariffcode-wrap");
            const codeSelect = document.getElementById("bc-tariffcode");
            const fieldsBox = document.getElementById("bc-fields");
            const resultBox = document.getElementById("bc-result");
            const introDesc = document.getElementById("bc-intro-desc");
            if (resultBox) resultBox.innerHTML = "";
            if (fieldsBox) fieldsBox.innerHTML = "";
            if (introDesc) introDesc.style.display = category ? "none" : "block";
            if (!category || !BILL_TARIFF_CODES[category]) {
                if (codeWrap) codeWrap.style.display = "none";
                if (codeSelect) codeSelect.innerHTML = "";
                return;
            }
            if (codeSelect) {
                codeSelect.innerHTML = `<option value="">-- Select Tariff Code --</option>` +
                    BILL_TARIFF_CODES[category].map((c) => `<option value="${c.code}">${escapeHtml(c.label)}</option>`).join("");
            }
            if (codeWrap) codeWrap.style.display = "block";
            renderBillCalculatorFields();
        }

        const billCalcSelectStyle = "width:100%; height:48px; margin-top:10px; display:block; border:1.5px solid #f9a8d4; border-radius:14px; padding:0 12px; font-size:0.78rem; font-weight:900; color:#0f172a; background:#ffffff;";
        const billCalcInputStyle = "width:100%; height:48px; margin-top:10px; display:block; border:1.5px solid #f9a8d4; border-radius:14px; padding:0 12px; font-size:0.85rem; font-weight:900; color:#0f172a; background:#ffffff; text-align:center;";
        const billCalcLabelStyle = "display:block; font-size:0.62rem; font-weight:900; color:#1d4ed8; margin-top:10px;";

        function billCalcUnitsField(placeholder) {
            return `<label style="${billCalcLabelStyle}">Total Unit (Consumption)</label>
                <input id="bc-units" type="number" inputmode="decimal" class="ivrs-input" style="${billCalcInputStyle}" placeholder="${placeholder}">`;
        }
        function billCalcLoadField(labelText, placeholder) {
            return `<label style="${billCalcLabelStyle}">${labelText}</label>
                <input id="bc-load" type="number" inputmode="decimal" class="ivrs-input" style="${billCalcInputStyle}" placeholder="${placeholder}">`;
        }
        function billCalcAreaField() {
            return `<label style="${billCalcLabelStyle}">Area Type</label>
                <select id="bc-area" class="ivrs-input" style="${billCalcSelectStyle}">
                    <option value="URBAN">Urban</option>
                    <option value="RURAL">Rural</option>
                </select>`;
        }
        function billCalcBillingDaysField() {
            return `<label style="${billCalcLabelStyle}">Billing Period (Days) - number of days in this month's reading cycle</label>
                <input id="bc-billing-days" type="number" inputmode="numeric" class="ivrs-input" style="${billCalcInputStyle}" placeholder="e.g. 30" value="30">`;
        }
        function billCalcSubsidyField() {
            return `<label style="${billCalcLabelStyle}">Griha Jyoti Subsidy Applicable?</label>
                <select id="bc-subsidy-toggle" class="ivrs-input" style="${billCalcSelectStyle}">
                    <option value="YES">YES (Eligible)</option>
                    <option value="NO">NO (Not Eligible)</option>
                </select>`;
        }

        function renderBillCalculatorFields() {
            const tariffCode = document.getElementById("bc-tariffcode")?.value || "";
            const fieldsBox = document.getElementById("bc-fields");
            const resultBox = document.getElementById("bc-result");
            if (resultBox) resultBox.innerHTML = "";
            if (!fieldsBox) return;
            if (!tariffCode) { fieldsBox.innerHTML = ""; return; }

            if (tariffCode === "LV1.2U" || tariffCode === "LV1.2R") {
                fieldsBox.innerHTML = billCalcUnitsField("e.g. 120") + billCalcBillingDaysField() + billCalcSubsidyField();
            } else if (tariffCode === "LV1.1") {
                fieldsBox.innerHTML = billCalcUnitsField("between 0 and 30") + billCalcSubsidyField();
            } else if (tariffCode === "LV1.UM") {
                fieldsBox.innerHTML = `<div style="${billCalcLabelStyle} margin-top:4px;">This connection is billed at a flat 75 units/month (calculated automatically).</div>` + billCalcSubsidyField();
            } else if (tariffCode === "LV2.1" || tariffCode === "LV2.2") {
                fieldsBox.innerHTML = billCalcAreaField() + billCalcLoadField("Sanctioned Load (kW, up to 10kW)", "e.g. 2") + billCalcUnitsField("e.g. 80");
            } else if (tariffCode === "LV2.1D" || tariffCode === "LV2.2D") {
                fieldsBox.innerHTML = billCalcAreaField() + billCalcLoadField("Billing Demand (kW)", "e.g. 15") + billCalcUnitsField("e.g. 2000");
            } else if (tariffCode === "LV3.1" || tariffCode === "LV3.2") {
                fieldsBox.innerHTML = billCalcLoadField("Sanctioned Load (kW)", "e.g. 5") + billCalcUnitsField("e.g. 300");
            } else if (tariffCode === "LV4.1A" || tariffCode === "LV4.1B") {
                fieldsBox.innerHTML = billCalcAreaField() + billCalcLoadField("Contract Demand (kW)", "e.g. 10") + billCalcUnitsField("e.g. 558");
            } else if (tariffCode === "LV5.1") {
                fieldsBox.innerHTML = billCalcLoadField("Sanctioned Load (HP)", "e.g. 5") + billCalcUnitsField("e.g. 350");
            } else if (tariffCode === "LV5.3") {
                fieldsBox.innerHTML = billCalcAreaField() + billCalcLoadField("Connected Load (HP, up to 25HP)", "e.g. 10") + billCalcUnitsField("e.g. 400");
            } else if (tariffCode === "LV5.4") {
                fieldsBox.innerHTML = `
                    <label style="${billCalcLabelStyle}">Sanctioned Load (HP)</label>
                    <input id="bc-load" type="number" inputmode="decimal" class="ivrs-input" style="${billCalcInputStyle}" placeholder="e.g. 5">
                    <label style="${billCalcLabelStyle}">Phase</label>
                    <select id="bc-phase" class="ivrs-input" style="${billCalcSelectStyle}">
                        <option value="3P">Three Phase</option>
                        <option value="1P">Single Phase</option>
                    </select>
                    <label style="${billCalcLabelStyle}">Season</label>
                    <select id="bc-season" class="ivrs-input" style="${billCalcSelectStyle}">
                        <option value="APR_SEP">April - September</option>
                        <option value="OCT_MAR">October - March</option>
                    </select>
                `;
            } else if (tariffCode === "LV6.0") {
                fieldsBox.innerHTML = billCalcUnitsField("e.g. 500") + `
                    <label style="${billCalcLabelStyle}">Is charging mostly done during Solar Hours (9AM-5PM)?</label>
                    <select id="bc-ev-timing" class="ivrs-input" style="${billCalcSelectStyle}">
                        <option value="NONSOLAR">Non-Solar Hours (20% surcharge)</option>
                        <option value="SOLAR">Solar Hours 9AM-5PM (20% rebate)</option>
                        <option value="MIX">Mix (normal rate, average)</option>
                    </select>
                `;
            } else {
                fieldsBox.innerHTML = "";
            }
        }

        function computeBillLv1Metered(units, area, subsidyApplicable, billingDays) {
            // Tariff Order ke anusar agar billing cycle 30 din ka na ho to
            // energy/fixed charge ki slab-boundaries (50/150/300) proportionally
            // prorate hoti hain (jaise 36-din cycle me 50->60, 150->180, 300->360).
            const days = Number(billingDays || 30) || 30;
            const ratio = days / 30;
            const b1 = 50 * ratio, b2 = 150 * ratio, b3 = 300 * ratio;
            const explain = [billCiteLine("LV-1.2 (Domestic, Metered)")];
            if (days !== 30) explain.push(`Billing cycle is ${days} days (${days > 30 ? "more" : "less"} than 30 days), so slab boundaries are prorated as per Note-2: 50→${b1.toFixed(1)}, 150→${b2.toFixed(1)}, 300→${b3.toFixed(1)} units.`);
            const et = billTelescopicExplain(units, [[b1, 471], [b2, 567], [b3, 705], [Infinity, 724]]);
            const energyCharge = et.total;
            explain.push(`Energy Charge (telescopic, ${area === "URBAN" ? "Urban" : "Rural"}): ${et.lines.join(" + ")} → Total = ${billFmtRs(energyCharge)}.`);
            let fixedCharge;
            if (units <= b1) { fixedCharge = area === "URBAN" ? 81 : 67; explain.push(`Fixed Charge: ${units} units ≤ ${b1.toFixed(0)}, so flat ${billFmtRs(fixedCharge)} per connection (${area === "URBAN" ? "Urban" : "Rural"} slab).`); }
            else if (units <= b2) { fixedCharge = area === "URBAN" ? 134 : 111; explain.push(`Fixed Charge: ${units} units, in the ${b1.toFixed(0)}-${b2.toFixed(0)} slab, so flat ${billFmtRs(fixedCharge)} per connection.`); }
            else {
                const blocksOf0p1kW = Math.ceil(units / 15);
                fixedCharge = blocksOf0p1kW * (area === "URBAN" ? 30 : 28);
                explain.push(`Fixed Charge: ${units} units > ${b2.toFixed(0)}, as per Note-1 every 15 units (or part thereof) = 0.1kW: ceil(${units}/15) = ${blocksOf0p1kW} block × ₹${area === "URBAN" ? 30 : 28}/block = ${billFmtRs(fixedCharge)}.`);
            }
            const fca = billCalcFcaAuto(energyCharge);
            explain.push(`F.C.A. (auto): F.C.A. is not part of the Tariff Order and is notified separately by the DISCOM every month - current ratio taken from the ledger is ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "PROGRESSIVE");
            explain.push(`Electricity Duty: State Govt notification (not in Tariff Order) - ${units}% of Energy Charge as per progressive slab for ${(lookupBillEdRatioLv1(units) * 100).toFixed(2)} units = ${billFmtRs(electricityDuty)}.`);
            const subsidy = subsidyApplicable ? lookupBillLv1Subsidy(units) : 0;
            if (subsidyApplicable && units <= 150) explain.push(`Griha Jyoti Subsidy: As per MP Govt circular, available on LV1 up to 150 units - estimated ${billFmtRs(subsidy)} on this consumption.`);
            else if (subsidyApplicable) explain.push(`Griha Jyoti Subsidy: ${units} units > 150, as per MP Govt circular subsidy is only up to 150 units, so ₹0.`);
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty", electricityDuty],
                ["Subsidy (Griha Jyoti)", -subsidy]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty - subsidy;
            explain.push(`Total = Energy Charge + F.C.A. + Fixed Charge + Electricity Duty − Subsidy = ${et.lines.length ? billFmtRs(energyCharge) : "₹0"} + ${billFmtRs(fca)} + ${billFmtRs(fixedCharge)} + ${billFmtRs(electricityDuty)} − ${billFmtRs(subsidy)} = ${billFmtRs(total)} ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv1Bpl(units, subsidyApplicable) {
            const cappedUnits = Math.min(30, Math.max(0, units));
            const energyCharge = cappedUnits * 372 / 100;
            const fixedCharge = 0;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, cappedUnits, "PROGRESSIVE");
            const subsidy = subsidyApplicable ? lookupBillLv1Subsidy(cappedUnits) : 0;
            const explain = [
                billCiteLine("LV-1.1 (BPL / ≤30 units, ≤100W load)"),
                `Energy Charge: ${cappedUnits} units × ₹3.72/unit = ${billFmtRs(energyCharge)}. Fixed Charge: NIL (tariff order gives ₹0 for this slab).`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge (ledger-based current rate) = ${billFmtRs(fca)}.`,
                `Electricity Duty: ${(lookupBillEdRatioLv1(cappedUnits) * 100).toFixed(2)}% of Energy Charge (progressive LV1 slab) = ${billFmtRs(electricityDuty)}.`
            ];
            if (subsidyApplicable) explain.push(`Griha Jyoti Subsidy (within the ≤150u LV1 rule): ${billFmtRs(subsidy)}.`);
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty", electricityDuty],
                ["Subsidy (Griha Jyoti)", -subsidy]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty - subsidy;
            explain.push(`Total = ${billFmtRs(energyCharge)} + ${billFmtRs(fca)} + ₹0 + ${billFmtRs(electricityDuty)} − ${billFmtRs(subsidy)} ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv1Unmetered(subsidyApplicable) {
            const units = 75;
            const energyCharge = units * 574 / 100;
            const fixedCharge = 122;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "PROGRESSIVE");
            const subsidy = subsidyApplicable ? lookupBillLv1Subsidy(units) : 0;
            const explain = [
                billCiteLine("LV-1 (iii) Unmetered rural domestic, ≤500W load"),
                `As per tariff order, such connections are billed at a flat 75 units/month: 75 × ₹5.74/unit = ${billFmtRs(energyCharge)}. Fixed Charge = ₹122 per connection (flat).`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: ${(lookupBillEdRatioLv1(units) * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(electricityDuty)}.`
            ];
            if (subsidyApplicable) explain.push(`Griha Jyoti Subsidy (75 units, within the ≤150u rule): ${billFmtRs(subsidy)}.`);
            const components = [
                ["Assessed Units", units],
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty", electricityDuty],
                ["Subsidy (Griha Jyoti)", -subsidy]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty - subsidy;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv21(units, area, load) {
            const energyCharge = units * 700 / 100;
            const fixedCharge = billCalcRoundLoad(load) * (area === "URBAN" ? 172 : 141);
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine("LV-2.1 (Institution/School/Hospital, ≤10kW sanctioned-load-based)"),
                `Energy Charge: ${units} units × ₹7.00/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: ${billCalcRoundLoad(load)} kW (round) × ₹${area === "URBAN" ? 172 : 141}/kW (${area === "URBAN" ? "Urban" : "Rural"}) = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: ED is fully EXEMPT on LV2.1 (ledger-verified), so ₹0.`,
                `Total = ${billFmtRs(energyCharge)} + ${billFmtRs(fca)} + ${billFmtRs(fixedCharge)} + ₹0 ≈ ₹${billRoundOff(energyCharge + fca + fixedCharge + electricityDuty).toLocaleString("en-IN")}.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty (Exempt)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv21Demand(units, area, demand) {
            const energyCharge = units * 720 / 100;
            const fixedCharge = billCalcRoundLoad(demand) * (area === "URBAN" ? 291 : 251);
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine("LV-2.1 Demand based (Institution, Connected load >10kW)"),
                `Energy Charge: ${units} units × ₹7.20/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge (Demand): ${billCalcRoundLoad(demand)} kW (rounded) × ₹${area === "URBAN" ? 291 : 251}/kW (${area === "URBAN" ? "Urban" : "Rural"}, the alternate "per kVA" option is not included in this calculator) = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: EXEMPT (LV2.1) = ₹0.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge (Demand)", fixedCharge],
                ["Electricity Duty (Exempt)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv22(units, area, load) {
            const energyRatePaise = units <= 50 ? 680 : 830;
            const fixedRatePerKw = units <= 50 ? (area === "URBAN" ? 98 : 83) : (area === "URBAN" ? 154 : 133);
            const energyCharge = units * energyRatePaise / 100;
            const fixedCharge = billCalcRoundLoad(load) * fixedRatePerKw;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "FLAT");
            const explain = [
                billCiteLine("LV-2.2 (Non-domestic shop/office, ≤10kW sanctioned-load-based)"),
                `${units} units is ${units <= 50 ? "≤ 50" : "> 50"}, so the rate of this slab applies: Energy Charge = ${units} × ₹${(energyRatePaise / 100).toFixed(2)}/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: ${billCalcRoundLoad(load)} kW × ₹${fixedRatePerKw}/kW (${area === "URBAN" ? "Urban" : "Rural"}, same slab) = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: LV2.2 par ~9.35% flat (ledger-verified) = ${billFmtRs(electricityDuty)}.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv22Demand(units, area, demand) {
            const energyCharge = units * 740 / 100;
            const fixedCharge = billCalcRoundLoad(demand) * (area === "URBAN" ? 312 : 230);
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "FLAT");
            const explain = [
                billCiteLine("LV-2.2 Demand based (Connected load >10kW)"),
                `Energy Charge: ${units} units × ₹7.40/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge (Demand): ${billCalcRoundLoad(demand)} kW × ₹${area === "URBAN" ? 312 : 230}/kW (${area === "URBAN" ? "Urban" : "Rural"}) = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: ~9.35% flat (LV2.2) = ${billFmtRs(electricityDuty)}.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge (Demand)", fixedCharge],
                ["Electricity Duty", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv3(units, load, isMunicipal) {
            const energyRatePaise = isMunicipal ? 638 : 610;
            const fixedRatePerKw = isMunicipal ? 389 : 208;
            const energyCharge = units * energyRatePaise / 100;
            const fixedCharge = load * fixedRatePerKw;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine(isMunicipal ? "LV-3.1 (Municipal Corp/Council/Cantonment)" : "LV-3.2 (Gram Panchayat water supply/street light)"),
                `Energy Charge: ${units} units × ₹${(energyRatePaise / 100).toFixed(2)}/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: ${load} kW × ₹${fixedRatePerKw}/kW = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: LV3 par poori tarah EXEMPT (ledger-verified) = ₹0.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty (Exempt)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv4(units, area, demand, discounted) {
            let energyRatePaise = 705;
            let fixedRatePerKw = area === "URBAN" ? 336 : 221;
            if (discounted) { energyRatePaise *= 0.7; fixedRatePerKw *= 0.7; }
            const energyCharge = units * energyRatePaise / 100;
            // LV4 (Contract Demand based) me ledger analysis me pata chala ki
            // billed demand = floor(Contract Demand, min 1) - normal (no MD
            // exceedance) case me ye 93% match deta hai. Agar actual Maximum
            // Demand contract se zyada nikle to alag 120%/130% surcharge lagta
            // hai jo is calculator me shamil nahi hai (kyoki future MD pehle
            // se pata nahi hota).
            const billedDemand = billCalcFloorLoad(demand);
            const fixedCharge = billedDemand * fixedRatePerKw;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "FLAT");
            const explain = [
                billCiteLine(`LV-4.1 (LT Industrial, Demand-based - ${discounted ? "≤20HP/15kW, 30% chhoot" : ">20HP, normal rate"})`),
                `Energy Charge: ${units} units × ₹${(energyRatePaise / 100).toFixed(2)}/unit${discounted ? " (after 30% rebate on normal ₹7.05)" : ""} = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge (Demand): As per Tariff Order, Fixed Charge in LT Industrial is based on Contract Demand, not units (Demand-based tariff is mandatory) - ${billedDemand} kW × ₹${fixedRatePerKw.toFixed(0)}/kW (${area === "URBAN" ? "Urban" : "Rural"}${discounted ? ", after 30% rebate" : ""}) = ${billFmtRs(fixedCharge)}. So this component can be large even for low units.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: LV4 par ~9.3% flat (ledger-verified) = ${billFmtRs(electricityDuty)}.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge (Demand)", fixedCharge],
                ["Electricity Duty", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total = Energy + F.C.A. + Fixed(Demand) + ED = ${billFmtRs(energyCharge)} + ${billFmtRs(fca)} + ${billFmtRs(fixedCharge)} + ${billFmtRs(electricityDuty)} ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv51(units, load) {
            const fixedRatePerHp = units <= 300 ? 77 : (units <= 750 ? 93 : 101);
            const et = billTelescopicExplain(units, [[300, 533], [750, 636], [Infinity, 664]]);
            const energyCharge = et.total;
            const fixedCharge = load * fixedRatePerHp;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine("LV-5.1 (Agriculture pump - Metered)"),
                `Energy Charge (telescopic): ${et.lines.join(" + ")} → Total = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: Rate of ₹${fixedRatePerHp}/HP is decided as per the slab of total ${units} units; ${load} HP × ₹${fixedRatePerHp}/HP = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: LV5 par poori tarah EXEMPT = ₹0.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty (Exempt)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv53(units, area, load) {
            const energyRatePaise = area === "URBAN" ? 589 : 572;
            const fixedRatePerHp = area === "URBAN" ? 139 : 108;
            const energyCharge = units * energyRatePaise / 100;
            const fixedCharge = load * fixedRatePerHp;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine("LV-5.3 (Fisheries/Poultry/Dairy, ≤25HP connected load)"),
                `Energy Charge: ${units} units × ₹${(energyRatePaise / 100).toFixed(2)}/unit (${area === "URBAN" ? "Urban" : "Rural"}) = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: ${load} HP × ₹${fixedRatePerHp}/HP = ${billFmtRs(fixedCharge)}.`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: EXEMPT (LV5) = ₹0.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty (Exempt)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function computeBillLv54(load, phase, season) {
            const perHp = season === "OCT_MAR" ? (phase === "1P" ? 180 : 170) : 95;
            const units = load * perHp;
            const result = computeBillLv51(units, load);
            result.components.unshift(["Assessed Units", units]);
            result.explain.unshift(billCiteLine("LV-5.4 (Flat rate/Unmetered agri pump) - as per assessment norms para 1.2") + ` Assessed Units = ${load} HP × ${perHp} units/HP (${phase === "1P" ? "Single" : "Three"} Phase, ${season === "OCT_MAR" ? "Oct-March" : "April-Sept"}) = ${units} units. After this the bill is made at LV-5.1 rates:`);
            return result;
        }

        function computeBillLv6(units, timing) {
            let energyRatePaise = 744;
            if (timing === "SOLAR") energyRatePaise *= 0.8;
            else if (timing === "NONSOLAR") energyRatePaise *= 1.2;
            const energyCharge = units * energyRatePaise / 100;
            const fixedCharge = 0;
            const fca = billCalcFcaAuto(energyCharge);
            const electricityDuty = billCalcEdAuto(energyCharge, units, "EXEMPT");
            const explain = [
                billCiteLine("LV-6.0 (EV/E-Rickshaw Charging Station)"),
                `Base rate ₹7.44/unit ${timing === "SOLAR" ? "during Solar Hours (9AM-5PM) with 20% rebate" : timing === "NONSOLAR" ? "during Non-Solar Hours with 20% surcharge" : "(Mix, average rate)"}: ${units} units × ₹${(energyRatePaise / 100).toFixed(2)}/unit = ${billFmtRs(energyCharge)}.`,
                `Fixed Charge: NIL (no minimum charge applicable).`,
                `F.C.A. (auto): ${(BILL_FCA_RATIO_OF_ENERGY_CHARGE * 100).toFixed(2)}% of Energy Charge = ${billFmtRs(fca)}.`,
                `Electricity Duty: tariff order does not explicitly mention ED for this category, assumed EXEMPT (unconfirmed) = ₹0.`
            ];
            const components = [
                ["Energy Charge", energyCharge],
                ["F.C.A. (auto)", fca],
                ["Fixed Charge", fixedCharge],
                ["Electricity Duty (Exempt, unconfirmed)", electricityDuty]
            ];
            const total = energyCharge + fca + fixedCharge + electricityDuty;
            explain.push(`Total ≈ ₹${billRoundOff(total).toLocaleString("en-IN")}.`);
            return { components, total: billRoundOff(total), explain };
        }

        function calculateBillEstimate() {
            const tariffCode = document.getElementById("bc-tariffcode")?.value || "";
            const resultBox = document.getElementById("bc-result");
            if (!resultBox) return;
            if (!tariffCode) { showToast("Please select Category and Tariff Code first", false); return; }
            const units = Number(document.getElementById("bc-units")?.value || 0);
            const load = Number(document.getElementById("bc-load")?.value || 0);
            const area = document.getElementById("bc-area")?.value === "RURAL" ? "RURAL" : "URBAN";
            const subsidyApplicable = document.getElementById("bc-subsidy-toggle")?.value === "YES";
            const billingDays = Number(document.getElementById("bc-billing-days")?.value || 30) || 30;
            let result;
            if (tariffCode === "LV1.2U") result = computeBillLv1Metered(units, "URBAN", subsidyApplicable, billingDays);
            else if (tariffCode === "LV1.2R") result = computeBillLv1Metered(units, "RURAL", subsidyApplicable, billingDays);
            else if (tariffCode === "LV1.1") result = computeBillLv1Bpl(units, subsidyApplicable);
            else if (tariffCode === "LV1.UM") result = computeBillLv1Unmetered(subsidyApplicable);
            else if (tariffCode === "LV2.1") result = computeBillLv21(units, area, load);
            else if (tariffCode === "LV2.1D") result = computeBillLv21Demand(units, area, load);
            else if (tariffCode === "LV2.2") result = computeBillLv22(units, area, load);
            else if (tariffCode === "LV2.2D") result = computeBillLv22Demand(units, area, load);
            else if (tariffCode === "LV3.1") result = computeBillLv3(units, load, true);
            else if (tariffCode === "LV3.2") result = computeBillLv3(units, load, false);
            else if (tariffCode === "LV4.1A") result = computeBillLv4(units, area, load, true);
            else if (tariffCode === "LV4.1B") result = computeBillLv4(units, area, load, false);
            else if (tariffCode === "LV5.1") result = computeBillLv51(units, load);
            else if (tariffCode === "LV5.3") result = computeBillLv53(units, area, load);
            else if (tariffCode === "LV5.4") {
                const phase = document.getElementById("bc-phase")?.value || "3P";
                const season = document.getElementById("bc-season")?.value || "APR_SEP";
                result = computeBillLv54(load, phase, season);
            } else if (tariffCode === "LV6.0") {
                const timing = document.getElementById("bc-ev-timing")?.value || "MIX";
                result = computeBillLv6(units, timing);
            } else {
                return;
            }
            // PDF me Devanagari font support nahi hai (jsPDF default font), isliye
            // input-summary sirf ASCII/romanized text me capture karte hain -
            // category/tariff-code dropdown ke Hindi/Devanagari options se text
            // nikal ke stripDevanagariForPdf() se saaf kar dete hain.
            const categorySelect = document.getElementById("bc-category");
            const tariffSelect = document.getElementById("bc-tariffcode");
            const fieldsBox = document.getElementById("bc-fields");
            const inputRows = [
                ["Category", stripDevanagariForPdf(categorySelect?.options[categorySelect.selectedIndex]?.text || tariffCode)],
                ["Tariff Code", stripDevanagariForPdf(tariffSelect?.options[tariffSelect.selectedIndex]?.text || tariffCode)]
            ];
            (fieldsBox ? Array.from(fieldsBox.querySelectorAll("label")) : []).forEach((lbl) => {
                const field = lbl.nextElementSibling;
                if (!field) return;
                let val = "";
                if (field.tagName === "SELECT") val = field.options[field.selectedIndex]?.text || field.value;
                else if (field.tagName === "INPUT") val = field.value;
                else return;
                inputRows.push([stripDevanagariForPdf(lbl.textContent), stripDevanagariForPdf(val)]);
            });
            lastBillCalcResult = result;
            lastBillCalcMeta = { inputRows };
            resultBox.innerHTML = renderBillCalculatorResultHtml(result);
        }

        let lastBillCalcResult = null;
        let lastBillCalcMeta = null;

        function stripDevanagariForPdf(text) {
            return String(text || "")
                .replace(/[ऀ-ॿ]+/g, "")
                .replace(/\(\s*\)/g, "")
                .replace(/\s{2,}/g, " ")
                .replace(/\s+([,)])/g, "$1")
                .replace(/-\s*-/g, "-")
                .replace(/^[\s\-]+|[\s\-]+$/g, "")
                .trim();
        }

        function downloadBillCalculatorPdf() {
            if (!lastBillCalcResult) { showToast("Please calculate the bill first", false); return; }
            if (!window.jspdf?.jsPDF) { showToast("PDF library could not be loaded", false); return; }
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const consumerName = document.getElementById("bc-consumer-name")?.value?.trim() || "";
            scPdfHeader_(doc, { title: "MONTHLY ELECTRICITY BILL ESTIMATE", lines: [], color: SC_PDF_THEME.revenue }); // SC PDF KIT (downloadBillCalculatorPdf) - Generated footer me
            let nextY = 20; // SC PDF KIT header ke niche
            if (consumerName) {
                doc.setFontSize(11);
                doc.setTextColor(0);
                doc.text(`Consumer Name: ${consumerName}`, 105, nextY, { align: "center" });
                nextY += 8;
            }
            doc.autoTable({
                startY: nextY,
                head: [["INPUT PARAMETER", "VALUE"]],
                body: (lastBillCalcMeta?.inputRows || []).filter(([, v]) => v),
                theme: "grid",
                headStyles: { fillColor: [236, 72, 153], halign: "center" },
                columnStyles: { 0: { halign: "left" }, 1: { halign: "right" } }
            });
            doc.autoTable({
                startY: doc.lastAutoTable.finalY + 6,
                head: [["COMPONENT", "AMOUNT (Rs.)"]],
                body: lastBillCalcResult.components.map(([label, value]) => [label, billRoundOff(value).toLocaleString("en-IN")]),
                foot: [["ESTIMATED MONTH BILL", lastBillCalcResult.total.toLocaleString("en-IN")]],
                theme: "grid",
                headStyles: { fillColor: [236, 72, 153], halign: "center" },
                columnStyles: { 0: { halign: "left" }, 1: { halign: "right" } },
                footStyles: { fillColor: [253, 242, 248], textColor: [157, 23, 77], fontStyle: "bold", halign: "right" }
            });
            // "Calculation kaise hui" step-by-step box - screen ke explain-box jaisa
            // hi content, PDF me bhi Download ke baad user ko dikhe isliye. jsPDF ka
            // default font ₹ aur Devanagari support nahi karta, isliye Rs. use kiya
            // hai aur stripDevanagariForPdf() se saaf kiya hai.
            const explainLines = (lastBillCalcResult.explain || []).map((line) => stripDevanagariForPdf(line.replace(/₹/g, "Rs.")));
            if (explainLines.length) {
                const citationLine = explainLines[0];
                const totalIdx = explainLines.map((l) => /^Total\b/i.test(l)).lastIndexOf(true);
                const totalLine = totalIdx >= 0 ? explainLines[totalIdx] : null;
                const stepLines = explainLines.slice(1, totalIdx >= 0 ? totalIdx : undefined);
                doc.autoTable({
                    startY: doc.lastAutoTable.finalY + 8,
                    head: [["HOW WAS IT CALCULATED? (Step-by-step)"]],
                    body: [
                        [{ content: citationLine, styles: { fontStyle: "italic", textColor: [30, 64, 175], fillColor: [239, 246, 255] } }],
                        ...stepLines.map((l, i) => [`${i + 1}.  ${l}`])
                    ],
                    foot: totalLine ? [[totalLine.replace(/^Total\s*/, "TOTAL ")]] : undefined,
                    theme: "grid",
                    tableWidth: 182,
                    headStyles: { fillColor: [29, 78, 216], halign: "left", fontSize: 10 },
                    styles: { fontSize: 8, cellPadding: 3, halign: "left", textColor: [51, 65, 85], overflow: "linebreak", cellWidth: "wrap" },
                    columnStyles: { 0: { cellWidth: 182 } },
                    footStyles: { fillColor: [253, 242, 248], textColor: [157, 23, 77], fontStyle: "bold", halign: "left", fontSize: 7.5, cellPadding: 4 }
                });
            }
            doc.setFontSize(7);
            doc.setTextColor(140);
            doc.text("This is an approximate estimate (PF surcharge/seasonal/DTR-metered not included). Arrear/Surcharge is not included in this total.", 14, doc.lastAutoTable.finalY + 10);
            savePdfDocumentForDevice(doc, `Electricity_Bill_Estimate_${consumerName ? consumerName.replace(/[^a-zA-Z0-9]/g, "_") + "_" : ""}${Date.now()}.pdf`);
        }

        function renderBillCalculatorResultHtml(result) {
            const unitRowLabels = ["Assessed/Billed Units", "Assessed Units"];
            const rows = result.components.map(([label, value]) => {
                const isUnitRow = unitRowLabels.includes(label);
                const isNegative = value < 0;
                const color = isNegative ? "#166534" : "#0f172a";
                const displayValue = isUnitRow
                    ? `${billRoundOff(value).toLocaleString("en-IN")} units`
                    : (isNegative ? "-₹" : "₹") + Math.abs(billRoundOff(value)).toLocaleString("en-IN");
                return `<div class="summary-table-row" style="grid-template-columns: 1.4fr 1fr;"><div>${escapeHtml(label)}</div><div class="font-black" style="color:${color};">${displayValue}</div></div>`;
            }).join("");
            return `
                <div class="summary-wrapper">
                    <div class="summary-table-header" style="grid-template-columns: 1.4fr 1fr;"><div>COMPONENT</div><div>AMOUNT</div></div>
                    ${rows}
                </div>
                <div class="summary-footer" style="margin-top:10px;">
                    <div class="font-black text-slate-800 text-center">ESTIMATED MONTH BILL</div>
                    <div style="text-align:center; font-size:1.4rem; font-weight:950; color:#9d174d; margin-top:6px;">₹${result.total.toLocaleString("en-IN")}</div>
                </div>
                <label style="${billCalcLabelStyle}">Consumer Name (Optional) - to identify the report</label>
                <input id="bc-consumer-name" type="text" class="ivrs-input" style="${billCalcInputStyle}" placeholder="e.g. Ramesh Kumar">
                <button class="dashboard-btn" style="width:100%; margin-top:12px; background:linear-gradient(135deg,#ef4444 0%,#b91c1c 100%); color:#ffffff !important; font-size:0.8rem; padding:14px;" onclick="downloadBillCalculatorPdf()">DOWNLOAD PDF</button>
                <div style="font-size:0.58rem; font-weight:800; color:#94a3b8; text-align:center; margin-top:10px; line-height:1.5;">This is an approximate estimate (PF surcharge/seasonal/DTR-metered not included). Arrear/Surcharge is not included in this total.</div>
                ${renderBillCalcExplainBox(result)}
            `;
        }

        // Har explain-line ka format zyadatar "Label: detail text" hota hai
        // (jaise computeBillXxx functions me banaya gaya) - isko todke label ko
        // alag rang/bold me dikhane ke liye chota parser.
        function billExplainSplitLabel(line) {
            const m = line.match(/^([A-Za-z0-9À-ž.()\/ ]{2,42}):\s*(.*)$/s);
            if (!m) return null;
            return { label: m[1].trim(), detail: m[2].trim() };
        }

        function renderBillCalcExplainBox(result) {
            const lines = (result.explain || []).slice();
            if (!lines.length) return "";

            // Pehli line hamesha tariff-order citation hoti hai (billCiteLine se
            // shuru hoti hai) - use header ke turant niche ek alag "source" strip
            // me dikhate hain.
            const citationLine = lines[0];
            const totalIdx = lines.map((l) => /^Total\b/i.test(l)).lastIndexOf(true);
            const totalLine = totalIdx >= 0 ? lines[totalIdx] : null;
            const stepLines = lines.slice(1, totalIdx >= 0 ? totalIdx : undefined);

            const stepIcons = ["⚡", "🔌", "➕", "🏛️", "🎁", "📐", "🔢", "➗"];
            const stepsHtml = stepLines.map((line, i) => {
                const parsed = billExplainSplitLabel(line);
                const icon = stepIcons[i % stepIcons.length];
                const numBadge = `<div style="flex-shrink:0; width:22px; height:22px; border-radius:50%; background:linear-gradient(135deg,#dbeafe,#bfdbfe); color:#1d4ed8; font-weight:950; font-size:0.6rem; display:flex; align-items:center; justify-content:center; margin-top:1px;">${i + 1}</div>`;
                const body = parsed
                    ? `<span style="color:#1d4ed8; font-weight:950;">${escapeHtml(parsed.label)}:</span> <span style="color:#334155; font-weight:700;">${escapeHtml(parsed.detail)}</span>`
                    : `<span style="color:#334155; font-weight:700;">${escapeHtml(line)}</span>`;
                return `
                    <div style="display:flex; gap:10px; align-items:flex-start; padding:10px 16px; ${i < stepLines.length - 1 ? "border-bottom:1px dashed #e2e8f0;" : ""}">
                        ${numBadge}
                        <div style="flex:1; font-size:0.66rem; line-height:1.55;">${body}</div>
                        <div style="flex-shrink:0; font-size:0.85rem; opacity:0.55; margin-top:1px;">${icon}</div>
                    </div>`;
            }).join("");

            const totalHtml = totalLine ? `
                <div style="background:linear-gradient(135deg,#fdf2f8,#fce7f3); border-top:1.5px dashed #f9a8d4; padding:12px 16px;">
                    <div style="font-size:0.6rem; font-weight:950; color:#9d174d; letter-spacing:0.4px; margin-bottom:3px;">FINAL TOTAL FORMULA</div>
                    <div style="font-size:0.68rem; font-weight:800; color:#831843; line-height:1.6;">${escapeHtml(totalLine.replace(/^Total\s*/, ""))}</div>
                </div>` : "";

            return `
                <div style="margin-top:16px; border-radius:16px; overflow:hidden; border:1.5px solid #bfdbfe; box-shadow:0 2px 10px rgba(30,64,175,0.10);">
                    <div style="background:linear-gradient(135deg,#1d4ed8 0%,#1e3a8a 100%); padding:12px 16px; display:flex; align-items:center; gap:8px;">
                        <span style="font-size:1rem;">📖</span>
                        <span style="color:#ffffff; font-weight:950; font-size:0.76rem; letter-spacing:0.2px;">HOW WAS IT CALCULATED?</span>
                        <span style="color:#bfdbfe; font-weight:800; font-size:0.58rem; margin-left:auto; background:rgba(255,255,255,0.15); padding:3px 8px; border-radius:999px;">STEP-BY-STEP</span>
                    </div>
                    <div style="background:#eff6ff; padding:10px 16px; font-size:0.62rem; font-weight:800; color:#1e40af; line-height:1.5; border-bottom:1px solid #bfdbfe; display:flex; gap:6px;">
                        <span>📘</span><span>${escapeHtml(citationLine)}</span>
                    </div>
                    <div style="background:#ffffff;">
                        ${stepsHtml}
                    </div>
                    ${totalHtml}
                </div>
            `;
        }
// =====================================================================
// MASTER RECONCILIATION FETCHER (PROGRESS REPORT FIX)
// =====================================================================
async function fetchRevenueCategoryReconciliation(dcName, periodMode, periodValue, dcNamesList) {
    try {
        const payload = {
            action: "getRevenueCategoryReconciliation",
            period_mode: periodMode || "date",
            period_value: periodValue
        };
        if (dcName) {
            payload.dc_name = dcName;
        } else if (dcNamesList && dcNamesList.length) {
            payload.dc_names = Array.isArray(dcNamesList) ? dcNamesList.join(",") : dcNamesList;
        }
        const res = await fetch(MASTER_SECURE_API_URL, {
            method: "POST",
            body: JSON.stringify(payload)
        }).then(r => r.json());
        if (res && res.status === "success" && Array.isArray(res.entries)) {
            return res.entries;
        }
        return [];
    } catch (err) {
        console.error("Reconciliation Fetch Error:", err);
        return [];
    }
}

async function fetchLiveRevenueDailySummary(dateStr, dcName, dcNamesList) {
    try {
        const params = {
            action: "getLiveRevenueDailySummary",
            date: dateStr
        };
        if (dcName) params.dc_name = dcName;
        if (dcNamesList && dcNamesList.length) {
            params.dc_names = Array.isArray(dcNamesList) ? dcNamesList.join(",") : dcNamesList;
        }
        const res = await fetch(MASTER_SECURE_API_URL, {
            method: "POST",
            body: JSON.stringify(params)
        }).then(r => r.json());
        if (res && res.status === "success" && Array.isArray(res.rows)) {
            return res.rows;
        }
        return [];
    } catch (err) {
        console.error("Live Summary Fetch Error:", err);
        return [];
    }
}